	auto X = MP(x.FI + a[i] - (n - 1 - i) * d, MP(i, x.SE));
	auto Y = MP(y.FI + a[i] -          i  * d, MP(i, y.SE));
	auto Z = min(X, Y);

	bool f = (Z <= ST[i]);
	ST.apply(i, AP(A = Z));

	return f;
}

int main() {
	cin >> n >> d;
	inc(i, n) { cin >> a[i]; }

	inc(k, 2) { st[k].init(n, OP(min(A, B)), MP(INF, 0)); }
	inc(i, n) { st[0].ref(i) = MP((n - 1 - i) * d + a[i], i); }
	inc(i, n) { st[1].ref(i) = MP(         i  * d + a[i], i); }
	inc(k, 2) { st[k].calc(); }

	ST.init(n, OP(min(A, B)), MP(INF, MP(0, 0)));

