			auto mi = ST.fold_ID(0, n);
			s = mi.FI;
			x = mi.SE.FI;
			y = mi.SE.SE;
			if(ch(x)) { break; }
		}
		ans += s;

		sf(x);
		sf(y);
		ch(x);
		ch(y);
	}

	cout << ans << endl;

	return 0;
}

