			leftmin[i]=1;
			left.erase(itr);
		}else{
			itr=left.find(a[i]+d*i);
			left.erase(itr);
		}
	}


	for(i=n-1;i>=0;i--){
		right.insert(a[i]-d*i);
	}

	for(i=n-1;i>=0;i--){
		itr=right.begin();
		temp=*itr;
		if(a[i]-d*i==temp){
			rightmin[i]=1;
			right.erase(itr);
		}else{
			itr=right.find(a[i]-d*i);
			right.erase(itr);
		}
	}

	count=0;
	for(i=0;i<n;i++){
		if(leftmin[i]==1&&rightmin[i]==1){
			localmin[count]=i;
			count++;
		}
	}

	//	for(i=0;i<count;i++){
	//		printf("localmin[%d]=%lld\n",i,localmin[i]);
	//	}

	temp=0;
	for(i=0;i<count-1;i++){
		road[i][0]=localmin[i];
		road[i][1]=localmin[i+1];
		//		printf("i=%d,(%lld,%lld)\n",i,road[i][0],road[i][1]);
	}
	temp=count-1;
	temp1=-1;
	temp2=localmin[0];
	count=1;
	for(i=0;i<n;i++){
		if(temp1==-1){
			if(i<temp2){
				road[temp][0]=i;
				road[temp][1]=temp2;
				temp++;
			}else if(i==temp2){
				temp1=temp2;
				temp2=localmin[1];
			}
		}else if(temp2!=-1){
			if(i<temp2){
				if(a[temp1]+(i-temp1)*d<a[temp2]+(temp2-i)*d){
					road[temp][0]=temp1;
					road[temp][1]=i;
					temp++;
				}else{
					road[temp][0]=i;
					road[temp][1]=temp2;
					temp++;
				}
			}else if(i==temp2){
				temp1=temp2;
				temp2=localmin[count+1];
				count++;
			}
		}else{
			road[temp][0]=temp1;
			road[temp][1]=i;
			temp++;
		}
	}

	fri(temp){
		ans=ans+a[road[i][0]]+a[road[i][1]]+llabs(road[i][1]-road[i][0])*d;
//				printf("(%lld,%lld)",road[i][0],road[i][1]);
	}


	//	printf("計算部分終了\n");

	//出力

	printf("%lld",ans);


	//	printf("結果の出力終了\n");


	return 0;
}

