	for(int i=0;i<edge.size();i++)
	{
		pair<int,int> p=edge[i].second;
		if(uf.root(p.first)!=uf.root(p.second))
		{
			uf.connect(p.first,p.second);
			ret+=edge[i].first;
		}
	}
	printf("%lld\n",ret);
	return 0;
}

