struct UF{
private:
    vector<ll> par,len,you;
public:
    UF(ll n){
        rep(i,0,n){
            par.push_back(i);
            len.push_back(0);
            you.push_back(1);
        }
    }
    ll root(ll n){
        if(par[n]==n)return n;
        else return par[n]=root(par[n]);
    }
    void unit(ll a,ll b){
        a=root(a);
        b=root(b);
        if(a==b)return;
        if(len[a]<len[b]){
            par[a]=b;
            you[b]+=you[a];
        }
        else{
            par[b]=a;
            you[a]+=you[b];
            if(len[a]==len[b])len[a]++;
        }
    }
    ll yo(ll a){
        a=root(a);
        return you[a];
    }
};
struct ST{
private:
    ll n;
    vector<pll> dat;
public:
    ST(vector<ll> v){
        ll sz=v.size();
        n=1;while(n<sz)n*=2;
        pll p={inf,inf};
        dat.resize(2*n-1,p);
        rep(i,0,sz)dat[i+n-1]={v[i],i};
        rrep(i,n-2,0){
            dat[i]=min(dat[i*2+1],dat[i*2+2]);
        }
    }
    void add(ll k,ll x){
        ll i=k+n-1;
        dat[i]={x,k};
        while(i>0){
            i=(i-1)/2;
            dat[i]=min(dat[2*i+1],dat[2*i+2]);
        }
    }
    pll que(ll a,ll b,ll k=0,ll l=0,ll r=-1){
        if(r<0)r=n;
        if(b<=l||a>=r)return {inf,inf};
        if(a<=l&&b>=r)return dat[k];
        pll m1=que(a,b,2*k+1,l,(l+r)/2);
        pll m2=que(a,b,2*k+2,(l+r)/2,r);
        return min(m1,m2);
    }
    ll get(ll k){
        return dat[k+n-1].first;
    }
};

