#define REP(i,p,n) for(int i=p;i<n;++i)
#define rep(i,n) REP(i,0,n)

typedef long long int ll;
typedef pair<ll,ll> pii;
typedef vector<ll>  vint;
typedef vector<pii> vpii;
typedef vector<vint> det1;
typedef vector<vpii> det2;

ll N, D;

const int MAXN = 200000;
ll A[MAXN];
// ll C[MAXN][MAXN];

const ll INF = 10000000000LL;

ll solve(const det1& C)
{
    ll left = N - 1;

    vector<int> visited(N, 0);
    visited[0] = 1;

    ll res = 0;

    priority_queue<pii, vector<pii>, greater<pii> > Q;
    REP(i, 1, N) { Q.push(pii(C[0][i], static_cast<ll>(i))); }

    while (!Q.empty() && left != 0)
    {
        const auto cost = Q.top().first;
        const auto to   = Q.top().second;
        Q.pop();

        if (visited[to]) { continue; }
        visited[to] = 1;
        --left;

        res += cost;
        if (left == 0) { break; }

        rep (i, N) if (!visited[i]) { Q.push(pii(C[to][i], static_cast<ll>(i))); }
    }

    return res;
}

int main()
{
    cin >> N >> D;
    rep(i, N) { cin >> A[i]; }

    det1 C(N, vint());
    rep(i, N) { C[i].assign(N, 0LL); }

    rep(i, N) { C[i][i] = INF; }

    REP(i, 0, N)
    REP(j, i + 1, N)
    {
        const ll cost = abs(i - j) * D + A[i] + A[j];
        C[i][j] = C[j][i] = cost;
    }

    const ll ans = solve(C);
    cout << ans << endl;

    return 0;
}

