struct UnionFind {
  vector<int> data; // 根の場合は集合の大きさ*-1、子の場合は親の番号が入る
  UnionFind(int size) : data(size, -1) { }
  bool link(int x, int y) { //新たな併合を行うとtrue
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  int root(int x) { // 代表元を返す
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) { // 要素xが含まれる集合の大きさ
    return -data[root(x)];
  }
  bool same(int x, int y) { // 同じ集合ならtrue
    return root(x) == root(y);
  }
};

const int MAX_N = 212345;
ll A[MAX_N];

struct Edge {
  int a;
  int b;
  ll w;
  bool operator <(const Edge &o) const {
    return w > o.w;
  }
};

int go[MAX_N];
int back[MAX_N];

int main2() {
  int N = nextInt();

  ll D = nextInt();
  REP(i, N) A[i] = nextInt();

  REP(i, N) go[i] = i+1;
  REP(i, N) back[i] = i-1;

  priority_queue<Edge> pq;
  REP(i, N) {
    if (go[i] < N) { 
      int j = go[i];
      pq.push((Edge){i, j, D+A[i]+A[j]});
      go[i]++;
    }
    if (back[i] >= 0) {
      int j = back[i]; back[i]--;
      pq.push((Edge){i, j, D+A[i]+A[j]});
    }
  }

  ll ans = 0;
  UnionFind uf(N);
  while (uf.size(0) != N) {
    Edge e = pq.top(); pq.pop();
    if (uf.link(e.a, e.b)) {
      ans += e.w;
    }
    {
      int i = e.a;
      int j = go[i]; go[i]++;
      if (j < N && !uf.same(i, j)) {
        pq.push((Edge){i, j, abs(i-j)*D+A[i]+A[j]});
      }
    }
    {
      int i = e.a;
      int j = back[i]; back[i]--;
      if (j >= 0 && !uf.same(i, j)) {
        pq.push((Edge){i, j, abs(i-j)*D+A[i]+A[j]});
      }
    }
    {
      int i = e.b;
      int j = go[i]; go[i]++;
      if (j < N && !uf.same(i, j)) {
        pq.push((Edge){i, j, abs(i-j)*D+A[i]+A[j]});
      }
    }
    {
      int i = e.b;
      int j = back[i]; back[i]--;
      if (j >= 0 && !uf.same(i, j)) {
        pq.push((Edge){i, j, abs(i-j)*D+A[i]+A[j]});
      }
    }
  }
  cout << ans << endl;
  return 0;
}

