ll find(ll x){
    if (par.at(x)==x){
        return x;
    }
    else{
        par.at(x)=find(par.at(x));
        return par.at(x);
    }
}

void unite(ll x, ll y){
    ll px,py;
    px=find(x);
    py=find(y);
    if (px == py){
        return;
    }
    if (ranki.at(px) < ranki.at(py)){
        par.at(px)=py;
    }
    else{
        par.at(py)=px;
        if (ranki.at(px) == ranki.at(py)){
            ranki.at(px)+=1;
        }
    }
}

bool connect(ll x,ll y){
    return find(x)==find(y);
}

