    ll s=1e16;
    while (i>0){
        s=min(s,lbit.at(i));
        i-=i & -i;
    }
    return s;
}

void add(ll i, ll x){
    while (i<=Nmax){
        lbit.at(i)=min(x,lbit.at(i));
        i += i & -i;
    }
}
