template<typename T>
struct Segment_tree{
    ll N;
    T mem;
    vector<T> node;
    Segment_tree(vector<T> &X,T m):mem(m){
        ll sz=X.size();
        N=1;
        while(N<sz) N*=2;
        node.resize(2*N-1,mem);
        rep(i,0,sz) node[N-1+i]=X[i];
        per(i,N-2,0){
            node[i]=Compare(node[i*2+1],node[i*2+2]);
        }
    }
    T Compare(T &A,T &B){
        return std::min(A,B);
    }
    void update(ll X,T val){
        X+=N-1;
        node[X]=val;
        while(X>0){
            X=(X-1)/2;
            node[X]=Compare(node[X*2+1],node[X*2+2]);
        }
    }
    T Query(ll a,ll b,ll now,ll l,ll r){ //[a,b),[l,r)
        if(r<0) r=N;
        if(r<=a||b<=l) return mem;
        if(a<=l&&r<=b) return node[now];
        auto vl=Query(a,b,now*2+1,l,(l+r)/2),vr=Query(a,b,now*2+2,(l+r)/2,r);
        return Compare(vl,vr);
    }
};
template<typename T>
struct lazy_Segment_tree{
    int N;
    vector<T> node,lazy;
    T INF;
    lazy_Segment_tree(vector<T> X,T Y):INF(Y){
        N=1;
        while(X.size()>N) N*=2;
        node.resize(2*N-1,Y);
        lazy.resize(2*N-1);
        rep(i,0,X.size()) node[i+N-1]=X[i];
        per(i,N-2,0) node[i]=compare(node[i*2+1],node[i*2+2]);
    }
    T compare(T X,T Y){
        return std::min(X,Y);
    }
    T plus(T X,int l,int r){
        return X;
    }
    void eval(int now,int l,int r){
        if(lazy[now]==0) return;
        node[now]+=lazy[now];
        if(r-l>1){
            lazy[now*2+1]+=plus(lazy[now],l,r);
            lazy[now*2+2]+=plus(lazy[now],l,r);
        }
        lazy[now]=0;
    }
    void update(int a,int b,T add,int now=0,int l=0,int r=-1){
        if(r<0) r=N;
        eval(now,l,r);
        if(b<=l||r<=a) return;
        if(a<=l&&r<=b){
            lazy[now]+=add;
            eval(now,l,r);
        }
        else{
            update(a,b,add,now*2+1,l,(r+l)/2);
            update(a,b,add,now*2+2,(r+l)/2,r);
            node[now]=compare(node[now*2+1],node[now*2+2]);
        }
    }
    T Query(int a,int b,int now=0,int l=0,int r=-1){
        if(r<0) r=N;
        eval(now,l,r);
        if(b<=l||r<=a) return INF;
        if(a<=l&&r<=b) return node[now];
        return compare(Query(a,b,now*2+1,l,(r+l)/2),Query(a,b,now*2+2,(r+l)/2,r));
    }
};
struct Tree{
    int N;
    vii dp;
    vi dist;
    Tree(vii edge){
        N=edge.size();
        dp.resize(N);
        dist.resize(N,-1);
        for(int i=0;i<N;i++) dp[i].resize(30);
        dist[0]=dp[0][0]=0;
        std::queue<int> que;
        que.push(0);
        while(!que.empty()){
            int now=que.front(); que.pop();
            for(int i=0;i<edge[now].size();i++){
                int next=edge[now][i];
                if(dist[next]==-1){
                    dist[next]=dist[now]+1;
                    que.push(next);
                    dp[next][0]=now;
                }
            }
        }
        for(int i=1;i<30;i++){
            for(int j=0;j<N;j++) dp[j][i]=dp[dp[j][i-1]][i-1];
        }
    }
    int LCA(int X,int Y){
        if(dist[X]<dist[Y]) std::swap(X,Y);
        {
            int Z=dist[X]-dist[Y];
            for(int i=0;i<30;i++){
                if(Z&(1<<i)){
                    X=dp[X][i];
                }
            }
        }
        if(X==Y) return X;
        for(int i=29;i>=0;i--){
            if(dp[X][i]!=dp[Y][i]){
                X=dp[X][i];
                Y=dp[Y][i];
            }
        }
        return dp[X][0];
    }
};
struct Binary_indexed_tree{
    int N;
    vi bit;
    Binary_indexed_tree(int n):N(n){
        bit.resize(N+1,0);
    }
    void add(int x,ll a){
        for(x;x<=N;x+=(x&-x)) bit[x]+=a;
    }
    ll sum(int x){
        ll ret=0;
        for(x;x>0;x-=(x&-x)) ret+=bit[x];
        return ret;
    }
    ll lower_bound(ll X){
        if(sum(N)<X) return -1;
        ll ret=0,memo=1,sum=0;
        while(memo*2<=N) memo*=2;
        while(memo>0){
            if(memo+ret<=N&&sum+bit[memo+ret]<X){
                sum+=bit[memo+ret];
                ret+=memo;
            }
            memo/=2;
        }
        return ret+1;
    }
};
struct Union_Find{
    ll N;
    vi par;
    vi siz;
    Union_Find(int n):N(n){
        par.resize(N);
        siz.resize(N,1);
        rep(i,0,N) par[i]=i;
    }
    ll root(ll X){
        if(par[X]==X) return X;
        return par[X]=root(par[X]);
    }
    bool same(ll X,ll Y){
        return root(X)==root(Y);
    }
    void unite(ll X,ll Y){
        X=root(X);
        Y=root(Y);
        if(X==Y) return;
        par[X]=Y;
        siz[Y]+=siz[X];
        siz[X]=0;
    }
    ll size(ll X){
        return siz[root(X)];
    }
};
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
vi fac,finv,inv;
void COMinit() {
    fac.resize(MAX);
    finv.resize(MAX);
    inv.resize(MAX);
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
ll COM(ll n,ll r){
    if(n<r||n<0||r<0) return 0;
    return fac[n]*finv[r]%MOD*finv[n-r]%MOD;
}
void comp(vi &A){
    std::map<ll,ll> memo;
    rep(i,0,A.size()) memo[A[i]]=0;
    ll cnt=0;
    for(auto &p:memo) p.second=cnt++;
    rep(i,0,A.size()) A[i]=memo[A[i]];
}
int main(){
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    ll N,D; cin>>N>>D;
    vi A(N);
    rep(i,0,N) cin>>A[i];
    vector<pii> B(N),C(N);
    rep(i,0,N){
        B[i]=mp(A[i],i);
        C[i]=mp(A[i],i);
        B[i].first-=i*D;
        C[i].first+=i*D;
    }
    Segment_tree<pii> b(B,mp(inf,inf)),c(C,mp(inf,inf));
    b.update(0,mp(inf,inf));
    c.update(0,mp(inf,inf));
    std::set<std::tuple<ll,ll,ll>> seg;
    seg.insert(std::make_tuple(0,N-1,0));
    ll ans=0;
    std::set<std::pair<pii,ll>> mem;
    vector<bool> seen(N);
    seen[0]=1;
    mem.insert(mp(mp(c.Query(0,N,0,0,-1).first+A[0],c.Query(0,N,0,0,-1).second),0));
    while(!mem.empty()){
        auto p=*begin(mem);
        ll i=p.first.second;
        mem.erase(p);
        if(i==inf) continue;
        //if(p.second==2&&!seen[i]) cout<<p.first.first<<" "<<p.first.second<<endl;
        //cout<<p.first.first<<" "<<p.first.second<<" "<<p.second<<endl;
        b.update(i,mp(inf,inf));
        c.update(i,mp(inf,inf));
        {
            ll P=p.second;
            auto it=seg.upper_bound(std::make_tuple(P,inf,inf));
            it--;
            ll X,Y,Z;
            std::tie(X,Y,Z)=*it;
            pii x=b.Query(X,P,0,0,-1),y=c.Query(P,Y+1,0,0,-1);
            x.first+=P*D+A[P];
            y.first-=P*D-A[P];
            //if(P==2) cout<<X<<" "<<Y<<" "<<i<<endl;
            if(x.first<=inf/2) mem.insert(mp(x,P));
            if(y.first<=inf/2) mem.insert(mp(y,P));
        }
        if(seen[i]) continue;
        ans+=p.first.first;
        //cout<<p.first.first<<" "<<p.first.second<<endl;
        seen[i]=1;
        auto it=seg.upper_bound(std::make_tuple(i,inf,inf));
        it--;
        ll left=i,right=N-1;
        std::set<std::tuple<ll,ll,ll>> era,ins;
        while(it!=seg.end()){
            ll X,Y,Z;
            std::tie(X,Y,Z)=*it;
            X=std::max(X,i);
            ll l=X,r=Y+1;
            while(l+1<r){
                ll mid=(r+l)/2;
                if(abs(mid-Z)*D+A[Z]>=abs(mid-i)*D+A[i]) l=mid;
                else r=mid;
            }
            if(l==Y){
                era.insert(*it);
                it++;
                continue;
            }
            right=l;
            pii x=b.Query(X,Z,0,0,-1),y=c.Query(Z,right,0,0,-1);
            x.first+=Z*D+A[Z];
            y.first-=Z*D-A[Z];
            if(x.first<=inf/2) mem.insert(mp(x,Z));
            if(y.first<=inf/2) mem.insert(mp(y,Z));
            era.insert(*it);
            ins.insert(std::make_tuple(right+1,Y,Z));
            break;
        }
        it=seg.upper_bound(std::make_tuple(i,inf,inf));
        it--;
        while(1){
            ll X,Y,Z;
            std::tie(X,Y,Z)=*it;
            Y=std::min(X,i);
            ll l=X-1,r=Y;
            while(l+1<r){
                ll mid=(r+l)/2;
                if(abs(mid-Z)*D+A[Z]>=abs(mid-i)*D+A[i]) r=mid;
                else l=mid;
            }
            if(r==X){
                era.insert(*it);
                if(it==seg.begin()){
                    left=r;
                    break;
                }
                it--;
                continue;
            }
            left=r;
            pii x=b.Query(left+1,Z,0,0,-1),y=c.Query(Z,Y+1,0,0,-1);
            x.first+=Z*D+A[Z];
            y.first-=Z*D-A[Z];
            if(x.first<=inf/2) mem.insert(mp(x,Z));
            if(y.first<=inf/2) mem.insert(mp(y,Z));
            era.insert(*it);
            ins.insert(std::make_tuple(X,left-1,Z));
            break;
        }
        ins.insert(std::make_tuple(left,right,i));
        it=seg.upper_bound(std::make_tuple(i,inf,inf));
        it--;
        era.insert(*it);
        ll X,Y,Z;
        std::tie(X,Y,Z)=*it;
        if(abs(Z-i)*D+A[Z]<=A[i]) continue;
        pii x=b.Query(left,i,0,0,-1),y=c.Query(i,right+1,0,0,-1);
        x.first+=i*D+A[i];
        y.first-=i*D-A[i];
        //cout<<left<<" "<<right<<" "<<i<<endl;
        if(x.first<=inf/2) mem.insert(mp(x,i));
        if(y.first<=inf/2) mem.insert(mp(y,i));
        for(auto p:era) if(seg.count(p)) seg.erase(p);
        for(auto p:ins){
            ll x,y,z; std::tie(x,y,z)=p;
            //cout<<x<<" "<<y<<" "<<z<<" "<<i<<endl;
            seg.insert(p);
        }
    }
    cout<<ans<<endl;
}

