set<pair<ll, ll> > S;

void add(ll x, ll v, ll dsum) {
    S.insert({v - dsum, A[x].second});
}

long long INF = 1e18;

pair<ll, ll> find_min(ll x, ll dsum) {
    pair<ll, ll> r;
    auto it = S.begin();
    while (it != S.end()) {
        if (uf.findSet(A[x].second, it->second)) {
            ++it;
        } else {
            r = *it;
            break;
        }
    }
//    hoge[uf.root(A[x].second)] = it;
    if (it == S.end()) return {INF, INF};
    return {r.first + dsum + A[x].first, r.second};
}

void init() {
    S.clear();
}

bool one_step(ll &ans) {
    init();
    vector<pair<ll,pair<ll, ll>>> seq;

    for (int i = 0; i < A.size(); i++) {
        auto r = find_min(i, i * D);
        seq.emplace_back(r.first, make_pair(r.second, i));
        add(i, A[i].first, i * D);
    }

    init();
    reverse(A.begin(), A.end());
    {
        for (int i = 0; i < A.size(); i++) {
            auto r = find_min(i, i * D);
            seq.emplace_back(r.first, make_pair(A[i].second, r.second));
            add(i, A[i].first, i * D);
        }
    }
    reverse(A.begin(), A.end());

    sort(seq.begin(), seq.end());
    for(auto i : seq ){
        if( i.first == INF ) continue;
        if( uf.unionSet(i.second.first, i.second.second) ){
            ans += i.first;
        }
    }
    return false;
}

