    ll sm = 0;
    while(nw < n-1){
        vl hoge1(n), hoge2(n);
        rep(i,n){
            hoge1[i] = a[i] + i*D;
            hoge2[i] = a[i] + (n-i-1)*D;
            visit[i] = false;
        }
        segtree<ll> l(hoge2), r(hoge1);
        vector<tri> add;
        rep(i,n){
            if(visit[i]) continue;
            vi ver;
            tri res = {2*INF, 2*INF, 2*INF};
            dfs(i, -1, ver);
            each(v, ver){
                l.update(v, INF), r.update(v, INF);
            }
            each(v, ver){
                auto p = l.query(0, v);
                auto q = r.query(v+1, n);
                p.fi -= (n-v-1)*D, q.fi -= v*D;
                auto hoge = min(p, q);
                cmn(res, ((tri){hoge.fi + a[v], hoge.se, v}));
            }
            add.pb((tri){res.th, res.se, res.fi});
            each(v, ver){
                l.update(v, a[v]+(n-v-1)*D), r.update(v, a[v]+v*D);
            }
        }
        each(p, add){
            if(G[p.fi].find(p.se) == G[p.fi].end()){
                G[p.fi].insert(p.se), G[p.se].insert(p.fi);
                nw++;
                sm += p.th;
            }
        }
    }
    cout << sm << "\n";
    return 0;
}

