    UnionFind(int n) : n(n), cnt(n), par(n), rank(n), sz(n, 1) {
        iota(par.begin(), par.end(), 0);
    }

    int find(int x) {
        if (x == par[x]) return x;
        return par[x] = find(par[x]);
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return sz[find(x)];
    }

    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            par[x] = y;
            sz[y] += sz[x];
        } else {
            par[y] = x;
            sz[x] += sz[y];
            if (rank[x] == rank[y]) {
                rank[x]++;
            }
        }
        cnt--;
    }
};

void solve1() {
    vector<tuple<i64, int, int>> es;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            i64 c = 1ll * d * abs(as[i].second - as[j].second) + as[i].first + as[j].first;
            es.emplace_back(c, as[i].second, as[j].second);
        }
    }
    sort(es.begin(), es.end());
    UnionFind uf(n);
    i64 cost = 0;
    for (int i = 0;; i++) {
        if (!uf.same(get<1>(es[i]), get<2>(es[i]))) {
            uf.unite(get<1>(es[i]), get<2>(es[i]));
            cost += get<0>(es[i]);
        }
        if (uf.cnt == 1) break;
    }
    cout << cost << endl;
}

