struct edge {
  int to;
  ll cost;
};

struct info {
  int origin;
  ll cost;
};

int main() {
  int n;
  scan(n);
  ll d;
  scan(d);
  vll a(n);
  scan(a);
  ll INF = LLONG_MAX / 2;
  auto g = make_v<edge>(2*n, 0);
  rep (i, n) {
    g[i].push_back({i+n, a[i]});
    g[i+n].push_back({i, a[i]});
  }
  rep (i, n-1) {
    g[i+n].push_back({i+1+n, d});
    g[i+1+n].push_back({i+n, d});
  }
  auto infos = vector<info>(2*n);
  rep (i, n) {
    infos[i] = {i, 0};
    infos[i+n] = {-1, INF};
  }

  vvll edges;
  priority_queue<vll, vvll, greater<vll>> q;
  vector<bool> fixed(2*n, false);
  rep (i, n) {
    q.push({0LL, (ll)i});
  }

  while (!q.empty()) {
    ll curr_cost = q.top()[0];
    int u = q.top()[1];
    q.pop();
    if (fixed[u]) { continue; }
    fixed[u] = true;
    for (auto&& e : g[u]) {
      int v = e.to;
      if (fixed[v]) {
        continue;
      }
      ll new_cost = curr_cost + e.cost;
      if (infos[v].cost > new_cost) {
        infos[v].cost = new_cost;
        infos[v].origin = infos[u].origin;
        q.push({new_cost, v});
      }
    }
  }
  fixed.assign(2*n, false);
  deque<int> stk = {0};
  while (!stk.empty()) {
    int u = stk.front();
    stk.pop_front();
    fixed[u] = true;
    for (auto&& e : g[u]) {
      int v = e.to;
      if (fixed[v]) { continue; }
      if (infos[u].origin != infos[v].origin) {
        edges.push_back({infos[u].cost + infos[v].cost + e.cost, infos[u].origin, infos[v].origin});
      }
      stk.push_back(v);
    }
  }
  //debug(edges.size());
  //debug(edges);
  assert((int)edges.size() == n-1);
  ll ans = 0;
  for (auto&& e : edges) {
    ans += e[0];
  }
  print(ans);

  return 0;
}

