	}
	for (int i = 1; i < N; i++) {
		lm[lsg.RMQ(i, i)].pop_back();
		Edge add;
		add.a = i;
		add.b = box.second;
		add.cost = box.first + v[i] - K * (N - i - 1);
		//cerr << add.a << " " << add.b << endl;
		edge.emplace_back(add);
		long long int cost = lsg.RMQ(i + 1, N - 1);
		if (cost == LLONG_MAX)continue;
		int index = lm[cost].back();
		add.a = index;
		add.cost = box.first + v[index] - K * (N - index - 1);
		edge.emplace_back(add);
		if (box.first >= v[i] + (N - 1 - i)*K) {
			box = { v[i] + (N - 1 - i)*K,i };
		}
	}
	box = { v.back() + (N - 1)*K,N - 1 };
	for (int i = N - 2; i >= 0; i--) {
		rm[rsg.RMQ(i, i)].pop_back();
		Edge add;
		add.a = i;
		add.b = box.second;
		add.cost = box.first + v[i] - K * i;
		//cerr << add.a << " " << add.b << endl;
		edge.emplace_back(add);
		long long int cost = rsg.RMQ(0, i - 1);
		if (cost == LLONG_MAX)continue;
		int index = rm[cost].back();
		add.a = index;
		add.cost = box.first + v[index] - K * index;
		edge.emplace_back(add);
		if (box.first >= v[i] + K * i) {
			box = { v[i] + K * i,i };
		}
	}
	sort(edge.begin(), edge.end());
	UnionFind uf(N);
	long long int ans = 0;
	for (auto i : edge) {
		//cerr << i.a << " " << i.b << " " << i.cost << endl;
		if (uf.Check_Same(i.a, i.b))continue;
		cerr << i.a << " " << i.b << endl;
		ans += i.cost;
		uf.Unite(i.a, i.b);
	}
	cout << ans << endl;
	return 0;
}

