void DnC(ll d, ll le = 0, ll ri = a.size())
{
	co++;
	if (le >= ri-1)
		return;
	DnC(d, le, (ri + le) / 2);
	DnC(d, (ri + le) / 2, ri);
	ll lem = 0, rim = (ri + le) / 2;

	forn(i, le, (ri + le) / 2)
	{
		ll cost1, cost2;
		cost1 = a[lem] - d*lem;
		cost2 = a[i] - d*i;
		if (cost2 < cost1)
			lem = i;
	}

	forn(i, (ri + le) / 2, ri)
	{
		ll cost1, cost2;
		cost1 = a[rim] + d*rim;
		cost2 = a[i] + d*i;
		if (cost2 < cost1)
			rim = i;
	}

	forn(i, le, (ri + le) / 2)
	{
		ll cle, cri;
		cle = a[i] - d*i;
		cri = a[rim] + d*rim;
		ll cost = cle + cri;
		ed[i].push_back(make_pair(cost, rim));
		if(i != lem)
			ed[rim].push_back(make_pair(cost, i));
	}

	forn(i, (ri + le) / 2, ri)
	{
		ll cle, cri;
		cle = a[lem] - d*lem;
		cri = a[i] + d*i;
		ll cost = cle + cri;
		ed[i].push_back(make_pair(cost, lem));
		if (i != rim)
			ed[lem].push_back(make_pair(cost, i));
	}
}

struct greater
{
	bool operator() (const pll& x, const pll& y)const
	{
		return x > y;
	}
};

ll MSTcost()
{
	priority_queue<pll, vector<pll>, greater> pile;
	vl used(ed.size(), 0);
	ll cost = 0;
	pile.push(make_pair(0, 0));
	while (pile.size())
	{
		pair<ll, ll> cur;
		cur = pile.top();
		pile.pop();
		if (used[cur.second])
			continue;
		used[cur.second] = 1;
		cost += cur.first;
		for (pair<ll, ll> edge : ed[cur.second])
		{
			if (used[edge.second])
				continue;
			pile.push(edge);
		}
	}
	cost;
	return cost;
}

