struct UF{
	int p[200010],rank[200010];	
	void init() {
		for (int i=0;i<200010;i++) p[i]=i;
		for (int i=0;i<200010;i++) rank[i]=0;
	}
	int getf(int x){
		if (p[x]==x) return x;
		return getf(p[x]);
	}
	bool same(int x,int y) {
		return getf(x)==getf(y);
	}
	void unite(int x,int y) {
		int xx=getf(x);
		int yy=getf(y);
		if (xx!=yy) {
			if (rank[xx]<rank[yy]) p[xx]=yy;
			else {
				p[yy]=xx;
				if (rank[xx]==rank[yy]) rank[xx]++;
			}
		}
	}
