void construct(int l, int r)
{
//    for (int i = 0; i < n; ++i)
//        for (int j = i + 1; j < n; ++j)
//            edges.push_back(edge(i, j, val[i] + val[j] + (j - i) * d));
//
//    return;

    if (l == r)
        return;

    int m = (l + r) >> 1;

    construct(l, m);
    construct(m + 1, r);

    int i0 = l, j0 = r;
    for (int i = l; i <= m; ++i)
        if (val[i] - d * i < val[i0] - d * i0)
            i0 = i;


    for (int i = m + 1; i <= r; ++i)
    {
        if (val[i] + d * i < val[j0] + d * j0)
            j0 = i;
    }

    for (int i = l; i <= r; ++i)
    {
        if (i <= m)
        {
            edges.push_back(edge(i, j0, val[i] + val[j0] + d * (j0 - i)));
        } else
        {
            edges.push_back(edge(i0, i, val[i0] + val[i] + d * (i - i0)));
        }
    }
}


