void init(int m_){
	m=1;
	while(m<m_) m<<=1;
	for(int i=1; i<=2*m-1; i++) mx[0][i]=mx[1][i]=INF, ind[0][i]=ind[1][i]=-1;
}

void update(int k, int a, int i){
	k+=m;
	mx[i][k]=a;
	ind[i][k]=k-m;
	while(k>1){
		k>>=1;
		if(mx[i][2*k]<mx[i][2*k+1]){
			ind[i][k]=ind[i][2*k];
		}else{
			ind[i][k]=ind[i][2*k+1];
		}
		mx[i][k]=min(mx[i][2*k], mx[i][2*k+1]);
	}
}

int query(int a, int b, int i){
	a+=m, b+=m;
	ll ans=INF; int ind0=-1;
	for(;a<b; a>>=1, b>>=1){
		if(b&1){
			b--;
			if(ans>mx[i][b]){
				ans=mx[i][b];
				ind0=ind[i][b];
			}
		}
		if(a&1){
			if(ans>mx[i][a]){
				ans=mx[i][a];
				ind0=ind[i][a];
			}
			a++;
		}
	}
	return ind0;
}
