struct UfData {
  int parsz;
  // LL w;
  UfData() : parsz(-1) {
    // w = 0;
  }

  void Merge(const UfData &d, int u, int v) {
    parsz += d.parsz;
    // w += d.w;
  }
};

struct UnionFind {
  vector<UfData> dat;

  UnionFind() {}
  UnionFind(int n) {
    Init(n);
  }

  void Init(int n) {
    dat.assign(n, UfData());
  }

  int Root(int v) {
    if (dat[v].parsz < 0) return v;
    return dat[v].parsz = Root(dat[v].parsz);
  }

  bool Unite(int u, int v) {
    int p = Root(u);
    int q = Root(v);
    if (p == q) return false;

    if (dat[p].parsz > dat[q].parsz) {
      swap(p, q);
      swap(u, v);
    }

    dat[p].Merge(dat[q], u, v);
    dat[q].parsz = p;

    return true;
  }

  bool Same(int u, int v) {
    return Root(u) == Root(v);
  }

  int Size(int v) {
    return -dat[Root(v)].parsz;
  }

  UfData& Data(int v) {
    return dat[Root(v)];
  }
};

