void solve(int l, int r, ll d) {
  if (r - l <= 1) return;
  int m = (l + r) / 2;
  ll mi1 = INF, mi2 = INF;
  int mii1 = -1, mii2 = -1;
  for (int i = l; i < m; i++) {
    if (mi1 > a[i] - d*i) {
      mi1 = a[i] - d*i;
      mii1 = i;
    }
  }
  for (int i = m; i < r; i++) {
    if (mi2 > a[i] + d*i) {
      mi2 = a[i] + d*i;
      mii2 = i;
    }
  }
  for (int i = l; i < m; i++) {
    edges.push_back({a[i] + a[mii2] + (mii2 - i)*d, pii(i, mii2)});
  }
  for (int i = m; i < r; i++) {
    edges.push_back({a[i] + a[mii1] + (i - mii1)*d, pii(mii1, i)});
  }
  solve(l, m, d); solve(m, r, d);
}

