void chmin(T& a, T b) {
  if (b < a) a = b;
}

struct UnionFind {
  vector<int> parent;  // parent[root] is the negative of the size.
  UnionFind(int n)
      : parent(n, -1){};
  bool unite(int u, int v) {
    u = root(u);
    v = root(v);
    if (u == v) return false;
    if (parent[u] > parent[v]) swap(u, v);
    parent[u] += parent[v];
    parent[v] = u;
    return true;
  }
  bool find(int u, int v) {
    return root(u) == root(v);
  }
  int root(int u) {
    return parent[u] < 0 ? u : parent[u] = root(parent[u]);
  }
  int size(int u) {
    return -parent[root(u)];
  }
};

using P = pair<ll, int>;

struct Edge {
  int x, y;
  ll w;

  bool operator<(const Edge& rhs) const {
    return w < rhs.w;
  }
};

void push(vector<P>& ps, P x) {
  bool found = false;
  for (auto& y : ps) {
    if (y.snd == x.snd) {
      y = min(y, x);
      found = true;
    }
  }
  if (!found) ps.push_back(x);
  sort(ps.begin(), ps.end());
  if (ps.size() > 2)
    ps.resize(2);
}

const ll INF = 1ll << 60;

int main() {
  int N;
  ll D;
  while (cin >> N >> D) {
    vector<ll> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    UnionFind uf(N);
    int components = N;
    ll res = 0;
    while (components >= 2) {
      vector<Edge> edges(N, Edge{-1, -1, INF});
      vector<P> L, R;
      for (int i = 0; i < N; i++) {
        int r = uf.root(i);
        for (auto p : L) {
          if (p.snd != r)
            chmin(edges[r], Edge{r, p.snd, p.fst + i * D + A[i]});
        }
        push(L, P(-i * D + A[i], r));
      }
      for (int i = N - 1; i >= 0; i--) {
        int r = uf.root(i);
        for (auto p : R) {
          if (p.snd != r)
            chmin(edges[r], Edge{r, p.snd, p.fst - i * D + A[i]});
        }
        push(R, P(+i * D + A[i], r));
      }
      for (auto& e : edges) {
        if (e.w >= INF)
          continue;
        if (uf.unite(e.x, e.y)) {
          res += e.w;
          --components;
        }
      }
    }
    cout << res << endl;
  }
  return 0;
}

