vl a;
gosh DnC(vl a, ll d, ll st = 0)
{
	gosh ed(1);
	if (a.size() == 1)
		return ed;
	vector<ll> le, ri;
	le = vector<ll>(a.begin(), a.begin() + a.size() / 2);
	ri = vector<ll>(a.begin() + a.size() / 2, a.end());
	gosh fir = DnC(le, d, st);
	gosh sec = DnC(ri, d, st + a.size()/2);
	ed = fir;
	ed.insert(ed.end(), sec.begin(), sec.end());
	ll lem = 0, rim = 0;
	forn(i, 0, le.size())
	{
		le[i] = le[i] - d*i;
		if (le[lem] > le[i])
			lem = i;
	}
	forn(i, 0, ri.size())
	{
		ri[i] = ri[i] + d*(le.size() + i);
		if (ri[rim] > ri[i])
			rim = i;
	}
	forn(i, 0, le.size())
	{
		ll cost, start, end;
		cost = le[i] + ri[rim];
		start = i + st;
		end = rim + st + le.size();
		ed[i].push_back(make_pair(cost, make_pair(start, end)));
		if (i == lem)
			continue;
		ed[rim + le.size()].push_back(make_pair(cost, make_pair(end, start)));
	}
	forn(i, 0, ri.size())
	{
		ll cost, start, end;
		cost = le[lem] + ri[i];
		start = i + st + le.size();
		end = lem + st;
		ed[i + le.size()].push_back(make_pair(cost, make_pair(start, end)));
		if (i == rim)
			continue;
		ed[lem].push_back(make_pair(cost, make_pair(end, start)));
	}
	return ed;
}


ll MSTcost(gosh ed)
{
	ll ret = 0;
	set<pair<ll, pll>> pile;
	vl used(ed.size(), 0);
	ll cost = 0, sum = 0;
	pile.insert(make_pair(0, make_pair(0, 0)));
	while (pile.size())
	{
		pair<ll, pll> cur;
		cur = *pile.begin();
		pile.erase(pile.begin());
		if (used[cur.second.second])
			continue;
		used[cur.second.second] = 1;
		cost += cur.first;
		for (pair<ll, pll> edge : ed[cur.second.second])
		{
			if (used[edge.second.second])
				continue;
			pile.insert(edge);
		}
	}
	ret = cost;
	return ret;
}

