    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        ai[i] = {a[i], i};
    }
    sort(ai.begin(), ai.end());
    SegmentTree<pair<lint, lint>> segl(n, f, unit), segr(n, f, unit);
    segl.update(ai[0].second, {ai[0].first - d * ai[0].second, ai[0].second});
    segr.update(ai[0].second, {ai[0].first + d * ai[0].second, ai[0].second});
    Kruskal<lint> graph(n);
    for (int i = 1; i < n; ++i) {
        auto minil = segl.query(0, ai[i].second);
        auto minir = segr.query(ai[i].second, n);
        if (minil.second != -1) {
            int idx   = minil.second;
            int aa    = a[idx];
            lint cost = ai[i].first + aa + abs(ai[i].second - idx) * d;
            graph.addEdge(idx, ai[i].second, cost);
        }
        if (minir.second != -1) {
            int idx   = minir.second;
            int aa    = a[idx];
            lint cost = ai[i].first + aa + abs(ai[i].second - idx) * d;
            graph.addEdge(idx, ai[i].second, cost);
        }
        segl.update(ai[i].second, {ai[i].first - d * ai[i].second, ai[i].second});
        segr.update(ai[i].second, {ai[i].first + d * ai[i].second, ai[i].second});
    }
    cout << graph.build() << "\n";
    return 0;
}

