struct SegmentTree {
  private:
    int n;
    vector<P> node;

public:
  SegmentTree(vector<P> v) {
    int sz = (int)v.size();
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n-1);

    REP(i,sz) node[i+n-1] = v[i];
    RREP(i,n-1) node[i] = min(node[i*2+1],node[i*2+2]); //最大値ならmax
  }

  // 0_indexedでk番目の要素をaに変更
  void update(int k, P a){
    k += n-1;
    node[k] = a;
    while(k > 0){
      k = (k-1) / 2;
      node[k] = min(node[k*2+1],node[k*2+2]); //最大値ならmax
    }
  }

  // 半開区間[l,r)から、[a,b)に対するクエリ。
  P query(int a, int b, int k=0, int l=0, int r=-1){
    if(r < 0) r = n;
    if(r <= a || b <= l) return P(INF,0); // 最大値なら-INF
    if(a <= l && r <= b) return node[k];
    else{
      P vl = query(a,b,k*2+1,l,(l+r)/2);
      P vr = query(a,b,k*2+2,(l+r)/2,r);
      return min(vl,vr); //最大値ならmax
    }
  }
};

struct UnionFind {
  private:
  vector<int> child,tree,sum;

public:
  UnionFind(int v) {
    tree.resize(v);
    sum.resize(v);
    REP(i,v) tree[i] = i, sum[i] = 1;
  }

  int root(int i){
    if(i == tree[i]){
      REP(j,child.size()) tree[child[j]] = i;
      child.clear(); 
      return i;
    }
    else{
      child.push_back(i);
      return i = root(tree[i]);
    }
  }

  int size(int i){
    return sum[root(i)];
  }

  int unit(int x, int y){
    x = root(x);
    y = root(y);
    sum[min(x,y)] += sum[max(x,y)];
    tree[max(x,y)] = min(x,y);
  }

  bool isUnit(int x, int y){
    return root(x) == root(y);
  }
};

