  SegmentTree segL(vector<P>(n,P(INF,0))),segR(vector<P>(n,P(INF,0)));
  vector<pair<int,P>> edge;
  REP(i,n){
    int id = tmp[i].sc;
    segL.update(id,P(tmp[i].fs+d*id,id));
    segR.update(id,P(tmp[i].fs+d*(n-1-id),id));

    P pos = segR.query(0,id);
    edge.push_back(make_pair(a[id]+pos.fs-(n-1-id)*d,P(pos.sc,id)));

    pos = segL.query(id+1,n);
    edge.push_back(make_pair(a[id]+pos.fs-id*d,P(pos.sc,id)));
  }

  sort(edge.begin(),edge.end());
