int par[200002];
int rk[200002];

void init(int n){
	for(int i=0; i<n; i++){
		par[i]=i; rk[i]=0;
	}
}

int find(int x){
	if(par[x]==x){
		return x;
	}else{
		return par[x]=find(par[x]);
	}
}

void unite(int x, int y){
	x=find(x);
	y=find(y);
	if(x==y) return;
	if(rk[x]<rk[y]){
		par[x]=y;
	}else{
		par[y]=x;
		if(rk[x]==rk[y]) rk[x]++;
	}
}

bool same(int x, int y){
	return find(x)==find(y);
}
int n;
ll d;
ll a[200001];
vector<Pi> e;
void solve(int l, int r){
	if(l==r) return;
	int m=(l+r)/2;
	vector<int> indl;
	for(int i=l; i<=m; i++) indl.push_back(i);
	sort(indl.begin(), indl.end(), [&](int i, int j){ return a[i]-(ll)i*d<a[j]-(ll)j*d;});
	priority_queue<Pi, vector<Pi>, greater<Pi>> que;
	for(int y=m+1; y<=r; y++){
		int x=indl[0];
		que.push(Pi(a[x]+a[y]+(ll)(y-x)*d, P(0, y)));
	}
	init(r-l+1);
	int ct=0;
	for(;ct<r-l;){
		Pi p=que.top(); que.pop();
		ll s=p.first; int i1=p.second.first, y=p.second.second;
		if(!same(i1, y-l)){
			unite(i1, y-l); ct++;
			e.push_back(Pi(s, P(indl[i1], y)));
		}
		if(i1<(int)indl.size()-1){
			s-=(a[indl[i1]]-(ll)indl[i1]*d);
			i1++;
			s+=(a[indl[i1]]-(ll)indl[i1]*d);
			que.push(Pi(s, P(i1, y)));
		}
	}
	solve(l, m);
	solve(m+1, r);
}
int main()
{
	cin>>n>>d;
	for(int i=0; i<n; i++){
		cin>>a[i];
	}
	if(n==1){
		cout<<0<<endl;
		return 0;
	}
	solve(0, n-1);
	ll ans=0;
	sort(e.begin(), e.end());
	init(n);
	for(int i=0; i<e.size(); i++){
		int x=e[i].second.first, y=e[i].second.second;
		if(!same(x, y)){
			unite(x, y);
			ans+=e[i].first;
		}
	}
	cout<<ans<<endl;
	return 0;
}

