	vector<int>uni(n);
	for(i=0;i<n;i++){uni[i]=i;}
	vector<int>ran(n,1);
	while(-1){
		pair<llint,int>saf=mp(a[0],uni[0]);
		pair<llint,int>sac=mp(big,0);
		vector<tuple<llint,int,int>>go(n,mt(big,-1,-1));
		for(i=1;i<n;i++){
			pair<llint,int>ter=saf;
			if(saf.sec==uni[i]){ter=sac;}
			mineq(go[uni[i]],mt(ter.fir+a[i]+D*i,ter.sec,uni[i]));
			if(uni[i]==sac.sec){mineq(saf,mp(a[i]-D*i,uni[i]));}
			else{mineq(sac,mp(a[i]-D*i,uni[i]));if(saf>sac){swap(saf,sac);}}
		}
		saf=mp(a[n-1]+D*(n-1),uni[n-1]);
		sac=mp(big,0);
		for(i=n-2;i>=0;i--){
			pair<llint,int>ter=saf;
			if(saf.sec==uni[i]){ter=sac;}
			mineq(go[uni[i]],mt(ter.fir+a[i]-D*i,ter.sec,uni[i]));
			//if(i==n-2){cerr<<"de"<<ter.fir+a[i]-D*i<<endl;}
			if(uni[i]==sac.sec){mineq(saf,mp(a[i]+D*i,uni[i]));}
			else{mineq(sac,mp(a[i]+D*i,uni[i]));if(saf>sac){swap(saf,sac);}}
		}

		for(auto it:go){
			llint cost,x,y;tie(cost,x,y)=it;
			if(cost>=big){continue;}
			while(x!=uni[x]){x=uni[x];}
			while(y!=uni[y]){y=uni[y];}

			if(x==y){continue;}
			//cerr<<"c,x,y"<<cost<<","<<x<<","<<y<<endl;
			if(ran[x]<ran[y]){swap(x,y);}
			uni[y]=x;ran[x]+=ran[y];ans+=cost;
		}
		for(i=0;i<n;i++){
			int x=i;
			while(x!=uni[x]){x=uni[x];}
			uni[i]=x;
		}
		bool can=1;
