int par[200200];
void init(int _n){
	rep(i, _n) par[i] = i;
}
int find(int now){
	if(par[now] == now) return now;
	return par[now] = find(par[now]);
}
bool unite(int a, int b){
	int Pa = find(a), Pb = find(b);
	if(Pa == Pb) return false;
	par[Pa] = Pb;
	return true;
}

int n, d;
int a[200200];
vector< pair< int, pii > > edge;

void solve(int l, int r){ // [l; r]
	if(l >= r) return ;
	int m = (l + r) / 2;
	int mnL = LINF, mnposL;
	for(int i = l; i <= m; i++){
		if(a[i] - d * (i + 1) < mnL){
			mnL = a[i] - d * (i + 1);
			mnposL = i;
		}
	}
	int mnR = LINF, mnposR;
	for(int i = m + 1; i <= r; i++){
		if(a[i] + d * (i + 1) < mnR){
			mnR = a[i] + d * (i + 1);
			mnposR = i;
		}
	}
	for(int i = m + 1; i <= r; i++){
		edge.pb( mp(mnL + a[i] + d * (i + 1), mp(mnposL, i)) );
	}
	for(int i = l; i <= m; i++){
		edge.pb( mp(mnR + a[i] - d * (i + 1), mp(i, mnposR)) );
	}
	solve(l, m);
	solve(m + 1, r);
}

