template<class M> struct segmini {
    int n;
    vector<int> seg;
    vector<M> dat;
    int f(int a, int b) { return dat[a] < dat[b] ? a : b; }
    int e;
    const M ev = MAX(M);
    void build(vector<M> datt) {        dat = datt;        e = sz(dat);        dat.emplace_back(ev);        n = 1;        int asz = dat.size();        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = i;        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);    }
    segmini();
    segmini(int len){build(vector<M>(len,ev));}
    segmini(vector<M> datt) : dat(datt) {        e = sz(dat);        dat.emplace_back(ev);        n = 1;        int asz = dat.size();        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = i;        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);    }
    void update(int k, M v) {        dat[k] = v;        k += n - 1;        while (k) {            k = (k - 1) >> 1;            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);        }    }
    void del(int k) { update(k, e); }
    void add(int k, int v) { update(k, v + seg[k + n - 1]); }
    //高速なquery 葉から辿る
    int query(int l, int r) {        M retl = e;        M retr = e;        l += n - 1;        r += n - 1;        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/            if (!(l & 1)) { retl = f(retl, seg[l]); }            /*右なら、左を取らないと機会を逃す*/            if (!(r & 1)) { retr = f(seg[r - 1], retr); }            l >>= 1;            r = (r - 1) >> 1;        }        return f(retl, retr);    }
    int geti(int l,int r) {        return query(l, min(r, n));    }
    int geti(int r) {        return query(0, min(r, n));    }
    int geti() {        return query(0, n);    }
    int getir(int m) {        return query(m, n);    }
    int get(int l,int r) {        return dat[geti(l, r)];    }
    int get(int r) {        return dat[geti(r)];    }
    int get() {        return dat[geti()];    }
    int getr(int m){return dat[getir(m)];}
    //***************************
#ifdef _DEBUG
    void debu() {        rep(i, min(n, 10ll)) {            int v = get(i,i+1);            if (v == MIN(ll) || v == MAX(ll)) {                cerr << "e ";            } else {                cerr << v << " ";            }        }        cerr << "" << endl;    }
#else
    inline void debu(){;}
#endif
};//@formatter:on


