class UF {
private:
  vector<int> data; // parent or size
  vector<int> next;
  vector<int> last;
  void init(int n) {
    data.assign(n, -1);
    next.assign(n, -1);
    last.resize(n);
    for (int i = 0; i < n; ++i) {
      last[i] = i;
    }
  }

public:
  UF() {}
  UF(int n) {
    init(n);
  }
  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y); // data[x] and data[y] are negative.
    data[x] += data[y];
    data[y] = x;
    next[last[x]] = y;
    last[x] = last[y];
    return true;
  }
  int size(int x) {
    return -data[root(x)];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int get_next(int x) {
    return next[x];
  }
};

int main() {
  ll n, d;
  scan(n, d);
  vll a(n);
  scan(a);
  vi lowest_left(n, 0);
  FOR (i, 1, n) {
    ll cur_cost = a[lowest_left[i-1]] + d * (i - lowest_left[i-1]);
    ll new_cost = a[i];
    if (cur_cost < new_cost) {
      lowest_left[i] = lowest_left[i-1];
    } else {
      lowest_left[i] = i;
    }
  }
  vi lowest_right(n, n-1);
  for (int i = n-2; i >= 0; --i) {
    ll cur_cost = a[lowest_right[i+1]] + d * (lowest_right[i+1] - i);
    ll new_cost = a[i];
    if (cur_cost < new_cost) {
      lowest_right[i] = lowest_right[i+1];
    } else {
      lowest_right[i] = i;
    }
  }
  ll INF = LLONG_MAX / 2;
  vi nearest(n, -1);
  rep (i, n) {
    int left_node = -1;
    int right_node = -1;
    ll left_cost = INF;
    ll right_cost = INF;
    if (i != 0) {
      left_node = lowest_left[i-1];
      left_cost = a[i] + a[left_node] + d * (i - left_node);
    }
    if (i != n-1) {
      right_node = lowest_right[i+1];
      right_cost = a[i] + a[right_node] + d * (right_node - i);
    }
    if (left_cost < right_cost) {
      nearest[i] = left_node;
    } else {
      nearest[i] = right_node;
    }
  }
  vvll edges;
  rep (i, n) {
    int u = i;
    int v = nearest[i];
    assert(u != v);
    if (u > v) { swap(u, v); }
    ll cost = a[u] + a[v] + d * (v - u);
    edges.push_back({cost, u, v});
  }
  rep (i, n-1) {
    int u = nearest[i];
    int v = nearest[i+1];
    if (u == v) { continue; }
    if (u > v) { swap(u, v); }
    ll cost = a[u] + a[v] + d * (v - u);
    edges.push_back({cost, u, v});
  }
  vi cores;
  rep (i, n) {
    int u = i;
    int v = nearest[i];
    if (a[u] >= a[v]) {
      if (!cores.empty() && cores.back() == v) { continue; }
      cores.push_back(v);
    }
  }
  rep (i, (int)cores.size()-1) {
    int u = cores[i];
    int v = cores[i+1];
    assert(u != v);
    if (u > v) { swap(u, v); }
    ll cost = a[u] + a[v] + d * (v - u);
    edges.push_back({cost, u, v});
  }

  sort(all(edges));
  UF uf(n);
  ll ans = 0;
  for (auto && edge : edges) {
    if (uf.same(edge[1], edge[2])) { continue; }
    uf.unite(edge[1], edge[2]);
    ans += edge[0];
  }
  print(ans);

  return 0;
}

