template <typename T>
struct SegTree{
    vector<T> dat;
    int n;
    const T Default;
    SegTree(int n_, const T& def) : Default(def){init(n_);}
    void init(int n_){
        n = 1;
        while(n < n_) n *= 2;
        dat = vector<T>(2*n-1, Default);
    }
    T f(const T& a, const T& b) {
        return min(a, b);
    }
    void update(int k, const T& a){
        k += n-1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = f(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    T query(int a, int b, int k, int l, int r ){
        if(r <= a || b <= l) return Default;
        if(a <= l && r <= b) return dat[k];
        T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return f(vl, vr);
    }
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};
struct UFT{    //O(loga(n))
    int n;
    vi d, r;
    UFT(int n) : n(n), d(n, -1), r(n, 0){};
    int root(int i){
        if(d[i] < 0) return i;
        return d[i] = root(d[i]);
    }
    bool same(int x, int y){
        return root(x) == root(y);
    }
    bool unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y) return false;

        if(r[x] < r[y]) swap(x, y);
        else if(r[x] == r[y]) r[x]++;
        d[x] += d[y];
        d[y] = x;
        return true;
    }
    int size(int i){
        return -d[root(i)];
    }
};

int main(){
    ll n, d;
    cin >> n >> d;
    vl a(n);
    rep(i, n) cin >> a[i];
    vl x(n), y(n);
    rep(i, n) {
        x[i] = a[i] + i * d;
        y[i] = a[i] - i * d;
    }
    using P = pair<ll, ll>;
    SegTree<P> st(n+10, P(INF, INF));
    rep(i, n) st.update(i, P(y[i], i));

    UFT uf(n);

    ll ans = 0LL;
    int cnt = 0;
    using PP = pair<ll, P>;
    priority_queue<PP,vector<PP>,greater<PP> > q;
    REP(i, 1, n) {
        auto p = st.query(0, i);
        q.push(PP(x[i] + p.fi, P(i, p.se)));
    }
    while(!q.empty() && cnt < n-1) {
        auto p = q.top();
        q.pop();
        auto i = p.se.fi, j = p.se.se;
        auto cost = p.fi;
        if(cost == INF) break;
        if(!uf.same(i, j)) {
            ans += cost;
            cnt++;
            uf.unite(i, j);
        }
        {
            st.update(j, P(INF, j));
            auto tmp = st.query(0, i);
            q.push(PP(x[i] + tmp.fi, P(i, tmp.se)));
        }
    }
    cout << ans << endl;
    return 0;
}

