      graph[i].push_back(P(cost, pos));
      graph[pos].push_back(P(cost, i));
      //debug(i); debug(pos); debugln(cost);
    }
    if (i<n) {
      //debugln("B");
      ll tmp = B.getmax(n+1-i);
      int pos = mpb[tmp];
      //debug(i); debug(n+1-i); debugln(pos);
      ll cost = a[i] + a[pos] + abs(i-pos)*d;
      graph[i].push_back(P(cost, pos));
      graph[pos].push_back(P(cost, i));
      //debug(i); debug(pos); debugln(cost);
    }
  }

  priority_queue<P, vector<P>, greater<>> que;
  for(auto e: graph[1]) {
    que.push(e);
  }
  used[1] = true;
  ll ans = 0;
  while(que.size()) {
    P pa = que.top(); que.pop();
    ll cost = pa.first;
    int pos = pa.second;
    if (used[pos]) continue;
    used[pos] = true;
    //debug(pos); debugln(cost);
    ans += cost;
    for(auto e: graph[pos]) {
      if (used[e.second]) continue;
      que.push(e);
    }
  }

  cout << ans << endl;

}

