int main() {
	cin >> N >> D;
	A.resize(N);
	REP(i, N) scanf("%d", &A[i]);

	vector<int> ord(N);
	iota(ALL(ord), 0);

	sort(ALL(ord), [&](int x, int y) {
		return A[x] > A[y];
	});

	vector<ll3> edge;

	SegTree<pll> lseg(N, pll(longINF, -1));
	SegTree<pll> rseg(N, pll(longINF, -1));

	REP(i, N) lseg.update(i, pll(A[i] + (ll)i * D, i));
	REP(i, N) rseg.update(i, pll(A[i] - (ll)i * D, i));

	for (int idx : ord) {
		pll cur = lseg.query(idx + 1, N);
		if (~cur.se) edge.emplace_back(A[idx] - (ll)idx * D + cur.fi, idx, cur.se);
		cur = rseg.query(0, idx);
		if (~cur.se) edge.emplace_back(A[idx] + (ll)idx * D + cur.fi, idx, cur.se);
		lseg.set(idx, pll(longINF, -1));
		rseg.set(idx, pll(longINF, -1));
	}

	sort(ALL(edge));

	UnionFind uf(N);
	ll ans = 0;
	for (ll3 &cur : edge) {
		ll cost, x, y;
		tie(cost, x, y) = cur;
		if (uf.same(x, y)) continue;
		uf.unite(x, y);
