long long int rng(int a, int b) {
	if (a > b)return 0;
	long long int ret = im[b];
	if (a)ret -= im[a - 1];
	return ret;
}

long long int calc(int star) {
	long long int ans = 0;
	int nex1=star;
	int nex2=star;
	for (int i = 0; i < n; i++) {
		if (star == i) {
			if (i == n - 1)break;
			if (lef[n - 1] <= i) {
				ans += eval(i, n - 1);
				star = n - 1;
				nex1 = i;
				nex2 = n-1;
			}
			else {
				auto cost = eval(i, rig[i]);
				ans += cost;
				nex1 = i;
				nex2 = rig[i];
				star = nex2;
				continue;
			}
		}
		else {
			ans += min(eval(i, nex1), eval(i, nex2));
		}
	}
	return ans;
}

