void solve() {
    ll ans = 0;
    DSU dsu(n);
    while (1) {
        vi comp(n);
        bool all_same = 1;
        forn(i, n) {
            comp[i] = dsu.get(i);
            if (comp[i] != comp[0]) {
                all_same = 0;
            }
        }
        if (all_same) {
            break;
        }

        vector<pair<ll, int>> min_to(n, mp(INF, -1));

        // j < i
        {
            pair<ll, int> mn1(INF, -1);
            pair<ll, int> mn2(INF, -1);
            forn(i, n) {
                for (const auto& mn : {mn1, mn2}) {
                    if (mn.snd != -1 && mn.snd != comp[i]) {
                        ll cost = mn.fst + i * 1ll * d + a[i];
                        remin(min_to[i], mp(cost, mn.snd));
                    }
                }

                const pair<ll, int> cur(-i * 1ll * d + a[i], comp[i]);
                if (cur.snd == mn1.snd) {
                    remin(mn1, cur);
                } else if (cur.snd == mn2.snd) {
                    if (cur < mn1) {
                        mn2 = mn1;
                        mn1 = cur;
                    } else if (cur < mn2) {
                        mn2 = cur;
                    }
                } else if (cur < mn1) {
                    mn2 = mn1;
                    mn1 = cur;
                } else if (cur < mn2) {
                    mn2 = cur;
                }
            }
        }

        // i < j
        {
            pair<ll, int> mn1(INF, -1);
            pair<ll, int> mn2(INF, -1);
            ford(i, n) {
                for (const auto& mn : {mn1, mn2}) {
                    if (mn.snd != -1 && mn.snd != comp[i]) {
                        ll cost = mn.fst - i * 1ll * d + a[i];
                        remin(min_to[i], mp(cost, mn.snd));
                    }
                }

                const pair<ll, int> cur(i * 1ll * d + a[i], comp[i]);
                if (cur.snd == mn1.snd) {
                    remin(mn1, cur);
                } else if (cur.snd == mn2.snd) {
                    if (cur < mn1) {
                        mn2 = mn1;
                        mn1 = cur;
                    } else if (cur < mn2) {
                        mn2 = cur;
                    }
                } else if (cur < mn1) {
                    mn2 = mn1;
                    mn1 = cur;
                } else if (cur < mn2) {
                    mn2 = cur;
                }
            }
        }

        vector<pair<ll, int>> min_to_comp(n, mp(INF, -1));
        forn(i, n) {
            assert(min_to[i].fst < INF);
            remin(min_to_comp[comp[i]], min_to[i]);
        }

        forn(c, n) {
            if (min_to_comp[c].fst < INF) {
                int i = c;
                int j = min_to_comp[c].snd;
                if (dsu.unite(i, j)) {
                    ans += min_to_comp[c].fst;
                }
            }
        }
    }

    cout << ans << endl;
}

