    }
    rep(i, N-1) add_edge(N+i, N+i+1, D);
    dijkstra(N);
    ll ans = 0;
    rep(i, 2*N){
        for(auto &e: es[i]){
            int u = col[i], v = col[e.to];
            if(u < v){
                ans += A[u]+A[v]+D*abs(u-v);
            }
        }
    }
    cout << ans << endl;
}

