void solve(int l, int r){
	if(l==r) return;
	int m=(l+r)/2;
	vector<int> indl, indr;
	for(int i=l; i<=m; i++) indl.push_back(i);
	for(int i=m+1; i<=r; i++) indr.push_back(i);
	sort(indl.begin(), indl.end(), [&](int i, int j){ return a[i]-(ll)i*d<a[j]-(ll)j*d;});
	sort(indr.begin(), indr.end(), [&](int i, int j){ return a[i]+(ll)i*d<a[j]+(ll)j*d;});
	priority_queue<Pi, vector<Pi>, greater<Pi>> que;
	for(int i=0; i<indr.size(); i++){
		int x=indl[0], y=indr[i];
		que.push(Pi(a[x]+a[y]+(ll)(y-x)*d, P(0, i)));
	}
	for(int i=0; i<r-l; i++){
		Pi p=que.top(); que.pop();
		ll s=p.first; int i1=p.second.first, i2=p.second.second;
		e.push_back(Pi(s, P(indl[i1], indr[i2])));
		if(i1<(int)indl.size()-1){
			s-=(a[indl[i1]]-(ll)indl[i1]*d);
			i1++;
			s+=(a[indl[i1]]-(ll)indl[i1]*d);
			que.push(Pi(s, P(i1, i2)));
		}
	}
	solve(l, m);
	solve(m+1, r);
}
