const int mx = 252345;
const long long inf = 0x3f3f3f3f3f3f3f3f;

typedef pair<long long, int> E;

struct T {
  E seg[2 * mx];

  E query(int L, int R, int idx, int l, int r) {
    int mid = (l+r)/2, left = 2 * idx + 1, right = 2 * idx + 2;
    if(R < l || L > r) return E{inf, -1};
    if(L <= l && r <= R) return seg[idx];
    return min(query(L, R, left, l, mid), query(L, R, right, mid + 1, r));
  }

  void update(E V, int I, int idx, int l, int r) {
    int mid = (l+r)/2, left = 2 * idx + 1, right = 2 * idx + 2;
    if(l > I || r < I) return;
    if(l == r) {
      seg[idx] = V;
      return;
    }
    update(V, I, left, l, mid); update(V, I, right, mid + 1, r);
    seg[idx] = min(seg[left], seg[right]);
  }
} t1, t2;

int arr[mx];

int root(int x) {
  return x == arr[x] ? x : arr[x] = root(arr[x]);
}

void join(int a, int b) {
  a = root(a);
  b = root(b);
  if(a == b) return;
  arr[a] = b;
}

int U[mx], best[mx];;

long long f(int a, int b, int D) {
  return 1LL * abs(a-b) * D + U[a] + U[b];
}

vector<int> G[mx];

int main () {
  ios::sync_with_stdio(0);
  cin.tie(0);
  int n, m, D;
  cin >> n >> D;
  for (int i = 0; i < n; i++) {
    cin >> U[i];
  }
  long long ans = 0;
  int ntrees = n;
  iota(arr, arr+n, 0);
  ans = 0;
  for (int i = 0; i < n; i++) {
    t1.update(E{1LL * i * D + U[i], i}, i, 0, 0, n-1);
    t2.update(E{1LL * (n-1-i) * D + U[i], i}, i, 0, 0, n-1);
  }
  while (ntrees > 1) {
    memset(best, -1, sizeof best);

    for(int i = 0; i < n; i++) G[i].clear();
    for(int i = 0; i < n; i++) {
      G[root(i)].push_back(i);
    }

    for(int i = 0; i < n; i++) {
      for (auto a: G[i]) {
        t1.update({inf, a}, a, 0, 0, n-1);
        t2.update({inf, a}, a, 0, 0, n-1);
      }
      for (auto a: G[i]) {
        E r1 = t1.query(a+1, n-1, 0, 0, n-1);
        r1.x += -1LL*a*D + U[a];
        E r2 = t2.query(0, a-1, 0, 0, n-1);
        r2.x += -1LL*(n-1-a)*D + U[a];

        E r = min(r1, r2);
        int b = r.y;
        if(b == -1) continue;
        if (best[a] == -1 || f(a, best[a], D) > r.x) best[a] = b;
        if (best[b] == -1 || f(b, best[b], D) > r.x) best[b] = a;
      }
      for (auto a: G[i]) {
        t1.update(E{1LL * a * D + U[a], a}, a, 0, 0, n-1);
        t2.update(E{1LL * (n-1-a) * D + U[a], a}, a, 0, 0, n-1);
      }
    }
    for (int i = 0; i < n; i++) {
      if (~best[i]) {
        int a = root(i);
        int b = root(best[i]);
        if(a == b) continue;
        ans += f(a, best[i], D);
        join(a, b);
        ntrees--;
      }
    }
  }
  cout << ans << endl;
}

