struct SEGTREE{
	pair<LL,int> tree[N*2];
	LL a[N*2];
	void modify(int index,LL val){
		index+=N-1;
		tree[index]=II(val,index-N+1);
		index>>=1;
		while(index){
			tree[index]=min(tree[index<<1],tree[index<<1|1]);
			index>>=1;
		}
