	return fa[x]=root(fa[x]);
}
void merge(int u,int v){
	u=root(u);
	v=root(v);
	if(have[u].size()>have[v].size()){
		for(auto it:have[v]){
			have[u].PB(it);
		}
		fa[v]=u;
		have[v].clear();
	}
	else{
		for(auto it:have[u]){
			have[v].PB(it);
		}
		fa[u]=v;
		have[u].clear();
	}
}
