LL MST(){
	priority_queue<pair<LL,int>,vector<pair<LL,int> > ,greater<pair<LL,int> > > q;
	q.push(II(0ll,1));
	LL rest=0;
	while(!q.empty()){
		pair<LL,int> now=q.top();
		if(vis[now.SEC]){
			q.pop();
			continue;
		}
		q.pop();
		rest+=now.FIR;
		vis[now.SEC]=1;
		for(auto it:g[now.SEC]){
			q.push(II(cost(it,now.SEC),it));
		}
	}
	return rest; 
}
