template<typename T, typename F> T boruvka(int n, F f) {    vector<int> rev(n), belong(n);    unionfind uf(n);    T ret = T();    while (uf.size(0) != n) {        int ptr = 0;        rep(i, n) {            if (uf.root(i) == i) {                belong[i] = ptr++;                rev[belong[i]] = i;            }        }        for (int i = 0; i < n; i++) {            belong[i] = belong[uf.root(i)];        }        auto v = f(ptr, belong);        bool update = false;        for (int i = 0; i < ptr; i++) {            if (~v[i].second && uf.unite(rev[i], rev[v[i].second])) {                ret += v[i].first;                update = true;            }        }        if (!update) return -1;    }    return ret;}
//(左i,右j)のコストがfl(i) + fr(j)で表せる場合
/*@formatter:on*/
template<typename T> T boruvka(int n, const function<T(T)> fl,const  function<T(T)> fr) {
    auto f = [&](int gsz, const vi &bel) {        /*           cost  to   toはgroupのid*/        vp ret(gsz, {linf, -1});        /*自分と違うグル―プで最小の物を選ぶ*/        {
        vp mi{{linf, -1},/*自分とは違うものも選べるように2種類ある*/
              {linf, -1}};            /*コストを足し算の形で表現できるようにする*/            rep(i, n) {
            auto e = (mi[0].se == bel[i]) ? mi[1] : mi[0];
            e.fi += fr(i);/*iが右側 e.fiは最終的なコスト*/                chmi(ret[bel[i]], e);
            P now(fl(i), bel[i]);/*iを左側のコストとしてみなした時の置き方*/                if (mi[0].se == bel[i]) { chmi(mi[0], now); } elf (mi[1].se == bel[i]) { chmi(mi[1], now); } el { chmi(mi[1], now); }
            sort(mi);
        }
    }
        {            /*     cost  to*/            vp mi{{linf, -1},
                                                        {linf, -1}};            /*右から*/            rer(i, n - 1) {
                auto e = (mi[0].se == bel[i]) ? mi[1] : mi[0];
                e.fi += fl(i); /*iが左側*/                chmi(ret[bel[i]], e);
                P now(fr(i), bel[i]);/*iを右側のコストとしてみなした時の置き方*/                if (mi[0].se == bel[i]) { chmi(mi[0], now); } elf (mi[1].se == bel[i]) { chmi(mi[1], now); } el { chmi(mi[1], now); }
                sort(mi);
            }
        }
        return ret;
    };
    return boruvka<int>(n, f);
}/*@formatter:on*/
