						match[v] = PLL(cost(i, top[0]), top[0]);
				}
			}
			top[2] = i;
			sort(all(top), [&](int64 a, int64 b){
					if (a == -1) return false;
					if (b == -1) return true;
					return A[a]+a*D < A[b]+b*D;
				});
			if (uf.find(top[0]) == uf.find(top[1])) swap(top[1], top[2]);
		}
		for (auto x : match) {
			if(uf.unite(x.fs, x.sc.sc)){
				res += x.sc.fs;
				updated = 1;
			}
		}
	}
	REP(i, N){
		assert(uf.find(i) == uf.find(0));
	}
	return res;
}

