struct segment_tree {
	#define ls  (u << 1)
	#define rs  (u << 1 | 1)
	int fm[nsz + 5];
	num mn[nsz + 5];

	void inline up(int u) {
		mn[u] = min(mn[ls], mn[rs]);
		fm[u] = mn[ls] < mn[rs] ? fm[ls] : fm[rs];
	}

	void init(num a[], int u = 1, int l = 1, int r = n) {
		if (l == r) { mn[u] = a[l], fm[u] = l; return; }
		int md = (l + r) >> 1;
		init(a, ls, l, md);
		init(a, rs, md + 1, r);
		up(u);
	}

	void upd(int id, num w, int u = 1, int l = 1, int r = n) {
		if (l == r) { mn[u] = w; return; }
		int md = (l + r) >> 1;
		id <= md ? upd(id, w, ls, l, md) : upd(id, w, rs, md + 1, r);
		up(u);
	}

	pair<num, int> qry(int el, int er, int u = 1, int l = 1, int r = n) {
		// cerr << el << ' ' << er << ' ' << u << ' ' << l << ' ' << r << ": " << mn[u] << ' ' << fm[u] << ln;
		if (l >= el && r <= er)  return {mn[u], fm[u]};
		int md = (l + r) >> 1;
		pair<num, int> res = {inf, 0};
		if (el <= md)  res = qry(el, er, ls, l, md);
		if (er > md) {
			pair<num, int> tmp = qry(el, er, rs, md + 1, r);
			if (res.first > tmp.first)  res = tmp;
		}
		// cerr << "<- " << res.first << ' ' << res.second << ln;
		return res;
	}
};
segment_tree tr1, tr2;

struct union_find {
	int sz, pr[nsz + 5];

	int inline operator [] (int id) { return qry(id); }

	void inline init(int sz = n) {
		this->sz = sz;
		cont (u, n)  pr[u] = u;
	}

	int qry(int u) {
		return pr[u] == u ? u : pr[u] = qry(pr[u]);
	}

	bool inline link(int u, int v) {
		int pu = qry(u), pv = qry(v);
		if (pu == pv)  return 0;
		pr[pv] = pu;
		return 1;
	}
};
union_find uf;

num inline w(int u, int v) {
	if (u < v)  swap(u, v);
	return w1[u] + w2[v];
}

num inline kruskal(vector< pair<int, pair<int, int> > > &e = ::e) {
	int cnt = 0;
	num res = 0;
	uf.init();
	sort(all(e));
	loop (i, e.size()) {
		int u = e[i].second.first, v = e[i].second.second;
		num w = e[i].first;
		if (uf.link(u, v)) {
			res += w;
			if (++cnt == n - 1)  break;
		}
	}
	return res;
}

