int prim(const vector< vector<edge> >& G, int s)
{
   int sum = 0;
   vector<bool> used(G.size(), false);
   priority_queue<P<int,int>, vector<P<int,int>>, greater<P<int,int>> > que;
   que.push(make_pair(0, s));
   while (!que.empty()) {
      int cost = que.top().first;
      int from = que.top().second;
      que.pop();
      if (used[from]) continue;
      used[from] = true;
      sum += cost;
      for (int i = 0; i < G[from].size(); i++) {
         edge e = G[from][i];
         if (!used[e.to]) {
            que.push(make_pair(e.cost, e.to));
         }
      }
   }
   return sum;
}

signed main()
{
   int N, D; cin >> N >> D;
   V<int> A(N);
   for (int i = 0; i < N; i++) {
      cin >> A[i];
   }

   RMQ<P<int,int>> L(N, {INF,-1}, {INF,-1}), R(N, {INF,-1}, {INF,-1});
   for (int i = 0; i < N; i++) {
      L.update(i, {A[i] - D * i, i});
      R.update(i, {A[i] + D * i, i});
   }

   V<V<edge>> G(N);
   for (int i = 0; i < N; i++) {
      int l = L.query(0, i).second;
      if (l != -1) {
         int cost = (i-l) * D + A[i] + A[l];
         G[i].push_back({ l, cost });
         G[l].push_back({ i, cost });
      }
      int r = R.query(i+1, N).second;
      if (r != -1) {
         int cost = (r-i) * D + A[i] + A[r];
         G[i].push_back({ r, cost });
         G[r].push_back({ i, cost });
      }
   }

   int sum = prim(G, 0);
   cout << sum << endl;

   return 0;
}

