pair<ll, ll> find_min(ll x, ll dsum, ll id) {
    auto it = S.begin();
    while (it != S.end()) {
        if (mn[uf.root(it->second)] != *it) {
            it = S.erase(it);
            continue;
        }
        if (uf.findSet(id, it->second)) {
            ++it;
        } else {
            break;
        }
    }
    if (it == S.end()) return {INF, INF};
    return {it->first + dsum + A[x], it->second};
}

void init() {
    S.clear();
    mn.clear();
}

bool one_step(ll &ans) {
    init();
    vector<pair<ll, ll> > seq1, seq2;

    for (int i = 0; i < A.size(); i++) {
        auto r = find_min(i, i * D, i);
        seq1.push_back(r);
        add(i, A[i], i * D, i);
    }

    init();
    reverse(A.begin(), A.end());
    {
        for (int i = 0; i < A.size(); i++) {
            int id = A.size() - i - 1;
            auto r = find_min(i, i * D, id);
            seq2.emplace_back(r);
            add(i, A[i], i * D, id);
        }
        reverse(seq2.begin(), seq2.end());
    }
    reverse(A.begin(), A.end());

    bool upd = false;
    map<int, pair<ll, pair<ll, ll>>> minv;

    for (int i = 0; i < seq1.size(); i++) {
        auto p = min(seq1[i], seq2[i]);
        if (minv.count(uf.root(i)) == 0 || minv[uf.root(i)].first > p.first) {
            minv[uf.root(i)] = {p.first, {i, p.second}};
        }
    }
    for (auto &&p : minv) {
        if (p.second.first == INF) continue;
        if (uf.unionSet(p.second.second.first, p.second.second.second)) {
            ans += p.second.first;
            upd = true;
        }
    }
    return upd;
}

