long long int calc(int star) {
	long long int ans = 0;
	int nex1 = star;
	int nex2 = star;
	for (int i = 0; i < n; i++) {
		if (nex2 == i) {
			if (i == n - 1)break;
			if (lef[n - 1] <= i) {
				ans += eval(i, n - 1);
				nex1 = i;
				nex2 = n - 1;
			}
			else {
				auto cost = eval(i, rig[i]);
				ans += cost;
				nex1 = i;
				nex2 = rig[i];
				continue;
			}
		}
		else {
			ans += min(eval(i, nex1), eval(i, nex2));
		}
	}
	return ans;
}

