class Union_Find_Tree{
	public:
	vi p,r;
	Union_Find_Tree(int n){
		p=r=vi(n);
		for(int i=0;i<n;i++) p[i]=i;
	}
	int Par(int x){
		if(p[x]==x) return x;
		return p[x]=Par(p[x]);
	}
	bool Unite(int x,int y){
		x=Par(x);
		y=Par(y);
		if(x==y) return 0;
		if(r[x]<r[y]) p[x]=y;
		else{
			p[y]=x;
			if(r[x]==r[y]) r[x]++;
		}
		return 1;
	}
};

const P Inf={INF,INF};
ll n;
vl a,b;
vp dp[2];
vvp g;
vvi G;

void dfs(int v,int pre){
	vp c;
	c.push_back(Inf);
	c.push_back(Inf);
	for(auto p:g[v]){
		ll u=p.first,w=p.second;
		if(u!=pre){
			dfs(u,v);
			P p1=dp[0][u],p2=dp[1][u];
			c.push_back({p1.first+w,p1.second});
			c.push_back({p2.first+w,p2.second});
			c.push_back({a[u]+w,b[u]});
		}
	}
	sort(c.begin(),c.end());
	ll t=INF,I=0;
	for(auto p:c){
		ll tmp=p.second;
		if(tmp!=t||tmp==INF){
			t=tmp;
			dp[I++][v]=p;
		}
		if(I==2) break;
	}
}

void DFS(int v,int pre,ll d){
	if(pre>=0){
		vp c;
		c.push_back(dp[0][v]);
		c.push_back(dp[1][v]);
		c.push_back({dp[0][pre].first+d,dp[0][pre].second});
		c.push_back({dp[1][pre].first+d,dp[1][pre].second});
		c.push_back({d+a[pre],b[pre]});
		sort(c.begin(),c.end());
		ll t=INF,I=0;
		for(auto p:c){
			ll tmp=p.second;
			if(tmp!=t||tmp==INF){
				t=tmp;
				dp[I++][v]=p;
			}
			if(I==2) break;
		}
	}
	for(auto p:g[v]){
		ll u=p.first,w=p.second;
		if(u!=pre) DFS(u,v,w);
	}
}

