		g[i].push_back({i+1,d});
		g[i+1].push_back({i,d});
	}
	Union_Find_Tree uft(n);
	ll cnt=0,res=0;
	while(1){
		dp[0]=dp[1]=vp(n,Inf);
		vl c(n);
		for(int i=0;i<n;i++){
			b[i]=uft.Par(i);
			c[b[i]]=i;
		}
		dfs(0,-1);
		DFS(0,-1,0);
		map<ll,P> mp;
		for(int v=0;v<n;v++){
			P p=dp[0][v];
			if(p.second==b[v]) p=dp[1][v];
			if(mp.find(b[v])==mp.end()) mp[b[v]]=Inf;
			P pre=mp[b[v]];
			mp[b[v]]=min(pre,{p.first+a[v],p.second});
