#define MAXN 262144
struct E{ int f,t; ll c; };

int n;
ll a[MAXN], d;

vc<E> es;
ll f[MAXN], g[MAXN];
void Divideandconquer( int l , int r ){
	if( l == r ) return;
	int mid = l+r >> 1;
	Divideandconquer(l,mid);
	Divideandconquer(mid+1,r);

	ll minf = *min_element(f+l,f+mid+1);
	int minfpos;
	Forx(i,l,mid) minfpos = f[i]==minf ? i : minfpos;

	ll ming = *min_element(g+mid+1,g+r+1);
	int mingpos;
	Forx(i,mid+1,r) mingpos = g[i]==ming ? i : mingpos;

	Forx(i,mid+1,r) es.Pb({minfpos,i,minf+g[i]});
	Forx(i,l,mid) es.Pb({i,mingpos,f[i]+ming});
}

int dsu[MAXN];
void Init(){
	For(i,n) dsu[i] = i;
}
int Findfa( int pos ){ return dsu[pos]==pos ? pos : dsu[pos] = Findfa(dsu[pos]); }
bool Unite( int a , int b ){
	a = Findfa(a);
	b = Findfa(b);
	if( a == b ) return 0;
	dsu[a] = b;
	return 1;
}
ll Kruskal(){
	Init();
	ll ans = 0;
	for( auto ue : es ){
		if(Unite(ue.f,ue.t))
			ans += ue.c;
	}
	return ans;
}

int main(){
	FILEIO();

	Read(n);
	Read(d);
	For(i,n) Read(a[i]);

	For(i,n){
		f[i] = a[i] - i*d;
		g[i] = a[i] + i*d;
	}

	Divideandconquer(1,n);
	sort(All(es),[]( const E &a , const E &b ){ return a.c < b.c; });

	ll ans = Kruskal();
	cout << ans << endl;

	END();
}

