void init(p64 sg[]){
	while(siz<n) siz*=2;
	FOR(i,1,2*siz-1) sg[i]=mp(INF,1);
}
void update(int x,ll val,p64 sg[]){
	sg[x+siz-1]=mp(val,x); 
	x+=siz-1; x/=2;
	while(x!=0){
		sg[x]=min(sg[2*x],sg[2*x+1]);
		x/=2;
	}
}
p64 query(int l,int r,p64 sg[]){
	l+=siz-1;r+=siz-1;
	p64 ret=mp(INF,1);
	while(r>=l){
		if(l%2==1){
			ret=min(ret,sg[l++]);
		}
		if(r%2==0){
			ret=min(ret,sg[r--]);
		}
		l/=2;
		r/=2;
	}
	return ret;
}
