struct segtree{
  vector<pll> seg;
  segtree(){seg.assign(2*N-1, pll(INF,INF));}
  void set(int x, ll v){
    seg[x+N-1] = pll(v, x);
    x += N-1;
    while(x>0){
      x = (x-1)/2;
      seg[x] = min(seg[2*x+1], seg[2*x+2]);
    }
  }
  pll qmin(int l, int r, int a, int b, int k){
    if(r<=a || b<=l)return pll(INF,INF);
    if(l<=a && b<=r)return seg[k];
    int m = (a+b)/2;
    return min(qmin(l,r,a,m,2*k+1), qmin(l,r,m,b,2*k+2));
  }
  pll qmin(int l, int r){return qmin(l,r,0,N,0);}
};

