	rep(i, 2 * nn - 1)dat[i] = { INF,0 };
}
void update(int k, ll a) {
	k += nn - 1;
	dat[k] = { a,k - (nn - 1) };
	while (k > 0) {
		k = (k - 1) / 2;
		if (dat[k * 2 + 1].first < dat[k * 2 + 2].first) {
			dat[k] = dat[k * 2 + 1];
		}
		else dat[k] = dat[k * 2 + 2];
	}
}
LP query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return { INF,0 };
	if (a <= l && r <= b)return dat[k];
	else {
		LP vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		LP vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		if (vl.first < vr.first)return vl;
		else return vr;
	}
}
typedef pair<ll, P> speP;
//最小値と行先
priority_queue<speP,vector<speP>,greater<speP>> q;
ll ans;

int par[1<<18];
int rank1[1<<18];
void initt(int n) {
	for (int i = 0; i < n; i++) {
		par[i] = i;
		rank1[i] = 0;
	}
}
int find(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = find(par[x]);
	}
}
void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)return;
	if (rank1[x] < rank1[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (rank1[x] == rank1[y])rank1[x]++;
	}
}
bool same(int x, int y) {
	return find(x) == find(y);
}

int main() {
