			LP vr = query(fr + 1, n, 0, 0, nn);
			q.push({ vr.first + y[fr],{fr,vr.second} });
			continue;
		}
		ans += z.first;
		unite(fr, to);
		update(to, INF);
		LP vr = query(to + 1, n, 0, 0, nn);
		LP vl = query(fr + 1, n, 0, 0, nn);
		if (vl.first + y[fr] < vr.first + y[to]) {
			q.push({ vl.first+y[fr],{fr,vl.second} });
