					else e[++len].x=i,e[len].y=c2.k1,e[len].c=C2;
				}
				for(LL j=0;j<vec[i].size();j++)
				{
					LL y=vec[i][j];
					change(1,1,n,y,node(y*d+a[y],-y*d+a[y],y,y));
				}
			}
		sort(e+1,e+len+1,cmp);
		for(LL i=1;i<=len;i++)
		{
			LL tx=findfa(e[i].x),ty=findfa(e[i].y);
			if(tx!=ty)
			{
				ans+=e[i].c;
				fa[tx]=ty;num--;
			}
		}
	}
	printf("%lld",ans);
}

