	scanf("%d%d", &n, &d);
	cont (i, n) {
		scanf("%d", &a[i]);
		w1[i] = (num) a[i] + (num) d * i;
		w2[i] = (num) a[i] - (num) d * i;
	}
	graph_init();
	printf("%lld\n", kruskal());
}

