//インデックスは正の数のみ
__int128_t th=1000000000000000000;
inline __int128_t encode(ll a, ll b){
  __int128_t A = a, B = b;
  return th*th+A*th+B;
}
pair<ll, ll> decode(__int128_t a){
  ll B = a%th;
  a -= B;
  return make_pair((a-th*th)/th, B);
}

struct segtree{
  __int128_t M=1, INIT;
  __int128_t INF = encode(th, th);
  vector<__int128_t> dat;
  segtree(ll N, ll num){
    INIT = num;
    while(M<N) M*=2;
    dat.resize(M*2-1, encode(num, 0));
  }
  void update(ll x, ll k, ll l=0, ll r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k] = encode(x, k-(M-1));
    while(k>0) {
      k = (k-1)/2;
      dat[k] = min(dat[k*2+1], dat[k*2+2]);
    }
  }
  __int128_t query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return INF;
    if(a<=l && r<=b) return dat[k];
    __int128_t A = query(a, b, k*2+1, l, (l+r)/2);
    __int128_t B = query(a, b, k*2+2, (l+r)/2, r);
    return min(A, B);
  }
};

ll INF = 1000000000000000000;
segtree l(200001, INF), r(200001, INF);

typedef tuple<ll, ll> p;
int main(int argc, char const *argv[]) {
  ll n, D;scanf("%lld %lld", &n, &D);
  vector<ll> A(n+1, 0);
  for(int i=1;i<=n;i++) scanf("%lld",&A[i]);
  for(ll i=1;i<=n;i++){
    l.update(A[i]-D*i, i);
    r.update(A[i]+D*i, i);
  }
  if(n==1){
    std::cout << 0 << '\n';
    return 0;
  }
  vector<bool> use(n+1, 0);
  use[0] = 1;
  ll ans = 0;
  vvl dat = VV(n+1, 2, -1, ll);

  //1から始める
  //(コスト, src, dst, right/left)
  priority_queue<p, vector<p>, greater<p>> q;
  set<ll> area;//今全域木に含まれるインデックス
  q.push(p(0, 1));

  while(!q.empty()){
    p top = q.top();q.pop();
    ll dst = get<1>(top);
    if(dst<0||get<0>(top)>=INF||use[dst]) continue;
    //std::cout << dst << " " << get<0>(top) << '\n';

    use[dst] = 1;
    l.update(INF, dst);
    r.update(INF, dst);
    ans += get<0>(top);

    //右と左の更新
    auto itr = area.upper_bound(dst);
    ll L = 1, R = n;
    if(itr!=area.end()){
      ll id = (*itr);
      ll x = 0, y = n;
      while(y-x>1){
        ll mid = (x+y)/2;
        ll costA = A[dst] + D*abs(dst-mid);
        ll costB = A[id] + D*abs(id-mid);
        if(costB<costA) y = mid;
        else x = mid;
      }//y:=右の一番左端
      R = y-1;
      pair<ll, ll> tmp = decode(l.query(y, id));
      q.push(p(A[id]+D*id+tmp.first, tmp.second));
    }

    if(itr!=area.begin()){
      itr--;
      ll id = (*itr);
      ll x = 0, y = n;
      while(y-x>1){
        ll mid = (x+y)/2;
        ll costA = A[dst] + D*abs(dst-mid);
        ll costB = A[id] + D*abs(id-mid);
        if(costB<costA) x = mid;
        else y = mid;
      }//x:=左の一番右端
      L = x+1;
      pair<ll, ll> tmp = decode(r.query(id, y+1));
      q.push(p(A[id]-D*id+tmp.first, tmp.second));
    }

    //std::cout << dst << " " << get<0>(top) << '\n';
    if(R-L>0)area.insert(dst);
    pair<ll, ll> tmp = decode(l.query(L, dst));
    q.push(p(A[dst]+D*dst+tmp.first, tmp.second));
    tmp = decode(r.query(dst+1, R+1));
    q.push(p(A[dst]-D*dst+tmp.first, tmp.second));
  }


  std::cout << ans << '\n';
  return 0;
}

