};
struct UnionFind {
	int N;
	vector<int> siz;
	vector<int> par;
	vector<int> Rank;
	UnionFind(int n) : siz(n, 1), par(n), Rank(n, 0) {
		N = n;
		for (int i = 0; i < N; i++) par[i] = i;
	}
	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);
		}
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (Rank[x] < Rank[y]) {
			par[x] = y;
			siz[x] += siz[y];
			siz[y] = siz[x];
		}
		else {
			siz[y] += siz[x];
			siz[x] = siz[y];
			par[y] = x;
			if (Rank[x] == Rank[y]) Rank[x]++;
		}
	}
	bool same(int x, int y) { return find(x) == find(y); }
};
void solve() {
	int N; cin >> N;
	int D; cin >> D;
	vector<int>A(N);
	REP(i, N) {
		cin >> A[i];
	}
	vector<pii>v(N);
	REP(i, N) {
		v[i] = { A[i],i };
	}
	VSORT(v);
	vector<edge>es;
	auto f = [](pii a, pii b) {return min(a,b); };
	SegmentTree<pii>segL(N, { LINF,LINF }, f), segR(N, { LINF,LINF }, f);
	REP(i, N) {
		int idx = v[i].second;
		//DEBUG(idx);
		pii pl = segL.query(0, idx);
		if (pl.second != LINF) {
			//DEBUG(pl.second);
			es.push_back({ idx, pl.second, A[idx] + A[pl.second] + abs(idx - pl.second)*D });
		}
		pii pr = segR.query(idx + 1, N);
		if (pr.second != LINF) {
			int to = pr.second;
			//DEBUG(to);
			es.push_back({ idx,to,A[idx] + A[to] + abs(idx - to)*D });
		}
		segL.update(idx, { A[idx] - idx * D,idx });
		segR.update(idx, { A[idx] + idx * D,idx });
	}
	sort(all(es), [](edge &a, edge &b) {return a.cost < b.cost; });
	UnionFind uf(N);
	ll ans = 0;
	for (auto e : es) {
		//DEBUG(e.cost);
		if (!uf.same(e.from, e.to)) {
			ans += e.cost;
			uf.unite(e.from, e.to);
		}
	}
	print(ans);
}



