        //cout<<p.first.first<<" "<<p.first.second<<" "<<p.second<<endl;
        b.update(i,mp(inf,inf));
        c.update(i,mp(inf,inf));
        {
            ll P=p.second;
            auto it=seg.upper_bound(std::make_tuple(P,inf,inf));
            it--;
            ll X,Y,Z;
            std::tie(X,Y,Z)=*it;
            pii x=b.Query(X,P,0,0,-1),y=c.Query(P,Y+1,0,0,-1);
            x.first+=P*D+A[P];
            y.first-=P*D-A[P];
            //if(P==2) cout<<X<<" "<<Y<<" "<<i<<endl;
            if(x.first<=inf/2) mem.insert(mp(x,P));
            if(y.first<=inf/2) mem.insert(mp(y,P));
        }
        if(seen[i]) continue;
        ans+=p.first.first;
        //cout<<p.first.first<<" "<<p.first.second<<endl;
        seen[i]=1;
        auto it=seg.upper_bound(std::make_tuple(i,inf,inf));
        it--;
        ll left=i,right=N-1;
        std::set<std::tuple<ll,ll,ll>> era,ins;
        while(it!=seg.end()){
            ll X,Y,Z;
            std::tie(X,Y,Z)=*it;
            X=std::max(X,i);
            ll l=X-1,r=Y+1;
            while(l+1<r){
                ll mid=(r+l)/2;
                if(abs(mid-Z)*D+A[Z]>=abs(mid-i)*D+A[i]) l=mid;
                else r=mid;
            }
            if(l==Y){
                era.insert(*it);
                it++;
                continue;
            }
            right=l;
            pii x=b.Query(X,Z,0,0,-1),y=c.Query(Z,right,0,0,-1);
            x.first+=Z*D+A[Z];
            y.first-=Z*D-A[Z];
            if(x.first<=inf/2) mem.insert(mp(x,Z));
            if(y.first<=inf/2) mem.insert(mp(y,Z));
            era.insert(*it);
            ins.insert(std::make_tuple(right+1,Y,Z));
            break;
        }
        it=seg.upper_bound(std::make_tuple(i,inf,inf));
        it--;
        while(1){
            ll X,Y,Z;
            std::tie(X,Y,Z)=*it;
            Y=std::min(X,i);
            ll l=X-1,r=Y+1;
            while(l+1<r){
                ll mid=(r+l)/2;
                if(abs(mid-Z)*D+A[Z]>=abs(mid-i)*D+A[i]) r=mid;
                else l=mid;
            }
            if(r==X){
                era.insert(*it);
                if(it==seg.begin()){
                    left=r;
                    break;
                }
                it--;
                continue;
            }
            left=r;
            pii x=b.Query(left+1,Z,0,0,-1),y=c.Query(Z,Y+1,0,0,-1);
            x.first+=Z*D+A[Z];
            y.first-=Z*D-A[Z];
