inline int in()
{
    char c=getchar();
    int neg=1, x=0;
    while(!isdigit(c)) (c=='-')?neg=-1, c=getchar():c=getchar();
    while(isdigit(c)) x=(x<<3)+(x<<1)+(c^48), c=getchar();
    return neg*x;
}

const int MAX=2e5+5;

ll A[MAX], D, N, ret;
vector<pii> e;

namespace DSU
{
    int par[MAX];
    inline void init()
    {
        Forn(i, MAX-2)
            par[i]=i;
    }
    inline int find(int x)
    {
        return x==par[x]?x:par[x]=find(par[x]);
    }
    inline bool unite(int x, int y)
    {
        x=find(x), y=find(y);
        if(x==y)
            return false;
        par[x]=y;
        return true;
    }
}

inline void solve(int l, int r)
{
    if(l==r)
        return;
    int m=l+r>>1, pl=-1, pr=-1;
    ll mnl=1e18, mnr=1e18;
    for(int i=l; i<=m; i++)
    {
        ll vl=A[i]-1LL*D*i;
        if(mnl>vl)
            mnl=vl, pl=i;
    }
    for(int i=m+1; i<=r; i++)
    {
        ll vr=A[i]+1LL*D*i;
        if(mnr>vr)
            mnr=vr, pr=i;
    }
    for(int i=l; i<=m; i++)
    {
        ll vl=A[i]-1LL*D*i;
        e.pb(mp(vl+mnr, mp(i, pr)));
    }
    for(int i=m+1; i<=r; i++)
    {
        ll vr=A[i]+1LL*D*i;
        e.pb(mp(mnl+vr, mp(pl, i)));
    }
    solve(l, m);
    solve(m+1, r);
}

int main()
{
    DSU::init();
    N=in(), D=in();
    Forn(i, N)
        A[i]=in();
    solve(1, N);
    sort(all(e));/*
    foreach(it, e)
        cout<<it->f<<" "<<it->s.f<<" "<<it->s.s<<endl;*/
    foreach(it, e)
        ret+=DSU::unite(it->s.f, it->s.s)*it->f;
    printf("%lld\n", ret);
    return 0;
}

