/* SimpleSegTree(0-index) */

struct SimpleSegTree{
  typedef pair<ll,int> Type;
  int segn2;
  Type initVal;
  vector<Type> data;
  function<Type(Type, Type)> merge;

  SimpleSegTree(int n, Type initVal, function<Type(Type, Type)> merge):
    initVal(initVal), merge(merge)
  {
    for(segn2=1; segn2<n; segn2*=2);
    data.assign(segn2*2, initVal);
  }

  SimpleSegTree(int n): //RangeMinimunQuery
    SimpleSegTree(n, {LLINF, -1}, [](Type a, Type b){ return min(a, b); }) {}

  SimpleSegTree(int n, Type initVal): //RangeMinimunQuery
    SimpleSegTree(n, initVal, [](Type a, Type b){ return min(a, b); }) {}

  //get value [a,b)
  Type query(int a, int b, int l = 0, int r = -1, int k = 0){
    if(r == -1) r = segn2;
    if(a <= l && r <= b) return data[k];
    if(r <= a || b <= l) return initVal;
    return merge(query(a,b,l,(l+r)/2,k*2+1),query(a,b,(l+r)/2,r,k*2+2));
  }

  //set kth number x
  void set(int k, Type x){
    k += segn2-1;
    data[k] = x;
    while(k > 0){
      k = (k-1)/2;
      data[k] = merge(data[k*2+1], data[k*2+2]);
    }
  }
};



int main(){
  ll n, d, a[SIZE];

  scanf("%lld%lld\n", &n, &d);

  SimpleSegTree segL(n), segR(n);

  for(int i=0;i<n;i++){
    scanf("%lld", a+i);
    segL.set(i, {-i*d + a[i], i});
    segR.set(i, {i*d + a[i], i});
  }

  ll ans = 0;
  int m = 0;
  bool visited[SIZE] = {};
  priority_queue<pair<ll,pair<int,int> > > pq;

  auto next = [&](int pos) {
    auto x = segL.query(0, pos);
    auto y = segR.query(pos+1, n);
    if (x.first == LLINF && y.first == LLINF)
      return make_pair(LLINF, -1);

    x.first += pos * d + a[pos];
    y.first += -pos * d + a[pos];

    if (x.first < y.first) return x;
    else return y;
  };

  pq.push({0, {0, -1}});

  while(pq.size() && m < n){
    auto p = pq.top(); pq.pop();

    ll cost = -p.first;
    int now = p.second.first;
    int prev = p.second.second;

    if (visited[now]) {
      if (prev != -1){
        auto res = next(prev);
        if (res.first != LLINF)
          pq.push({-res.first, {res.second, prev}});
      }
      continue;
    }
    visited[now] = true;
    m++;

    segL.set(now, {LLINF, now});
    segR.set(now, {LLINF, now});

    if (prev != -1){
      auto res = next(prev);
      if (res.first != LLINF)
        pq.push({-res.first, {res.second, prev}});
    }

    ans += cost;

    auto res = next(now);
    if (res.first != LLINF)
      pq.push({-res.first, {res.second, now}});
  }

  cout << ans << endl;

  return 0;
}

