    P INFP = {1e18, -1};
    Segtree<P> stL(N, [](auto a, auto b){ return min(a, b); }, INFP);
    Segtree<P> stR(N, [](auto a, auto b){ return min(a, b); }, INFP);
    for(int i=0; i<N; i++){
