bool inline cmp(edge a, edge b) {
    return a.val < b.val;
}

int find_pr(int a) {
    return pr[a] == a ? a : pr[a] = find_pr(pr[a]);
}

void solve(int l, int r) {
    if (l == r)  return;
    int mid = (l + r) >> 1, pl = 0, pr = 0;
    num ml = 5e18, mr = 5e18;
    circ (i, l, mid) {
        num cur = w[i] - d * i;
        if (cur < ml) {
            pl = i;
            ml = cur;
        }
    }
    circ (i, mid + 1, r) {
        num cur = w[i] + d * i;
        if (cur < mr) {
            pr = i;
            mr = cur;
        }
    }
    circ (i, mid + 1, r) {
        dat.push_back(edge(pl, i, ml + w[i] + d * i));
    }
    circ (i, l, mid) {
        dat.push_back(edge(i, pr, mr + w[i] - d * i));
    }
    solve(l, mid);
    solve(mid + 1, r);
}

