void dfs(int64 l, int64 r){
	if(r-l == 1) return;
	int64 lmin = INF_LL, lidx = -1;
	int64 rmin = INF_LL, ridx = -1;
	int32 m = (l+r)/2;
	FOR(i, l, m){ if (lmin > A[i]-i*D) { lmin = A[i]-i*D; lidx = i; } }
	FOR(i, m, r){ if (rmin > A[i]+i*D) { rmin = A[i]+i*D; ridx = i; } }
	FOR(i, l, m){ e.emplace_back(i, ridx); ed.emplace_back(rmin+(A[i]-i*D));}
	FOR(i, m, r){ e.emplace_back(lidx, i); ed.emplace_back(lmin+(A[i]+i*D));}
	dfs(l, m); dfs(m, r);
}

int64 dis(int64 a, int64 b){
	return A[a]+A[b]+abs(a-b)*D;
}

int64 Boruvka(){
	UnionFind uf(N);
	int64 res = 0;
	bool updated = 1;
	while (updated) {
		updated = 0;
		map<int64, PLL> match; // match[v] := (dis(v, u), u)
		PLL top[2] = {PLL(-1, -1), PLL(-1, -1)}; // (idx, top of (idx) ) 
		REP(i, N){
			int32 v = uf.find(i);
			REP(j, 2){
				if (top[j].fs == -1) break;
				if (top[j].sc != v && (match.count(v) == 0 || match[v].fs > dis(top[j].fs, i))) {
					match[v] = PLL(dis(top[j].fs, i), top[j].fs);
					break;
				}
			}
			REP(j, 2){
				if (top[j].fs == -1 || A[top[j].fs]-D*top[j].fs > A[i]-i*D) {
					if (j == 0 && top[j].sc != v) { top[1] = top[0]; }
					top[j] = PLL(i, v);
					break;
				}
			}
		}
		top[0] = PLL(-1, -1); top[1] = PLL(-1, -1);
		for(int32 i = N-1; i >= 0; i--){
			int32 v = uf.find(i);
			REP(j, 2){
				if (top[j].fs == -1) break;
				if (top[j].sc != v && (match.count(v) == 0 || match[v].fs > dis(top[j].fs, i))) {
					match[v] = PLL(dis(top[j].fs, i), top[j].fs);
					break;
				}
			}
			REP(j, 2){
				if (top[j].fs == -1 || A[top[j].fs]+D*top[j].fs > A[i]+i*D) {
					if (j == 0 && top[j].sc != v) { top[1] = top[0]; }
					top[j] = PLL(i, v);
					break;
				}
			}
		}
		for (auto x : match) {
			if(uf.unite(x.fs, x.sc.sc)) res += x.sc.fs;
			updated = 1;
		}
	}
	REP(i, N){
		assert(uf.find(i) == uf.find(0));
	}
	return res;
}

