        input();
        left();
        right();
        UnionFind uf(N);

        sort(all(edges), [](edge a, edge b) {
            return a.w < b.w;
        });

        ll ans = 0ll;
        for (auto e : edges) {
            if (!uf.same(e.a, e.b)) {
                uf.unite(e.a, e.b);
                ans += e.w;
            }
        }

        cout << ans << endl;


    }
};


