using namespace std;

struct edge {
    int u, v;
    num val;
    edge() {}
    edge(int u, int v, num val) {
        this->u = u;
        this->v = v;
        this->val = val;
    }
};

int n, d, w[200005], pr[200005];
num ans;
vector<edge> dat;

bool cmp(edge a, edge b) {
    return a.val < b.val;
}

int find_pr(int a) {
    return pr[a] == a ? a : pr[a] = find_pr(pr[a]);
}

void solve(int l, int r) {
    if (l == r)  return;
    int mid = (l + r) >> 1, pl = 0, pr = 0;
    num ml = 5e18, mr = 5e18;
    circ (i, l, mid) {
        int cur = w[i] - d * i;
        if (cur < ml) {
            pl = i;
            ml = cur;
        }
    }
    circ (i, mid + 1, r) {
        int cur = w[i] + d * i;
        if (cur < mr) {
            pr = i;
            mr = cur;
        }
    }
    circ (i, mid + 1, r) {
        dat.push_back(edge(pl, i, ml + w[i] + d * i));
    }
    circ (i, l, mid) {
        dat.push_back(edge(i, pr, mr + w[i] - d * i));
    }
    solve(l, mid);
    solve(mid + 1, r);
}

