        int u = dat[i].u, v = dat[i].v, pu = find_pr(u), pv = find_pr(v);
        num val = dat[i].val;
        if (pu == pv)  continue;
        pr[pv] = pu;
        ans += val;
    }
    cout << ans << endl;
}

