  int to;
  T cost;
};

template <typename T>
bool comp(const edge<T> &a, const edge<T> &b){
  return a.cost < b.cost;
}

template <typename T>
struct Graph {
  int n;
  vector<edge<T>> es;
  Graph(int n_){
    n = n_;
  }
  void adde(int from, int to, T cost){
    es.push_back((edge<T>){from, to, cost});
  }
  T kruskal(){
    T res = 0;
    UnionFind uf(n);
    sort(es.begin(), es.end(), comp<T>);
    for(auto e: es){
      int from = e.from;
      int to = e.to;
      T cost = e.cost;
      if(uf.same(from, to))continue;
      res += cost;
      uf.unite(from, to);
    }

    return res;
  }
};

