    }
    seg.update(i, mk( - (i + 1) * d + a[i], i));
  }
  seg = SegmentTree<Pll, Pll>(n, [](Pll a, Pll b){return a.first < b.first ? a: b;},
      [](Pll a,Pll b){return b;}, mk(linf, -1), vector<Pll>());
  rrep(i, n){
    if(i < n - 1){
      auto p = seg.query(i + 1, n);
      graph.adde(i, p.SE, (p.SE - i) * d + a[i] + a[p.SE]);
      graph.adde(p.SE, i, (p.SE - i) * d + a[i] + a[p.SE]);
