void make_seg(SegmentTree<t2> &seg, const V<ll> &alist, ll n, ll d)
{
    rep (i, n) seg.update(i, t2(i * d + alist[i], i));
    debug_printf("------------- seg\n");
    rep (i, n) { debug_printf("i=%lld ", i); debug_print(seg.query(i, i+1LL)); }
}

int _main()
{
    ll n; llin(n);
    ll d; llin(d);
    V<ll> alist; llina(alist, n);

    V<ll> alist_rev = alist;
    reverse(ALL(alist_rev));

    SegmentTree<t2> seg(n, t2(1e18, -1LL), mint2);
    make_seg(seg, alist, n, d);

    SegmentTree<t2> seg_rev(n, t2(1e18, -1LL), mint2);
    make_seg(seg_rev, alist_rev, n, d);

    set<t3> linkset;

    rep (aidx, n) {
        ll right_aidx = get<1>(seg.query(aidx + 1LL, n));
        if (right_aidx >= 0LL) {
            ll cost = abs(aidx - right_aidx) * d + alist[aidx] + alist[right_aidx];
            linkset.insert(t3(cost, aidx, right_aidx));
        }
        ll left_aidx = get<1>(seg_rev.query(n - aidx, n));
        if (left_aidx >= 0LL) {
            left_aidx = n - left_aidx - 1LL;
            ll cost = abs(aidx - left_aidx) * d + alist[aidx] + alist[left_aidx];
            linkset.insert(t3(cost, aidx, left_aidx));
        }
    }

    debug_printf("---- linkset\n"); debug_print(linkset);

    UnionFind uf(n);
    ll cnt = 0LL;
    ll ans = 0LL;

    for (auto link : linkset) {
        ll cost = get<0>(link);
        ll idx1 = get<1>(link);
        ll idx2 = get<2>(link);
        if (uf.root(idx1) != uf.root(idx2)) {
            uf.unite(idx1, idx2);
            cnt++;
            ans += cost;
        }
        if (cnt >= n - 1LL) {
            break;
        }
    }

    cout << ans << endl;

    return 0;
}

