inline void dfs(int l,int r){
	if(l+1==r)return;
	int mid=(l+r)/2;
	pair<long long int,int> lef={LLONG_MAX,-1};
	for(int i=l;i<mid;i++){
		lef=min(lef,make_pair((long long int)(mid-i)*d+v[i],i));
	}
	pair<long long int,int> rig={LLONG_MAX,-1};
	for(int i=mid;i<r;i++){
		rig=min(rig,make_pair((long long int)(i-mid)*d+v[i],i));
	}
	for(int i=l;i<mid;i++){
		add_edge(i,rig.second);
	}
	for(int i=mid;i<r;i++){
		add_edge(lef.second,i);
	}
	dfs(l,mid);
	dfs(mid,r);
}
struct UF{
	vector<int> belong;
	vector<int> size;
	void resize(int n){
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
	}
	inline int root(int b){
		if (belong[b] == -1){
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b){
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
	}
};
