/*
完全グラフが与えられるので、それに対する最小全域木を求める.
最小全域木となる辺の候補数を減らしてあげたい.
分割統治を用いて辺の候補をNlogNくらいに減らす.
参考記事
http://drken1215.hatenablog.com/entry/2019/01/15/081500
*/

#include <bits/stdc++.h>
#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;
typedef pair<ll, ll> pll;

template<typename T, typename E> class SegmentTree {
public:
  typedef function<T (T, T)> Operator;
  typedef function<T (T, E)> Apply;

  vector<T> data;
  ll n;
  T e;
  Operator op;
  Apply apply;

  SegmentTree(ll _n, T e, Operator op, Apply apply): e(e), op(op), apply(apply) {
    for(n = 1; n < _n; n *= 2);
    data.resize(n * 2 - 1, e);
  }

  T query(ll a, ll b) { return query(a, b, 0, 0, n); }
  T query(ll a, ll b, ll k, ll l, ll r) {
    if(r <= a || b <= l) return e;
    if(a <= l && r <= b) return data[k];
    T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return op(vl, vr);
  }

  void update(ll k, E x) {
    k += n - 1;
    data[k] = apply(data[k], x);
    while(k > 0) {
      k = (k - 1) / 2;
      data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
    }
  }
};

class UnionFind {
private:
  vector<ll> data;

public:
  UnionFind(ll n): data(n, -1) {}

  ll size(ll i) { return -data[find(i)]; }
  bool root(ll i) { return data[i] < 0; }
  bool same(ll i, ll j) { return find(i) == find(j); }

  ll find(ll i) { return root(i) ? i : (data[i] = find(data[i])); }

  bool unite(ll i, ll j) {
    if(same(i, j)) return false;
    data[find(i)] += data[find(j)];
    data[find(j)] = find(i);
    return true;
  }
};

int main(void) {
  ll N, D;
  cin >> N >> D;
  vector<ll> A(N);
  REP(i, 0, N) cin >> A[i];

  vector<ll> ord(N);
  REP(i, 0, N) ord[i] = i;
  sort(ord.begin(), ord.end(), [&](ll i, ll j) { return A[i] < A[j]; });

  const ll INF = 1LL << 60;
  SegmentTree<pll, pll>::Operator op = [](pll a, pll b) { return min(a, b); };
  SegmentTree<pll, pll>::Apply apply = [](pll a, pll x) { return x; };
  SegmentTree<pll, pll> stl(N, make_pair(INF, INF), op, apply);
  SegmentTree<pll, pll> str(N, make_pair(INF, INF), op, apply);

  struct edge { ll d, u, v; };
  vector<edge> edges;
  for (ll v : ord) {
    pll l = stl.query(0, v);
    if (l.first < INF) {
      ll d = l.first + A[v] + v * D;
      ll u = l.second;
      edges.push_back({ d, u, v });
    }
    stl.update(v, make_pair(A[v] - v * D, v));

    pll r = str.query(v + 1, N);
    if (r.first < INF) {
      ll d = r.first + A[v] - v * D;
      ll u = r.second;
      edges.push_back({ d, u, v });
    }
    str.update(v, make_pair(A[v] + v * D, v));
  }

  sort(edges.begin(), edges.end(), [](edge x, edge y) { return x.d < y.d; });

  UnionFind uf(N);
  ll ans = 0;
  for (edge e : edges) if (uf.unite(e.u, e.v)) ans += e.d;
  cout << ans << endl;
}

