#define fastIO ios::sync_with_stdio(false);cin.tie(0);cout.tie(0);

const int N = (int)2e5 + 9;
int par[N];
ll a[N];

int fin(int x){ 
  if(par[x] == x) return x;
  return par[x]=fin(par[x]);
}

bool unite(int a, int b){ 
  a=fin(a);
  b=fin(b);
  if(a == b) return false;
  if(rand()%2) par[a]=b;
  else par[b]=a;
  return true;
}

struct Edge{
  int ai;
  int bi;
  ll wi;
  bool operator<( const Edge &T) const {
    return wi < T.wi;
  }
};

int main(){
  fastIO;
  ll d;
  int n;
  cin >> n >> d;
  for(int i = 1; i <= n; i ++ ){
    cin >> a[i];
    par[i] = i;
  }
  pii best = mp(a[1] - d, 1);
  vector<Edge> shit;
  for(int i = 2 ; i <= n; i ++ ){
    shit.push_back({best.se,i,a[i] + i * 1ll * d + best.fi});
    best = min(best, mp(a[i] - i * 1ll * d,i));
  }
  best = mp(a[n] + n * 1ll * d, n);
  for(int i = n - 1; i >= 1; i -- ){
    shit.push_back({best.se,i,a[i] - i * 1ll * d + best.fi});
    best = min(best, mp(a[i] + i * 1ll * d,i));
  }
  sort(shit.begin(), shit.end());
  ll ans = 0;
  for(auto p : shit){
    ans += p.wi * unite(p.ai, p.bi);
  }
  cout << ans << "\n";
  return 0;
}

