{
	int u,v;
	ll cst;
	Edge(){}
	Edge(int u,int v,ll cst):u(u),v(v),cst(cst){}
	bool operator < (const Edge &t)const
	{
		return cst<t.cst;
	}
};
vector<Edge> edge;
void solve(int l,int r)
{
	if(l==r)return;
	int mid=(l+r)>>1;

	int v1=0;
	ll mn=inf;
	for(int i=l;i<=mid;i++)
	{
		ll vl=A[i]-D*i;
		if(vl<mn)
		{
			mn=vl;
			v1=i;
		}
	}

	int v2=0;
	mn=inf;

	for(int i=mid+1;i<=r;i++)
	{
		ll vl=A[i]+D*i;
		if(vl<mn)
		{
			mn=vl;
			v2=i;
		}
	}

	for(int i=l;i<=mid;i++)
	{
	//	cout<<(A[v2]+A[i]+D*(v2-i))<<" "<<v2<<" "<<i<<endl;
		edge.push_back(Edge(v2,i,A[v2]+A[i]+D*(v2-i)));
