DSU<200005> dsu;
int n,d;
int a[200005];
vector<pair3<ll>> egs;

void solve(int l,int r){
	if(l==r){
		return;
	}
	int m=(l+r)>>1;
	int ml=-1,mr=-1;
	ll mn=INF;
	circ(i,l,m){
		ll val=a[i]-1ll*d*i;
		if(val<mn){
			mn=val;
			ml=i;
		}
	}
	mn=INF;
	circ(i,m+1,r){
		ll val=a[i]+1ll*d*i;
		if(val<mn){
			mn=val;
			mr=i;
		}
	}
	circ(i,l,m){
		egs.pub(mak3(a[i]+a[mr]+1ll*(mr-i)*d,i,mr));
	}
	circ(i,m+1,r){
		egs.pub(mak3(a[ml]+a[i]+1ll*(i-ml)*d,ml,i));
	}
	solve(l,m);
	solve(m+1,r);
}

