typedef long long ll;
typedef pair<ll,int> P;

class segtree{
public:
    static const int N=1<<19;
    P dp[1<<20];
    segtree(){
        for(int i=N-1;i<N*2;i++){
            dp[i]=P(INF,i-(N-1));
        }
        for(int i=N-2;i>=0;i--){
            dp[i]=min(dp[i*2+1],dp[i*2+2]);
        }
    }
    void update(int k,int v){
        k+=N-1;
        dp[k].first=v;
        while(k>0){
            k=(k-1)/2;
            dp[k]=min(dp[k*2+1],dp[k*2+2]);
        }
    }

    P query(int a,int b,int k=0,int l=0,int r=N){
        if(b<=l || r<=a)return P(INF,-1);
        if(a<=l && r<=b)return dp[k];
        int mid=(l+r)/2;
        P vl=query(a,b,k*2+1,l,mid);
        P vr=query(a,b,k*2+2,mid,r);
        return min(vl,vr);
    }
};

