void gen(int l, int r)
{
	int mid=(l+r)>>1;
	int mnl=l; int mnr=r;
	for(int i=l;i<=mid;i++)
	{
		if(a[i]<a[mnl]) mnl=i;
	}
	for(int i=mid+1;i<=r;i++)
	{
		if(a[i]<a[mnr]) mnr=i;
	}
	for(int i=l;i<=mid;i++) G.addedge(i,mnr,a[mnr]+a[i]+abs(i-mnr)*d);
	for(int i=mid+1;i<=r;i++) G.addedge(i,mnl,a[mnl]+a[i]+abs(i-mnl)*d);
	if(l==r) return ;
	gen(l,mid); gen(mid+1,r);
}

