//Big Range Query
//セグメント木 pll(x, y) = pll(値, 要素番号)
//インデックス取得したい場合: get_m**_with_idx()を使う
class SegmentTree{
public:
	int n = 1;
	vector<pll> seg[2];		//0:最大	1:最小
	void init(int N){		//N要素のセグメントツリー作成
		while(n < N)n *= 2;
		rep(i,2)seg[i].resize(2*n);
		fill(ALL(seg[0]), pll(-INF, -1));
		fill(ALL(seg[1]), pll(INF, -1));
	}
	pll cmp_min(pll x, pll y){		//比較関数
		if(x.first == y.first)return x.second < y.second ? x : y;
		return min(x, y);
	}
	pll cmp_max(pll x, pll y){		//比較関数
		if(x.first == y.first)return x.second < y.second ? x : y;
		return max(x, y);
	}
	void update(ll k, ll x, bool flag=false){		//idx:kの値をxに変更
		k += n-1;
		seg[0][k] = seg[1][k] = pll(x, k-(n-1));
		if(flag){seg[0][k] = pll(-INF, -1);seg[1][k] = pll(INF, -1);}
		while(k > 0){
			k = (k-1)/2;
			seg[0][k] = cmp_max(seg[0][k*2+1], seg[0][k*2+2]);
			seg[1][k] = cmp_min(seg[1][k*2+1], seg[1][k*2+2]);
		}
	}
	pll calc(ll a, ll b, ll k, ll l, ll r, ll f){
		if(b <= l || r <= a)return f ? pll(INF, -1) : pll(-INF, -1);
		if(a <= l && r <= b)return seg[f][k];
		pll vl = calc(a, b, k*2+1, l, (l+r)/2, f);
		pll vr = calc(a, b, k*2+2, (l+r)/2, r, f);
		return f ? cmp_min(vl, vr) : cmp_max(vl, vr);
	}
	void erase(ll k){update(k, -1, true);} //要素を削除（実際にはINF, -INFにする）
  //最大値・最小値のみ取得
	ll get_max(ll a, ll b){return calc(a, b, 0, 0, n, 0).first;}
	ll get_min(ll a, ll b){return calc(a, b, 0, 0, n, 1).first;}
  //インデックスも取得（pll<最大値, 最大値のidx>）を返す
  pll get_max_with_idx(ll a, ll b){return calc(a, b, 0, 0, n, 0);}
	pll get_min_with_idx(ll a, ll b){return calc(a, b, 0, 0, n, 1);}
};


int main() {
  ll N, D;
  cin >> N >> D;

  //1. Asに[a:都市の規模, i:idx]を格納
  vector<pll> As(N); // (ll 規模, ll idx)
  rep(i,N){
    cin >> As.at(i).first;
    As.at(i).second = i;
  }

  //2. 規模降順にソート
  sort(ALL(As), greater<pll>()); //降順

  // check
  for (pll a: As){
    cout << a.first << ' ' << a.second << endl;
  }

  //3. SegTreeを2つ作り、それぞれにコストを入れる（segtreeのidxがAsにおけるidxとなるようにする）
  SegmentTree seg_left;
  seg_left.init(N);
  SegmentTree seg_right;
  seg_right.init(N);


  for (pll a: As){
    seg_left.update((N - 1 - i) * D + a.second, a.first);
    seg_right.update(i * D + a.second, a.first);
  }
 // cout << seg_left.get_min_with_idx(1,3).first << ' ' << seg_left.get_min_with_idx(1,3).second << endl;
 // cout << seg_left.get_max_with_idx(2,6).first << ' ' << seg_left.get_max_with_idx(2,6).second << endl;


  //ここからの流れ
  //4. それを使って、規模降順forで左右領域の「[l, r)における最もコストの低い接続先都市」をピックアップする
  //  --> ピックアップしたら、priority_queue(edge_candidates)に[idx, adjidx]を入れていく

  for (pll a : As){
    if (a.second == 0){
      tie(ll rightmin, ll rminidx) = seg_right.get_min_with_idx(1, N);
    }
    else if (a.second == N-1){
      tie(ll leftmin, ll lminidx) = seg_left.get_min_with_idx(0, a.second);
    }
    else{
      tie(ll leftmin, ll lminidx) = seg_left.get_min_with_idx(0, a.second);
      tie(ll rightmin, ll rminidx) = seg_right.get_min_with_idx(a.second + 1, N);
    }
    seg_left.erase(a.second);
    seg_right.erase(a.second);
  }

  //5. 1つずつtop()->pop()して、Uniteする（Uniteできたらans+=コスト, できなかったら無視）
  //6. できあがり！





}

