        for (int i = N - 2; i >= 0; --i) {
            val += D;
//            ret[i] = key;
            edges.push_back(edge{key, i, val + A[i]});
            if (A[i] <= val) {
                val = A[i];
                key = i;
            }
        }
    }

    void right() {
        int key = 0;
        ll val = A[0];
        for (int i = 1; i < N; ++i) {
            val += D;
//            edges.emplace_back(key, i, val + A[i]);
            edges.push_back(edge{key, i, val + A[i]});
            if (A[i] <= val) {
                val = A[i];
                key = i;
            }

        }
    }

    void solve() {
        input();
        left();
        right();
        UnionFind uf(N);

        sort(all(edges), [](edge a, edge b) {
            return a.w < b.w;
        });

        ll ans = 0ll;
        int cnt = 0;
        for (auto e : edges) {
            if (!uf.same(e.a, e.b)) {
                uf.unite(e.a, e.b);
                ans += e.w;
                cnt++;
            }
        }

//        assert(cnt == N - 1);
        if (cnt != N - 1) exit(-1);

        cout << ans << endl;


    }
};


