void gao(int l,int r)
{
	if(l==r) return;
	int mid = (l+r)>>1;

	pli lmn = lval[l];
	for(int i=l; i<=mid; ++i)
		lmn = min(lmn, lval[i]);
	pli rmn = rval[r];
	for(int i=mid+1; i<=r; ++i)
