struct UF{
  vector<int> par,sizes;
  int cnt;
  UF(int N) : par(N),sizes(N, 1),cnt(N){ for(int i=0; i<N; i++) par[i]=i; }

  int find(int x){ return par[x]==x ? x : par[x] = find(par[x]); }

  bool same(int x,int y){ return find(x) == find(y); }

  int size(int x){ return sizes[find(x)]; }

  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(sizes[x] < sizes[y]) swap(x,y);
    par[y] = x;
    sizes[x] += sizes[y];
    cnt--;
  }

  int count() const{return cnt;}
};

template<typename T>
T kruskal(int N,Edges<T> &es){
  sort(begin(es) , end(es) , [&](edge<T> a,edge<T> b){
    return a.cost < b.cost;
  });
  UF uf(N);
  T ret = 0;
  for(edge<T> &e : es){
    if(uf.same(e.src , e.to)) continue;
    ret += e.cost;
    uf.unite(e.src , e.to);
  }
  return ret;
}

// セグ木
template<typename T,typename F>
struct ST{

  int size;
  vector<T> seg;
  const F func;
  const T UNIT;

  ST(int N,F func , T UNIT): func(func) , UNIT(UNIT) {
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
  }

  ST(const vector<T> &v,F func , T UNIT) : func(func) , UNIT(UNIT){
    // initialize
    int N = (int)v.size();
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size , UNIT);
    // set
    for(int i = 0; i < N; i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k, T x){
    seg[k + size] = x;
  }

  void build(){
    for(int k = size-1; k > 0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void update(int k, T x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func( seg[2 * k] , seg[2 * k + 1] );
    }
  }

  void add(int k , T x){
    k += size; seg[k] += x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1] );
    }
  }

  // 半開区間[a,b)へのクエリ
  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};
auto f = [&](P a,P b){return a.first <= b.first ? a : b;};
using SEG = ST<P,decltype(f)>;

void solve(){
  inl(N,D);
  vl A(N); in(A);
  SEG left(N + 1 , f , P(infLL , -1)) , right(N + 1 , f , P(infLL , -1));

  auto mkord = [&](int n , auto f) -> vector<int>{
    vector<int> ord(n);
    iota(begin(ord) , end(ord) , 0);
    sort(begin(ord) , end(ord) , f);
    return ord;
  };
  vector<int> ord = mkord(N , [&](int a,int b){return A[a]<A[b];});

  Edges<ll> es;

  // left A[i] - i * D
  // right A[i] + i * D
  auto upd = [&](ll i) -> void{
    left.update(i , P(A[i] - i * D , i));
    right.update(i, P(A[i] + i * D , i));
  };

  auto add = [&](ll i,ll j){
    ll c = D * abs(i - j) + A[i] + A[j];
    es.emplace_back(i , j , c);
  };

  each(i , ord){
    trc(i);
    // i番目が極小
    // 左側
    P l = left.query(0 , i);
    if(l.second >= 0) add(i , l.second);
    P r = right.query(i , N);
    if(r.second >= 0) add(i , r.second);
    upd(i);
  }

  each(x,es)trc(x.src,x.to,x.cost);
  out(kruskal(N , es));
}

