inline void update(node &v,LL a){
    chmin(v.a,a);
    if(v.is_leaf||v.y.y>v.a+v.y.b){
        v.y.y=v.a+v.y.b;
        v.y.id=v.y.bid;
    }
}

SetInitialLeaf<node>
set_leaf = [](node &v, const int id) {
    v.y.y=1e17;
    v.y.id = id;
	v.y.b = A[id%N];
    if(id<N)v.y.b+=D*(id%N);
    else v.y.b+=-D*(id%N);
    v.y.bid=id;
    v.a = 1e17;
    update(v,v.a);
};

SetInitialSegment<node>
set_segment = [](node &v, const int l, const int r) {
    v.a=1e17;
    v.is_leaf = (r-l==1);
};

