merge_segment = [](ret l, ret r) {
	ret x;
    if(l.y<r.y){
        x.id=l.id;
        x.y=l.y;
    }
    else{
        x.id=r.id;
        x.y=r.y;
    }
    if(l.b<r.b){
        x.bid=l.bid;
        x.b=l.b;
    }
    else{
        x.bid=r.bid;
        x.b=r.b;
    }
    return x;
};

