class union_find
{
private:
	std::vector<int>parent;
	std::vector<int>rank;
	std::vector<int>size;
public:
	union_find(int siz)
	{
		parent.resize(siz);
		rank.resize(siz);
		size.resize(siz);
		for (int i = 0; i < siz; ++i)
		{
			parent[i] = i;
			rank[i] = 0;
			size[i] = 1;
		}
	}
	void unite(int x, int y)
	{
		int xr = find(x);
		int yr = find(y);
		if (xr == yr) {
			return;
		}

		if (rank[xr] > rank[yr])
		{
			std::swap(xr, yr);
		}

		if (rank[xr] < rank[yr])
		{
		}
		else 
		{
			++rank[xr];
		}

		parent[yr] = xr;
		size[xr] += size[yr];
	}
	int find(int x)
	{
		if (parent[x] == x)
		{
			return x;
		}
		else
		{
			return parent[x] = find(parent[x]);
		}
	}
	bool is_same(int x, int y)
	{
		return find(x) == find(y);
	}
};


