    while(L.size()>=2&&check(L[L.size()-2],L[L.size()-1],line)) L.pop_back();
    L.emplace_back(line);    
  }

  T get(T x){
    if(L.empty()) return isMin?INF:-INF;
    ll low=-1,high=L.size()-1;
    while(low+1<high){
      ll mid=(low+high)>>1;
      if(getY(L[mid],x)>=getY(L[mid+1],x)) low=mid;
      else high=mid;
    }
    return (!isMin?-1:1)*getY(L[high],x);
  }
};

