struct edge {
    ll u, v;
    ll w;
    edge() {}
    edge(ll u, ll v, ll w) : u(u), v(v), w(w) {}
    bool operator<(const edge &other) const { return w < other.w; }
};
edge edges[200005*30];

void add(ll l, ll r) {
    if (l == r) return;
    ll mid = (l + r) >> 1;
    ll min = LLONG_MAX;
    ll pos = -1;
    for (ll i = l; i <= mid; i++) {
        ll f = a[i] - i * d;
        if (f < min) {
            min = f;
            pos = i;
        }
    }
    for (ll i = mid + 1; i <= r; i++) {
        edges[m++] = edge(pos, i, (i - pos) * d + a[i] + a[pos]);
    }
    min = LLONG_MAX;
    pos = -1;
    for (ll i = mid + 1; i <= r; i++) {
        ll f = a[i] + i * d;
        if (f < min) {
            min = f;
            pos = i;
        }
    }
    for (ll i = l; i <= mid; i++) {
        edges[m++] = edge(pos, i, a[pos] + a[i] + d * (pos - i));
    }
    add(l, mid);
    add(mid + 1, r);
}

ll find(ll x) {
    if (0 == pre[x])
        return x;
    return pre[x] = find(pre[x]);
}


ll kruskal() {
    memset(pre, 0, sizeof(pre));
    sort(edges + 1, edges + m + 1);
    ll cnt = 1;
    ll res = 0;
    for (ll i = 1; i <= m; i++) {
        ll u = edges[i].u;
        ll v = edges[i].v;
        ll w = edges[i].w;
        ll fu = find(u);
        ll fv = find(v);
        if (fu == fv) continue;
        pre[fu] = fv;
        res += w;
        ++cnt;
        if (cnt == n) return res;
    }
    return res;
}

