#include <bits/stdc++.h>
#define INF (1LL<<60)
using namespace std;
typedef long long ll;
typedef pair<ll,int> P;

class segtree{
public:
    static const int N=1<<19;
    P dp[1<<20];
    segtree(){
        for(int i=N-1;i<N*2;i++){
            dp[i]=P(INF,i-(N-1));
        }
        for(int i=N-2;i>=0;i--){
            dp[i]=min(dp[i*2+1],dp[i*2+2]);
        }
    }
    void update(int k,int v){
        k+=N-1;
        dp[k].first=v;
        while(k>0){
            k=(k-1)/2;
            dp[k]=min(dp[k*2+1],dp[k*2+2]);
        }
    }

    P query(int a,int b,int k=0,int l=0,int r=N){
        if(b<=l || r<=a)return P(INF,-1);
        if(a<=l && r<=b)return dp[k];
        int mid=(l+r)/2;
        P vl=query(a,b,k*2+1,l,mid);
        P vr=query(a,b,k*2+2,mid,r);
        return min(vl,vr);
    }
};

segtree seg,seg2;

int n;
ll d;
ll a[200005];
ll ans=0;

// [l,r)=区間[l,r)がつながってない
void solve(int l,int r,ll lc,ll rc){
    if(l<=r)return;
    P p1=seg.query(l,r);
    P p2=seg2.query(l,r);
    p1.first-=d*(l-1);
    p2.first-=d*(n-r-1);
    if(l==0)p1.first=INF;
    if(r==n)p2.first=INF;
    //printf("%d %d %lld %lld p1=%lld,%d p2=%lld,%d\n",l,r,lc,rc,p1.first,p1.second,p2.first,p2.second);
    p1.first+=lc;
    p2.first+=rc;
    //printf("%d %d %lld %lld p1=%lld,%d p2=%lld,%d\n",l,r,lc,rc,p1.first,p1.second,p2.first,p2.second);
    if(p1.first<p2.first){
        //printf("use left %d %d as%lld cost%lld\n",l-1,p1.second,a[l-1]+a[p1.second],p1.first);
        ans+=p1.first;
        solve(l,p1.second,lc,min(a[p1.second],(ll)rc+d*((ll)r-p1.second)));
        solve(p1.second+1,r,min(a[p1.second],(ll)lc+d*((ll)p1.second+1LL-l)),rc);
    }else{
        //printf("use right %d %d as%lld cost%lld\n",p2.second,r,a[r]+a[p2.second],p2.first);
        ans+=p2.first;
        solve(l,p2.second,lc,min(a[p2.second],(ll)rc+d*((ll)r-p2.second)));
        solve(p2.second+1,r,min(a[p2.second],(ll)lc+d*((ll)p2.second+1LL-l)),rc);
    }
}

int main(void){
    scanf("%d%lld",&n,&d);
    for(int i=0;i<n;i++){
        scanf("%lld",&a[i]);
    }
    if(n==1){
        printf("0\n");
        return 0;
    }
    for(int i=0;i<n;i++){
        seg.update(i,a[i]+(ll)d*i);
        seg2.update(i,a[i]+(ll)d*(n-i-1));
    }
    int best=0;
    for(int i=0;i<n-1;i++){
        if(a[i]+a[i+1]<a[best]+a[best+1]){
            best=i;
        }
    }
    ans+=a[best]+a[best+1]+d;
    solve(0,best,INF,min(a[best],a[best+1]+d));
    solve(best+2,n,min(a[best+1],a[best]+d),INF);
    printf("%lld\n",ans);
    return 0;
}

