const LL INF = 1LL << 61;

int N;
int size;
LL D;
LL A[214514];
pll seg1[1 << 23];
pll seg2[1 << 23];

void Update(pll *seg, int k, pll x) {
  k += size-1;
  seg[k] = x;
  while (k > 0) {
    k = (k-1)/2;
    seg[k] = min(seg[k*2+1], seg[k*2+2]);
  }
}

pll GetMin(pll *seg, int wishl, int wishr, int k, int watchl, int watchr) {
  int mid;
  pll lval, rval;
  if (wishr <= watchl || watchr <= wishl) return pll(INF, INF);
  if (wishl <= watchl && watchr <= wishr) return seg[k]; 

  mid = (watchl+watchr)/2;
  lval = GetMin(seg, wishl, wishr, k*2+1, watchl, mid);
  rval = GetMin(seg, wishl, wishr, k*2+2, mid, watchr);
  return min(lval, rval);
}

vector<int> belong;
vector<vector<int>> grps;

signed main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);

  cin >> N >> D;
  size = 1;
  while (size < N) size <<= 1;

  belong.resize(N);
  grps.resize(N);
  rep(i, N) {
    cin >> A[i];
    Update(seg1,  i, pll(A[i]+i*D, i));
    Update(seg2, i, pll(A[i]+(N-i)*D, i));
    grps[i] = vector<int>(1, i);
    belong[i] = i;
  }

  LL ans = 0;
  using Edge = pair<LL, pii>;
  rep(_, 18) {
    vector<Edge> mines;
    mines.reserve(grps.size());
    for (auto &grp : grps) {
      vector<pll> restore1, restore2;
      restore1.reserve(grp.size());
      restore2.reserve(grp.size());
      for (int v : grp) {
        restore1.eb(seg1[size-1+v]);
        Update(seg1, v, pll(INF, INF));
        restore2.eb(seg2[size-1+v]);
        Update(seg2, v, pll(INF, INF));
      }

      Edge mine(INF, pii(-1, -1));
      for (int v : grp) {
        pll p = GetMin(seg1, v+1, N, 0, 0, size);
      //cout << p.X << ", " << p.Y << endl;
        if (p.X != INF) {
          MN(mine, Edge(A[v]+A[p.Y]+abs(v-p.Y)*D, pii(v, p.Y)));
        }

        pll q = GetMin(seg2, 0, v, 0, 0, size);
        //cout << q.X << ", " << q.Y << endl;
        if (q.X != INF) {
          MN(mine, Edge(A[v]+A[q.Y]+abs(v-q.Y)*D, pii(v, q.Y)));
        }
      }

      for (auto &p : restore1) {
        Update(seg1, p.Y, p);
      }

      for (auto &p : restore2) {
        Update(seg2, p.Y, p);
      }

      mines.eb(mine);
    }

    bool all = false;
    for (auto &e : mines) {
      LL c = e.X;
      int u, v;
      tie(u, v) = e.Y;
      if (belong[u] == belong[v]) continue;

      ans += c;
      u = belong[u];
      v = belong[v];
      if (grps[u].size() > grps[v].size()) swap(u, v);
      grps[v].reserve(grps[v].size()+grps[u].size());
      for (int w : grps[u]) {
        belong[w] = v;
        grps[v].eb(w);
      }
      grps[u].clear();
      if (grps[v].size() == N) all = true;
    }

    if (all) break;
  }
  cout << ans << "\n";
}

