class Monoid {
public:
    using t = pair<long,int>;
    static t id() {
        return {10000000000000000,-1};
    }
    static t op(const t& l, const t& r) {
        return min(l, r);
    }
};
template< typename M >
class SegmentTree {
	using T = typename M::t;
	const int n;
	vector<T> data;
	int size(int n_) {
        int res = 1;
        while (res < n_) {
			res <<= 1;
		}
        return res;
    }
	public:
    SegmentTree(int n_)
        : n(size(n_)), data(n * 2, M::id()) {}
    SegmentTree(int n_, T v)
        : n(size(n_)), data(n * 2, v) {}
    SegmentTree(const vector<T>& data_)
        : n(size(data_.size())), data(n * 2, M::id()) {
            init(data_);
    }
    void init() {
        for (int i = n - 1; i >= 1; i--) data[i] = Monoid::op(data[i * 2], data[i * 2 + 1]);
    }
    void init(const vector<T>& data_) {
        for (int i = 0; i < (int)data_.size(); i++) data[i + n] = data_[i];
        init();
    }
  	void Update(int k,const T x){
    	k += n;
    	data[k] = x;
    	while(k >>= 1){
      		data[k] = Monoid::op(data[2*k+0],data[2*k+1]);
    	}
  	}
  	T Query(int a,int b){
    	T L = Monoid::id(), R = Monoid::id();
    	for(a += n,b += n+1;a < b;a >>= 1,b >>= 1){
      		if(a & 1) L = Monoid::op(L,data[a++]);
      		if(b & 1) R = Monoid::op(data[--b],R);
    	}
    	return Monoid::op(L,R);
  	}
	T Query(int a){
    	return data[a+n];
  	}
