long A[200000];
bool Used[199999];
void Calc(){
	int N = rei();
	long D = rel();
	vector<pair<long,int>> VA(N);
	for(int i=0;i<N;i++){
		A[i] = rel();
		VA[i] = {A[i],i};
	}
	SegmentTree<Monoid> Seg(VA);
	long ans = 0;
	int res = N-1;
	while(res){
		pair<long,int> m = Seg.Query(0,N-1);
		Seg.Update(m.second,Monoid::id());
		if(m.second != 0 && !Used[m.second-1]){
			res--;
			ans += Seg.Query(m.second-1).first + m.first + D;
			Used[m.second-1] = true;
			Seg.Update(m.second-1,{min(Seg.Query(m.second-1).first,m.first+D),m.second-1});
		}
		if(m.second != N-1 && !Used[m.second]){
			res--;
			ans += Seg.Query(m.second+1).first + m.first + D;
			Used[m.second] = true;
			Seg.Update(m.second+1,{min(Seg.Query(m.second+1).first,m.first+D),m.second+1});
		}
	}
	cout << ans << endl;
}
