/* SimpleSegTree(0-index) */

struct SimpleSegTree{
  typedef pair<ll,int> Type;
  int segn2;
  Type initVal;
  vector<Type> data;
  function<Type(Type, Type)> merge;

  SimpleSegTree(int n, Type initVal, function<Type(Type, Type)> merge):
    initVal(initVal), merge(merge)
  {
    for(segn2=1; segn2<n; segn2*=2);
    data.assign(segn2*2, initVal);
  }

  SimpleSegTree(int n): //RangeMinimunQuery
    SimpleSegTree(n, {LLINF, -1}, [](Type a, Type b){ return min(a, b); }) {}

  SimpleSegTree(int n, Type initVal): //RangeMinimunQuery
    SimpleSegTree(n, initVal, [](Type a, Type b){ return min(a, b); }) {}

  //get value [a,b)
  Type query(int a, int b, int l = 0, int r = -1, int k = 0){
    if(r == -1) r = segn2;
    if(a <= l && r <= b) return data[k];
    if(r <= a || b <= l) return initVal;
    return merge(query(a,b,l,(l+r)/2,k*2+1),query(a,b,(l+r)/2,r,k*2+2));
  }

  //set kth number x
  void set(int k, Type x){
    k += segn2-1;
    data[k] = x;
    while(k > 0){
      k = (k-1)/2;
      data[k] = merge(data[k*2+1], data[k*2+2]);
    }
  }
};

/* UnionFind */

struct UnionFind{
  vector<int> data;
  UnionFind(int s):data(s, -1) {}

  int root(int x){
    if(data[x] < 0) return x;
    return data[x] = root(data[x]);
  }

  bool set(int x,int y){
    x = root(x); y = root(y);
    if(x == y) return false;
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  bool check(int x, int y){
    return root(x) == root(y);
  }

  int size(int x){
    return -data[root(x)];
  }
};



int main(){
  ll n, d, a[SIZE];

  scanf("%lld%lld\n", &n, &d);

  SimpleSegTree segL(n), segR(n);

  for(int i=0;i<n;i++){
    scanf("%lld", a+i);
    segL.set(i, {-i*d + a[i], i});
    segR.set(i, {i*d + a[i], i});
  }

  ll ans = 0;

  vector<pair<ll, pair<int,int> > > vec;

  for(int i=0;i<n;i++){
    auto x = segL.query(0, i);

    if (x.first != LLINF) {
      vec.push_back({x.first + i * d + a[i], {i, x.second}});
    }

    auto y = segR.query(i+1, n);

    if (y.first != LLINF) {
      vec.push_back({y.first - i * d + a[i], {i, y.second}});
    }
  }

  sort(vec.begin(), vec.end());

  UnionFind uf(n);

  for(int i=0;i<vec.size();i++){
    if(uf.set(vec[i].second.first, vec[i].second.second))
      ans += vec[i].first;
    debug(vec[i].second);
  }

  cout << ans << endl;

  return 0;
}

