struct UnionFind {
	vector<LL> data;

	UnionFind(LL sz) {
		data.assign(sz, -1LL);
	}

	bool unite(LL x, LL y) {
		x = find(x), y = find(y);
		if (x == y) return (false);
		if (data[x] > data[y]) swap(x, y);
		data[x] += data[y];
		data[y] = x;
		return (true);
	}

	LL find(LL k) {
		if (data[k] < 0) return (k);
		return (data[k] = find(data[k]));
	}

	LL size(LL k) {
		return (-data[find(k)]);
	}
};

template< typename T >
T kruskal(Edges< T > &edges, LL V) {
	sort(begin(edges), end(edges), [](const edge< T > &a, const edge< T > &b) {
		return (a.cost < b.cost);
	});
	UnionFind tree(V);
	T ret = 0;
	for (auto &e : edges) {
		if (tree.unite(e.src, e.to)) ret += e.cost;
	}
	return (ret);
}

int main() {
	LL n, d; cin >> n >> d;

	vector<LL> a(n);

	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}

	Edges<LL> edges;

	for (LL i = 0; i < n; i++) {
		for (LL j = 0; j < n; j++) {
			if (i == j)continue;

			LL costs = abs(i - j)*d + a[i] + a[j];

			edges.emplace_back(i, j, costs);

		}
	}

	cout << kruskal(edges, n) << endl;



	return 0;
}

