    if (!right) min_a_idx = seg.query(0LL, aidx1);
    else min_a_idx = seg.query(aidx1 + 1LL, n);
    ll aidx2 = get<1>(min_a_idx);

    ll cost = 1e18;
    if (!right) cost = (n - aidx1) * d + alist[aidx1];
    else cost = aidx1 * d + alist[aidx1];
    seg.update(aidx1, t2(cost, aidx1));

    if (aidx2 < 0LL) return;
    linkset.insert(t3(abs(aidx1 - aidx2) * d + alist[aidx1] + alist[aidx2],
                     aidx1, aidx2));
}

