	{
		ll cost1, cost2;
		cost1 = a[rim] + d*rim;
		cost2 = a[i] + d*i;
		if (cost2 < cost1)
			rim = i;
	}

	forn(i, le, (ri + le) / 2)
	{
		ll cle, cri;
		cle = a[i] - d*i;
		cri = a[rim] + d*rim;
		ll cost = cle + cri;
		ed[i].push_back(make_pair(cost, rim));
		if(i != lem)
			ed[rim].push_back(make_pair(cost, i));
	}

	forn(i, (ri + le) / 2, ri)
	{
		ll cle, cri;
		cle = a[lem] - d*lem;
		cri = a[i] + d*i;
		ll cost = cle + cri;
		ed[i].push_back(make_pair(cost, lem));
		if (i != rim)
			ed[lem].push_back(make_pair(cost, i));
	}
}

template <class T> struct greater
{
	bool operator() (const T& x, const T& y)const
	{
		return x > y;
	}
};

ll MSTcost()
{
	priority_queue<pll, vector<pll>, greater<pll> > pile;
	vl used(ed.size(), 0);
	ll cost = 0;
	pile.push(make_pair(0, 0));
	while (pile.size())
	{
		pair<ll, ll> cur;
		cur = pile.top();
		pile.pop();
		if (used[cur.second])
			continue;
		used[cur.second] = 1;
		cost += cur.first;
		for (pair<ll, ll> edge : ed[cur.second])
		{
			if (used[edge.second])
				continue;
			pile.push(edge);
		}
	}
	cost;
	return cost;
}

