void gao(int l,int r)
{
	if(l==r) return;
	int mid = (l+r)>>1;

	ll lmn = lval[l];
	int lpos = l;
	for(int i=l; i<=mid; ++i)
		if(lmn > lval[i])
			lmn = lval[i], lpos = i;
	ll rmn = rval[r];
	int rpos = r;
	for(int i=mid+1; i<=r; ++i)
		if(rmn > rval[i])
			rmn = rval[i], rpos = i;

