    ll cnt = 0LL;
    ll ans = 0LL;

    for (auto link : linkset) {
        ll cost = get<0>(link);
        ll idx1 = get<1>(link);
        ll idx2 = get<2>(link);
        if (uf.root(idx1) != uf.root(idx2)) {
            uf.unite(idx1, idx2);
            cnt++;
            ans += cost;
        }
        if (cnt >= n - 1LL) {
