status merge(status a,status b)
{
	status c;c.init();
	c.ans=min(b.ans,a.ans);
	c.asmall=min(a.asmall,b.asmall);
	c.abig=min(a.abig,b.abig);
	c.bsmall=min(a.bsmall,b.bsmall);
	c.bbig=min(a.bbig,b.bbig);

	c.ans=min(c.ans,a.asmall+b.bbig);
	c.ans=min(c.ans,b.abig+a.bsmall);
	return c;
}

ll D;ll a[nn];
struct segmenttree
{
	status tree[nn*2+10];
	#define lc id<<1
	#define rc id<<1|1
	#define mid (l+r)/2
	void up(ll id)
	{
		tree[id]=merge(tree[lc],tree[rc]);
	}
	void init(ll l,ll r,ll id)
	{
		if(l==r)
		{
			tree[id].init();
			tree[id].bsmall=make_pair(a[l]-D*l,l);
			tree[id].bbig=make_pair(a[l]+D*l,l);
			return ;
		}
		init(l,mid,lc);init(mid+1,r,rc);
		up(id);
	}
	void update(ll x,ll l,ll r,ll id)
	{
		if(l==r) 
		{
			tree[id].init();
			tree[id].asmall=make_pair(a[l]-D*l,l);
			tree[id].abig=make_pair(a[l]+D*l,l);
			return ;
		}
		if(x<=mid) update(x,l,mid,lc);
		else update(x,mid+1,r,rc);
		up(id);
	}
	pair<ll,ll> query()
	{
		return tree[1].ans;
	}
}trcyx;
int main()
{
	ll n;scanf("%lld",&n);scanf("%lld",&D);
	memset(a,0x3f,sizeof(a));
	for(ll i=1;i<=n;i++) scanf("%lld",&a[i]);
	trcyx.init(1,nn,1);
	ll ans=0;  
	trcyx.update(1,1,nn,1);
	for(ll i=1;i<n;i++) 
	{
		pair<ll,ll> op=trcyx.query();
		ans+=op.first;//cout<<op.second;
		trcyx.update(op.second,1,nn,1);
	}
	cout<<ans;
	return 0;  
}

