struct UnionFind{
    vector<ll>data;
    UnionFind(ll n):data(n,-1){}
    bool unite(ll a,ll b){
        a=root(a);b=root(b);
        if(a==b)return 0;
        if(data[a]>data[b])swap(a,b);
        data[a]+=data[b];
        data[b]=a;
        return 1;
    }
    bool find(ll a,ll b){return root(a)==root(b);}
    ll root(ll a){return data[a]<0?a:data[a]=root(data[a]);}
    ll size(ll a){return -data[root(a)];}
    ll operator[](ll a){return root(a);}
};
int main(){
    LL(n,d);
    VEC(ll,a,n);
    UnionFind uf(n);
    auto cost=[&](ll x,ll y){
        return a[x]+a[y]+abs(x-y)*d;
    };
    vec(ll,l,n);
    l[0]=0;
    rep(n-1)l[i+1]=cost(l[i],i+1)>=cost(i+1,i+1)?i+1:l[i];
    vec(ll,r,n);
    r.back()=n-1;
    rrep(n-1)r[i]=cost(r[i+1],i)>=cost(i,i)?i:r[i+1];
    ll ans=0;
    rep(n-1)if(uf.unite(l[i],r[i+1]))ans+=cost(l[i],r[i+1]);
    rep(i,1,n-1)if(ll j=min(l[i-1],r[i+1],[&](ll a,ll b){return cost(i,a)<cost(i,b);});uf.unite(i,j))ans+=cost(i,j);
    out(ans);
}

