#include <tuple>
#include <iostream>
using namespace std;

constexpr long long INF = 1LL<<60;

using T = tuple<long long, int, int>;

inline bool operator<(const T lhs, const T rhs) {
    return get<0>(lhs) < get<0>(rhs);
}

class Solver {
    int N;
    long long D;
    int* A;
    pair<long long, int> *Ap, *Am, *Bp, *Bm;
    T* C;
public:
    Solver(int* a, int n, int d) : D(d) {
        N = 1;
        while (N < n) N *= 2;
        A = a;
        Ap = new pair<long long, int>[2*N-1];
        Am = new pair<long long, int>[2*N-1];
        Bp = new pair<long long, int>[2*N-1];
        Bm = new pair<long long, int>[2*N-1];
        C = new T[2*N-1];
        fill(Ap, Ap+2*N-1, make_pair(INF, -1));
        fill(Am, Am+2*N-1, make_pair(INF, -1));
        for (int i = 0; i < n; i++) {
            Bp[i+N-1] = {A[i] + D * i, i};
            Bm[i+N-1] = {A[i] - D * i, i};
            C[i+N-1] = {INF, -1, -1};
        }
        for (int i = n; i < N; i++) {
            Bp[i+N-1] = {INF, i};
            Bm[i+N-1] = {INF, i};
            C[i+N-1] = {INF, -1, -1};
        }
        for (int x = N-2; x >= 0; x--) {
            Bp[x] = min(Bp[2*x+1], Bp[2*x+2]);
            Bm[x] = min(Bm[2*x+1], Bm[2*x+2]);
            C[x] = min(C[2*x+1], C[2*x+2]);
        }
    }
    T query() { return C[0]; }
    void add(int i) {
        int x = i + N - 1;
        Ap[x] = {A[i] + D * i, i};
        Am[x] = {A[i] - D * i, i};
        Bp[x] = Bm[x] = {INF, -1};
        while (x > 0) {
            x = (x - 1) / 2;
            const int lc = 2*x+1, rc = 2*x+2;
            Ap[x] = min(Ap[lc], Ap[rc]);
            Am[x] = min(Am[lc], Am[rc]);
            Bp[x] = min(Bp[lc], Bp[rc]);
            Bm[x] = min(Bm[lc], Bm[rc]);
            long long v1 = Am[lc].first + Bp[rc].first;
            int i1 = Am[lc].second, j1 = Bp[rc].second;
            long long v2 = Ap[rc].first + Bm[lc].first;
            int i2 = Ap[rc].second, j2 = Bm[lc].second;
            C[x] = min({{v1, i1, j1}, {v2, i2, j2}, C[lc], C[rc]});
        }
    }
};

int main() {
    int N, D; cin >> N >> D;
    int a[N];
    for (int i = 0; i < N; i++) cin >> a[i];
    Solver S(a, N, D);
    long long ans = 0;
    S.add(0);
    int cnt = 1;
    bool added[N];
    fill(added, added+N, false);
    added[0] = true;
    while (cnt < N) {
        T r = S.query();
        long long d = get<0>(r);
        int i = get<1>(r), j = get<2>(r);
        ans += d;
        if (added[i]) swap(i, j);
        S.add(i);
        cnt++;
        added[i] = true;
    }
    cout << ans << endl;
}

