struct node
{
    int x, y;
    long long v;
    node(int X = 0, int Y = 0, long long V = 0)
    {
        x = X;
        y = Y;
        v = V;
    }
};
vector<node>edge;
bool operator<(const node &a, const node &b)
{
    return a.v < b.v;
}
long long G(int x)
{
    return A[x] + (long long)x * d;
}
long long F(int x)
{
    return A[x] - (long long)x * d;
}
int getfa(int x)
{
    return x == fa[x] ? x : fa[x] = getfa(fa[x]);
}
