    for (int i = 2 ; i <= n ; i ++)
    {
        edge.push_back(node(F_min, i, F(F_min) + G(i)));
        if (F(F_min) >= F(i))
            F_min = i;
    }
    int G_min = n;
    for (int i = n - 1 ; i ; i --)
    {
