	int find(int i){return p[i]=p[i]==i?i:find(p[i]);}
	void unite(int a,int b){if((a=find(a))!=(b=find(b))){if(r[a]>r[b]){swap(a,b);}s[b]+=s[a];r[p[a]=b]+=r[a]==r[b];}}
