const int M = 2e5 + 10;
const int mod = 1e9 + 7;
const ll inf = 1e18;

int n, D, A[M];

struct pa {
  ll w;
  int id;
  pa() {}
  pa(ll w, int id) : w(w), id(id) {}
  friend pa operator + (const pa &a, const pa &b) {
    if(a.w < b.w) return a;
    else return b;
  }
};

struct SMT {
  # define ls (x << 1)
  # define rs (x << 1 | 1)
  pa w[2][M << 2];

  void build(int x, int l, int r) {
    w[0][x] = w[1][x] = pa(inf, l);
    if(l == r) return ;
    int mid = l + r >> 1;
    build(ls, l, mid);
    build(rs, mid+1, r);
  }

  void modify(int x, int l, int r, int pos, ll _w, int op) {
    if(l == r) {
      w[op][x].w = _w;
      return ;
    }
    int mid = l + r >> 1;
    if(pos <= mid) modify(ls, l, mid, pos, _w, op);
    else modify(rs, mid+1, r, pos, _w, op);
    w[op][x] = w[op][ls] + w[op][rs]; 
  }

  # undef ls
  # undef rs 
} tag, untag;

struct SMT2 {
  # define ls (x << 1)
  # define rs (x << 1 | 1)
  pa w[M << 2];

  void build(int x, int l, int r) {
    w[x] = pa(inf, l);
    if(l == r) return ;
    int mid = l + r >> 1;
    build(ls, l, mid);
    build(rs, mid+1, r);
  }

  void update(int x, int l, int r, int pos) {
    if (l == r) return ;
    int mid = l + r >> 1;
    if(pos <= mid) update(ls, l, mid, pos);
    else update(rs, mid+1, r, pos);
    // edge only in ls || only in rs.
    w[x] = w[ls] + w[rs];
    // edge across ls & rs
    // tag.ls with untag.rs
    w[x] = w[x] + pa(tag.w[0][ls].w + untag.w[1][rs].w, untag.w[1][rs].id);
    // untag.ls with tag.rs
    w[x] = w[x] + pa(untag.w[0][ls].w + tag.w[1][rs].w, untag.w[0][ls].id); 
  }
  # undef ls
  # undef rs
}edge;

int main() {
  std :: ios :: sync_with_stdio(false);
  std :: cin.tie(0);
  std :: cout.tie(0);
  cin >> n >> D;
  for (int i = 1; i <= n; ++ i) cin >> A[i];
  tag.build(1, 1, n);
  untag.build(1, 1, n);
  tag.modify(1, 1, n, 1, -1ll * D + A[1], 0);
  tag.modify(1, 1, n, 1, 1ll * D + A[1], 1);
  for (int i = 2; i <= n; ++ i) {
    untag.modify(1, 1, n, i, -1ll * D * i + A[i], 0);
    untag.modify(1, 1, n, i, 1ll * D * i + A[i], 1);
  }
  edge.build(1, 1, n);
  edge.update(1, 1, n, 1);

  ll ans = 0; 
  for (int i = 1; i < n; ++ i) {
    ans += edge.w[1].w;
    int p = edge.w[1].id;
    untag.modify(1, 1, n, p, inf, 0);
    untag.modify(1, 1, n, p, inf, 1);
    tag.modify(1, 1, n, p, -1ll * D * p + A[p], 0);
    tag.modify(1, 1, n, p, 1ll * D * p + A[p], 1);
    edge.update(1, 1, n, p);
  }
  cout << ans;
  return 0;
}

