//Union Find
const ll MAX_V = 1000010;

ll par[MAX_V];//
ll Rank[MAX_V];
ll child[MAX_V];

void init_UF(){
  for(ll i = 0; i < MAX_V; i++){
    par[i] = i;
    Rank[i] = 1;
    child[i] = 1;
  }
}

ll find(ll x){
  if(par[x] == x) return x;
  else{
    return par[x] = find(par[x]);
  }
}

bool same(ll x, ll y){
  return find(x) == find(y);
}

void unite(ll x, ll y){
  ll rx = find(x), ry = find(y);
  if(rx != ry){
    if(Rank[rx] >= Rank[ry]){
      par[ry] = rx;
      if(Rank[rx] == Rank[ry]) Rank[rx]++;
      child[rx] += child[ry];
    }else{
      par[rx] = ry;
      child[ry] += child[rx];
    }
  }
}


const ll N_ = (1<<18);
pair<ll, ll> seg[2*N_-1][2];
void update(ll k, pair<ll, ll> x, ll id){
  k += N_-1;
  seg[k][id] = x;
  while(k > 0){
    k = (k-1)/2;
    seg[k][id] = min(seg[2*k+1][id], seg[2*k+2][id]);
  }
}

pair<ll, ll> getminimum(ll x, ll y, ll id, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return {INFL, -1};
  if(x <= left && right <= y) return seg[k][id];
  ll mid = (left + right) / 2;
  pair<ll, ll> l = getminimum(x, y, id, 2*k+1, left, mid);
  pair<ll, ll> r = getminimum(x, y, id, 2*k+2, mid, right);
  return min(l, r);
}

struct edge{ll from, to, cost;};

bool comp(edge e, edge f){
  return e.cost < f.cost;
}

void solve(){
  ll N, D;
  cin >> N >> D;
  vector<pair<ll, ll>> A(N);
  vector<ll> B(N);
  rep(i, N){
    cin >> A[i].f;
    A[i].s = i;
    B[i] = A[i].f;
  }
  sort(A.begin(), A.end());
  rep(i, N_){
    update(i, {INFL, -1}, 0);
    update(i, {INFL, -1}, 1);
  }
  vector<edge> E;
  rep(i, N){
    pair<ll, ll> p = getminimum(0, A[i].s, 1);
    pair<ll, ll> q = getminimum(A[i].s + 1, N, 0);
    if(p.f != INFL){
      E.pb({A[i].s, p.s, B[A[i].s] + B[p.s] + D * abs(A[i].s - p.s)});
    }
    if(q.f != INFL){
      E.pb({A[i].s, q.s, B[A[i].s] + B[q.s] + D * abs(A[i].s - q.s)});
    }
    update(A[i].s, {A[i].f + D * A[i].s, A[i].s}, 0);
    update(A[i].s, {A[i].f + D * (N - A[i].s), A[i].s}, 1);
  }
  sort(E.begin(), E.end(), comp);
  init_UF();
  ll ans = 0;
  rep(i, E.size()){
    edge e = E[i];
    if(same(e.from, e.to)) continue;
    unite(e.from, e.to);
    ans += e.cost;
  }
  cout << ans << endl;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

