template<class Weight>
struct Prim {
    int n;
    vector<vector<pair<int, Weight>>> G;
    vector<int> parent;
    vector<bool> vis;

    Prim() {}

    Prim(int n_) :n(n_), G(n), parent(n, -1) {}

    void addEdge(int u, int v, Weight w) {
        G[u].emplace_back(v, w);
        G[v].emplace_back(u, w);
    }

    Weight getMST(int start = 0) {
        Weight res = 0;
        using E = tuple<Weight, int, int>;
        priority_queue<E, vector<E>, greater<E>> Q;
        Q.push(E(0, start, start));
        while (!Q.empty()) {
            Weight w;
            int p, u;
            tie(w, p, u) = Q.top();
            Q.pop();
            if (parent[u] != -1)continue;
            parent[u] = p;
            res += w;
            for (auto &e : G[u]) {
                if (parent[e.first] == -1) {
                    Q.push(E(e.second, u, e.first));
                }
            }
        }
        return res;
    }
};

int N;
ll D;
vll A;

Prim<ll> prim;
ll INF = LLONG_MAX / 3;

void f(int l, int r) {
    if (r - l == 1)return;
    int m = (l + r) / 2;
    using P = pair<ll, int>;
    P lefMin(INF, -1), rigMin(INF, -1);
    FOR(i, l, m) smin(lefMin, P(A[i] - D * i, i));
    FOR(i, m, r) smin(rigMin, P(A[i] + D * i, i));
    FOR(i, l, m) prim.addEdge(i, rigMin.second, rigMin.first + A[i] - D * i);
    FOR(i, m, r) prim.addEdge(i, lefMin.second, lefMin.first + A[i] + D * i);
    f(l, m);
    f(m, r);
}

void solve() {
    cin >> N >> D;
    A.resize(N);
    rep(i, N)cin >> A[i];
    prim = Prim<ll>(N);

    f(0, N);
    cout << prim.getMST() << endl;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

