	}

	bool is_same(ll x, ll y) {
		return root(x) == root(y);
	}

	bool unite(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (v[x] > v[y]) swap(x, y);
		v[x] += v[y];
		v[y] = x;
		return true;
	}

	ll size(ll x) {
		return -v[root(x)];
	}
};

/*
グラフ上のボロノイ図を作る 要Edge,UnionFind
引数
　g:探索するグラフ
　startv:探索するスタートノード番号の集合
戻り値
  vector<Edge>: ボロノイ図で接しているセルの情報
    e.from,e.to = 接しているセルの2ノード
    e.cost = e.from-e.to間の距離, 接点までの位置は÷2してください
*/
vector<Edge> voronoi(vector<vector<Edge>> &g, vector<ll> &startv){
	priority_queue<Edge, vector<Edge>, function<bool(Edge,Edge)>> que(
		[](const Edge &x, const Edge &y){
			return x.cost != y.cost ? (x.cost > y.cost) : 
				(x.from != y.from ? x.from < y.from : x.to < y.to);
		}
	);
	for(ll v : startv){
		que.push(Edge(v, v, 0));
	}

	vector<ll> dist(g.size(), INF);
	vector<ll> prev(g.size(), -1);
	UnionFind u(g.size());
	vector<Edge> ans;
	while(!que.empty()){
		Edge e = que.top();
		que.pop();
		if(dist[e.to] == INF){
			dist[e.to] = e.cost;
			prev[e.to] = e.from;
			for(Edge f : g[e.to]){
				que.push(Edge(e.from, f.to, e.cost + f.cost));
			}
		}else{
			if(!u.is_same(e.from, prev[e.to])){
				//prev[e.to] と e.from が出会った
				ans.emplace_back(e.from, prev[e.to], dist[e.to] + e.cost);
				u.unite(e.from, prev[e.to]);
			}
		}
	}
	return ans;
}


