void solve() {
	scanf("%lld%lld", &N, &D);
	A.assign(N, 0);
	rep(i, N) { scanf("%lld", &A[i]); }

	vector<vector<Edge>> g(2*N);
	rep(i,N){
		Edge e(i, N+i, A[i]);
		g[e.from].push_back(e);
		Edge f(N+i, i, A[i]);
		g[f.from].push_back(f);
	}
	rep(i,N-1){
		Edge e(N+i, N+i+1, D);
		g[e.from].push_back(e);
		Edge f(N+i+1, N+i, D);
		g[f.from].push_back(f);
	}

	vector<ll> startv;
	rep(i,N)startv.push_back(i);
	vector<Edge> volg = voronoi(g, startv);


	vector<vector<Edge>> g2(N);
	for(Edge e : volg){
		Edge f1(e.from, e.to, abs(e.from-e.to)*D+A[e.from]+A[e.to]);
		g2[f1.from].push_back(f1);
		Edge f2(e.to, e.from, abs(e.from-e.to)*D+A[e.from]+A[e.to]);
		g2[f2.from].push_back(f2);
	}

	vector<vector<Edge>> ming;
	ll mincost = kruskal(g2, ming);
	printf("%lld\n", mincost);
}

