    ll d,tmp;
    cin >> n >> d;

    if(n <= 1) {
        cout << "0" << endl;
        return 0;
    }
    RMQ seg,seg2;
    seg.init(n);
    seg2.init(n);
    Unionfind uf(n);
    vector<pair<ll,int> > A(n);
    rep(i,n){
        cin >> tmp;
        A[i] = {tmp,i};
        seg.update(i,tmp+i*d);
        seg2.update(i,tmp+(n-i-1)*d);
    }
    sort(A.begin(),A.end(),comp2);

    rep(i,n){
        if(A[i].second < n-1 && 
                    seg.getMin(A[i].second+1,n-1).second >= 0){
        es.push_back({A[i].second ,
                    seg.getMin(A[i].second+1,n-1).second,
                    seg.getMin(A[i].second+1,n-1).first + A[i].first - (A[i].second)*d  });
        }
        if(A[i].second > 0 && 
                    seg.getMin(0,A[i].second-1).second >= 0){
        es.push_back({A[i].second ,
                    seg2.getMin(0,A[i].second-1).second,
                    seg2.getMin(0,A[i].second-1).first + A[i].first - (n-A[i].second-1) * d});
        }
        seg.update(A[i].second,INF);
        seg2.update(A[i].second,INF);
