class UnionFind {
    vector<int> p;//p[i]はiの属する組織
public:
    UnionFind(int n) {
        p = vector<int>(n);
        for (int i = 0; i < n; i++) {
            p[i] = i;
        }
        return;
    }

/* xの属する集合を返す */
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }

/* yにxを統合する */
    void unite(int x, int y) {
        p[find(x)] = p[find(y)];
    }

/* xとyが属する集合が同じかを判定する */
    bool same(int x, int y) {
        return find(x) == find(y);
    }

};

class Solve {
public:
    int N;
    ll D;
    vector<ll> A;

    void input() {
        cin >> N >> D;
        A.resize(N);
        rep(i, 0, N) cin >> A[i];
    }

    struct edge {
        int a;
        int b;
        ll w;
    };
    vector<edge> edges;

    void left() {
        //右から見ていけ
        //どこを参照すべきかを教えてくれる。
//        vector<int> ret(N, -1);
        int key = N - 1;
        ll val = A[N - 1];
        for (int i = N - 2; i >= 0; --i) {
            val += D;
//            ret[i] = key;
            edges.push_back(edge{key, i, val + A[i]});
            if (A[i] <= val) {
                val = A[i];
                key = i;
            }
        }
    }

    void right() {
        int key = 0;
        ll val = A[0];
        for (int i = 1; i < N; ++i) {
            val += D;
//            edges.emplace_back(key, i, val + A[i]);
            edges.push_back(edge{key, i, val + A[i]});
            if (A[i] <= val) {
                val = A[i];
                key = i;
            }

        }
    }

    void solve() {
        input();
        left();
        right();
        UnionFind uf(N);

        sort(all(edges), [](edge a, edge b) {
            return a.w < b.w;
        });

        ll ans = 0;
        for (auto e : edges) {
            if (!uf.same(e.a, e.b)) {
                uf.unite(e.a, e.b);
                ans += e.w;
            }
        }

        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

