    for(int i=0; i<n; ++i){
        cin >> a[i];
        b[i] = a[i];
        left[i] = i - 1;
        right[i] = i + 1;
    }
    right[n-1] = -1;

    multiset<tuple<long long, int, int> > ms;
    for(int i=0; i<n-1; ++i)
        ms.insert(make_tuple(a[i] + b[i+1] + d, i, i+1));

    UnionFindTree uft(n);
    long long ans = 0;
    while(!ms.empty()){
        long long cost;
        int i, j;
        tie(cost, i, j) = *ms.begin();
        ms.erase(ms.begin());
        i = uft.find(i);
        j = uft.find(j);
        if(uft.same(i, j))
            continue;

        ans += cost;
        a[i] = min(a[i] + d, a[j]);
        b[i] = min(b[i], b[j] + d);
