			pl=i;
		}
	}
	int pr=middle+1;
	long long vr=1ll*a[middle+1]+1ll*d*(middle+1);
	for(int i=middle+1;i<=right;i++){
		long long cv=1ll*a[i]+1ll*d*i;
		if(cv<vr){
			vr=cv;
			pr=i;
		}
	}
	for(int i=left;i<=middle;i++) seg.push_back(Seg(1ll*a[i]-1ll*d*i+vr,i,pr));
	for(int i=middle+1;i<=right;i++) seg.push_back(Seg(1ll*a[i]+1ll*d*i+vl,pl,i));
	solve(left,middle);
	solve(middle+1,right);
}

