void upd(int u, int v, int tl, int tr, int ps, int vl)
{
	if (tl == tr) {
		t[u][v] = { ps, vl };
	}
	else
	{
		int tm = tl + tr >> 1;
		if (ps <= tm)
			upd(u, v << 1, tl, tm, ps, vl);
		else
			upd(u, v << 1 | 1, tm + 1, tr, ps, vl);
		if (t[u][v << 1].second < t[u][v << 1 | 1].second)
			t[u][v] = t[u][v << 1];
		else
			t[u][v] = t[u][v << 1 | 1];
	}
}

void init()
{
	for (int i = 0; i < 4 * N; i++)
	{
		t[0][i] = { oo, oo };
		t[1][i] = { oo, oo };
	}
}

pii get(int u, int v, int tl, int tr, int l, int r)
{
	if (l > r)
		return{ oo, oo };
	if (tl == l && tr == r)
		return t[u][v];
	int tm = tl + tr >> 1;

	pii p1 = get(u, v << 1, tl, tm, l, min(tm, r));
	pii p2 = get(u, v << 1 | 1, tm + 1, tr, max(tm + 1, l), r);

	if (p1.second < p2.second)
		return p1;
	else
		return p2;
}

