/// --- Union Find Library {{{ ///
struct UF {
  int n, comps;
  vector< int > par;
  UF(int n) : n(n), comps(n), par(n, -1) {}
  int find(int x) { return par[x] < 0 ? x : par[x] = find(par[x]); }
  int size(int x) { return -par[find(x)]; }
  int size() { return n; }
  int components() { return comps; }
  bool same(int a, int b) { return find(a) == find(b); }
  bool unite(int a, int b) {
    a = find(a);
    b = find(b);
    if(a == b) return 0;
    if(par[a] < par[b]) swap(a, b);
    par[b] += par[a];
    par[a] = b;
    comps--;
    return 1;
  }
};
/// }}}--- ///

// require UnionFind
// F(component-size, belongs) -> vector<(cost, to)>
template < class T, class F >
T boruvka(int n, const F &f) {
  UF uf(n);
  T res(0);
  bool update = 1;
  vector< int > belongs(n), rev(n);
  while(update) {
    update = 0;
    int ptr = 0;
    for(int i = 0; i < n; i++)
      if(i == uf.find(i)) rev[ptr] = i, belongs[i] = ptr++;
    for(int i = 0; i < n; i++) belongs[i] = belongs[uf.find(i)];
    auto v = f(ptr, belongs);
    for(int i = 0; i < ptr; i++)
      if(v[i].second >= 0 && uf.unite(rev[i], rev[v[i].second])) res += v[i].first, update = 1;
    if(!update) break;
  }
  return res;
}

