struct SegT {
private:
	int n; vector<LP> node;
public:
	SegT(int n_) {
		n = 1;
		while (n < n_)n *= 2;
		node.resize(2 * n - 1, LP{INF,-1});
	}
	void update(int k, ll x) {
		k += n - 1;
		node[k] = { x,(k - n + 1) };
		while (k > 0) {
			k = (k - 1) / 2;
			if (node[k * 2 + 1].first < node[k * 2 + 2].first) {
				node[k] = node[k * 2 + 1];
			}
			else node[k] = node[k * 2 + 2];
		}
	}
	LP query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		if (r <= a || b <= l)return { INF,-1 };
		if (a <= l && r <= b)return node[k];
		else {
			LP vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
			LP vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
			if (vl.first < vr.first)return vl;
			else return vr;
		}
	}
};

