      es.push_back({A[i] + A[j] + D * abs(i - j), i, j});
    }
    REPI (i, mid, en) {
      int j = mi1.se;
      es.push_back({A[i] + A[j] + D * abs(i - j), i, j});
    }
    conquer(st, mid);
    conquer(mid, en);
  };
