{
    ll n,d;
    cin >> n >> d;
    vll a(n);
    rep(i, n) cin >> a[i];
    SegmentTree seg(infl);
    seg.build(a);
    ll ans = 0;
    UnionFind UF;
    UF.__init__(n);
    ll cnt = n - 1;
    vvll idx(n, vll(2));
    rep(i,n){
        idx[i][0] = i;
        idx[i][1] = i;
    }
    while (cnt>0){
        int k = seg.need();
        ll x = seg.show_one(k);
        //cout << i << " " << k << endl;
        if (seg.show_one(k-1)==infl && seg.show_one(k+1)==infl){
            seg.update(k, infl);
            continue;
        }
        if (seg.show_one(k - 1) < infl)
        {
            ans += seg.show_one(k - 1) + x + d;
            int ry = UF.find(k - 1);
            int rx = UF.find(k);
            seg.update(idx[ry][0], min(x + (k - idx[ry][0]) * d, seg.show_one(idx[ry][0])));
            if (idx[ry][0]<k-1){
                seg.update(k - 1, infl);
            }
            UF.unit(k, k - 1);
            int rz = UF.find(k);
            ll left = min(idx[rx][0], idx[ry][0]);
            ll right = max(idx[rx][1], idx[ry][1]);
            idx[rz][0] = left;
            idx[rz][1] = right;
            cnt--;
        }
        if (seg.show_one(k + 1) < infl)
        {
            ans += seg.show_one(k + 1) + x + d;
            int ry = UF.find(k + 1);
            int rx = UF.find(k);
            seg.update(idx[ry][1], min(x + (idx[ry][1] - k) * d, seg.show_one(idx[ry][1])));
            if (idx[ry][1]>k+1){
                seg.update(k + 1, infl);
            }
            UF.unit(k, k + 1);
            int rz = UF.find(k);
            ll left = min(idx[rx][0], idx[ry][0]);
            ll right = max(idx[rx][1], idx[ry][1]);
            idx[rz][0] = left;
            idx[rz][1] = right;
            cnt--;
        }
        seg.update(k, infl);
    }
    //rep(i, n) cout << seg.show_one(i) << " ";
    //cout << endl;
    cout << ans << endl;
}

