struct UF{
private:
    vector<ll> par,len,you;
public:
    UF(ll n){
        rep(i,0,n){
            par.push_back(i);
            len.push_back(0);
            you.push_back(1);
        }
    }
    ll root(ll n){
        if(par[n]==n)return n;
        else return par[n]=root(par[n]);
    }
    void unit(ll a,ll b){
        a=root(a);
        b=root(b);
        if(a==b)return;
        if(len[a]<len[b]){
            par[a]=b;
            you[b]+=you[a];
        }
        else{
            par[b]=a;
            you[a]+=you[b];
            if(len[a]==len[b])len[a]++;
        }
    }
    ll yo(ll a){
        a=root(a);
        return you[a];
    }
};
