int p[200100];
int r[200100];

void init(int n){
  REP(i, n){
    p[i] = i;
    r[i] = 0;
  }
}

int find(int n) {return (p[n] == n ? n : p[n] = find(p[n]));}

void unite(int x, int y){
  x = find(x);
  y = find(y);
  if(x == y) return;
  if(r[x] < r[y]) p[x] = y;
  else{
    p[y] = x;
    if(r[x] == r[y]) r[x]++;
  }
}

bool same(int x, int y){
  return (find(x) == find(y));
}

int main(){
	int n;
	cin >> n;
	ll d;
	cin >> d;
	ll a[n];
	REP(i, n) cin >> a[i];
	ll ap[n], am[n];
	REP(i, n){
		ap[i] = a[i] + d*i;
		am[i] = a[i] - d*i;
	}
	ll pm[n], mm[n];
	mm[0] = 0;
	REP(i, n-1){
		if(am[i+1] < am[mm[i]]) mm[i+1] = i+1;
		else mm[i+1] = mm[i];
	}
	pm[n-1] = n-1;
	REP(i, n-1){
		if(ap[n-2-i] < ap[pm[n-i-1]]) pm[n-2-i] = n-2-i;
		else pm[n-2-i] = pm[n-1-i];
	}
	vector<edge> e;
	REP(i, n-1) e.pb({mm[i], i+1, ap[i+1]+am[mm[i]]});
	REP(i, n-1){e.pb({n-2-i, pm[n-1-i], ap[pm[n-1-i]]+am[n-2-i]});}
	int E = e.size();
	sort(ALL(e), comp);
	init(n);
	ll ans = 0;
	REP(i, E){
		edge ex = e[i];
		if(!same(ex.u, ex.v)){
			unite(ex.u, ex.v);
			ans += ex.cost;
		}
	}
	cout << ans << endl;
}

