int parent[200005];
int mx[200005],mn[200005];
int sz[200005];

int find_parent(int ver)
{
    if(parent[ver]==ver)
        return ver;
    return parent[ver]=find_parent(parent[ver]);
}

bool merge(int a,int b)
{
    a=find_parent(a);
    b=find_parent(b);
    if(a!=b)
    {
        if(sz[a]<sz[b])
            swap(a,b);
        sz[a]+=sz[b];
        parent[b]=a;
        return true;
    }
    return false;
}

pair<int,int> seg_max[800005],seg_min[800004];

void build(int ver,int tl,int tr)
{
    if(tl>tr)
        return ;
    else if(tl==tr)
    {
        seg_max[ver]={mx[tl],tl};
        seg_min[ver]={mn[tl],tl};
    }
    else
    {
        int tm=(tl+tr)/2;
        build(2*ver,tl,tm);
        build(2*ver+1,tm+1,tr);
        seg_max[ver]=min(seg_max[2*ver],seg_max[2*ver+1]);
        seg_min[ver]=min(seg_min[2*ver],seg_min[2*ver+1]);
    }
}

pair<int,int> get_max(int ver,int tl,int tr,int l,int r)
{
    if(tl>tr||l>r||tr<l||r<tl)
        return {1e17,0};
    else if(tl==l&&tr==r)
        return seg_max[ver];
    else
    {
        int tm=(tl+tr)/2;
        return min(get_max(2*ver,tl,tm,l,min(tm,r)),get_max(2*ver+1,tm+1,tr,max(tm+1,l),r));
    }    
}
pair<int,int> get_min(int ver,int tl,int tr,int l,int r)
{
    if(tl>tr||l>r||tr<l||r<tl)
        return {1e17,0};
    else if(tl==l&&tr==r)
        return seg_min[ver];
    else
    {
        int tm=(tl+tr)/2;
        return min(get_min(2*ver,tl,tm,l,min(tm,r)),get_min(2*ver+1,tm+1,tr,max(tm+1,l),r));
    }    
}


