}
struct lin{
	int u,v;
	ll w;
}line[N*5];
ll check(int i,int j){
	if(i>j)swap(i,j);
	return 1ll*(j-i)*d+a[i]+a[j];
}
bool cmp(lin A,lin B){
	return A.w<B.w;
}
ll ans;
int main(){
	scanf("%d%d",&n,&d);
	for(int i=1;i<=n;i++)scanf("%d",&a[i]),f[i]=i;
	sta[st=1]=1;
	for(int i=2;i<=n;i++){
		int l=1,r=st,m1,m2;
		while(r-l>2){
			m1=l+(r-l)/3;
			m2=m1+(r-l)/3;
			if(check(sta[m1],i)<check(sta[m2],i))r=m2;
			else l=m1;
		}
		int x=l;
		if(check(sta[r],i)<check(sta[x],i))x=r;
		if(check(sta[(l+r)/2],i)<check(sta[x],i))x=(l+r)/2;
		line[++top];
		line[top].u=sta[x];
		line[top].v=i;
		line[top].w=check(sta[x],i);
		while(st&&a[sta[st]]>=a[i])st--;
		sta[++st]=i;
	}
	sta[st=1]=n;
	for(int i=n-1;i>=1;i--){
		int l=1,r=st,m1,m2;
		while(r-l>2){
			m1=l+(r-l)/3;
			m2=m1+(r-l)/3;
			if(check(sta[m1],i)<check(sta[m2],i))r=m2;
			else l=m1;
		}
		int x=l;
		if(check(sta[r],i)<check(sta[x],i))x=r;
		if(check(sta[(l+r)/2],i)<check(sta[x],i))x=(l+r)/2;
		line[++top];
