            e.cost = D * (right_path[i] - i) + A[i] + A[right_path[i]];
            graph.push_back(e);
            if (A[right_path[i]] + D * (right_path[i] - i) < A[i]) {
                is_effective = false;
            }
        }
        if (1 < i) {
            Edge e;
            e.node1 = i;
            e.node2 = left_path[i];
            e.cost = D * (i - left_path[i]) + A[i] + A[left_path[i]];
            graph.push_back(e);
            if (A[left_path[i]] + D * (i - left_path[i]) < A[i]) {
                is_effective = false;
            }
        }
        if (is_effective) {
            if (ef_prev != 0) {
                Edge e;
                e.node1 = ef_prev;
                e.node2 = i;
                e.cost = D * (i - ef_prev) + A[i] + A[ef_prev];
                graph.push_back(e);
            }
            ef_prev = i;
        }
    }



    std::sort(graph.begin(), graph.end(),
        [](const Edge& a, const Edge& b) { return a.cost < b.cost; }
    );

    for (auto e : graph) {
        unite(e.node1, e.node2, e.cost);
