struct quickfind {
  vector<int> par;
  vector<vector<int>> vs;
  quickfind() {}
  quickfind(int n) : par(n), vs(n) {
    REP(i, n) par[i] = i, vs[i].push_back(i);
  }
  int root(int a) { return par[a]==a ? a : par[a] = root(par[a]); }
  bool unite(int a, int b) {
    a = root(a), b = root(b);
    if(a == b) return false;
    if(vs[a].size() > vs[b].size()) swap(a, b);
    par[b] = a;
    for(int x: vs[b]) vs[a].push_back(x);
    vs[b].clear();
    return true;
  }
  int same(int a, int b) { return root(a) == root(b); }
  int size(int a) { return vs[root(a)].size(); }
};

template <typename T>
struct segtree {
  int n;
  vector<T> dat;
  T d;

  segtree(int n_, T d_) : d(d_) {
    n = 1; while(n < n_) n *= 2;
    dat.assign(n*2, d); 
  }
  // [a, b)
  T query(int a, int b, int k, int l, int r) {
    if(r <= a || b <= l) return d;
    if(a <= l && r <= b) return dat[k];
    return min(query(a, b, 2*k+1, l, (l+r)/2),
               query(a, b, 2*k+2, (l+r)/2, r));
  }
  T query(int a, int b) {return query(a, b, 0, 0, n);}
  void update(int i, T v) {
    i += n-1;
    dat[i] = v;
    while(i > 0) {
      i = (i-1)/2;
      dat[i] = min(dat[i*2+1], dat[i*2+2]);
    }
  }
};
