void solve(int l, int r){
    if(l >= r) return;
    int mid = (l+r)/2, f = l, s = mid+1;
    for(int i=l; i<=mid; i++)
        if(arr[i]-D*i < arr[f]-D*f)
            f = i;
    for(int i=mid+1; i<=r; i++)
        if(arr[i]+D*i < arr[s]+D*s)
            s = i;
    for(int i=l; i<=r; i++){
        if(i <= mid) edges.pb(mp(get(i,s),mp(i,s)));
        else edges.pb(mp(get(f,i),mp(f,i)));
    }
    solve(l,mid);
    solve(mid+1,r);
}

inline int root(int node){
    while(node != par[node]){
        par[node] = par[par[node]];
        node = par[node];
    }
    return node;
}

