vector<edge> solve(int l,int r){
    vector<edge> res;
    res.reserve(r-l);
    if(l==r)return res;
    int m=(l+r)/2;
    auto lt=solve(l,m);
    auto rt=solve(m+1,r);
    int mnl=l;
    for(int i=l;i<=m;++i)if(a[i]-d*i<a[mnl]-d*mnl)mnl=i;
    int mnr=r;
    for(int i=m+1;i<=r;++i)if(a[i]+d*i<a[mnr]+d*mnr)mnr=i;
    vector<edge> ltomnr(m-l+1);
    forn(i,sz(ltomnr))ltomnr[i]=edge{l+i,mnr,cost(l+i,mnr)};
    vector<edge> mnltor(r-(m+1)+1);
    forn(i,sz(mnltor))mnltor[i]=edge{mnl,m+1+i,cost(mnl,m+1+i)};
    vector<edge> all;
    all.reserve(sz(lt)+sz(rt)+sz(ltomnr)+sz(mnltor));
    for(edge e:lt)all.pb(e);
    for(edge e:rt)all.pb(e);
    for(edge e:mnltor)all.pb(e);
