        if (pos == 0 || pos == n - 1) continue;
        ksum -= 2 * v;
        LL mincost = 1LL << 60;
        int index = -1;
        REP(k,0,n) {
            bool bo = false;
            REP(l,0,i) {
                if (b[l].second == k) bo = true;
            }
            if (bo) continue;
            if (k == pos) continue;
            // if (abs(pos - k) <= 1) continue;
            LL cost = d * (abs(pos - k)) + a[k] + a[pos];
            if (cost < mincost) {
                mincost = cost;
                index = k;
            }
        }
        //cerr << i << " " << pos << " " << index << endl;
        ksum += mincost;
        tmp += mincost;
    }
    return ksum;
} 

void solve() {
    LL n,d;
    cin >> n >> d;
    VI a(n);
    VP b(n);
    REP(i,0,n) {
        cin >> a[i];
        b[i] = MP(a[i], i);
    }
    if (n == 1) {
        cout << 0 << endl;
        return;
    } else if (n == 2) {
        cout << d + a[0] + a[1] << endl;
        return;
    }
    sort(all(b));
    reverse(all(b));
    LL asum = 0;
    REP(i,0,n) asum += a[i];
    //LL diff = b[0][0] + b[1][0] - a[0] - a[n-1];
    LL sum = asum * 2 - a[0] - a[n-1] + (n - 1) * d;
    int L = 0,  R = n - 2;
    int cnt = 0;
    while (cnt++ < 15 && R - L > 1) {
        int m1 = (R-L)/3 + L, m2 = (R-L)*2/3 + L;
        //dump(L);
        //dump(R);
        //dump(m1);
        //dump(m2);
        //LL lv = f(a,b,L,sum,d,n);
        LL m1v = f(a,b,m1,sum,d,n);
        LL m2v = f(a,b,m2,sum,d,n);
        //dump(m1v);
        //dump(m2v);
        //LL Rv = f(a,b,R,sum,d,n);
        if (m1v > m2v) L = m1;
        else R = m2;
    }
    //dump(L);
    //dump(R);
    LL ans = f(a,b,L,sum,d,n);
    REP(i,L+1-10,R+1+10) {
        if (i < 0 || i >= n - 1) continue;
        ans = min(ans, f(a,b,i,sum,d,n));
        //dump(f(a,b,i,sum,d,n));
    }
    cout << ans << endl;
}

int main() {
    solve();

    return 0;
}

