template<class T=int> class grid_k6 : public undigraph<T> {public:    using undigraph<T>::g;    using undigraph<T>::n;    using undigraph<T>::edges;    using undigraph<T>::usedv;    int H, W;    int eid = 0;    void add(int f, int t, T c = 1, int id = -1, int ty = -1) {        if (!(0 <= f && f < n && 0 <= t && t < n)) {            debugline("grid_k6 add");            deb(f, t, c, id, ty);            ole();        }        g[f].emplace_back(f, t, c, eid++, ty);        g[t].emplace_back(t, f, c, eid++, ty);    }    int getid(int h, int w) {        if (!ins(h, w, H, W))return -1;        return W * h + w;    }    P get2(int id) {        return mp(id / W, id % W);    }    P operator()(int id) {        return get2(id);    }    int operator()(int h, int w) {        return getid(h, w);    }    grid_k6(int H, int W) : H(H), W(W), undigraph<T>(H * W) {        rep(h, H) {            rep(w, W) {                int f = getid(h, w);                if (w + 1 < W) add(f, getid(h, w + 1));                if (h + 1 < H)add(f, getid(h + 1, w));            }        }    }    grid_k6(vector<vector<char>> ba, char wall = '#') : H(sz(ba)), W(sz(ba[0])), undigraph<T>(sz(ba) * sz(ba[0])) {        rep(h, H) {            rep(w, W) {                if (ba[h][w] == wall)con;                int f = getid(h, w);                if (w + 1 < W && ba[h][w + 1] != wall) {                    add(f, getid(h, w + 1));                }                if (h + 1 < H && ba[h + 1][w] != wall) {                    add(f, getid(h + 1, w));                }            }        }    }    void add(int fh, int fw, int th, int tw) {        add(getid(fh, fw), getid(th, tw));    }    void set_edges() {        rep(i, n)fora(e, g[i])edges.push_back(e);    }};
