  int cost[N][N];
  int mincost[N];
  bool used[N];
  for(int i=0; i< N; i++){
    mincost[i] = INT_MAX;
    used[i] = false;
  }

  mincost[0] = 0;
  int res=0;

  for(int u = 0; u < N; u++){
    for(int v = 0; v < N; v++){
      if(u==v){
	cost[v][u]=INT_MAX;
