    int v = -1;
    for(int u = 0; u < N; u++){
      if(!used[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
    }

    if(v == -1) break;
    used[v] = true;
    res += mincost[v];
    for(int u=0; u < N; u++){
      mincost[u] = min(mincost[u], cost[v][u]);
    }
  }
  cout << res <<endl;
  return 0;

}

