struct T {
  E seg[4 * mx];

  E query(int L, int R, int idx, int l, int r) {
    int mid = (l+r)/2, left = 2 * idx + 1, right = 2 * idx + 2;
    if(R < l || L > r) return E{inf, -1};
    if(L <= l && r <= R) return seg[idx];
    return min(query(L, R, left, l, mid), query(L, R, right, mid + 1, r));
  }

  void update(E V, int I, int idx, int l, int r) {
    int mid = (l+r)/2, left = 2 * idx + 1, right = 2 * idx + 2;
    if(l > I || r < I) return;
    if(l == r) {
      seg[idx] = V;
      return;
    }
    update(V, I, left, l, mid); update(V, I, right, mid + 1, r);
    seg[idx] = min(seg[left], seg[right]);
  }
} t1, t2;

int arr[mx];

int root(int x) {
  return x == arr[x] ? x : arr[x] = root(arr[x]);
}

void join(int a, int b) {
  a = root(a);
  b = root(b);
  if(a == b) return;
  arr[a] = b;
}

int U[mx], best[mx];;

long long f(int a, int b, int D) {
  return 1LL * abs(a-b) * D + U[a] + U[b];
}

vector<int> G[mx];

int main () {
