  ans = 0;
  for (int i = 0; i < n; i++) {
    t1.update(E{1LL * i * D + U[i], i}, i, 0, 0, n-1);
    t2.update(E{1LL * (n-1-i) * D + U[i], i}, i, 0, 0, n-1);
  }
  while (ntrees > 1) {
    memset(best, -1, sizeof best);

    for(int i = 0; i < n; i++) G[i].clear();
    for(int i = 0; i < n; i++) {
      G[root(i)].push_back(i);
    }

    for(int i = 0; i < n; i++) {
      for (auto a: G[i]) {
        t1.update({inf, a}, a, 0, 0, n-1);
        t2.update({inf, a}, a, 0, 0, n-1);
      }
      for (auto a: G[i]) {
        E r1 = t1.query(a+1, n-1, 0, 0, n-1);
        r1.x += -1LL*a*D + U[a];
        E r2 = t2.query(0, a-1, 0, 0, n-1);
        r2.x += -1LL*(n-1-a)*D + U[a];

        E r = min(r1, r2);
        int b = r.y;
        if(b == -1) continue;
        if (best[a] == -1 || f(a, best[a], D) > r.x) best[a] = b;
        if (best[b] == -1 || f(b, best[b], D) > r.x) best[b] = a;
      }
      for (auto a: G[i]) {
        t1.update(E{1LL * a * D + U[a], a}, a, 0, 0, n-1);
        t2.update(E{1LL * (n-1-a) * D + U[a], a}, a, 0, 0, n-1);
      }
    }
    for (int i = 0; i < n; i++) {
      if (~best[i]) {
        int a = root(i);
        int b = root(best[i]);
        if(a == b) continue;
        ans += f(a, best[i], D);
        join(a, b);
        ntrees--;
      }
    }
  }
  cout << ans << endl;
}

