struct segTree{
    vector<ll> data, lazy;
    int _n = 1;

    segTree(int n){
        while(n > _n) _n *= 2;
        data.resize(4* _n);
        lazy.resize(4* _n,0);
    }

    void lazy_pro(int p){
        data[p] +=  lazy[p];
        if(p < _n-1){// _n-1  
            lazy[p*2+1] += lazy[p];
            lazy[p*2+2] += lazy[p];
        }
        lazy[p] = 0;
    }

    void add(int a,int b,ll x){
        add(a,b,x,0,0,_n-1);
    }

    void add(int a,int b, ll x,int k, int l, int r){
        if(b < l || r < a){
            lazy_pro(k);
            return;
        }
        if(a <= l && r <= b){
            lazy[k] += x;
            lazy_pro(k);
            return;
        }
        lazy_pro(k);
        add(a,b,x,2*k+1,        l, (l+r)/2);
        add(a,b,x,2*k+2,(l+r)/2+1,       r);
        data[k] = min(data[2*k+1],data[2*k+2]);

    }

    int getMinPos2(int a,int b){

        if(a==b) return a;
        int k = 0;
        ll tmp = getMin(a,b);
        int l = a,r=b;
        while(k < _n -1){
            if(getMin((l+r)/2+1,r) == tmp){
                l = (l+r)/2+1;
                k = 2*k+2;
            }
            else if(getMin(l,(l+r)/2) == tmp){
                r = (l+r)/2;
                k = 2*k+1;
            }

        }
        return l;
    }

    ll getMin(int a, int b){
        return getMin(a,b,0,0,_n-1);
    }

    ll getMin(int a ,int b, int k, int l, int r){
        if(b < l || r < a) return INF;
        if(a <= l && r <= b){ 
            lazy_pro(k);
            return data[k];
        }
        else{
            lazy_pro(k);
            ll vl = getMin(a,b,2*k+1,        l,(l+r)/2);
            ll vr = getMin(a,b,2*k+2,(l+r)/2+1,      r);
            return min(vl,vr);
        }
    }
};

class Unionfind{
public:
    vector<int> par,rank;

    Unionfind(int n){
        par.resize(n);
        rank.resize(n);
        rep(i,n){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int x){
        if(par[x]==x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x,int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(int x,int y){
        return find(x) == find(y);
    }
};

