struct LazySegmentTree{
    int n, width;
    vector<PL> dat;
    VL lazy;
    const PL INF = PL(1e18, 1e9);
    const ll INFLL = 1e17;

    LazySegmentTree(VL v){
        int n = v.size();
        width = 1;
        while (width < n) width *= 2;
        dat.assign(2 * width - 1, INF);
        lazy.assign(2 * width - 1, 0);
        REP(i,n) dat[i + width - 1] = PL(v[i], i);
        FORR(i,width-2,0) dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
    }

    void eval(int k, int l, int r){
        dat[k].first = min(INFLL, dat[k].first + lazy[k]);
        if (r - l > 1){
            lazy[2 * k + 1] = min(INFLL, lazy[2 * k + 1] + lazy[k]);
            lazy[2 * k + 2] = min(INFLL, lazy[2 * k + 2] + lazy[k]);
        }
        lazy[k] = 0;
    }

    void add(int a, int b, ll x, int k, int l, int r){
        eval(k, l, r);
        if (r <= a || b <= l) return;
        if (a <= l && r <= b){
            lazy[k] += x;
            eval(k, l, r);
        }else{
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    // [l, r) += x
    void add(int l, int r, ll x){
        add(l, r, x, 0, 0, width);
    }

    PL query(int a, int b, int k, int l, int r){
        eval(k, l, r);
        if (r <= a || b <= l) return INF;
        if (a <= l && r <= b) return dat[k];
        PL vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        PL vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }

    PL query(int l, int r){
        return query(l, r, 0, 0, width);
    }
};

