        now+=d;
    }
    ss.clear();
    now=d; ss.insert(P(a[n],n));
    for(ll i=n-1;i>=1;i--)
    {
        auto it=ss.begin();
        ll to=it->S,cost=it->F;
        add_edge(i,to,cost+now+a[i]);
        ss.insert(P(a[i]-now,i));
        now+=d;
    }
    V=n; printf("%lld\n",kruskal());
    return 0;
}

