struct UnionFind {
    vector<int> data;

    UnionFind(int size) : data(size, -1) {}

    UnionFind() {}

    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
            //cout << x << " " << y << endl;
        }
        return x != y;
    }

    bool findSet(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    int size(int x) {
        return -data[root(x)];
    }
};


UnionFind uf;

set<pair<ll, ll> > S;

void add(ll x, ll v, ll dsum) {
    S.insert({v - dsum, x});
}

long long INF = 1e18;

pair<ll, ll> find_min(ll x, ll dsum) {
    pair<ll, ll> r;
    auto it = S.begin();

    while (it != S.end()) {
        if (uf.findSet(x, it->second)) {
            ++it;
        } else {
            r = *it;
            break;
        }
    }
    if( it == S.end() ) return {INF, INF};
    return {r.first + dsum + A[x], r.second};
}

void init(){
    S.clear();
}

bool one_step(ll &ans){
    init();
    vector< pair<ll,ll> > seq1, seq2;

    for (int i = 0; i < A.size(); i++) {
        auto r = find_min(i, i * D);
        seq1.push_back(r);
        add(i, A[i], i * D);
    }

    init();
    reverse(A.begin(), A.end());
    {
        for (int i = 0; i < A.size(); i++) {
            auto r = find_min(i, i * D);
            seq2.emplace_back(r.first, A.size() - r.second - 1);
            add(i, A[i], i * D);
        }
        reverse(seq2.begin(), seq2.end());
    }
    reverse(A.begin(), A.end());

    bool upd = false;
    map<int,pair<ll,pair<ll,ll>>> minv;

    for(int i = 0 ; i < seq1.size() ; i++) {
        auto p = min(seq1[i], seq2[i]);
        if (minv.count(uf.root(i)) == 0 || minv[uf.root(i)].first > p.first) {
            minv[uf.root(i)] = {p.first, {i, p.second}};
        }
