public:
    vector<int> par,rank;

    Unionfind(int n){
        par.resize(n);
        rank.resize(n);
        rep(i,n){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int x){
        if(par[x]==x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x,int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(int x,int y){
        return find(x) == find(y);
    }
};

struct RMQ{
    vector< pair<ll,int> > node;
    int n=1;

    void init(int x){
        while(n < x){
            n *= 2;
        }
        node.resize(4*n,{1000000000000000,-1});
    }

    void update(int s,ll x){
        int i = s + n - 1;

        node[i].first = x;
        node[i].second = s;

        while(i > 0){
            i = (i-1)/2;
            node[i].first = min(node[2*i+1].first,node[2*i+2].first);
            if(node[2*i+1].first > node[2*i+2].first)
                node[i].second = node[2*i+2].second; 
            else 
                node[i].second = node[2*i+1].second; 
        }
    }

    pair<ll,int> getMin(int a, int b){
        return getMin(a,b,0,0,n-1);
