ll solve(PriorityQueue q) {
    ll acc = 0;

    while (!q.empty()) {
        pair<int, ll> edge = q.top();
        int dest = edge.first;
        ll cost = edge.second;
        q.pop();
        if (visited[dest]) continue;

        visited[dest] = true;
        acc += cost;
        for (int i = 0; i < (int) edges[dest].size(); i++) {
            q.push(edges[dest][i]);
        }
    }

    return acc;
}

