	for (int i = 0; i < N; i++) {
		lsg.Insert(i, v[i] + (N - 1 - i)*K, false);
	}
	lsg.TopDown();
	for (int i = 0; i < N; i++) {
		rsg.Insert(i, v[i] + i * K, false);
	}
	rsg.TopDown();
	pair<long long int, int>box = { (N - 1)*K + v[0],0 };
	map<long long int, vector<int>>lm;
	for (int i = N - 1; i > 0; i--) {
		lm[lsg.RMQ(i, i)].push_back(i);
	}
	map<long long int, vector<int>>rm;
	for (int i = 0; i < N - 1; i++) {
		rm[rsg.RMQ(i, i)].push_back(i);
	}
	for (int i = 1; i < N; i++) {
		lm[lsg.RMQ(i, i)].pop_back();
		Edge add;
		add.a = i;
		add.b = box.second;
		add.cost = box.first + v[i] - K * (N - i - 1);
		cerr << add.a << " " << add.b << endl;
		edge.emplace_back(add);
		long long int cost = lsg.RMQ(i + 1, N - 1);
		if (cost == LLONG_MAX)continue;
		int index = lm[cost].back();
		add.b = index;
		add.cost = box.first + v[index] - K * (N - index - 1);
		edge.emplace_back(add);
		if (box.first >= v[i] + (N - 1 - i)*K) {
			box = { v[i] + (N - 1 - i)*K,i };
		}
	}
	box = { v.back() + (N - 1)*K,N - 1 };
	for (int i = N - 2; i >= 0; i--) {
		rm[rsg.RMQ(i, i)].pop_back();
		Edge add;
		add.a = i;
		add.b = box.second;
		add.cost = box.first + v[i] - K * i;
		cerr << add.a << " " << add.b << endl;
		edge.emplace_back(add);
		long long int cost = rsg.RMQ(0, i - 1);
		if (cost == LLONG_MAX)continue;
		int index = rm[cost].back();
		add.b = index;
		add.cost = box.first + v[index] - K * index;
		edge.emplace_back(add);
		if (box.first >= v[i] + K * i) {
			box = { v[i] + K * i,i };
		}
	}
	sort(edge.begin(), edge.end());
	UnionFind uf(N);
	long long int ans = 0;
	for (auto i : edge) {
		if (uf.Check_Same(i.a, i.b))continue;
		cerr << i.a << " " << i.b << endl;
		ans += i.cost;
		uf.Unite(i.a, i.b);
	}
	cout << ans << endl;
	return 0;
}

#include "bits/stdc++.h"

using namespace std;

struct edge {long to, cost;};

struct UnionFind
{
	//number of parents(par[i] = i => root)
	vector<int> par;
	//rank of tree
	vector<int> rank;

	UnionFind(int n) : par(n), rank(n, 1)
	{
		//initialize
		for (int i = 0; i < n; i++) par[i] = i;
	}

	//find root (keiroasshuku at the same time)
	int root(int x)
	{
		if (par[x] == x)
			return x;
		else
			return par[x] = root(par[x]);
	}

	//unite
	void unite(int x, int y)
	{
		x = root(x);
		y = root(y);
		if (x == y)
			return;
		if (rank[x] > rank[y])
			swap(x, y);
		par[x] = y;
		rank[y] += rank[x];
	}

	//same tree?
	bool same(int x, int y)
	{
		return root(x) == root(y);
	}
};

struct Edge
{
	long from, to, cost;

	// コストの大小で順序定義
	bool operator<(const Edge &o) const
	{
		return cost < o.cost;
	}
};

struct Kruskal
{
	int V; // number of nodes
	vector<Edge> edges;

	Kruskal(int v)
	{
		V = v;
	}

	// グラフが非連結のときは最小全域森のコストの和となる
	long calc()
	{
		//init
		UnionFind uf(V);
		sort(edges.begin(), edges.end());
		long min_cost = 0L;

		for (Edge e : edges)
		{
			if (!uf.same(e.from, e.to))
			{
				min_cost += e.cost;
				uf.unite(e.from, e.to);
			}
		}
		return min_cost;
	}
};

void solve()
{
	long N, D;
	cin >> N >> D;
	priority_queue<pair<long, long>, vector<pair<long, long>>, greater<pair<long, long>>> q;
	vector<edge> graph[2*N];
	for (int i = 0; i < N; i++)
	{
		long A; cin >> A;
		if (i != N-1)
		{
			graph[i+N].push_back({i+N+1, D});
			graph[i+N+1].push_back({i+N, D});
		}
		graph[i].push_back({i+N, A});
		graph[i+N].push_back({i, A});
		q.push({0, i});
	}

	Kruskal kruskal(N);

	vector<long> dist(2*N, 1e18), par(2*N, -1);
	for (int i = 0; i < N; i++)
	{
		par[i] = i;
		dist[i] = 0;
	}
	bitset<400040> vst;

	while(!q.empty())
	{
		auto p = q.top(); q.pop();
		long v = p.second, d = p.first;
		vst[v] = 1;
		for (auto e : graph[v])
		{
			long nv = e.to;
			if (vst[nv])
			{
				kruskal.edges.push_back({par[v], par[nv], dist[v] + dist[nv] + e.cost});
				//cout << par[v] << ' ' << par[nv] << ' ' << dist[v] << ' ' << dist[nv] << ' ' << e.cost << endl;
			}
			else
			{
				if (dist[nv] > d + e.cost)
				{
					par[nv] = par[v];
					dist[nv] = d + e.cost;
					q.push({d + e.cost, nv});
				}
			}
		}
	}

	cout << kruskal.calc() << endl;
}

int main(void)
{
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

