int walk(int o,int l,int r) {
    if (l==r) {ans+=T[o].mn; T[o].tag=-1; T[o].mn=T[o].l=T[o].r=1e17; return l;}
    if (T[o].tag!=2) {
        if (T[lc].tag!=-1) {
            T[lc].tag=T[o].tag; T[lc].del=T[o].del;
            T[lc].mn=qmin(l,mid,T[o].tag)+T[o].del;
            T[lc].l=f[l][T[o].tag][0]+T[o].del; T[lc].r=f[mid][T[o].tag][0]+T[o].del;
        }
        if (T[rc].tag!=-1) {
            T[rc].tag=T[o].tag; T[rc].del=T[o].del;
            T[rc].mn=qmin(mid+1,r,T[o].tag)+T[o].del;
            T[rc].l=f[mid+1][T[o].tag][0]+T[o].del; T[rc].r=f[r][T[o].tag][0]+T[o].del;
        }
        T[o].tag=2; T[o].del=0;
    }
    int pos;
    if (T[lc].mn==T[o].mn) {
        pos=walk(lc,l,mid);
        if (T[rc].l<1e17&&T[rc].l>a[pos]+a[mid+1]+(mid+1ll-pos)*D) change_r(rc,mid+1,r,1,a[pos]-1ll*pos*D);
    } else {
        pos=walk(rc,mid+1,r);
        if (T[lc].r<1e17&&T[lc].r>a[pos]+a[mid]+1ll*(pos-mid)*D) change_l(lc,l,mid,0,a[pos]+1ll*pos*D);
    }
    T[o].mn=min(T[lc].mn,T[rc].mn);
    T[o].l=T[lc].l; T[o].r=T[rc].r;
    return pos;
}
