int Merge(int v, int u)
{
    v = Root(v), u = Root(u);
    if (v == u) return 0;
    if (sz[v] < sz[u])
    {
        sz[u] += sz[v];
        root[v] = u;
    }
    else
    {
        sz[v] += sz[u];
        root[u] = v;
    }
    return 1;
}

void call(int l, int r)
{
    if (l + 1 == r) return;
    int m = (l + r) / 2;
    int id1 = l, id2 = m;
    for (int i = l; i < m; i++)
    {
        if (a[i] - i * D < a[id1] - id1 * D) id1 = i;
    }
    for (int i = m; i < r; i++)
    {
        if (a[i] + i * D < a[id2] + id2 * D) id2 = i;
    }
    for (int i = l; i < r; i++)
    {
        edges.push_back({i, id1, a[i] + a[id1] + abs(id1 - i) * D});
        edges.push_back({i, id2, a[i] + a[id2] + abs(id2 - i) * D});
    }
    call(l, m);
    call(m, r);
}

