struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

using pint = pair<int,int>;
using Edge = pair<long long,pint>;

// 入力
int N;
long long D;
vector<long long> A;

// 分割統治法
vector<Edge> edges;
void rec(int left, int right) {
    if (right - left <= 1) return;
    int mid = (left + right) / 2;

    long long leftmin = 1LL<<60;
    int leftminp = -1;
    for (int i = left; i < mid; ++i) if (chmin(leftmin, A[i]-D*i)) leftminp = i;
    long long rightmin = 1LL<<60;
    int rightminp = -1;
    for (int i = mid; i < right; ++i) if (chmin(rightmin, A[i]+D*i)) rightminp = i;

    for (int i = left; i < mid; ++i)
        edges.push_back(Edge(A[rightminp] + A[i] + D * (rightminp - i), pint(i, rightminp)));
    for (int i = mid; i < right; ++i)
        edges.push_back(Edge(A[leftminp] + A[i] + D * (i - leftminp), pint(leftminp, i)));

    rec(left, mid);
    rec(mid, right);
}

int main() {
    cin >> N >> D;
    A.resize(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    // 分割統治法
    edges.clear();
    rec(0, N);

    // Kruskal
    UnionFind uf(N);
    sort(edges.begin(), edges.end());
    long long res = 0;
    for (auto e : edges) {
        long long w = e.first;
        int u = e.second.first, v = e.second.second;
        if (uf.issame(u, v)) continue;
        res += w;
        uf.merge(u, v);
    }
    cout << res << endl;
}

