vector<ll> Right, Left;
vector<ll> Rmin, Lmin;
struct UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<ll> Size;
    vector<ll> l, r, Lmin, Rmin;
    UnionFind(int n = 1) {
        init(n);
    }

    void init(int n = 1) {
        par.resize(n + 1); rank.resize(n + 1); Size.resize(n + 1);
        for (int i = 0; i <= n; ++i) par[i] = i, rank[i] = 0, Size[i] = 1;
        l.resize(n);
        r.resize(n);
        Lmin.resize(n);
        Rmin.resize(n);
        for(int i = 0; i < N; i++) {
            l[i] = i;
            r[i] = i;
            Lmin[i] = Left[i];
            Rmin[i] = Right[i];
        }
    }

    int root(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            int r = root(par[x]);
            return par[x] = r;
        }
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        par[y] = x;
        Size[x] += Size[y];
        chmin(l[x], l[y]);
        chmax(r[x], r[y]);
        chmin(Lmin[x], Lmin[y]);
        chmin(Rmin[x], Rmin[y]);
        return true;
    }

    ll size(int x){
        return Size[root(x)];
    }
};

