        Right[i] = A[i] + i * D;
        Left[i] = A[i] - i * D;
    }
    Lmin[0] = 0;
    for(int i = 1; i < N; i++) {
        Lmin[i] = Lmin[i-1];
        if(Left[i] < Left[Lmin[i]]) Lmin[i] = i;
    }
    Rmin[N-1] = N-1;
    for(int i = N - 2; i >= 0; i--) {
        Rmin[i] = Rmin[i+1];
        if(Right[i] < Right[Rmin[i]]) Rmin[i] = i;
    }
