        if(L > 0) {
            ll idx = Lmin[L - 1];
            //cerr << "L:" << L << " " << idx << endl;
            ll nowval = Left[idx] + uni.Rmin[uni.root(i)];
            if(chmin(val, nowval)) to = idx;
        }
        ll R = uni.r[uni.root(i)];
        if(R < N - 1) {
            ll idx = Rmin[R + 1];
            ll nowval = Right[idx] + uni.Lmin[uni.root(i)];
            //cerr << "R:" << R << " " << idx << " " << nowval << endl;
            if(chmin(val, nowval)) to = idx;
        }
        //cerr << i << " " << to << " " << val << endl;
        ans += val;
        uni.merge(i, to);
    }
    cout << ans << endl;
    return 0;
}

