using namespace std;

class UF {
private:
  vector<int> data; // parent or size
  vector<int> next;
  vector<int> last;
  void init(int n) {
    data.assign(n, -1);
    next.assign(n, -1);
    last.resize(n);
    for (int i = 0; i < n; ++i) {
      last[i] = i;
    }
  }

public:
  UF() {}
  UF(int n) {
    init(n);
  }
  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y); // data[x] and data[y] are negative.
    data[x] += data[y];
    data[y] = x;
    next[last[x]] = y;
    last[x] = last[y];
    return true;
  }
  int size(int x) {
    return -data[root(x)];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int get_next(int x) {
    return next[x];
  }
};

struct Monoid_Struct {
  using T = pair<int, ll>; // type or class of monoid
  T operator()(const T& left, const T& right) {
    return left.second < right.second ? left : right; // definition of operator
  }
  static constexpr T identity() { return (pair<int, ll>){-1, LLONG_MAX}; }
};

template<class Monoid>
class SegTree {
private:
  using T = typename Monoid::T;
  Monoid op;
  const int n;
  vector<T> t;

  void propagate_to(int i) { t[i] = op(t[2*i], t[2*i+1]); }

public:
  SegTree(int n_) : n(n_), t(2*n, op.identity()) {}
  SegTree(const vector<T>& v) : n(v.size()), t(2*n) {
    copy(begin(v), end(v), begin(t) + n);
    for (int i = n-1; i > 0; --i) {
      propagate_to(i);
    }
  }

  void set(int i, const T& x) {
    t[i += n] = x;
    while (i >>= 1) {
      propagate_to(i);
    }
  }

  T get(int i) { return t[i + n]; }

  T accumulate(int l, int r) {
    T accl = op.identity(), accr = op.identity();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) accl = op(accl, t[l++]);
      if (r & 1) accr = op(t[r-1], accr);
    }
    return op(accl, accr);
  }
};

int main() {
  ll n, d;
  scan(n, d);
  vll a(n);
  scan(a);
  vector<pair<int, ll> > lefts(n), rights(n);
  rep (i, n) {
    lefts[i].first = i;
    rights[i].first = i;
    lefts[i].second = a[i] + d * (n-1 - i);
    rights[i].second = a[i] + d * i;
  }
  SegTree<Monoid_Struct> seg_left(lefts), seg_right(rights);

  vvi ai(n, vi(2));
  rep (i, n) {
    ai[i][0] = a[i];
    ai[i][1] = i;
  }
  sort(all(ai));
  reverse(all(ai));

  vvll edges;
  ll INF = LLONG_MAX / 2;

  rep (ind, n) {
    int i = ai[ind][1];
    if (i != 0) {
      int left_node = seg_left.accumulate(0, i).first;
      ll left_cost = a[i] + a[left_node] + d * (i - left_node);
      edges.push_back({left_cost, left_node, i});
    }
    if (i != n-1) {
      int right_node = seg_right.accumulate(i+1, n).first;
      ll right_cost = a[i] + a[right_node] + d * (right_node - i);
      edges.push_back({right_cost, i, right_node});
    }
    seg_left.set(i, {i, INF});
    seg_right.set(i, {i, INF});
  }
  sort(all(edges));
  UF uf(n);
  ll ans = 0;
  for (auto && edge : edges) {
    if (uf.same(edge[1], edge[2])) { continue; }
    uf.unite(edge[1], edge[2]);
    ans += edge[0];
  }
  print(ans);

  return 0;
}

