struct Val {
  ll value; int i;

  Val() : value(INFLL), i(-1) {}
  Val(ll value, int i) : value(value), i(i) {}

};

bool operator<(const Val &a, const Val &b) {
  return a.value < b.value;
}

class SegmentTree {
  Val inf = Val();
  Val *ldata;
  Val *rdata;
  int *p, *q;
  int n0;

  void __update(Val *data, int k, ll x) {
    Val v = Val(x, k);
    k += n0-1;
    data[k] = v;
    while(k) {
      k = (k - 1) >> 1;
      data[k] = min(data[2*k+1], data[2*k+2]);
    }
  }

public:
  SegmentTree(int n) {
    n0 = 1;
    while(n0 < n) n0 <<= 1;
    ldata = new Val[2*n0];
    rdata = new Val[2*n0];


    p = new int[n0+1];
    q = new int[n0+1];
    int z;
    rep(x, n0+1) {
      int y = n0 + x;
      z = (y / (y & -y)) >> 1;
      p[x] = z ? 2*z-1 : 0;
      z = (y / (y & -y));
      q[n0-x] = z-1;
    }
  }

  void lupdate(int k, ll x) {
    __update(ldata, k, x);
  }

  void rupdate(int k, ll x) {
    __update(rdata, k, x);
  }

  Val lquery(int r) {
    Val v = inf;
    while(r) {
      v = min(v, ldata[p[r]]);
      r -= r & -r;
    }
    return v;
  }

  Val rquery(int l) {
    Val v = inf;
    int r = n0 - l;
    while(r) {
      v = min(v, rdata[q[r]]);
      r -= r & -r;
    }
    return v;
  }
};

int parent[N];
int root(int x) {
  if(x == parent[x]) {
    return x;
  }
  return parent[x] = root(parent[x]);
}

bool unite(int x, int y) {
  int px = root(x), py = root(y);
  if(px == py) return false;

  if(px < py) {
    parent[py] = px;
  } else {
    parent[px] = py;
  }
  return true;
};

