      ll c = p.value - d*(n-1-j);
      es.push_back(Edge(c + a[j], P(p.i, j)));
    }
    Val q = st.rquery(j+1);
    if(q.i != -1) {
      ll c = q.value - d*j;
      es.push_back(Edge(c + a[j], P(j, q.i)));
    }
    st.lupdate(j, d*(n-1-j) + a[j]);
    st.rupdate(j, d*j + a[j]);
  }

