    for(int i = 1;i <= n;i++) {
#ifndef TEST
        cin >> a[i];
#else
        a[i] = rnd() % 100 + 1;
#endif
        p[i] = i;
    }

    vector< pair< ll, pii > > ed;
    set< pair< ll, int > > top;

    top.clear();
    for(int i = 1;i <= n;i++) {
        int ptr = 0;
        for(auto it = top.begin();it != top.end() && ptr < 40;it++, ptr++) {
            int j = it->second;
            ed.push_back({1ll * abs(i - j) * d + a[i] + a[j], {i, j}});
        }
