using namespace std;
typedef long long ll;
typedef pair<ll,int> pli;
#define fir first
#define sec second
#define Mp make_pair
const int MAXN = 2e5 + 5;
const int N = 262144;
const int inf = 0x3f3f3f3f;
const ll linf = 0x3f3f3f3f3f3f3f3f;

template<typename T>
void chk_min(T &a,T b){ if(a>b) a=b;}

struct Segment_Tree
{
	pli mn[(N<<1)+5];
	Segment_Tree(void){ for(int i=0; i<=(N<<1); ++i) mn[i] = Mp(linf,inf);}
	#define ls(u) ((u)<<1)
	#define rs(u) ((u)<<1|1)
	void update(int q,ll k)
	{
		mn[q+N] = Mp(k,q);
		q+=N;
		while(q>>=1)
			mn[q] = min(mn[ls(q)], mn[rs(q)]);
	}
	pli query(int l,int r)
	{
		pli res(linf,inf);
		for(l+=N-1,r+=N+1; l^r^1; l>>=1, r>>=1)
		{
			if(~l&1) chk_min(res, mn[l^1]);
			if( r&1) chk_min(res, mn[r^1]);
		}
		return res;
	}
};

struct Union_Find
{
	int fa[MAXN],sz[MAXN];
	inline void init(int n){ for(int i=1; i<=n; ++i) fa[i]=i, sz[i]=1;}
	int find(int u){ return fa[u]==u? u: fa[u]=find(fa[u]);}
	bool connect(int u,int v)
	{
		int fu=find(u), fv=find(v);
		if(fu==fv) return 0;
		sz[fv]+=sz[fu]; fa[fu]=fv;
		return 1;
	}
	inline int size(int u){ return sz[find(u)];}
};

struct Edge
{
	int u,v;
	ll w;
	inline friend bool operator < (const Edge &p,const Edge &q){ return p.w<q.w;}
};

int a[MAXN];
ll lval[MAXN],rval[MAXN];
Segment_Tree lmn,rmn;
Union_Find uf;
vector<int> p[MAXN];
vector<Edge> mnE;

int main(void)
{
	int n;	
	ll d;
	scanf("%d%lld",&n,&d);
	for(int i=1; i<=n; ++i) scanf("%d",&a[i]);

	for(int i=1; i<=n; ++i)
		lval[i] = a[i] - d*i,
		rval[i] = a[i] + d*i;

	for(int i=1; i<=n; ++i)
		lmn.update(i,lval[i]),
		rmn.update(i,rval[i]);

	uf.init(n);
	ll ans=0;
	while(uf.size(1)<n)
	{
		for(int i=1; i<=n; ++i) p[i].clear();
		for(int i=1; i<=n; ++i)
			p[uf.find(i)].push_back(i);

		mnE.clear();
		for(int k=1; k<=n; ++k)
		{
			if(uf.find(k)!=k) continue;
			vector<int> &vec = p[k];

			for(int i=0; i<(int)vec.size(); ++i)
				lmn.update(vec[i], linf),
				rmn.update(vec[i], linf);

			Edge now = (Edge){-1,-1,linf};
			for(int i=0; i<(int)vec.size(); ++i)
			{
				int u=vec[i];
				pli res;
				Edge tmp;

				res = lmn.query(1,u);
				tmp = (Edge){ res.sec, u, res.fir + rval[u]};
				if(tmp<now) now=tmp;

				res = rmn.query(u,n);
				tmp = (Edge){ u, res.sec, lval[u] + res.fir};
				if(tmp<now) now=tmp;
			}

			mnE.push_back(now);

			for(int i=0; i<(int)vec.size(); ++i)
				lmn.update(vec[i], lval[vec[i]]),
				rmn.update(vec[i], rval[vec[i]]);
		}

		for(int i=0; i<(int)mnE.size(); ++i)
		{
			int u=mnE[i].u, v=mnE[i].v;
			ll w=mnE[i].w;
			if(uf.connect(u,v)) ans += w;
		}
	}
	printf("%lld",ans);
	return 0;
}

