struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};
int N;
ll D;
vector<ll> A;
vector<tuple<ll, int, int>> edges;

void rec(int left, int right){
    if(right - left <= 1) return;
    int mid = (left + right) >> 1;

    ll lmin = LINF;
    int lmidx = -1;
    for(int i=left;i<mid;i++) if(chmin(lmin, A[i]-D*i)) lmidx = i;
    ll rmin = LINF;
    int rmidx = -1;
    for(int i=mid;i<right;i++) if(chmin(rmin, A[i]+D*i)) rmidx = i;

    for(int i=left;i<mid;i++) edges.emplace_back(A[i] + A[rmidx] + D * (rmidx - i), i, rmidx);
    for(int i=mid;i<right;i++) edges.emplace_back(A[i] + A[lmidx] + D * (i - lmidx), lmidx, i);

    rec(left, mid);
    rec(mid, right);
}

int main(){
