    ll res = 0;
    sort(edges.begin(), edges.end());

    for(auto e : edges){
        ll w, u, v;
        tie(w, u, v) = e;
        if(uf.issame(u, v)) continue;
        res += w;
        uf.unite(u, v);
    }
    cout << res << endl;
}

