			T[rt]=mp(a[l]+1ll*l*D,l);
			return;
		}
		int m=l+r>>1;
		build(l,m,rt<<1);
		build(m+1,r,rt<<1|1);
		T[rt]=min(T[rt<<1],T[rt<<1|1]);
	}
	void upd(int l,int r,int rt,int x,LL y){
		if (l==r){
			T[rt]=mp(y,x);
			return;
		}
		int m=l+r>>1;
		if (x<=m) upd(l,m,rt<<1,x,y);
		else upd(m+1,r,rt<<1|1,x,y);
		T[rt]=min(T[rt<<1],T[rt<<1|1]);
	}
	pa que(int l,int r,int rt,int L,int R){
		if (l>=L && r<=R) return T[rt];
		int m=l+r>>1;
		pa t=mp(INF,0);
		if (L<=m) t=min(t,que(l,m,rt<<1,L,R));
		if (R>m) t=min(t,que(m+1,r,rt<<1|1,L,R));
		return t;
	}
};
//T1 -
//T2 +
void ins(int x,int tp){
	if (tp==1){
		if (x>1){
			pa tmp=T1::que(1,n,1,1,x-1);
			if (tmp.fi>=INF) return;
			if (tmp.se<1 || tmp.se>n || u[tmp.se]) return;
			tmp.fi+=1ll*x*D+a[x];
			Q.push(mp(tmp,x));
		}
	}
	else{
		if (x<n){
			pa tmp=T2::que(1,n,1,x+1,n);
			if (tmp.fi>=INF) return;
			if (tmp.se<1 || tmp.se>n || u[tmp.se]) return;
			tmp.fi+=a[x]-1ll*x*D;
			Q.push(mp(tmp,x));
		}
	}
}
void prim(){
	T1::build(1,n,1);
	T2::build(1,n,1);
	u[1]=1;
	T1::upd(1,n,1,1,INF);
	T2::upd(1,n,1,1,INF);
	ins(1,1);
	ins(1,2);
	while (!Q.empty()){
		pair<pa,int> t=Q.top();
		Q.pop();
		LL c=t.fi.fi;
		int y=t.fi.se;
		int x=t.se;
		int tp=2;
		if (x>y) tp=1;
		if (u[y]){
			ins(x,tp);
			continue;
		}
		u[y]=1;
		ans+=c;
		T1::upd(1,n,1,y,INF);
		T2::upd(1,n,1,y,INF);
		ins(x,tp);
		ins(y,1);
		ins(y,2);
	}
}
int main(){
	cin>>n>>D;
	FOR(i,1,n) getint(a[i]);
	prim();
	cout<<ans<<endl;
	return 0;
}

