pair<Weight, Edges> VoronoiMST(const Graph &G1,const vint &S,Graph &G2){
  int N = S.size();
  G2.resize(N);
  Weight total=0;
  Edges F;
  priority_queue<Edge> Q;
  vint dist(G1.size(),0),used(G1.size(),0),from(G1.size(),-1);
  repeat(i,N){
    Q.push({-1,S[i],0});
    from[S[i]]=i;
  }
  int cnt=1;
  while(!Q.empty()){
    Edge e=Q.top();Q.pop();
    int v = e.dst;
    if(used[v]){
      if(used[v]>used[e.src]){
        total += dist[v]+e.weight;
        F.push_back({from[v],from[e.src],dist[v]+e.weight});
        G2[from[v]].push_back({from[v],from[e.src],dist[v]+e.weight});
        G2[from[e.src]].push_back({from[e.src],from[v],dist[v]+e.weight});
      }
      continue;
    }
    used[v]=cnt;
    cnt++;
    dist[v] = e.weight;
    from[v] = from[e.src];
    for(Edge f:G1[v]){
      Q.push({v,f.dst,dist[v]+f.weight});
    }
  }
  return make_pair(total,F);
