template <class T> struct greater {
	bool operator() (const T& x, const T& y) const { return x>y; }
	typedef T first_argument_type;
	typedef T second_argument_type;
	typedef bool result_type;
};

ll MSTcost()
{
	priority_queue<pll, vector<pll>, greater<pll> > pile;
	vl used(ed.size(), 0);
	ll cost = 0;
	pile.push(make_pair(0, 0));
	while (pile.size())
	{
		pair<ll, ll> cur;
		cur = pile.top();
		pile.pop();
		if (used[cur.second])
			continue;
		used[cur.second] = 1;
		cost += cur.first;
		for (pair<ll, ll> edge : ed[cur.second])
		{
			if (used[edge.second])
				continue;
			pile.push(edge);
		}
	}
	cost;
	return cost;
}

