struct UnionFind {
    vector<int> A;
    UnionFind(int n) : A(n, -1) {}
    int find(int x) {
        if (A[x] < 0) return x;
        return A[x] = find(A[x]);
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return;
        if (A[x] > A[y]) swap(x, y);
        A[x] += A[y];
        A[y] = x;
    }
};
template <class T>
struct SegTreeMin {
    vector<T> A;
    int N;
    T minval;
    SegTreeMin(int n, T minv) : minval(minv) {
        N = 1;
        while (N < n) N *= 2;
        A.assign(2*N, minval);
    }
    void set(int idx, T val) {
        idx += N;
        A[idx] = val;
        for (idx /= 2; idx > 0; idx /= 2) {
            A[idx] = min(A[2*idx+0], A[2*idx+1]);
        }
    }
    T query(int L, int R) { // [L, R)
        L += N, R += N;
        T ans = minval;
        while (L < R) {
            if (R & 1) ans = min(ans, A[--R]);
            if (L & 1) ans = min(ans, A[L++]);
            L /= 2, R /= 2;
        }
        return ans;
    }
};
