pair<ll, ll> find_min(ll x, ll dsum) {
    auto it = S.begin();
    while (it != S.end()) {
        if( mn[uf.root(it->second)] != *it ){
            it = S.erase(it);
            continue;
        }
        if (uf.findSet(x, it->second)) {
            ++it;
        } else {
            break;
        }
    }
    if( it == S.end() ) return {INF, INF};
    return {it->first + dsum + A[x], it->second};
}

