bool one_step(ll &ans){
    init();
    vector< pair<ll,ll> > seq1, seq2;

    for (int i = 0; i < A.size(); i++) {
        auto r = find_min(i, i * D);
        seq1.push_back(r);
        add(i, A[i], i * D);
    }

    init();
    reverse(A.begin(), A.end());
    {
        for (int i = 0; i < A.size(); i++) {
            auto r = find_min(i, i * D);
            seq2.emplace_back(r.first, A.size() - r.second - 1);
            add(i, A[i], i * D);
        }
        reverse(seq2.begin(), seq2.end());
    }
    reverse(A.begin(), A.end());

    bool upd = false;
    map<int,pair<ll,pair<ll,ll>>> minv;

    for(int i = 0 ; i < seq1.size() ; i++) {
        auto p = min(seq1[i], seq2[i]);
        if (minv.count(uf.root(i)) == 0 || minv[uf.root(i)].first > p.first) {
            minv[uf.root(i)] = {p.first, {i, p.second}};
        }
    }
    for( auto &&p : minv ){
        if( p.second.first == INF ) continue;
        if( uf.unionSet(p.second.second.first, p.second.second.second) ){
            ans += p.second.first;
            upd = true;
        }
    }
    return upd;
}
