class SegmentTree{
private:
	int sz;
	struct Node{
		pair<ll,int> v[2];
		Node(){}
		Node(int x):v({MP(INF,x),MP(INF,x)}){}
	}dat[maxn<<2];
	friend Node operator + (Node a,Node b){
		Node ret;
		ret.v[0]=min(a.v[0],b.v[0]);
		ret.v[1]=min(a.v[1],b.v[1]);
		return ret;
	}
	inline void build(int x,int l,int r){
		if(l==r){
			dat[x]=Node(l);
			return;
		}
		int md=(l+r)>>1;
		build(x<<1,l,md);
		build(x<<1|1,md+1,r);
		dat[x]=dat[x<<1]+dat[x<<1|1];
		return;
	}
public:
	inline int size(){return sz;}
	inline void init(int n){
		for(sz=1;sz<n;sz<<=1);
		build(1,0,sz-1);
		return;
	}
	inline void update(int x,int l,int r,int y,ll k,bool f){
		//printf("update: x=%d l=%d r=%d y=%d k=%lld f=%d\n",x,l,r,y,k,f);
		if(l==r){
			dat[x].v[f]=min(dat[x].v[f],MP(k,l));
			return;
		}
		int md=(l+r)>>1;
		if(y<=md) update(x<<1,l,md,y,k,f);
		else update(x<<1|1,md+1,r,y,k,f);
		dat[x]=dat[x<<1]+dat[x<<1|1];
		return;
	}
	inline pair<ll,int> query(int x,int l,int r,int s,int t,bool f){
		//printf("query: x=%d l=%d r=%d s=%d t=%d f=%d\n",x,l,r,s,t,f);
		if(s>t) return MP(INF,-1);
		if(l>=s&&r<=t) return dat[x].v[f];
		int md=(l+r)>>1;
		if(t<=md) return query(x<<1,l,md,s,t,f);
		if(s>md) return query(x<<1|1,md+1,r,s,t,f);
		return min(query(x<<1,l,md,s,t,f),query(x<<1|1,md+1,r,s,t,f));
	}
}seg;

