// ref. arihon 3-3
// E: type of data, R: type of query result
template<typename E, typename R>
class SegmentTree {
    public:
        SegmentTree(const int _n, const E inf, R (*f)(E, E)): f(f), inf(inf) {
            n = 1;
            while (n < _n) n *= 2;
            data.resize(2 * n, inf);
        }

        // update data[k] with a
        // time complexity: O(n)
        void update(int k, E a) {
            k += n - 1;
            data[k] = a;
            while (k > 0) {
                k = (k - 1) / 2;
                data[k] = (*f)(data[k * 2 + 1], data[k * 2 + 2]);
            }
        }

        // query value from [a, b)
        // // time complexity: O(n)
        R query(int a, int b) {
            return query(a, b, 0, 0, n);
        }

    private:
        int n;
        R (*f)(E, E);
        const E inf;
        vector<E> data;

        R query(int a, int b, int k, int l, int r) {
            // if [a, b) intersect [l, r) = empty
            if (r <= a || b <= l) {
                return inf;
            }

            // if [a, b) includes [l, r)
            if (a <= l && r <= b) {
                return data[k];
            } else {
                R vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
                R vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
                return (*f)(vl, vr);
            }
        }
};

// descending order base on costs
auto compare = [](const pair<int, int> &x, const pair<int, int> &y) {
    return x.second > y.second;
};
typedef priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(compare)> PriorityQueue;

// {city, cost}
vector<vector<pair<int, int>>> edges;
vector<bool> visited;

ll solve(PriorityQueue q) {
    ll acc = 0;

    while (!q.empty()) {
        pair<int, int> edge = q.top();
        int dest = edge.first;
        int cost = edge.second;
        q.pop();
        if (visited[dest]) continue;

        visited[dest] = true;
        acc += cost;
        for (int i = 0; i < (int) edges[dest].size(); i++) {
            q.push(edges[dest][i]);
        }
    }

    return acc;
}

