constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n - 1); }
template <class T> using V = vector<T>;
template <class T> using VV = V<V<T>>;

struct UnionFind {
    V<int> p, r;
    int gn;
    UnionFind(int n = 0) : p(n, -1), r(n, 1), gn(n) {}
    void merge(int a, int b) {
        int x = group(a), y = group(b);
        if (x == y) return;  // same
        gn--;
        if (r[x] < r[y])
            p[x] = y;
        else if (r[x] > r[y])
            p[y] = x;
        else {
            p[x] = y;
            r[x]++;
        }
    }
    int group(int a) {
        if (p[a] == -1) return a;
        return p[a] = group(p[a]);
    }
    bool same(int a, int b) { return group(a) == group(b); }
};

struct E {
    int from, to;
    ll cost;
    bool operator<(const E& r) const { return cost < r.cost; }
};
ll D;
V<ll> a;
V<E> edges;
void adde(int l, int r) {
    edges.push_back(E{l, r, D * abs(l - r) + a[l] + a[r]});
}
void solve(int l, int r) {
    if (l + 1 == r) return;
    int md = (l + r) / 2;
    solve(l, md); solve(md, r);
    {
        ll ma = TEN(18);
        int ma_ar = -1;
        for (int i = md; i < r; i++) {
            if (i * D + a[i] < ma) {
                ma = i * D + a[i];
                ma_ar = i;
            }
        }
        for (int i = l; i < md; i++) {
            adde(i, ma_ar);
        }
    }
    {
        ll ma = TEN(18);
        int ma_ar = -1;
        for (int i = l; i < md; i++) {
            if ((-i) * D + a[i] < ma) {
                ma = (-i) * D + a[i];
                ma_ar = i;
            }
        }
        for (int i = md; i < r; i++) {
            adde(i, ma_ar);
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20) << fixed;
    int n;
    cin >> n >> D;
    a = V<ll>(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    solve(0, n);
    sort(edges.begin(), edges.end());
    auto uf = UnionFind(n);
    ll ans = 0;
    for (auto e: edges) {
        if (uf.same(e.from, e.to)) continue;
        uf.merge(e.from, e.to);
        ans += e.cost;
    }
    cout << ans << endl;
    return 0;
}

