    up(x);

    // printf("x:%d l:%d r:%d tr[x].mn[0]:%lld tr[x].pos[0]:%d\n", x, l, r, tr[x].mn[0], tr[x].pos[0]);
    // printf("x:%d l:%d r:%d tr[x].mn[1]:%lld tr[x].pos[1]:%d\n", x, l, r, tr[x].mn[1], tr[x].pos[1]);
}

void update(int x, int l, int r, int cl, int cr, ll delta, int ty)
{
    if(cl<=l && r<=cr) return addone(x, delta, ty);

    down(x);

    int mid=(l+r)>>1;
    if(cl<=mid) update(x<<1, l, mid, cl, cr, delta, ty);
    if(cr>mid) update(x<<1|1, mid+1, r, cl, cr, delta, ty);

    up(x);
}

inline void insert(int x)
{
    ll delta=a[x]-1ll*x*D;
    ddq pos=s1.lower_bound((poi){x, delta}); 
    ddq pre=pos; pre--;
    if(pre->w>delta)
    {
        ddq it=pos; 
        for(;it!=s1.end() && it->w>=delta;it++)
        {
            ddq nxt=it; it++;
            update(1, 1, n, it->pos, nxt->pos-1, -it->w+delta, 0);
        }
        update(1, 1, n, x, pos->pos-1, delta-pre->w, 0);
        s1.erase(pos, it); 
        s1.insert((poi){x, delta}); 
    }

    delta=a[x]+1ll*x*D;
    pos=s2.lower_bound((poi){x, delta});
    if(pos->w>delta)
    {
        ddq it=pos;
        while(it!=s2.begin())
        {
            it--;
            if(it->w<delta)
            {
                it++; break;
            }
            else 
            {
                ddq pre=it; pre--;
                update(1, 1, n, pre->pos+1, it->pos, -it->w+delta, 1);
            }   
        }
        pre=pos; pre--;
        update(1, 1, n, pre->pos+1, x, delta-pos->w, 1);
        s2.erase(it, pos);
        s2.insert((poi){x, delta});
    }

    updateset(1, 1, n, x);
}

