class Solve {
public:
    int N;
    ll D;
    vector<ll> A;

    struct edge {
        int from;
        int to;
        ll cost;

        edge(int from, int to, ll cost) : from(from), to(to), cost(cost) {

        }
    };

    vector<edge> edges;

    void input() {
        cin >> N;
        cin >> D;
        A.resize(N);
        rep(i, 0, N) cin >> A[i];
    }

    void add_edge() {
        int pt = 0;
        ll ecost = A[pt] + D;

        for (int i = 1; i < N; ++i) {
            if (ecost < A[i - 1] + D) {
//                edges.emplace_back(pt, i, );
            } else {
                pt = i - 1;
                ecost = A[pt] + D;
            }
            edges.emplace_back(pt, i, A[i] + ecost);
            ecost += D;
        }

        pt = N - 1;
        ecost = A[pt] + D;

        for (int i = N - 2; i >= 0; --i) {
            if (ecost < A[i + 1] + D) {

            } else {
                pt = i + 1;
                ecost = A[pt] + D;
            }
            edges.emplace_back(pt, i, A[i] + ecost);
            ecost += D;
        }
    }


    void solve() {
        input();
        add_edge();

        UnionFind uf(N);

        sort(all(edges), [](edge a, edge b) {
            return a.cost < b.cost;
        });

        ll ans = 0ll;
        int cnt = 0;
        for (auto e : edges) {
            int a = e.from;
            int b = e.to;
            ll cost = e.cost;
            if (!uf.same(a, b)) {
                uf.unite(a, b);
                ans += cost;
                cnt++;
            }
        }

        assert(cnt == N - 1);

        cout << ans << endl;

    }
};


