enum FUNC_SparseTable { MIN, MAX };
template<class T>
class SparseTable {
	size_t N;
	std::vector<T> a;
	std::vector<size_t> logTable;
	std::vector<std::vector<T>> table;
	std::function<T(T&, T&)> f;
public:
	SparseTable(const std::vector<T>& _a, FUNC_SparseTable func = MIN) : N(_a.size()), a(_a) {
		logTable.resize(N + 1, 0);
		for (size_t i = 2; i <= N; ++i) {
			logTable[i] = logTable[i >> 1] + 1;
		}

		switch (func) {
		case MIN: f = [](T& l, T& r) { return std::min(l, r); }; break;
		case MAX: f = [](T& l, T& r) { return std::max(l, r); }; break;
		}

		table.resize(logTable[N] + 1, std::vector<T>(N));
		for (size_t i = 0; i < N; ++i) table[0][i] = a[i];
		for (size_t k = 1; k <= logTable[N]; ++k) {
			for (size_t i = 0; i + (1 << k) <= N; ++i) {
				table[k][i] = f(table[k - 1][i], table[k - 1][i + (1 << (k - 1))]);
			}
		}
	}
	// query in [l, r)
	inline T query(int l, int r) {
		int lg = logTable[r - l];
		return f(table[lg][l], table[lg][r - (1 << lg)]);
	}
};

//Union-Find
class UnionFind {
private:
	std::vector<int> parent;
	std::vector<int> height;
	std::vector<int> m_size;

public:
	UnionFind(int size_) : parent(size_), height(size_, 0), m_size(size_, 1) {
		for (int i = 0; i < size_; ++i) parent[i] = i;
	}
	void init(int size_) {
		parent.resize(size_);
		height.resize(size_, 0);
		m_size.resize(size_, 0);
		for (int i = 0; i < size_; ++i) parent[i] = i;
	}
	int find(int x) {
		if (parent[x] == x) return x;
		return parent[x] = find(parent[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		int t = size(x) + size(y);
		m_size[x] = m_size[y] = t;
		if (height[x] < height[y]) parent[x] = y;
		else parent[y] = x;
		if (height[x] == height[y]) ++height[x];
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		if (parent[x] == x) return m_size[x];
		return size(parent[x] = find(parent[x]));
	}
};

signed main() {
	INIT;

	VAR(int, n, d);
	VEC(int, a, n);

	std::vector<PAIR> aL(n);
	REP(i, n) aL[i] = PAIR(a[i] - i * d, i);
	SparseTable<PAIR> stL(aL);

	std::vector<PAIR> aR(n);
	REP(i, n) aR[i] = PAIR(a[i] + i * d, i);
	SparseTable<PAIR> stR(aR);

	UnionFind uf(n);
	int ans = 0;

	REP(i, n) {
		PAIR p(INFLL, INFINT), q(INFLL, INFINT);
		if (0 < i) {
			p = stL.query(0, i);
			p.first += i * d + a[i];
		}

		if (i + 1 < n) {
			q = stR.query(i + 1, n);
			q.first += -i * d + a[i];
		}

		CHMIN(p, q);

		if (uf.same(i, p.second)) continue;
		uf.unite(i, p.second);
		ans += p.first;
	}

	int r = 0;
	while (r < n && uf.find(0) == uf.find(r)) ++r;
	while (r < n) {
		int r2 = r + 1;
		while (r2 < n && uf.find(r) == uf.find(r2)) ++r2;

		int p = stL.query(0, r).second;
		int q = stR.query(r, r2).second;

		ans += std::abs(p - q) * d + a[p] + a[q];
		r = r2;
	}

	OUT(ans)BR;

	return 0;
}

