    for (int i = 0; i < edges.size(); ++i) {
        if (dd.find_set(edges[i].S.F) != dd.find_set(edges[i].S.S)) {
            dd.union_set(edges[i].S.F, edges[i].S.S);
            ans += edges[i].F;
        }
    }
    cout << ans << endl;
    return 0;
}

