    if (s == t) {
      val[k] = node(1ll << 60, s); return;
    }
    build(lson), build(rson), val[k] = min(ls, rs);
  }
  void upd(int k, int s, int t, node x) {
    if (s == t) {
      val[k] = x; return;
    }
    if (x.second <= mid) {
      upd(lson, x);
