{
	return find(u)==find(v);
}
void solve(int l,int r)
{
	if(l==r)return;
	int mid=(l+r)/2;
	int pl=-1;
	LL vl=INF;
	for(int i=l;i<=mid;i++)
	{
		if(Ai_Di[i]<vl)
		{
			vl=Ai_Di[i];
			pl=i;
		}
	}
	int pr=-1;
	LL vr=INF;
	for(int i=mid+1;i<=r;i++)
	{
		if(Aj_Dj[i]<vr)
		{
			vr=Aj_Dj[i];
			pr=i;
		}
	}
	for(int i=l;i<=mid;i++)
	{
		g.push_back(edge(i,pr,vr+Ai_Di[i]));
	}
	for(int i=mid+1;i<=r;i++)
	{
		g.push_back(edge(i,pl,vl+Aj_Dj[i]));
	}
	solve(l,mid);
	solve(mid+1,r);
}
