struct UnionFind{
	vector<int> par;
	UnionFind(int N){
		par.assign(N,0);
		rep(i,N) par[i]=i;
	}
	int find(int x){
		if(par[x]==x) return x;
		return par[x]=find(par[x]);
	}
	bool same(int x,int y){
		return find(x)==find(y);
	}
	void unite(int x,int y){
		x=find(x),y=find(y);
		if(x==y) return;
		par[y]=x;
	}
};
vector<PP> es;
ll inf = 1e18;
void solve(int l,int r){
	if(r-l==1) return;
	int m = (l+r)/2;
	solve(l,m);
	solve(m,r);
	{
		ll bestl = inf;
		int agl = -1;
		for(int i=l;i<m;i++){
			ll cost = -i*D+A[i];
			if(bestl>cost){
				bestl = cost;
				agl = i;
			}
		}
		int agr = -1;
		ll bestr = inf;
		for(int i=m;i<r;i++){
			ll cost = i*D+A[i];
			if(bestr>cost){
				bestr = cost;
				agr = i;
			}
		}

		for(int i=l;i<m;i++){
			es.pb(PP(-i*D+A[i]+bestr,P(i,agr)));
		}
		for(int i=m;i<r;i++){
			es.pb(PP(i*D+A[i]+bestl,P(i,agl)));
		}
	}
}
