    Seg() { init(); }
    void build() { F0Rd(i, SZ) seg[i] = comb(seg[2 * i], seg[2 * i + 1]); }
    T comb(const T &a, const T &b) const { return min(a, b); }
    void upd(int p, T value) {
        for (seg[p += SZ] = value; p > 1; p >>= 1)
            seg[p >> 1] = comb(seg[(p | 1) ^ 1], seg[p | 1]);
    }
    T query(int l, int r) {
        if (l > r)
            return ID;
        T res1 = ID, res2 = ID;
        r++;
        for (l += SZ, r += SZ; l < r; l >>= 1, r >>= 1) {
            if (l & 1)
                res1 = comb(res1, seg[l++]);
            if (r & 1)
                res2 = comb(seg[--r], res2);
        }
        return comb(res1, res2);
    }
};
Seg<N> seg1, seg2;
int32_t main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cout.precision(10);
    cout << fixed;
    int n;
    ll d;
    cin >> n >> d;
    vector<ll> V(n);
    vector<ll> cost1(n);
    vector<ll> cost2(n);
    for (int i = 0; i < n; i++) {
        cin >> V[i];
        cost1[i] = i * d + V[i];
        cost2[i] = -i * d + V[i];
        seg1.upd(i, make_pair(cost1[i], i));
        seg2.upd(i, make_pair(cost2[i], i));
    }
    ll ans = 0;
    while (true) {
        set<int> st;
        for (int i = 0; i < n; i++)
            st.insert(dsu.seek(i));
        if (st.size() == 1)
            break;
        vector<pair<ll, int>> dis(n, make_pair(INF, -1));
        for (int i : st) {
            for (auto j : dsu.el[i]) {
                seg1.upd(j, seg1.ID);
                seg2.upd(j, seg2.ID);
            }
            for (int j : dsu.el[i]) {
                auto cost1 = seg1.query(j + 1, n);
                cost1.first += -j * d + V[j];
                dis[i] = min(dis[i], cost1);

                auto cost2 = seg2.query(0, j - 1);
                cost2.first += j * d + V[j];
                dis[i] = min(dis[i], cost2);
            }
            for (auto j : dsu.el[i]) {
                seg1.upd(j, make_pair(cost1[j], j));
                seg2.upd(j, make_pair(cost2[j], j));
            }
        }
        for (int i : st) {
            if (dis[i].second != -1) {
                int fa1 = dsu.seek(i);
                int fa2 = dsu.seek(dis[i].second);
                if (fa1 != fa2) {
                    dsu.merge(fa1, fa2);
                    ans += dis[i].first;
                }
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

