  belong.resize(N);
  grps.resize(N);
  vector<Monoid> v1, v2;
  rep(i, N) {
    cin >> A[i];
    v1.eb(pll(A[i]+i*D, i));
    v2.eb(pll(A[i]+(N-i)*D, i));
    grps[i].resize(1, i);
    belong[i] = i;
  }

  Seg seg1(v1);
  Seg seg2(v2);

  LL ans = 0;
  using Edge = pair<LL, pii>;
  vector<Edge> mines;
  vector<pll> restore1, restore2;
  rep(_, 18) {
    mines.clear();
    for (auto &grp : grps) {
      restore1.clear();
      restore2.clear();
      for (int v : grp) {
        restore1.eb(seg1.seg[size+v].p);
        seg1.Update(v, pll(INF, INF));
        restore2.eb(seg2.seg[size+v].p);
        seg2.Update(v, pll(INF, INF));
      }

      Edge mine(INF, pii(-1, -1));
      for (int v : grp) {
        pll p = seg1.Get(v+1, N).p;
      //cout << p.X << ", " << p.Y << endl;
        if (p.X != INF) {
          MN(mine, Edge(A[v]+A[p.Y]+abs(v-p.Y)*D, pii(v, p.Y)));
        }

        pll q = seg2.Get(0, v).p;
        //cout << q.X << ", " << q.Y << endl;
        if (q.X != INF) {
          MN(mine, Edge(A[v]+A[q.Y]+abs(v-q.Y)*D, pii(v, q.Y)));
        }
      }

      for (auto &p : restore1) {
        seg1.Update(p.Y, p);
      }

      for (auto &p : restore2) {
        seg2.Update(p.Y, p);
      }

      mines.eb(mine);
    }

    bool all = false;
    for (auto &e : mines) {
      LL c = e.X;
      int u, v;
      tie(u, v) = e.Y;
      if (belong[u] == belong[v]) continue;

      ans += c;
      u = belong[u];
      v = belong[v];
      if (grps[u].size() > grps[v].size()) swap(u, v);
      grps[v].reserve(grps[v].size()+grps[u].size());
      for (int w : grps[u]) {
        belong[w] = v;
        grps[v].eb(w);
      }
      grps[u].clear();
      if (grps[v].size() == N) all = true;
    }

    if (all) break;
  }
  cout << ans << "\n";
}

