        }
      }
      guys[id].push_back(i);
      for(int v : guys[id]) smallest.insert(make_pair(-d * v + a[v], v));
    }
    for(int i = 0; i < n; i++) if(who[i] != -1){
      int id = find(i), idWho = find(who[i]);
      if(id != idWho){
        ans += best[id];
        u[id] = idWho;
        comp--;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

