	cc--;
	if (siz[x]<siz[y]) swap(x,y);
	siz[x]+=siz[y];par[y]=x;
	largest=max(largest,siz[x]);
	return true;
    }
};


ll n, d;
ll a[maxn];

vector<array<ll,3>> edges;


void solve(int l, int r) {
    if (l==r) return;
    if (l+1==r) {
	edges.push_back({d + a[l] + a[r], l, r});
	return;
    }
    int mid=(l+r)/2;
    int l0=l,r0=r;
    auto f = [&](ll i) {
	return a[i]-d*i;
    };
    auto g = [&](ll i) {
	return a[i]+d*i;
    };

    for (int i=l; i<=mid; i++) {
	if (f(i) < f(l0)) {
	    l0=i;
	}
    }
    for (int i=mid+1; i<=r; i++) {
	if (g(i) < g(r0)) {
	    r0 = i;
	}
    }

    //cout<<l<<" "<<r<<": "<<l0<<" "<<r0<<endl;

    for (int j=mid+1; j<=r; j++) {
	edges.push_back({f(l0)+g(j),l0,j});
    }
    for (int i=l; i<=mid; i++) {
	edges.push_back({f(i)+g(r0),i,r0});
    }

    solve(l,mid);
    solve(mid+1,r);
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);  cout.tie(0);

    cin>>n>>d;
