	ll wei = ed[0];
	int u = ed[1];
	int v = ed[2];
	//cout<<wei<<": "<<u<<","<<v<<endl;
	if (dsu.join(u,v)) {
	    res += wei;
	}
    }
    assert(dsu.cc==1);
    cout<<res<<endl;    
    return 0;
}

