static std::set<int> unlinked{};
static int n;
static int64_t d;
static std::vector<int> as;

struct link_t {
  int64_t cost;
  int from;
  int to;
};

link_t getCheapestLinkToUnlinked(int from) {
  link_t ret{};
  ret.from = from;
  ret.cost = INT64_MAX;
  for (auto to : unlinked) {
    if (to == from) {
      continue;
    }
    int64_t const cost = int64_t(abs(from - to)) * d + as[from] + as[to];
    if (cost < ret.cost) {
      ret.cost = cost;
      ret.to = to;
    }
  }
  return ret;
}

int64_t solve() {
  for (int i = 1; i < n; ++i) {
    unlinked.insert(i);
  }

  std::vector<link_t> links{};
  links.reserve(n);
  links.push_back(getCheapestLinkToUnlinked(0));

  int64_t ret = 0;
  while (true) {
    auto cheapestLink = links.front();
    for (auto& link : links) {
      if (link.cost >= cheapestLink.cost) {
        continue;
      }
      cheapestLink = link;
    }
    ret += cheapestLink.cost;
    if (links.size() + 1 >= n) {
      break;
    }
    int const to = cheapestLink.to;
    unlinked.erase(to);
    links.push_back(getCheapestLinkToUnlinked(to));
    for (auto& link : links) {
      if (link.to != to) {
        continue;
      }
      link = getCheapestLinkToUnlinked(link.from);
    }
  }
  return ret;
}

