using namespace std;
typedef long long lint;
typedef pair<int, int> pii;
typedef pair<lint, pii> plp;
typedef pair<lint, int> pli;

typedef struct SegTree{
  int n;
  vector<pli> node;
  lint initv;

  SegTree(int n_, lint initv_){
    n = 1;
    while(n < n_) n *= 2;
    node.resize(n*2-1);
    initv = initv_;
    rep(i, n*2-1) node[i] = make_pair(initv, -1);
  }

  void update(int i, pair<lint, int> x){
    i += n - 1;
    node[i] = x;
    while(i > 0){
        i = (i-1) / 2;
        if(node[i*2+1].fi <= node[i*2+2].fi) node[i] = node[i*2+1];
        else node[i] = node[i*2+2];
    }
  }

  pli getmin(int a, int b, int i, int l, int r){
    if(r<=a || b<=l) return make_pair(initv, -1);
    if(a<=l && r<=b) return node[i];
    auto pl = getmin(a, b, i*2+1, l, (l+r)/2);
    auto pr = getmin(a, b, i*2+2, (l+r)/2, r);
    if(pl.fi <= pr.fi) return pl;
    return pr;
  }
}SegTree;

typedef struct UnionFindTree{
    vector<int> par;

    UnionFindTree(int n){
        par.resize(n, -1);
    }

    int find(int x){
        if(par[x] < 0) return x;
        return par[x] = find(par[x]);
    }

    int size(int x){
        return -par[find(x)];
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(size(x) < size(y)) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
}UF;

int main(){
    int n;
