    scanf("%d%lld", &n, &d);
    pli a[n];
    rep(i, n){
        lint t;
        scanf("%lld", &t);
        a[i] = make_pair(t, i);
    }
    sort(a, a+n);
    SegTree st_l(n, 1e18);
    SegTree st_r(n, 1e18);
    vector<plp> E;
    rep(i, n){
        pli p_l = st_l.getmin(0, a[i].se+1, 0, 0, st_l.n);
        st_l.update(a[i].se, pli(a[i].fi + (lint)(n-a[i].se) * d, i));
        pli p_r = st_r.getmin(a[i].se, n, 0, 0, st_r.n);
        st_r.update(a[i].se, pli(a[i].fi + (lint)a[i].se * d, i));
        if(p_l.se >= 0) E.push_back(plp(a[p_l.se].fi + a[i].fi + (lint)abs(a[i].se - a[p_l.se].se) * d, pii(a[i].se, a[p_l.se].se)));
        if(p_r.se >= 0) E.push_back(plp(a[p_r.se].fi + a[i].fi + (lint)abs(a[i].se - a[p_r.se].se) * d, pii(a[i].se, a[p_r.se].se)));
    }
