class Unionfind{
public:
    vector<int> par,rank;

    Unionfind(int n){
        par.resize(n);
        rank.resize(n);
        rep(i,n){
            par[i] = i;
            rank[i] = 0;
        }
    }

    int find(int x){
        if(par[x]==x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x,int y){
        x = find(x);
        y = find(y);
        if(x == y) return;

        if(rank[x] < rank[y]){
            par[x] = y;
        }else{
            par[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(int x,int y){
        return find(x) == find(y);
    }
};

struct RMQ{

    vector<ll> node;
    int n=1;

    void init(int x){
        while(n < x){
            n *= 2;
        }
        node.resize(4*n,0);
    }

    void update(int s,ll x){
        int i = s + n - 1;
        node[i] = x;
        while(i > 0){
            i = (i-1)/2;
            node[i] = min(node[2*i+1],node[2*i+2]);
        }
    }

    ll getMin(int a, int b){
        return getMin(a,b,0,0,n-1);
    }

    ll getMin(int a,int b,int k, int l, int r){
        if(r < a || b < l) return LONG_MAX;
        if(a <= l && r <= b){ 
            return node[k];
        }
        else{
            ll vl = getMin(a,b,2*k+1,l,(l+r)/2);
            ll vr = getMin(a,b,2*k+2,(l+r)/2+1,r);
            return min(vl,vr);
        }
    }

    int getMinPos2(int a,int b){    
        if(a==b) return a;
        int k = 0;
        ll tmp = getMin(a,b);
        int l = a,r=b;
        while(k < n -1){
            if(getMin((l+r)/2+1,r) == tmp){
                l = (l+r)/2+1;
                k = 2*k+2;
            }
            else if(getMin(l,(l+r)/2) == tmp){
                r = (l+r)/2;
                k = 2*k+1;
            }

        }
        return l;
    }

    int getMinPos(int a,int b){
        ll tmp = getMin(a,b);
        int l=a,r=b;
        int k=0;
        while(n > k){
            if(tmp == getMin(l,(l+r)/2)){
                r = (l+r)/2;
                k=2*k+1;
            }
            else{
                l =(l+r)/2+1;
                k=2*k+2;
            } 
        }
        return k-n+1;
    }
};


