	for(int i = 0; i < n; i++) {
		for(int j = 0; j < size; j++) {
			int u = i, v = p[j];
			Edge e;
			e.u = u, e.v = v, e.c = getCost(u, v);
			edges.push_back(e);
		}
	}
	std::sort(edges.begin(), edges.end(), [](Edge v1, Edge v2) { return v1.c < v2.c; });
	for(int i = 0; i < n; i++) {
		par[i] = i;
	}
	long long ans = 0;
	for(auto e : edges) {
		if(makeUnion(e.u, e.v)) {
			ans += e.c;
		}
	}
	std::cout << ans << '\n';
}

