struct status{
	pair<ll,ll> asmall,abig,bsmall,bbig;
	pair<ll,ll> ans;//by a i mean we have already put them in
	void init()
	{
		asmall=abig=bsmall=bbig=ans=make_pair(1e18,0);
	}
};
pair<ll,ll> operator +(pair<ll,ll> a,pair<ll,ll> b)
{
	a.first+=b.first;a.second=b.second;//special made, watch out, never abuse!
	return a;
}

status merge(status a,status b)
{
	status c;c.init();
	c.ans=min(b.ans,a.ans);
	c.asmall=min(a.asmall,b.asmall);
	c.abig=min(a.abig,b.abig);
	c.bsmall=min(a.bsmall,b.bsmall);
	c.bbig=min(a.bbig,b.bbig);

	c.ans=min(c.ans,a.asmall+b.bbig);
	c.ans=min(c.ans,b.abig+a.bsmall);
	return c;
}

ll D;ll a[nn];
struct segmenttree
{
	status tree[nn*2+10];
	#define lc id<<1
	#define rc id<<1|1
	#define mid (l+r)/2
	void up(int id)
	{
		tree[id]=merge(tree[lc],tree[rc]);
	}
	void init(int l,int r,int id)
	{
		if(l==r)
		{
			tree[id].init();
			tree[id].bsmall=make_pair(a[l]-D*l,l);
			tree[id].bbig=make_pair(a[l]+D*l,l);
			return ;
		}
		init(l,mid,lc);init(mid+1,r,rc);
		up(id);
	}
	void update(int x,int l,int r,int id)
	{
		if(l==r) 
		{
			tree[id].init();
			tree[id].asmall=make_pair(a[l]-D*l,l);
			tree[id].abig=make_pair(a[l]+D*l,l);
			return ;
		}
		if(x<=mid) update(x,l,mid,lc);
		else update(x,mid+1,r,rc);
		up(id);
	}
	pair<ll,ll> query()
	{
		return tree[1].ans;
	}
}trcyx;
