struct SUS {
	vector<vector<int>> comps;
	vector<int> up;
	int get_root(int v) {
		if (up[v] == v) return v;
		return up[v] = get_root(up[v]);
	}
	SUS(int n) {
		up.resize(n);
		comps.resize(n);
		f(i, n) {
			up[i] = i;
			comps[i].pb(i);
		}
	}
	void merge(int a, int b) {
		a = get_root(a);
		b = get_root(b);
		if (a == b) return;
		if (len(comps[a]) > len(comps[b])) swap(a, b);

		for (int x : comps[a]) {
			comps[b].pb(x);
		}
		comps[a].clear();
		comps[a].shrink_to_fit();

		up[a] = b;
	}
	bool one_comp(int a, int b) {
		return get_root(a) == get_root(b);
	}
};

signed main(signed argc, char *argv[]) {
	scan n, D;
	a.resize(n);
	scan a;

	SUS sus(n);

	ll result = 0;

	auto __min = [](pair<ll, int> a, pair<ll, int> b) {
		return min(a, b);
	};
	auto __apply_mod = [](pair<ll, int> value, bool, int, int) {
		return value;
	};
	auto __merge_mods = [](bool, bool, int, int) {
		return true;
	};

	TreeSegment<pair<ll, int>, bool, decltype(__min), decltype(__apply_mod), decltype(__merge_mods)> POS(n, mp((ll)1e18, -1), __min, __apply_mod, __merge_mods, true);
	TreeSegment<pair<ll, int>, bool, decltype(__min), decltype(__apply_mod), decltype(__merge_mods)> NEG(n, mp((ll)1e18, -1), __min, __apply_mod, __merge_mods, true);


	vector<pair<ll, int>> edges(n);

	for (int i = 0; i < n; i++) {
		POS.change(i, mp(D * (i + 1) + a[i], i));
		NEG.change(i, mp(-D * (i + 1) + a[i], i));
	}

	while (true) {
		int noempty = 0;
		f(i, n) {
			if (!sus.comps[i].empty()) {
				noempty++;
			}
		}
		if (noempty == 1) break;

		for (int i = 0; i < n; i++) {
			if (sus.comps[i].empty()) continue;
			edges[i] = mp((ll)1e18, -1);
			for (int j : sus.comps[i]) {
				POS.change(j, mp((ll)1e18, -1));
				NEG.change(j, mp((ll)1e18, -1));
			}
			for (int j : sus.comps[i]) {
				auto c = NEG.query(0, j);
				auto d = POS.query(j + 1, n);
				c.x += a[j] + (j + 1) * D;
				d.x += a[j] - (j + 1) * D;
				edges[i] = min(edges[i], min(c, d));
			}
			for (int j : sus.comps[i]) {
				POS.change(j, mp(D * (j + 1) + a[j], j));
				NEG.change(j, mp(-D * (j + 1) + a[j], j));
			}
		}
		for (int i = 0; i < n; i++) {
			if (edges[i].second == -1) continue;
			int a = i;
			int b = edges[i].second;
			if (sus.one_comp(a, b)) continue;
			sus.merge(a, b);
			result += edges[i].first;
		}
	}
	print result;
}

