struct UF{
	int p[200010],rank[200010];	
	void init() {
		for (int i=0;i<200010;i++) p[i]=i;
		for (int i=0;i<200010;i++) rank[i]=0;
	}
	int getf(int x){
		if (p[x]==x) return x;
		return getf(p[x]);
	}
	bool same(int x,int y) {
		return getf(x)==getf(y);
	}
	void unite(int x,int y) {
		int xx=getf(x);
		int yy=getf(y);
		if (xx!=yy) {
			if (rank[xx]<rank[yy]) p[xx]=yy;
			else {
				p[yy]=xx;
				if (rank[xx]==rank[yy]) rank[xx]++;
			}
		}
	}
}uf;

void solve(int l,int r) {
	if (l==r) return;
	int mid=l+r>>1;
	ll mn=1e18;
	int pl,pr;
	for (int i=l;i<=mid;i++) {
		ll cur=a[i]-(ll)d*(ll)i;
		if (cur<mn) {
			mn=cur;
			pl=i;
		}
	}
	mn=1e18;
	for (int j=mid+1;j<=r;j++) {
		ll cur=a[j]-(ll)d*(ll)j;
		if (cur<mn) {
			mn=cur;
			pr=j;
		}
	}
	for (int i=mid+1;i<=r;i++) {
		ll vl=a[pl]-1ll*d*pl;
		ll vr=a[i]+1ll*d*i;
		e.pb(mp(vl+vr,mp(pl,i)));
	}
	for (int i=l;i<=mid;i++) {
		ll vl=a[i]-1ll*d*i;
		ll vr=a[pr]+1ll*d*pr;
		e.pb(mp(vl+vr,mp(i,pr)));
	}
	solve(l,mid);
	solve(mid+1,r);
}

