const i64 MAXN = 200005;

i64 parent[MAXN];

void make_set(i64 v) {
    parent[v] = v;
}

i64 find_set(i64 v) {
    if (v == parent[v])
        return v;
    return find_set(parent[v]);
}

void union_sets(i64 a, i64 b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b)
        parent[b] = a;
}

