        if (y == n - 1) {
            break;
        }

        auto it = q.begin();
        i64 i = it->second;

        i64 j1 = i - z[i];
        i64 j2 = i + z[i];

        q.erase(it);
        if (1 <= j1 && j2 > n) {
            if (check(i, j1)) {
                y++;
            }

            z[i]++;
            q.insert({cost(i), i});
        }
        else if (1 > j1 && j2 <= n) {
            if (check(i, j2)) {
                y++;
            }

            z[i]++;
            q.insert({ cost(i), i });
        }
        else if (1 <= j1 && j2 <= n) {
            if (y + 2 <= n - 1) {
                if (check(i, j1)) {
                    y++;
                }

                if (check(i, j2)) {
                    y++;
                }
            }
            else {
                if (a[j1] > a[j2]) {
                    swap(j1, j2);
                }

                if (check(i, j1)) {
                    y++;
                }
                else if (check(i, j2)) {
                    y++;
                }
            }

            z[i]++;
            q.insert({ cost(i), i });
        }
    }

    cout << R << endl;

    return 0;
}

