const int N = 200000;

int n, d, a[N], par[N];
std::pair<long long, std::pair<int, int>> candidates[N];

int find(int u)
{
    if (par[u] != u) {
        par[u] = find(par[u]);
    }
    return par[u];
}

long long cost(const std::pair<int, int>& p)
{
    return 1LL * d * std::abs(p.first - p.second) + a[p.first] + a[p.second];
}

int main()
{
    scanf("%d%d", &n, &d);
    for (int i = 0; i < n; ++ i) {
        scanf("%d", a + i);
        par[i] = i;
    }
    int comp = n;
    long long result = 0;
    while (comp > 1) {
        for (int i = 0; i < n; ++ i) {
            candidates[i] = std::make_pair(std::numeric_limits<long long>::max(), std::make_pair(-1, -1));
        }
        for (int t = 0; t < 2; ++ t) {
            std::tuple<long long, int, int> best[3];
            best[0] = std::make_tuple(std::numeric_limits<long long>::max(), -1, 0);
            best[1] = std::make_tuple(std::numeric_limits<long long>::max(), -1, 0);
            for (int ii = 0; ii < n; ++ ii) {
                int i = t ? n - 1 - ii : ii;
                int idx = 0;
                if (std::get<1>(best[idx]) == find(i)) {
                    idx ++;
                }
                if (~std::get<1>(best[idx])) {
                    int j = std::get<2>(best[idx]);
                    candidates[find(i)] = std::min(candidates[find(i)], std::make_pair(cost(std::make_pair(i, j)), std::make_pair(i, j)));
                }
                long long value = a[i] - 1LL * d * ii;
                best[2] = std::make_tuple(value, find(i), i);
                std::sort(best, best + 3);
                if (std::get<1>(best[0]) == std::get<1>(best[1])) {
                    best[1] = best[2];
                }
            }
        }
        for (int i = 0; i < n; ++ i) {
            auto e = std::make_pair(candidates[i].second.first, candidates[i].second.second);
            if (~e.first && find(e.first) != find(e.second)) {
                comp --;
                par[find(e.first)] = find(e.second);
                result += cost(e);
            }
        }
    }
    std::cout << result << std::endl;
}

