struct Bit1 {
    vector<li> node;
    Bit1 (int sz = 0) {
        node.assign(sz + 5, li(inf, 0) );
    }
    void update (int pos, li val) {
        for (; pos < (int)node.size(); pos += pos & -pos) node[pos] = min(node[pos], val);
    }
    li get (int pos) {
        li ret = li(inf, 0);
        for (; pos > 0; pos -= pos & -pos) ret = min(ret, node[pos]);
        return ret;
    }
};

struct Bit2 {
    vector<li> node;
    Bit2 (int sz = 0) {
        node.assign(sz + 5, li(inf, 0) );
    }
    void update (int pos, li val) {
        pos = (int)node.size() - pos;
        for (; pos < (int)node.size(); pos += pos & -pos) node[pos] = min(node[pos], val);
    }
    li get (int pos) {
        pos = (int)node.size() - pos;
        li ret = li(inf, 0);
        for (; pos > 0; pos -= pos & -pos) ret = min(ret, node[pos]);
        return ret;
    }
};

struct Dsu {
    vector<int> pSet, szSet;
    Dsu (int _n = 0) {
        pSet.assign(_n + 5, 0); for (int i = 0; i < (int)pSet.size(); ++i) pSet[i] = i;
        szSet.assign(_n + 5, 1);
    }
    int findSet (int i) { return i == pSet[i] ? i : pSet[i] = findSet(pSet[i]); }
    bool unionSet (int i, int j) {
        i = findSet(i);
        j = findSet(j);
        if (i == j) return false;
        if (szSet[i] > szSet[j]) swap(i, j);
        szSet[j] += szSet[i];
        pSet[i] = j;
        return true;
    }
};

long long cost (int i, int j) { return 1LL * abs(i - j) * d + a[i] + a[j]; }

int main () {
    scanf("%d %d", &n, &d);
    for (int i = 1; i <= n; ++i) {
        scanf("%d", a + i);
        vec.pb(ii(a[i], i) );
    }
    sort(vec.begin(), vec.end() );

    Bit1 bit1(n);
    Bit2 bit2(n);

    for (auto _ : vec) {
        int i = _.se;
        li tmp1 = bit1.get(i), tmp2 = bit2.get(i);
        if (tmp1.se) edge.pb(lii(cost(tmp1.se, i), ii(tmp1.se, i) ) );
        if (tmp2.se) edge.pb(lii(cost(tmp2.se, i), ii(tmp2.se, i) ) );
        bit1.update(i, li(a[i] - 1LL * i * d, i) );
        bit2.update(i, li(a[i] + 1LL * i * d, i) );
    }
    sort(edge.begin(), edge.end() );

    Dsu dsu(n);

    for (auto _ : edge) {
        if (dsu.unionSet(_.se.fi, _.se.se) ) ans += _.fi;
    }

    printf("%I64d", ans);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef pair<long,long> P;
typedef pair<long,P> PP;

vector<PP> edge;
long long N,D;
vector<long long> A;
const long INF=(1L<<50);
class UF{
  vector<int> par,rank;
public:
  UF(int size){
    for (int i = 0; i < size; i++) {
      par.push_back(i);
      rank.push_back(0);
    }
  }
  int find(int x){
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }
  void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)return;
    if(rank[x]<rank[y])par[x]=y;
    else{
      par[y]=x;
      if(rank[x]==rank[y])rank[x]++;
    }
  }
  bool same(int x,int y){
    return find(x)==find(y);
  }
};


void solve(long l,long r){
    if(l==r)return;
    long m=(l+r)/2;
    long mn=INF;
    int pl=-1;
    for(long i = l; i <= m; i++)
    {
        long vl=A[i]-D*i;
        if(mn>vl){
            mn=vl;
            pl=i;
        }
    }
    long pr=-1;
    mn=INF;
    for(long i=m+1;i<=r;i++){
        long vr=A[i]+D*i;
        if(mn>vr){
            mn=vr;
            pr=i;
        }
    }
    for(long i = 0; i <= m; i++)
    {
        edge.push_back(PP(A[i]+A[pr]+D*(pr-i),P(i,pr)));
    }
    for(long i = m+1; i < r+1; i++)
    {
        edge.push_back(PP(A[i]+A[pl]+D*(i-pl),P(pl,i)));
    }
    solve(0,m);
    solve(m+1,r);
    return;
}


int main(){
    scanf("%lld",&N);
    scanf("%lld",&D);
    for(int i = 0 ; i < N ; i++){
        long long tmp;
        scanf("%lld",&tmp);
        A.push_back(tmp);
    }
    solve(0,N-1);
    sort(edge.begin(),edge.end());
    UF uf(N);
    long ret=0;
    for(auto tmp:edge){
        P p=tmp.second;
        if(!uf.same(p.first,p.second)){
            uf.unite(p.first,p.second);
            ret+=tmp.first;
        }
    }
    cout<<ret<<endl;
    return 0;
}

