using namespace std;

typedef long long ll;
typedef unsigned long long ull;

const int N = 200010;
const ll INF = 1LL << 60;

struct Node {
  int l, r;
  ll lazy;
  pair<ll, int> d;
  Node *ls, *rs;

  void* operator new(size_t) {
    static Node pool[N << 2];
    static Node* p = pool;
    return p++;
  }

  void pd() {
    if (lazy) {
      d.first += lazy;
      ls->lazy += lazy;
      rs->lazy += lazy;
      lazy = 0;
    }
  }

  pair<ll, int> get() const { return make_pair(d.first + lazy, d.second); }

  void ch(int l, int r, ll v) {
    if (this->l == l && this->r == r) {
      lazy += v;
      return;
    }
    pd();
    if (r <= ls->r)
      ls->ch(l, r, v);
    else if (l >= rs->l)
      rs->ch(l, r, v);
    else {
      ls->ch(l, ls->r, v);
      rs->ch(rs->l, r, v);
    }
    d = min(ls->get(), rs->get());
  }
};

struct Mach {
  Node* seg;
  map<int, ll> val;

  void ins(int r, ll v) {
    map<int, ll>::iterator it = val.lower_bound(r);
    if (it->second <= v)
      return;
    it = val.upper_bound(r);
    --it;
    if (it->first < r)
      seg->ch(it->first + 1, r, v - next(it)->second);
    while (v <= it->second) {
      seg->ch(prev(it)->first + 1, it->first, v - it->second);
      val.erase(it--);
    }
    val.insert(make_pair(r, v));
  }

  void rmv(int k) { seg->ch(k, k, INF); }
};

int n, d;
bool f;
int a[N];
ll tmp[N];
Mach m1, m2;

Node* build(int l, int r);

int main() {


  scanf("%d%d", &n, &d);
  for (int i = 1; i <= n; ++i)
    scanf("%d", &a[i]);
  for (int i = 1; i <= n; ++i)
    tmp[i] = a[i] + i * (ll)d + INF;
  reverse(tmp + 1, tmp + n + 1);
  f = true;
  m1.seg = build(1, n);
  f = false;
  m1.val[n] = INF;
  m1.val[0] = -INF;
  m1.ins(n, a[1] - d);
  for (int i = 1; i <= n; ++i)
    tmp[i] = a[i] - i * (ll)d + INF;
  m2.seg = build(1, n);
  m2.val[0] = -INF;
  m2.val[n] = INF;
  m1.rmv(n);
  m2.rmv(1);
  ll ans = 0;
  for (int rep = 1; rep < n; ++rep) {
    pair<ll, int> choice = min(m1.seg->get(), m2.seg->get());
    int pos = choice.second;
    m1.rmv(n - pos + 1);
    m2.rmv(pos);
    ans += choice.first;
    m1.ins(n - pos + 1, a[pos] - pos * (ll)d);
    m2.ins(pos, a[pos] + pos * (ll)d);
  }
  printf("%lld\n", ans);

  return 0;
}

Node* build(int l, int r) {
  Node* p = new Node;
  p->l = l;
  p->r = r;
  if (l == r) {
    p->d = make_pair(tmp[l], f ? (n - l + 1) : l);
    return p;
  }
  int mid = (l + r) >> 1;
  p->ls = build(l, mid);
  p->rs = build(mid + 1, r);
  p->d = min(p->ls->d, p->rs->d);
  return p;
}

