        seg.view(); */
        int k = seg.need();
        ll x = seg.show_one(k);
        //cout << k << " " << x << " ";
        if (k>0 && seg.show_one(k - 1) < infl)
        {
            ans += seg.show_one(k - 1) + x + d;

            seg.update(idx[k-1][0], min(x + (k - idx[k-1][0]) * d, seg.show_one(idx[k-1][0])));
            if (idx[k-1][0]<k-1){
                seg.update(k - 1, infl);
            }
            idx[idx[k][1]][0] = idx[k - 1][0];
            idx[k][0] = idx[k - 1][0];
            idx[k - 1][1] = idx[k][1];
            idx[idx[k - 1][0]][1] = idx[k][1];
            cnt--;
        }
        if (k<n && seg.show_one(k + 1) < infl)
        {
            ans += seg.show_one(k + 1) + x + d;
            seg.update(idx[k+1][1], min(x + (idx[k+1][1] - k) * d, seg.show_one(idx[k+1][1])));
            if (idx[k+1][1]>k+1){
                seg.update(k + 1, infl);
            }
            idx[idx[k][0]][1] = idx[k + 1][1];
            idx[k][1] = idx[k + 1][1];
            idx[idx[k + 1][1]][0] = idx[k][0];
            idx[k + 1][0] = idx[k][0];
