	for(int i=0;i<v.size();i++)
	{

		int x=search(v[i].L),y=search(v[i].R);
		if(x==y)continue;
		ans+=v[i].val;
		fa[x]=y;
	}
	printf("%lld\n",ans);
	return 0;
}

