  scanf("%d%lld", &n, &D);
  for (int i = 0; i < n; ++i) scanf("%d", &A[i]);
  int64 best = 1LL << 60, best_k = -1;
  vector<ii> e;
  for (int i = 0; i < n; ++i) {
    if (best_k >= 0) {
      e.emplace_back(best_k, i);
    }
    int64 cur = A[i] - D * i;
    if (best > cur) {
      best = cur;
      best_k = i;
    }
  }
  best = 1LL << 60; best_k = -1;
  for (int i = n - 1; i >= 0; --i) {
    if (best_k >= 0) {
      e.emplace_back(best_k, i);
    }
    int64 cur = A[i] + D * i;
    if (best > cur) {
      best = cur;
      best_k = i;
    }
  }
  sort(e.begin(), e.end(),
       [&](const ii& u, const ii& v) {
         int64 L = A[u.first] + A[u.second] + D * abs(u.first - u.second);
         int64 R = A[v.first] + A[v.second] + D * abs(v.first - v.second);
