            edge.insert(e[0]);

            REP(j, SZ(nodes[i])) {
                seg_left.update(bkup_left[j].second, bkup_left[j]);
                seg_right.update(bkup_right[j].second, bkup_right[j]);
            }
        }

        FORE(e, edge) {
            dump(e.first, e.second);
            ans += e.first;
            uf.unite(e.second.first, e.second.second);
        }
    }
    cout << ans << endl;
    return (0^_^0);
}

