bool topos(vi &res, digraph<int> g) {
    int n = g.g.size();
    vi nyu(n);
    rep(i, n)for (auto &&e :g[i])nyu[e.to]++;
    set<int> st;
    rep(i, n)if (nyu[i] == 0)st.insert(i);
    while (st.size()) {
        int i = *st.begin();
        st.erase(st.begin());
        res.pb(i);
        fora(e, g[i])if (--nyu[e.to] == 0)st.insert(e.to);
    }
    return res.size() == n;
}

