struct Tree {
	LL orig_small, applied_small, min_apply;
	int id_orig, id_applied;
};
Tree tree[2][4 * 200005];
int N; LL D;
LL A[200005];
const LL INF = 10000000000000000LL;

void apply(int rt, int at, int l, int r, int L, int R, LL amount) {
	if (R < l || L > r) return;
	if (L <= l && r <= R) {
		tree[rt][at].min_apply = MIN(tree[rt][at].min_apply, amount);
		tree[rt][at].applied_small = tree[rt][at].orig_small + tree[rt][at].min_apply;
		tree[rt][at].id_applied = tree[rt][at].id_orig;
		if (l != r) {
			int k = at * 2;
			if (tree[rt][at * 2].applied_small > tree[rt][at * 2 + 1].applied_small) k = at * 2 + 1;
			if (tree[rt][at].applied_small > tree[rt][k].applied_small) {
				tree[rt][at].applied_small = tree[rt][k].applied_small;
				tree[rt][at].id_applied = tree[rt][k].id_applied;
			}
		}
		if (tree[rt][at].id_applied == -1) tree[rt][at].applied_small = INF;
		return;
	}
	int m = (l + r) / 2;
	apply(rt, at * 2, l, m, L, R, amount);
	apply(rt, at * 2 + 1, m + 1, r, L, R, amount);
	int k = at * 2;
	if (tree[rt][at * 2].applied_small > tree[rt][at * 2 + 1].applied_small) {
		k = at * 2 + 1;
	}
	tree[rt][at].applied_small = tree[rt][k].applied_small;
	tree[rt][at].id_applied = tree[rt][k].id_applied;
	if (tree[rt][at].orig_small + tree[rt][at].min_apply < tree[rt][at].applied_small) {
		tree[rt][at].applied_small = tree[rt][at].orig_small + tree[rt][at].min_apply;
		tree[rt][at].id_applied = tree[rt][at].id_orig;
	}
	if (tree[rt][at].id_applied == -1) tree[rt][at].applied_small = INF;
}

pair<LL, int> query(int rt) {
	return make_pair(tree[rt][1].applied_small,
		tree[rt][1].id_applied);
}

void remove(int rt, int at, int l, int r, int id) {
	if (l == r) {
		tree[rt][at].orig_small = INF;
		tree[rt][at].id_orig = -1;
		tree[rt][at].applied_small = INF;
		tree[rt][at].id_applied = -1;
		tree[rt][at].min_apply = INF;
		return;
	}
	int mid = (l + r) / 2;
	if (id <= mid) {
		remove(rt, at * 2, l, mid, id);
	}
	else {
		remove(rt, at * 2 + 1, mid + 1, r, id);
	}
	int k = at * 2;
	if (tree[rt][at * 2].orig_small > tree[rt][at * 2 + 1].orig_small) {
		k = at * 2 + 1;
	}
	tree[rt][at].orig_small = tree[rt][k].orig_small;
	tree[rt][at].id_orig = tree[rt][k].id_orig;
	k = at * 2;
	if (tree[rt][at * 2].applied_small > tree[rt][at * 2 + 1].applied_small) {
		k = at * 2 + 1;
	}
	tree[rt][at].applied_small = tree[rt][k].applied_small;
	tree[rt][at].id_applied = tree[rt][k].id_applied;
	if (tree[rt][at].orig_small + tree[rt][at].min_apply < tree[rt][at].applied_small) {
		tree[rt][at].applied_small = tree[rt][at].orig_small + tree[rt][at].min_apply;
		tree[rt][at].id_applied = tree[rt][at].id_orig;
	}
	if (tree[rt][at].id_applied == -1) tree[rt][at].applied_small = INF;
}

void build(int rt, int at, int l, int r) {
	if (l == r) {
		tree[rt][at].orig_small = (rt == 0 ? A[l] + l * D : A[l] - l * D);
		tree[rt][at].id_orig = l;
		tree[rt][at].applied_small = INF;
		tree[rt][at].id_applied = -1;
		tree[rt][at].min_apply = INF;
		return;
	}
	int mid = (l + r) / 2;
	build(rt, at * 2, l, mid);
	build(rt, at * 2 + 1, mid + 1, r);
	int k = at * 2;
	if (tree[rt][at * 2].orig_small > tree[rt][at * 2 + 1].orig_small) {
		k = at * 2 + 1;
	}
	tree[rt][at].orig_small = tree[rt][k].orig_small;
	tree[rt][at].id_orig = tree[rt][k].id_orig;
	tree[rt][at].applied_small = INF;
	tree[rt][at].id_applied = -1;
	tree[rt][at].min_apply = INF;
}

LL solve() {
	if (N == 1) return 0;
	build(0, 1, 1, N);
	build(1, 1, 1, N);
	remove(0, 1, 1, N, 1);
	remove(1, 1, 1, N, 1);
	apply(0, 1, 1, N, 2, N, A[1] - 1 * D);
	LL ret = 0;
	for (int i = 2; i <= N; i++) {
		auto X = query(0);
		auto Y = query(1);
		if (Y.first < X.first) X = Y;
		ret += X.first;
		//printf(">>>%lld %d\n", X.first, X.second);
		remove(0, 1, 1, N, X.second);
		remove(1, 1, 1, N, X.second);
		apply(0, 1, 1, N, X.second + 1, N, A[X.second] - X.second * D);
		apply(1, 1, 1, N, 1, X.second - 1, A[X.second] + X.second * D);
	}
	return ret;
}

void solve(int ks) {
	scanf("%d %lld", &N, &D);
	for (int i = 1; i <= N; i++) scanf("%lld", &A[i]);
	LL ans = solve();
	printf("%lld\n", ans);
}

