struct segment_tree_min {
	static const int maxn = 1 << 18;
	ll mn[maxn << 1];
	void init() {
		for (int i = 1; i < (maxn << 1); ++ i)
			mn[i] = (ll)(1e18);
	}
	void upd(int x, ll v) {
		for (x += maxn; x; x >>= 1)
			mn[x] = min(mn[x], v);
	}
	ll qry(int l, int r) {
		ll ans = linf;
		for (l += maxn, r += maxn; l < r; l >>= 1, r >>= 1) {
			if (l & 1) ans = min(ans, mn[l ++]);
			if (r & 1) ans = min(ans, mn[-- r]);
		}
		return ans;
	}
} seg0_min, seg1_min;

struct segment_tree_fill {
	static const int maxn = 1 << 18;
	ll add[maxn << 1];
	pair <ll, int> mn[maxn << 1];
	void init() {
		for (int i = 1; i < (maxn << 1); ++ i)
			add[i] = 0;
		for (int i = 0; i < maxn; ++ i)
			mn[i + maxn] = mp(0, i);
		for (int i = maxn - 1; i; -- i)
			mn[i] = min(mn[i << 1], mn[i << 1 | 1]);
	}
	void pushdown(int x) {
		if (add[x]) {
			mn[x].first = min(mn[x].first + add[x], linf);
			if (x < maxn) {
				add[x << 1] += add[x];
				add[x << 1 | 1] += add[x];
			}
			add[x] = 0;
		}
	}
	void upd(int l, int r, ll v, int i = 1, int a = 0, int b = maxn) {
		if (l <= a && b <= r) {
			add[i] += v;
			pushdown(i);
			return ;
		}
		pushdown(i);
		if (r <= a || b <= l) return ;
		int m = (a + b) >> 1;
		upd(l, r, v, i << 1, a, m);
		upd(l, r, v, i << 1 | 1, m, b);
		mn[i] = min(mn[i << 1], mn[i << 1 | 1]);
	}
	pair <ll, int> qry(int l, int r, int i = 1, int a = 0, int b = maxn) {
		pushdown(i);
		if (l <= a && b <= r) return mn[i];
		if (r <= a || b <= l) return mp(linf, -1);
		int m = (a + b) >> 1;
		pair <ll, int> ans = mp(linf, -1);
		ans = min(ans, qry(l, r, i << 1, a, m));
		ans = min(ans, qry(l, r, i << 1 | 1, m, b));
		return ans;
	}
} seg0_fill, seg1_fill;

