//size無し
class UnionFind {
private:
    int sz;
    vector<int> par, nrank;
public:
    UnionFind(){}
    UnionFind(int node_size) : sz(node_size), par(sz), nrank(sz, 0){
        iota(par.begin(), par.end(), 0);
    }
    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }
    void unite(int x,int y){
        x = find(x), y = find(y);
        if(x == y) return;
        if(nrank[x] < nrank[y]) swap(x,y);
        par[y] = x;
        if(nrank[x] == nrank[y]) nrank[x]++;
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};
struct edge{
    int a,b;
    ll cost;
    edge(int a,int b,ll cost):a(a),b(b),cost(cost){}
    bool operator<(const edge&b) const{
        return cost < b.cost;
    }
};
vector<ll>a;
vector<edge>e;
ll d;
void dfs(int l,int r){
    if(l==r)return;
    int mid = (l+r)/2;
    int id = - 1;
    ll mi = 1LL<<60;
    for(int i = l; i <= mid; i++){
        if(mi > -d*i+a[i]){
            mi = -d*i+a[i];
            id = i;
        }
    }
    for(int i = mid + 1; i <= r; i++){
        e.emplace_back(id,i,mi+a[i]+d*i);
    }
    mi = 1LL<<60;
    for(int i = mid + 1; i <= r; i++){
        if(mi > d*i+a[i]){
            mi = d*i+a[i];
            id = i;
        }
    }
    for(int i = l; i<= mid; i++){
        e.emplace_back(id,i,mi+a[i]-d*i);
    }
    dfs(l,mid);
    dfs(mid+1,r);
}
int main(){
    int n;
    cin >> n;
    cin >> d;
    a.resize(n);
    rep(i,n)cin >> a[i];
    dfs(0,n-1);
    sort(e.begin(),e.end());
    UnionFind uf(n);
    ll ans = 0;
    for(auto &x:e){
        if(!uf.same(x.a,x.b)){
            uf.unite(x.a,x.b);
            ans += x.cost;
        }
    }
    cout << ans << endl;
    return 0;
}

