typedef pair<ll, int> Value;

Value INF = mp((ll)1e18, -1);

const int N = (1 << 18);

Value TP[2 * N + 1];
Value TN[2 * N + 1];

Value queryR(Value T[], int i, int tl, int tr, int R) {
	if (tr <= R) return T[i];
	if (tl >= R) return INF;
	int m = (tl + tr) / 2;
	return min(queryR(T, i * 2 + 1, tl, m, R), queryR(T, i * 2 + 2, m, tr, R));
}

Value queryL(Value T[], int i, int tl, int tr, int L) {
	if (tl >= L) return T[i];
	if (tr <= L) return INF;
	int m = (tl + tr) / 2;
	return min(queryL(T, i * 2 + 1, tl, m, L), queryL(T, i * 2 + 2, m, tr, L));
}

void update(Value T[], int i, Value value) {
	i += N - 1;
	T[i] = value;
	while (i > 0) {
		i = (i - 1) / 2;
		T[i] = min(T[i * 2 + 1], T[i * 2 + 2]);
		if (i == 0) break;
	}
}

int n;
ll D;

vector<int> a;

struct SUS {
	vector<vector<int>> comps;
	vector<int> up;
	int get_root(int v) {
		if (up[v] == v) return v;
		return up[v] = get_root(up[v]);
	}
	SUS(int n) {
		up.resize(n);
		comps.resize(n);
		f(i, n) {
			up[i] = i;
			comps[i].pb(i);
		}
	}
	void merge(int a, int b) {
		a = get_root(a);
		b = get_root(b);
		if (a == b) return;
		if (len(comps[a]) > len(comps[b])) swap(a, b);

		for (int x : comps[a]) {
			comps[b].pb(x);
		}
		comps[a].clear();
		comps[a].shrink_to_fit();

		up[a] = b;
	}
	bool one_comp(int a, int b) {
		return get_root(a) == get_root(b);
	}
};

signed main(signed argc, char *argv[]) {
	scan n, D;
	a.resize(n);
	scan a;

	SUS sus(n);

	ll result = 0;

	auto __min = [](pair<ll, int> a, pair<ll, int> b) {
		return min(a, b);
	};
	auto __apply_mod = [](pair<ll, int> value, pair<ll, int> mod, int, int) {
		return mod;
	};
	auto __merge_mods = [](pair<ll, int> a, pair<ll, int> b, int, int) {
		return b;
	};
	// TreeSegment<pair<ll, int>, pair<ll, int>, decltype(__min), decltype(__apply_mod), decltype(__merge_mods)> POS(n, mp((ll)1e18, -1), __min, __apply_mod, __merge_mods, mp(1LL, (int)1));
	// TreeSegment<pair<ll, int>, pair<ll, int>, decltype(__min), decltype(__apply_mod), decltype(__merge_mods)> NEG(n, mp((ll)1e18, -1), __min, __apply_mod, __merge_mods, mp(1LL, (int)1));


	vector<pair<ll, int>> edges(n);

	for (int i = 0; i < N; i++) {
		update(TP, i, INF);
		update(TN, i, INF);
	}

	for (int i = 0; i < n; i++) {
		update(TP, i, mp(D * (i + 1) + a[i], i));
		update(TN, i, mp(-D * (i + 1) + a[i], i));
	}
	int cnt = 0;
	while (true) {
		cnt++;
		int noempty = 0;
		f(i, n) {
			if (!sus.comps[i].empty()) {
				noempty++;
			}
		}
		if (noempty == 1) break;

		for (int i = 0; i < n; i++) {
			if (sus.comps[i].empty()) continue;
			edges[i] = mp((ll)1e18, -1);
			for (int j : sus.comps[i]) {
				update(TP, j, mp((ll)1e18, -1));
				update(TN, j, mp((ll)1e18, -1));
			}
			for (int j : sus.comps[i]) {
				auto c = queryR(TN, 0, 0, N, j);
				auto d = queryL(TP, 0, 0, N, j + 1);
				c.x += a[j] + (j + 1) * D;
				d.x += a[j] - (j + 1) * D;
				edges[i] = min(edges[i], min(c, d));
			}
			for (int j : sus.comps[i]) {
				update(TP, j, mp(D * (j + 1) + a[j], j));
				update(TN, j, mp(-D * (j + 1) + a[j], j));
			}
		}
		for (int i = 0; i < n; i++) {
			if (edges[i].second == -1) continue;
			int a = i;
			int b = edges[i].second;
			if (sus.one_comp(a, b)) continue;
			sus.merge(a, b);
			result += edges[i].first;
		}
	}
	// log(cnt);
