int main() {
	int n, d; cin >> n >> d;
	vector<int> a(n), l(n), r(n);
	ll ans = 0;
	rep(i, 0, n) {
		cin >> a[i]; ans += a[i];
		if (i)l[i] = max(l[i - 1], i * d - a[i]);
		else l[0] = - a[0];
	}
	ans += 1LL * (n - 1) * d;
	rrep(i, n - 1, -1) {
		if (i == n - 1)r[i] = i * d + a[i];
		else r[i] = min(r[i + 1], i * d + a[i]);
		if (i > 0 && i < n - 1)ans += min(i * d - l[i], r[i] - i * d);
	}
	printf("%lld\n", ans);
	return 0;
}

