	for(int i=1;i<=m;i++)
	{
		long long vl=a[i]-d*(long long)i;
		long long vr=a[pr]+d*(long long)pr;
		edge.push_back(PP(vl+vr,P(i,pr)));
	}
	for(int i=m+1;i<=r;i++)
	{
		long long vl=a[pl]-d*(long long)pl;
		long long vr=a[i]+d*(long long)i;
		edge.push_back(PP(vl+vr,P(pl,i)));
	}
