    e.push_back(node(f[i] + f[pr], pii(i, pr)));
  }
  for (int i = mid + 1; i <= r; i++) {
    e.push_back(node(f[pl] + f[i], pii(i, pl)));
  }
  solve(l, mid), solve(mid + 1, r);
