        cost1[i] = i * d + V[i];
        cost2[i] = -i * d + V[i];
    }
    seg1.build(cost1);
    seg2.build(cost2);
    ll ans = 0;
    while (true) {
        set<int> st;
        for (int i = 0; i < n; i++)
            st.insert(dsu.seek(i));
        if (st.size() == 1)
            break;
        vector<pair<ll, int>> dis(n, make_pair(INF, -1));
        for (int i : st) {
            for (auto j : dsu.el[i]) {
                seg1.upd(j, seg1.ID);
                seg2.upd(j, seg2.ID);
            }
            for (int j : dsu.el[i]) {
                auto cost1 = seg1.query(j + 1, n);
                cost1.first += -j * d + V[j];
                dis[i] = min(dis[i], cost1);

