		if (!vis[u])  tr.set(u, w1[u], w2[u], inf, inf);
		if (!vis[v])  tr.set(v, w1[v], w2[v], inf, inf);
		vis[u] = vis[v] = 1;
		res += cur.res;
	}
	return res;
}

