template<typename T, typename BiOp>
struct SegmentTree {
	vector<T> data;
	T e;
	BiOp op;
	int size;
	SegmentTree(int n, T e, BiOp op) :e(e), op(op) {
		size = 1;
		while (size < n) size *= 2;
		data.resize(size * 2 - 1);
		for (int i = 0; i < size * 2 - 1; i++) data[i] = e;
	}
	void update(int k, T v) {
		k += size - 1;
		data[k] = v;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}
	T query(int a, int b, int k, int l, int r) const {
		if (b <= l || r <= a) return e;
		if (a <= l && r <= b) {
			return data[k];
		}
		return op(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
	}
	T query(int a, int b) const {
		return query(a, b, 0, 0, size);
	}
	T get(int i) {
		return data[i + size - 1];
	}
};
struct UnionFind {
	vector<int> par;
	vector<int> rank;
	int size;
	UnionFind(int n) :size(n) {
		par.resize(size);
		rank.resize(size);
		for (int i = 0; i < size; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (rank[x] < rank[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
	int find(int x) {
		if (par[x] == x) return x;
		return par[x] = find(par[x]);
	}
	bool same(int x, int y) {
		x = find(x);
		y = find(y);
		return x == y;
	}
};
ll A[200000];
int main() {
	int N;
	ll D;
	cin >> N >> D;
	vector<P> city;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
		city.emplace_back(A[i], i);
	}
	sort(city.begin(), city.end());
	vector<E> edge;
	SegmentTree<P, Min> S1(N, P(INF, INF), Min());
	SegmentTree<P, Min> S2(N, P(INF, INF), Min());
	for (int i = 0; i < N; i++) {
		int c = city[i].second;
		ll l = c * D + A[c], r = (-c)*D + A[c];
		P p1 = S1.query(0, c);
		if (p1.second != INF) {
			edge.emplace_back(l + p1.first, P(c, p1.second));
		}
		P p2 = S2.query(c + 1, N);
		if (p2.second != INF) {
			edge.emplace_back(r + p2.first, P(c, p2.second));
		}
		S1.update(c, P(r, c));
		S2.update(c, P(l , c));
	}
	sort(edge.begin(), edge.end());
	UnionFind U(N);
	ll ans = 0;
	for (E e : edge) {
		int u = e.second.first, v = e.second.second;
		if (!U.same(u, v)) {
			U.unite(u, v);
			ans += e.first;
		}
	}
	cout << ans << endl;
}

