		w2[i] = (num) a[i] - (num) d * i;
	}
	sort(dat + 1, dat + n + 1);
	tr1.init(w1);
	tr2.init(w2);
	for (int i = n; i >= 1; --i) {
		int u = dat[i].second, v1 = u != 1 ? tr2.qry(1, u - 1).second : 0, v2 = u != n ? tr1.qry(u + 1, n).second : 0;
		if (v1)  e.push_back({w(u, v1), {u, v1}});
		if (v2)  e.push_back({w(u, v2), {u, v2}});
		tr1.upd(u, inf);
		tr2.upd(u, inf);
	}
	printf("%lld\n", kruskal());
}

