    k += N0-1;
    data[k][0] = x;
    data[k][1] = y;
    while(k > 0) {
      k = (k - 1) / 2;
			if(data[2*k+1][0] > data[2*k+2][0]) {data[k][0] = data[2*k+2][0];data[k][1] = data[2*k+2][1];}
			else {data[k][0] = data[2*k+1][0];data[k][1] = data[2*k+1][1];}
