		else
			upd(u, v << 1 | 1, tm + 1, tr, ps, vl);
		if (t[u][v << 1].second < t[u][v << 1 | 1].second)
			t[u][v] = t[u][v << 1];
		else
			t[u][v] = t[u][v << 1 | 1];
	}
}

void init()
{
	for (int i = 0; i < 4 * N; i++)
	{
		t[0][i] = { oo, oo };
		t[1][i] = { oo, oo };
	}
}

pii get(int u, int v, int tl, int tr, int l, int r)
{
	if (l > r)
		return{ oo, oo };
	if (tl == l && tr == r)
		return t[u][v];
	int tm = tl + tr >> 1;

	pii p1 = get(u, v << 1, tl, tm, l, min(tm, r));
	pii p2 = get(u, v << 1 | 1, tm + 1, tr, max(tm + 1, l), r);

	if (p1.second < p2.second)
		return p1;
	else
		return p2;
}

set<triple(int)> st;

void prec(int i)
{
	pii pr1 = get(0, 1, 0, n - 1, i + 1, n - 1);
	pii pr2 = get(1, 1, 0, n - 1, 0, i - 1);

	int p1 = pr1.first, p2 = pr2.first, s1 = pr1.second, s2 = pr2.second;


	int lol = oo, fr = oo, sc = oo;

	if (s1 != oo)
	{
		int y = abs(i - p1) * d + a[i] + a[p1];
		if (y < lol)
		{
			lol = y;
			fr = i;
			sc = p1;
		}
	}

	if (s2 != oo)
	{
		int y = abs(i - p2) * d + a[i] + a[p2];
		if (y < lol)
		{
			lol = y;
			fr = i;
			sc = p2;
		}
	}
	//cout << fr << " " << sc << endl;
	st.insert(make_tuple(lol, fr, sc));
}


void smain()
{

	init();

	cin >> n >> d;
	for (int i = 0; i < n; i++)
	{
		cin >> a[i];
		upd(0, 1, 0, n - 1, i, a[i] + (i + 1) * d);
		upd(1, 1, 0, n - 1, i, a[i] + (n - i) * d);
	}



	int ans = 0;
	prec(0);
	vi used(n);
	used[0] = 1;
	for (int i = 1; i < n; i++)
	{
		auto kek = *st.begin();
		st.erase(st.begin());
		int fr, sc, sum;
		tie(sum, fr, sc) = kek;
		while (used[fr] && used[sc])
		{
			prec(fr);
			kek = *st.begin();
			st.erase(st.begin());
			tie(sum, fr, sc) = kek;
		}


		ans += abs(fr - sc) * d + a[fr] + a[sc];
		used[sc] = 1;
		upd(0, 1, 0, n - 1, fr, oo);
		upd(1, 1, 0, n - 1, fr, oo);
		upd(0, 1, 0, n - 1, sc, oo);
		upd(1, 1, 0, n - 1, sc, oo);

		prec(fr);
		prec(sc);
	}


	cout << ans;

}

