int N;
ll D;
vi a;


vector<pair<ll,ii>> prepare(){
    vector<pair<ll,ii>> res;

    vll b(N), c(N);
    rep(i,N) {
        b[i] = D*i + a[i];
        c[i] = -D*i + a[i];
    }

    ll bmin = LLONG_MAX; int bmin_at;
    for (int i=N-1; i>=0; --i) {
        if (b[i] < bmin) {
            bmin = b[i]; bmin_at = i;
        }
    }
    for (int i=0; i<bmin_at; ++i) {
        ll cost = a[i] + a[bmin_at] + D*(bmin_at - i);
        res.emplace_back(cost, ii(i,bmin_at));
    }

    ll cmin = LLONG_MAX; int cmin_at;
    for (int i=0; i<N; ++i) {
        if (c[i] < cmin) {
            cmin = c[i]; cmin_at = i;
        }
    }
    for (int i=cmin_at+1; i<N; ++i) {
        ll cost = a[cmin_at] + a[i] + D*(i - cmin_at);
        res.emplace_back(cost, ii(cmin_at,i));
    }

    priority_queue<pair<ll,int>> pq;
    if (bmin_at < cmin_at) {
        for (int i=N-1; i>=0; --i) {
            if (i < N-1) {
                int j = pq.top().second;
                ll cost = (a[i] + a[j]) + D*(j-i);
                res.emplace_back(cost, ii(i,j));
            }
            pq.emplace( -b[i], i );
        }
    }

    return move(res);
}

class UnionFind {
 public:
  vector<int> data;
  int count;
 public:
  UnionFind(int size) : data(size, -1), count(size) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
      --count;
    }
    return x != y;
  }
  bool findSet(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

ll solve() {
    priority_queue<pair<ll,ii>> pq;

    vector<pair<ll,ii>> l2r = prepare();
    for (auto &p : l2r) {
        ll cost = p.first;
        int i = p.second.first, j = p.second.second;
        pq.emplace(-cost, ii(i,j));
    }

    reverse(ALL(a));
    vector<pair<ll,ii>> r2l = prepare();
    for (auto &p : r2l) {
        ll cost = p.first;
        int i = p.second.first, j = p.second.second;
        pq.emplace(-cost, ii(N-1-j, N-1-i));
    }

    ll total = 0LL;
    UnionFind uf(N);
    int isles = N;
    while (!pq.empty()) {
        ll cost = -pq.top().first;
        int i = pq.top().second.first, j = pq.top().second.second;
        pq.pop();
        if (uf.root(i) != uf.root(j)) {
            total += cost;
            uf.unionSet(i,j); --isles;
            if (isles == 1) break;
        }
    }

    return total;
}

