const int MAX_N=1<<18;
int m; ll mx[2][2*MAX_N], ind[2][2*MAX_N];
const ll INF=1e18;
void init(int m_){
	m=1;
	while(m<m_) m<<=1;
	for(int i=1; i<=2*m-1; i++) mx[0][i]=mx[1][i]=INF;
	for(int i=m; i<m+m_; i++) ind[0][i]=ind[1][i]=i-m;
	for(int i=m-1; i>=1; i--){
		ind[0][i]=max(ind[0][2*i], ind[0][2*i+1]);
		ind[1][i]=max(ind[1][2*i], ind[1][2*i+1]);
	}
}

void update(int k, int a, int i){
	k+=m;
	mx[i][k]=a;
	while(k>1){
		k>>=1;
		if(mx[i][2*k]<mx[i][2*k+1]){
			ind[i][k]=ind[i][2*k];
		}else{
			ind[i][k]=ind[i][2*k+1];
		}
		mx[i][k]=min(mx[i][2*k], mx[i][2*k+1]);
	}
}

P query(int a, int b, int i){
	a+=m, b+=m;
	ll ans=INF; int ind0=0;
	for(;a<b; a>>=1, b>>=1){
		if(b&1){
			b--;
			if(ans>mx[i][b]){
				ans=mx[i][b];
				ind0=ind[i][b];
			}
		}
		if(a&1){
			if(ans>mx[i][a]){
				ans=mx[i][a];
				ind0=ind[i][a];
			}
			a++;
		}
	}
	return P(ind0, ans);
}
int par[200002];
int rk[200002];

void init1(int n){
	for(int i=0; i<n; i++){
		par[i]=i;
	}
}

int find(int x){
	if(par[x]==x){
		return x;
	}else{
		return par[x]=find(par[x]);
	}
}

void unite(int x, int y){
	x=find(x);
	y=find(y);
	if(x==y) return;
	if(rk[x]<rk[y]){
		par[x]=y;
	}else{
		par[y]=x;
		if(rk[x]==rk[y]) rk[x]++;
	}
}

bool same(int x, int y){
	return find(x)==find(y);
}
