	for(int i=1; i<n; i++){
		update(ind0[i-1], a[ind0[i-1]]-(ll)ind0[i-1]*d, 0);
		update(ind0[i-1], a[ind0[i-1]]+(ll)ind0[i-1]*d, 1);
		if(ind0[i]>0){
			P p=query(0, ind0[i], 0);
			if(p.second<INF){
				int ind1=p.first;
				e.push_back(Pi(a[ind0[i]]+a[ind1]+(ll)(ind0[i]-ind1)*d, P(ind0[i], ind1)));
