	For(i,n) Read(a[i]);

	For(i,n){
		f[i] = a[i] - i*d;
		g[i] = a[i] + i*d;
	}

	Divideandconquer(1,n);
	sort(All(es),[]( const E &a , const E &b ){ return a.c < b.c; });

	ll ans = Kruskal();
	cout << ans << endl;

	END();
}

