const int N = 200003;
int n, sz[N], par[N];
ll d, a[N];
vector <pr <ll> > cand;

void rec(int l, int r) {
	if (l >= r) {
		return;
	}
	int m = l + r >> 1;
	int L = -1, R = -1;
	for (int i = l; i <= m; i++) {
		if (L == -1 || a[i] - i * d < a[L] - L * d) {
			L = i;
		}
	}
	for (int i = m + 1; i <= r; i++) {
		cand.pb({a[L] + a[i] + (i - L) * d, L, i});
		if (R == -1 || a[i] + i * d < a[R] - R * d) {
			R = i;
		}
	}
	for (int i = l; i <= m; i++) {
		cand.pb({a[R] + a[i] + (R - i) * d, i, R});
	}
	rec(l, m);
	rec(m + 1, r);
}

void make_set(int x) {
	par[x] = x;
	sz[x] = 1;
}

int find_set(int x) {
	if (x == par[x]) {
		return x;
	}
	return par[x] = find_set(par[x]);
}

bool union_set(int x, int y) {
	x = find_set(x), y = find_set(y);
	if (x == y) {
		return false;
	}
	if (sz[x] < sz[y]) {
		swap(x, y);
	}
	par[y] = x;
	sz[x] += sz[y];
	return true;
}

