	sort(all(cand));
	ll ans = 0;
	for (int i = 1; i <= n; i++) {
		make_set(i);
	}
	for (auto i : cand) {
		int w = i[0], x = i[1], y = i[2];
		if (union_set(x, y)) {
			ans += w;
		}
	}
	cout << ans;
}

