  ll d;
  cin >> n >> d;
  vector<ll> a(n),b(n);
  for(int i=0;i<n;i++) cin >> a[i];
  vector<ll> v(n,0);
  v[0]=INF;
  for(int i=1;i<n;i++){
    v[i]=d*i+a[i];
