struct UnionFind{
    vl par;
    vl rank;
    map<ll, ll> size;
    UnionFind(ll N) : par(N, 0), rank(N, 0){
        for(ll i = 0; i < N; i++){
            par[i] = i; size[i] = 1;
        }
    }

    ll root(ll x){
        if(par[x] == x) return x;
        else{
            par[x] = root(par[x]); // compression
            return par[x];
        }
    }

    void unite(ll x, ll y){
        ll rx = root(x); ll ry = root(y);
        if(rx == ry) return;
        if(rank[rx] < rank[ry]) swap(rx, ry);
        if(rank[rx] == rank[ry]) ++rank[rx];
        par[ry] = rx;
        if(rx != ry) size[rx] = size[rx] + size[ry];
        else{
            size[rx] = max(size[rx], size[ry]);
        }
    }

    ll get_size(ll x){
        return size[root(x)];
    }

    bool same(ll x, ll y){
        return root(x) == root(y);
    }
};


int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N, D; cin >> N >> D;
    vl A(N); multimap<ll, ll> idx;
    rep(i, N){
        cin >> A[i]; idx.insert({A[i], i});
    }
    auto min_func = [](PL l, PL r){
        if(l.ff <= r.ff) return l;
        else return r;
    };
    auto lseg = SegmentTree<PL>(N, min_func, {LINF,-1});
    auto rseg = SegmentTree<PL>(N, min_func, {LINF,-1});

    rep(i, N){
        lseg.update(i, {A[i]-i*D,i});
        rseg.update(i, {A[i]+i*D,i});
    }

    multimap<ll, PL> m;
    FORMAP(it, idx){
        ll i = it->ss;
        if(i < N-1){
            auto idx = rseg.query(i+1, N).ss;
            m.insert({A[i]+A[idx]+D*abs(i-idx), {i, idx}});
        }
        if(i > 0){
            auto idx = lseg.query(0, i).ss;
            m.insert({A[i]+A[idx]+D*abs(i-idx), {i, idx}});
        }
    }

    ll ans = 0;
    auto uf = UnionFind(N);
    FORMAP(it, m){
        auto p = it->ss;
        if(uf.same(p.ff, p.ss)) continue;
        ans += it->ff;
        uf.unite(p.ff, p.ss);
    }
    cout << ans << endstr;
    return 0;
}

