struct Tree {
	#define lson (root << 1)
	#define rson (root << 1 | 1)
	#define mid ((tree[root].stdl + tree[root].stdr) >> 1)
	struct Node {
		int stdl, stdr;
		pair<ll,int> mn;
	}	tree[MAXN << 2];
	inline void buildtree(int root, int l, int r) {
		tree[root].stdl = l;
		tree[root].stdr = r;
		tree[root].mn = mp(1e18, l);
		if (l == r) return;
		buildtree(lson, l, mid);
		buildtree(rson, mid + 1, r);
	}
	inline void update(int root) {
		tree[root].mn = min(tree[lson].mn, tree[rson].mn);
	}
	inline pair<ll,int> query(int root, int l, int r) {
		if (l <= tree[root].stdl && tree[root].stdr <= r) {
			return tree[root].mn;
		}
		pair<ll,int> ret(1e18, 1e9);
		if (l <= mid) ret = min(ret, query(lson, l, r));
		if (r > mid) ret = min(ret, query(rson, l, r));
		return ret;
	}
	inline void change(int root, int x, ll p) {
		if (tree[root].stdl == tree[root].stdr) {
			tree[root].mn = mp(p, tree[root].stdl);
			return;
		} 
		if (x <= mid) change(lson, x, p);
		else change(rson, x, p);
		update(root);
	}
}	T;
