inline void solve(int l, int r) {
	if (l == r) return;
	int m = (l + r) >> 1;
	ll ml = 1e18, li = 0;
	rep (i, l, m) {
		if (ml > A[i] - i * d) {
			ml = A[i] - i * d;
			li = i;
		}
	}
	ll mr = 1e18, ri = 0;
	rep (i, m + 1, r) {
		if (mr > A[i] + i * d) {
			mr = A[i] + i * d;
			ri = i;
		}
	}
	rep (i, l, m) {
		edge[i].pb(mp(A[i] - i * d + mr, ri));
		edge[ri].pb(mp(A[i] - i * d + mr, i));
	}
	rep (i, m + 1, r) {
		edge[i].pb(mp(A[i] + i * d + ml, li));
		edge[li].pb(mp(A[i] + i * d + ml, i));
	}
	solve(l, m);
	solve(m + 1, r);
}
