struct Seg {
	LL n;
	vector<Pll>node;
	Seg(LL n_) {
		n = 1; while (n < n_)n *= 2;
		node.resize(n * 2 - 1);
		rep(i, n)node[n + i - 1] = Pll(INF,-1);
		Rrep(i, n - 2)node[i] = Pll(INF,-1);
	}

	void update(LL i, LL x) {
		LL y = i;
		i = i + n - 1;
		node[i] = Pll(x, y);
		while (i > 0) {
			i = (i - 1) / 2;
			node[i] = (node[i * 2 + 1].fir < node[i * 2 + 2].fir ? node[i * 2 + 1] : node[i * 2 + 2]);
		}
	}
	Pll find(LL l, LL r) {
		return find(0, 0, n - 1, l, r);
	}
	Pll find(LL i, LL a, LL b, LL l, LL r) {
		if (b< l || r < a)return Pll(INF,-1);
		if (l <= a && b <= r)return node[i];
		Pll x = find(i * 2 + 1, a, (a + b) / 2, l, r), y = find(i * 2 + 2, (a + b + 1) / 2, b, l, r);
		return (x.first < y.first ? x : y);
	}
};

