template<typename T>

struct Kruskal{

  struct edge{
    int from,to;
    T cost;
    int used;
    edge(int from,int to,T cost):
      from(from),to(to),cost(cost),used(0){}
    bool operator<(const edge& e) const{
      return cost<e.cost;
    }
  };
  vector<int> r,p;
  vector<edge> es;
  vector<vector<pair<int,T>>> G;

  Kruskal(){}
  Kruskal(int n):r(n,1),p(n),G(n){
    iota(p.begin(),p.end(),0);
  }

  int find(int x){
    return (x==p[x]?x:p[x]=find(p[x]));
  }

  bool same(int x,int y){
    return find(x)==find(y);
  }

  void unite(int x,int y){
    x=find(x);y=find(y);
    if(x==y) return;
    if(r[x]<r[y]) swap(x,y);
    r[x]+=r[y];
    p[y]=x;
  }

  void add_edge(int u,int v,T c){
    es.emplace_back(u,v,c);
  }

  T build(){
    sort(es.begin(),es.end());
    T res=0;
    for(auto &e:es){
      cout << e.from << " " << e.to << " " << e.cost << endl;
      if(!same(e.from,e.to)){
        res+=e.cost;
        unite(e.from,e.to);
        G[e.from].push_back(make_pair(e.to,e.cost));
        G[e.to].push_back(make_pair(e.from,e.cost));
        e.used=1;
      }
    }
    return res;
  }

  vector<vector<pair<int,T>>> graph(){
    return G;
  }
};

