void rec(int l,int r,Kruskal<ll> &k){
  if (r-l<=1) return;
  int mid=(l+r)/2;
  ll mi1=INF;int idx1=-1;
  Rep(i,l,mid){
    if(mi1>a[i]-d*(ll)i){
      mi1=a[i]-d*(ll)i;
      idx1=i;
    }
  }
  Rep(i,mid,r){
    k.add_edge(i,idx1,mi1+a[i]+d*(ll)i);
  }
  ll mi2=INF;int idx2=-1;
  Rep(i,mid,r){
    if(mi2>a[i]+d*(ll)i){
      mi2=a[i]+d*(ll)i;
      idx2=i;
    }
  }
  Rep(i,l,mid){
    k.add_edge(i,idx2,mi2+a[i]-d*(ll)i);
  }
  rec(l,mid,k);rec(mid,r,k);
}

