    }    
}

LL f(VI &a, VP &b, int &i, LL &sum, LL &d, LL &n, VLL &lcost, VLL &rcost) {
    LL ksum = sum;
    VI lpos(n, -1), rpos(n, n);
    calcPos(lpos, rpos, lcost, rcost, b, i);
    REP(j,0,i) {
        int index = b[j].second;
        LL v = b[j].first;
        if (index == 0 || index == n - 1) continue;
        ksum -= 2 * v;
        LL lcost, rcost;
        if (lpos[index - 1] == -1) lcost = 1LL << 60;
        else lcost = d * (abs(index - lpos[index - 1])) + a[index] + a[lpos[index - 1]];
        if (rpos[index + 1] == n) rcost = 1LL << 60;
        else rcost = d * (abs(index - rpos[index + 1])) + a[index] + a[rpos[index + 1]]; 
        ksum += min(lcost, rcost);
    }
    return ksum;
} 

void solve() {
    LL n,d;
    cin >> n >> d;
    VI a(n);
    VP b(n);
    VLL lcost(n), rcost(n);
    REP(i,0,n) {
        cin >> a[i];
        b[i] = MP(a[i], i);
        lcost[i] = a[i] + d * (n - i - 1);
        rcost[i] = a[i] + d * i;
    }
    if (n == 1) {
        cout << 0 << endl;
        return;
    } else if (n == 2) {
        cout << d + a[0] + a[1] << endl;
        return;
    }
    sort(all(b));
    reverse(all(b));
    LL asum = 0;
    REP(i,0,n) asum += a[i];
    LL sum = asum * 2 - a[0] - a[n-1] + (n - 1) * d;
    int L = 0,  R = n - 2;
    int cnt = 0;
    while (cnt++ < 15 && R - L > 1) {
        int m1 = (R-L)/3 + L, m2 = (R-L)*2/3 + L;
        //dump(m1);
        //dump(m2);
        LL m1v = f(a,b,m1,sum,d,n,lcost,rcost);
        LL m2v = f(a,b,m2,sum,d,n,lcost,rcost);
        //dump(m1v);
        //dump(m2v);
        if (m1v > m2v) L = m1;
        else R = m2;
    }
    //dump(L);
    //dump(R);
    LL ans = f(a,b,L,sum,d,n,lcost,rcost);
    REP(i,L+1-5,R+1+5) {
        if (i < 0 || i >= n - 1) continue;
        LL tmp = f(a,b,i,sum,d,n,lcost,rcost);
        if (ans > tmp) {
            //dump(i);
            //dump(tmp);
            ans = tmp;
        }
    }
    cout << ans << endl;
}

