struct {
std::vector<ll> bit = vector<ll>(MAXN);

// update bit[j] (j >= i) with max(bit[j], x)
void update(int i, ll x) {
  while (i <= 200000) {
    bit.at(i) = std::max(bit.at(i), x);
    i += i & -i;
  }
}

// get max bit[j] (0 <= j <= i)
ll getmax(int i) {
  ll s = 0;
  while (i>0) {
    s = std::max(bit.at(i), s);
    i -= i & -i;
  }
  return s;
}
} B, C;

