    //debug(i); debugln(tmp);
    B.update(n+1-i, tmp);
    mpb[tmp] = i;
  }
  unordered_map<ll, int> mpc;
  for(int i=1; i<=n-1; i++) {
    ll tmp = INF-(a[i]+(n-i)*d);
    C.update(i, tmp);
    mpc[tmp] = i;
  }

  ll mincost = LONG_MAX;
