      //debugln("C");
      ll tmp = C.getmax(i-1);
      int pos = mpc[tmp];
      ll cost = a[i] + a[pos] + abs(i-pos)*d;
      graph[i].push_back(P(cost, pos));
      graph[pos].push_back(P(cost, i));
      //debug(i); debug(pos); debugln(cost);
    }
    if (i<n) {
      //debugln("B");
      ll tmp = B.getmax(n-i);
