vp sega;
ll N=1;
void inita(vi v){
    while(N<v.size())N*=2;
    sega=vp(N*2-1,P(inf,-1));
    rep(i,v.size())sega[i+N-1]=P(v[i],i);
    for(int i=N-2;i>=0;i--)sega[i]=min(sega[i*2+1],sega[i*2+2]);
}
void updatea(ll i,ll x){
    i=N+i-1;
    sega[i].fi=x;
    while(i>0){
        i=(i-1)/2;
        sega[i]=min(sega[i*2+1],sega[i*2+2]);
    }
}
P getmia(ll a,ll b,ll k,ll l,ll r){
    if(r<=a||b<=l)return P(inf,-1);
    if(a<=l&&r<=b)return sega[k];
    P c1=getmia(a,b,k*2+1,l,(l+r)/2);
    P c2=getmia(a,b,k*2+2,(l+r)/2,r);
    return min(c1,c2);
}
vp segb;
void initb(vi v){
    segb=vp(N*2-1,P(inf,-1));
    rep(i,v.size())segb[i+N-1]=P(v[i],i);
    for(int i=N-2;i>=0;i--)segb[i]=min(segb[i*2+1],segb[i*2+2]);
}
void updateb(ll i,ll x){
    i=N+i-1;
    segb[i].fi=x;
    while(i>0){
        i=(i-1)/2;
        segb[i]=min(segb[i*2+1],segb[i*2+2]);
    }
}
P getmib(ll a,ll b,ll k,ll l,ll r){
    if(r<=a||b<=l)return P(inf,-1);
    if(a<=l&&r<=b)return segb[k];
    P c1=getmib(a,b,k*2+1,l,(l+r)/2);
    P c2=getmib(a,b,k*2+2,(l+r)/2,r);
    return min(c1,c2);
}
int main(){
    ll n,d;cin>>n>>d;
    vi v(n);
    rep(i,n)cin>>v[i];
    vi a(n,inf),b(n,inf);
    REP(i,1,n)a[i]=d*i+v[i];
    REP(i,1,n)b[i]=d*(n-1-i)+v[i];
    inita(a);initb(b);
    SPQ(PP) pq;
    pq.push(PP(getmia(1,N,0,0,N).fi+v[0],getmia(1,N,0,0,N).se,0));
    ll ans=0,cnt=0;
    while(cnt<n-1){
        auto t=pq.top();pq.pop();
        ll cost=get<0>(t),i=get<1>(t),p=get<2>(t);
        //cout<<cost<<' '<<i<<' '<<p<<endl;
        bool done=false;
        if(sega[i+N-1].fi==inf)done=true;
        updatea(i,inf);updateb(i,inf);
        if(p!=-1){
            P x=getmia(p+1,N,0,0,N),y=getmib(0,p,0,0,N);
            x.fi-=p*d;
            y.fi-=(n-p-1)*d;
            pq.push(PP(min(x,y).fi+v[p],min(x,y).se,p));
        }
        if(done)continue;
        ans+=cost;
        cnt++;
        P x=getmia(i+1,N,0,0,N),y=getmib(0,i,0,0,N);
        x.fi-=i*d;
        y.fi-=(n-i-1)*d;
        pq.push(PP(min(x,y).fi+v[i],min(x,y).se,i));
    }
    out(ans);
}

