struct segtree{
	pair<ll,int> x[(1<<19)];
	void init(){
		for(int i=0;i<(1<<19);i++) x[i] = make_pair(1e18,INF);
	}
	void update(int i,ll a){
		i += (1<<18)-1;
		x[i] = make_pair(a,i-(1<<18)+1);
		while(i){
			i = (i-1)/2;
			x[i] = min(x[i*2+1],x[i*2+2]);
		}
	}
	pair<ll,int> query(int a,int b,int k,int l,int r){
		if(r<a || b<l || a>b) return make_pair(1e18,INF);
		if(a<=l && r<=b) return x[k];
		pair<ll,int> L = query(a,b,k*2+1,l,(l+r)/2);
		pair<ll,int> R = query(a,b,k*2+2,(l+r)/2+1,r);
		return min(L,R);
	}
}seg_plus,seg_minus;
struct union_find{
	int par[200005],ran[200005];
	void init(){ for(int i=0;i<200005;i++) par[i] = i; }
	int find(int x){ if(x == par[x]) return x; else return par[x] = find(par[x]); }
	void unite(int x,int y){
		x = find(x); y = find(y); if(x==y) return;
		if(ran[x] < ran[y]) par[x] = y;
		else{
			par[y] = x;
			if(ran[x] == ran[y]) ran[x]++;
		}
	}
	bool same(int x,int y){ return find(x)==find(y); }
}uf;
vector<pair<ll,int> >vec;
