	sort(vec.begin(),vec.end());
	seg_plus.init();
	seg_minus.init();
	for(int i=0;i<vec.size();i++){
		ll val = vec[i].first;
		int x = vec[i].second;
		pair<ll,int>w = seg_minus.query(1,x-1,0,0,(1<<18)-1);
		if(w.first <= 1e17 && w.second <= n){
			ll cs = w.first+1LL*x*D+val;
			edge.push_back(mp(cs,mp(w.second,x)));
		}
		w = seg_plus.query(x+1,n,0,0,(1<<18)-1);
		if(w.first <= 1e17 && w.second <= n){
			ll cs = w.first-1LL*x*D+val;
			edge.push_back(mp(cs,mp(w.second,x)));
		}
		seg_minus.update(x,val-1LL*D*x);
		seg_plus.update(x,val+1LL*D*x);
	}
	SORT(edge);
	uf.init();
	ll ans = 0;
	int cnt = 0;
	for(int i=0;i<edge.size();i++){
		if(uf.same(edge[i].second.first,edge[i].second.second) == false){
			uf.unite(edge[i].second.first,edge[i].second.second);
			ans += edge[i].first;
			cnt ++;
		}
	}
	assert(cnt == n-1);
	printf("%lld\n",ans);
}

