        if(l==1) tr[x].mn[0]=tr[x].mn[1]=inf;
        else tr[x].mn[0]=a[l]+a[1]+1ll*(l-1)*D, tr[x].mn[1]=a[l]-l*D+inf;
        tr[x].pos[0]=tr[x].pos[1]=l;
        return;
    }

    int mid=(l+r)>>1;
    build(x<<1, l, mid); build(x<<1|1, mid+1, r);

    up(x);
    // printf("x:%d l:%d r:%d mn0:%lld pos0:%d mn1:%lld pos1:%d\n", x, l, r, tr[x].mn[0], tr[x].pos[0], tr[x].mn[1], tr[x].pos[1]);
}

inline void addone(int x, ll delta, int ty)
{
    tr[x].mn[ty]+=delta;
    tr[x].delta[ty]+=delta;
}

inline void down(int x)
{
    for(int i=0;i<2;i++)
        if(tr[x].delta[i])
            addone(x<<1, tr[x].delta[i], i), addone(x<<1|1, tr[x].delta[i], i);

    tr[x].delta[0]=tr[x].delta[1]=0;
}

void updateset(int x, int l, int r, int cx)
{
    if(l==r) return (void)(tr[x].mn[0]=tr[x].mn[1]=inf);

    down(x);

    int mid=(l+r)>>1;
    if(cx<=mid) updateset(x<<1, l, mid, cx);
    else updateset(x<<1|1, mid+1, r, cx);

    up(x);

    // printf("x:%d l:%d r:%d tr[x].mn[0]:%lld tr[x].pos[0]:%d\n", x, l, r, tr[x].mn[0], tr[x].pos[0]);
    // printf("x:%d l:%d r:%d tr[x].mn[1]:%lld tr[x].pos[1]:%d\n", x, l, r, tr[x].mn[1], tr[x].pos[1]);
}

void update(int x, int l, int r, int cl, int cr, ll delta, int ty)
{
    if(cl<=l && r<=cr) return addone(x, delta, ty);

    down(x);

    int mid=(l+r)>>1;
    if(cl<=mid) update(x<<1, l, mid, cl, cr, delta, ty);
    if(cr>mid) update(x<<1|1, mid+1, r, cl, cr, delta, ty);

    up(x);
}

inline void insert(int x)
{
    // printf("x:%d\n", x);
    ll delta=a[x]-1ll*x*D;
    ddq pos=s1.lower_bound((poi){x, delta}); 
    ddq pre=pos; pre--;
    if(pre->w>delta)
    {
        ddq it=pos; //printf("it->w:%lld\n", it->w);
        for(;it!=s1.end() && it->w>=delta;it++)
        {
            ddq nxt=it; it++;
            update(1, 1, n, it->pos, nxt->pos-1, -it->w+delta, 0);
            // printf("iterator->w:%lld\n", it->w);
        }
        update(1, 1, n, x, pos->pos-1, delta-pre->w, 0);
        s1.erase(pos, it); 
        s1.insert((poi){x, delta}); 
    }

    delta=a[x]+1ll*x*D;
    pos=s2.lower_bound((poi){x, delta});
    // if(x==4) printf("x:%d delta:%lld pos->w:%lld\n", x, delta, pos->w);
    if(pos->w>delta)
    {
        ddq it=pos;
        while(it!=s2.begin())
        {
            it--;
            if(it->w<delta)
            {
                it++; break;
            }
            else 
            {
                ddq pre=it; pre--;
                // printf("change:: L:%d R:%d it->w:%lld delta:%lld\n", pre->pos+1, it->pos, it->w, delta);
                update(1, 1, n, pre->pos+1, it->pos, -it->w+delta, 1);
            }   
        }
        pre=pos; pre--;
        // printf("pre->pos+1:%d x:%d delta:%lld pos->w:%lld\n", pre->pos+1, x, delta, pos->w);
        update(1, 1, n, pre->pos+1, x, delta-pos->w, 1);
        s2.erase(it, pos);
        s2.insert((poi){x, delta});
    }

    updateset(1, 1, n, x);
}

