void solve(ll l,ll r, vector< pair<ll , pll > > &e)
{
        ll mid = (l + r) /2;
        ll id1=-1;
        ll id2=-1;
        if(l == r) return;
        ll mnm = 1e16;
        for(ll i=l;i<=mid;i++) {
                if(mnm > a[i] - i*D) {
                        mnm = a[i] - i*D;
                        id1 = i;
                }
        }
        mnm = 1e16;
        for(ll i=mid+1;i <= r; i++) {
                if(mnm > a[i] - i*D) {
                        mnm = a[i] - i*D;
                        id2 = i;
                }
        }
        for(ll i=mid+1;i<=r;i++) {

                e.pb(make_pair(a[i] + a[id1] + (i - id1)*D , make_pair(i , id1)));
        }
        for(ll i=l;i<=mid;i++) {

                e.pb(make_pair(a[i] + a[id2] + (id2 - i)*D , make_pair(i , id2)));
        }
        solve(l,mid, e);
        solve(mid+1, r, e);
}
