struct UnionFind{
   vector<int> par;
   UnionFind(int n):par(n,-1){}
   int find(int x){
       if(par[x]<0)return x;
       return par[x]=find(par[x]);
   }
   bool unite(int x,int y){
       x=find(x);
       y=find(y);
       if(x==y)return false;
       if(par[x]>par[y]){
           par[y]+=par[x];
           par[x]=y;
       }
       else{
           par[x]+=par[y];
           par[y]=x;
       }
       return true;
   }

   bool same(int x,int y){
       return find(x)==find(y);
   }
};


using p3=pair<ll,pint>;
ll a[202020],d;

ll dist(int x,int y){
    return d*(ll)abs(x-y)+a[x]+a[y];
}
void dfs(int l,int r,vector<p3> &v){
    vector<p3> ret;
    ret.push_back({longinf,{0,0}});
    if(l+1>=r){
        v.push_back({longinf,{0,0}});
        return;
    }
    ll mini=longinf,idx=-1;
    int m=(l+r)/2;
    for(int i=l;i<m;++i){
        if(dist(i,m)<mini)mini=dist(i,m),idx=i;
    }
    for(int i=m;i<r;++i){
        ret.push_back({dist(idx,i),{idx,i}});
    }
    mini=longinf;idx=-1;
    for(int i=m;i<r;++i){
        if(dist(i,l)<mini)mini=dist(i,l),idx=i;
    }
    for(int i=l;i<m;++i){
        ret.push_back({dist(idx,i),{idx,i}});
    }
    sort(ret.begin(),ret.end());
    vector<p3> vl,vr;
    dfs(l,m,vl);
    dfs(m,r,vr);
    int il=0,im=0,ir=0,sl=vl.size(),sm=ret.size(),sr=vr.size();
    while(il<sl&&im<sm&&ir<sr){
        if(vl[il]<ret[im]&&vl[il]<vr[ir])v.push_back(vl[il++]);
        else if(ret[im]<vr[ir])v.push_back(ret[im++]);
        else v.push_back(vr[ir++]);
    }
}
