// 最小全域技を求める
// O(E log V)
// verify http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=GRL_2_A

template<typename T>
T prim(vector<vector<pair<int, T>>> &g){
    int n = (int)g.size();
    T ret = 0;
    vector<bool> used(n, false);
    using P = pair<T, int>;
    priority_queue<P, vector<P>, greater<P>> que;
    que.push({0, 0});
    while(!que.empty()){
        auto p = que.top();
        que.pop();
        if(used[p.second]) continue;
        used[p.second] = true;
        ret += p.first;
        for(auto &e : g[p.second]){
            que.push({e.second, e.first});
        }
    }

    return ret;
}

int main(){
  using T = pair<lint, lint>;  // type T
  using E = lint;  // type E
  auto f = [](T a, T b){ // return type T value
    return min(a, b);
  };
  auto g = [](T a, E b){ // return type T value
    return make_pair(b, a.second);  // return b;
  };
  T ti = {INF, -1};  // identify element
  int n, D; cin >> n >> D;
  vector<pair<lint, lint>> dat(n);
  for(int i = 0; i < n; i++) {
    dat[i] = {INF, i};
  }
  SegmentTree<T, E, decltype(f), decltype(g)> sg1(f, g, ti);  // don't change
  sg1.build(dat);   // 初期配列を代入
  SegmentTree<T, E, decltype(f), decltype(g)> sg2(f, g, ti);  // don't change
  sg2.build(dat);   // 初期配列を代入

  vector<vector<pair<int, lint>>> graph(n);

  vector<lint> a(n);
  for(int i = 0; i < n; i++) cin >> a[i];
  for(int i = 0; i < n; i++) {
    sg1.update(i, -i * D + a[i]);
    sg2.update(i,  i * D + a[i]);
  }

  // cout << sg1.query(0, n).first << " " << sg1.query(0, n).second << endl;

  vector<pair<int, int>> pv(n);
  for(int i = 0; i < n; i++) pv[i] = {a[i], i};
  sort(RALL(pv));

  for(int i = 0; i < n; i++) {
    lint id = pv[i].second;
    lint id1 = sg1.query(0, id).second;
    lint id2 = sg2.query(id + 1, n).second;
    // cerr << id << " " << id1 << " " << id2 << endl;
    if(id1 != -1) {
      graph[id].push_back({id1, a[id] + a[id1] + (int)abs(id - id1) * D});
      graph[id1].push_back({id, a[id] + a[id1] + (int)abs(id - id1) * D});
    }
    if(id2 != -1) {
      graph[id].push_back({id2, a[id] + a[id2] + (int)abs(id - id2) * D});
      graph[id2].push_back({id, a[id] + a[id2] + (int)abs(id - id2) * D});
    }

    sg1.update(id, INF);
    sg2.update(id, INF);
    // sg1.update(id1, INF);
    // sg2.update(id2, INF);
  }

  cout << prim(graph) << endl;

  return 0;
}

