#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
using T = tuple<ll, ll, ll>;
bool operator>(const T a, const T b){return get<0>(a) > get<1>(b);};

class UnionFind {
	public:
		vector<ll> table;

		UnionFind(int size){
			table.resize(size, -1);
		}

		int find(int x){
			if (table[x] < 0) return x;
			else {
				table[x] = find(table[x]);
				return table[x];
			}
		}

		bool same(int x, int y) {
			return find(x) == find(y);
		}

		bool is_root(int x){
			if (table[x] < 0) return true;
			else return false;
		}

		void unite(int x, int y){
			int r1 = find(x);
			int r2 = find(y);
			if (r1 != r2) {
				if (table[r1] > table[r2]){
					table[r2] = r1;
					table[r1]--;
				} else {
					table[r1] = r2;
					table[r2]--;
				}
			}
			return;
		}
};

int main() {
	ll n, d; cin >> n >> d;
	vector<ll> a(n), cost_left_num(n), cost_left_id(n), cost_right_num(n), cost_right_id(n), limit_left(n), limit_right(n);
	for (int i = 0; i < n; ++i) {
		ll x; cin >> x;
		a[i] = x; cost_left_num[i] = x; cost_right_num[i] = x;
	}
	UnionFind uf(n);
	iota(cost_left_id.begin(), cost_left_id.end(), 0);
	iota(cost_right_id.begin(), cost_right_id.end(), 0);
	iota(limit_left.begin(), limit_left.end(), 0);
	iota(limit_right.begin(), limit_right.end(), 0);
	priority_queue<T, vector<T>, greater<T> > q;
	for (int i = 0; i < n-1; ++i) {
		T t0 = make_tuple(a[i] + a[i+1], i, i+1);
		q.push(t0);
	}

	int cnt = n;
	ll ans = 0;

	while (cnt > 1) {
		T l = q.top(); q.pop();
		ll c = get<0>(l); ll i = get<1>(l); ll j = get<2>(l);
		if (uf.same(i, j)) continue;
		else {
			cnt--;
			ll x = uf.find(i); ll y = uf.find(j);
			uf.unite(x, y);
			ll z = uf.find(x);
			ans += d + c;
			limit_right[z] = limit_right[y];
			limit_left[z] = limit_left[x];

			if (a[cost_left_id[x]] + d * (cost_left_id[x] - limit_left[z]) <= a[cost_left_id[y]] + d * (cost_left_id[y] - limit_left[z])) {
				cost_left_num[z] = cost_left_num[x];
				cost_left_id[z] = cost_left_id[x];
			}
			else {
				cost_left_num[z] = a[cost_left_id[y]] + d * (cost_left_id[y] - limit_left[z]);
				cost_left_id[z] = cost_left_id[y];
			}

			if (a[cost_right_id[y]] + d * (limit_right[z] - cost_right_id[y]) <= a[cost_right_id[x]] + d * (limit_right[z] - cost_right_id[x])) {
				cost_right_num[z] = cost_right_num[y];
				cost_right_id[z] = cost_right_id[y];
			}
			else {
				cost_right_num[z] = a[cost_right_id[x]] + d * (limit_right[z] - cost_right_id[x]);
				cost_right_id[z] = cost_right_id[x];
			}

			if (limit_left[z] > 0) {
				ll w = uf.find(limit_left[z]-1);
				T t0 = make_tuple(cost_left_num[z] + cost_right_num[w], w, z);
				q.push(t0);
			}
			if (limit_right[z] < n-1) {
				ll w = uf.find(limit_right[z]+1);
				T t0 = make_tuple(cost_left_num[w] + cost_right_num[z], z, w);
				q.push(t0);
			}
		}
	}
	cout << ans << "\n";
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long
const int N = 200005;
vector<int> pai , peso ;
int A[N];
int best[N];
int n , D;
void init(int N){
	for(int i = 0 ; i <= N ; i ++) pai[i] = i , peso[i] = 1;
}
int fd(int x){
	return pai[x] == x ? x : pai[x] = fd(pai[x]);
}
void join(int u , int v){
	u = fd(u) , v = fd(v);
	if(peso[u] > peso[v]) swap(u,v);
	pai[u] = v , peso[v] += peso[u];
}

struct node{
	int vl,  idx;
};

node merge(node a , node b){
	node x;
	if(a.vl < b.vl) x = a;
	else x = b;
	return x;
}


node st[4*N];

void update(int x , int vl , int idx,  int l = 1 , int r = n, int curr = 1){
	int mid = (l+r)/2;
	if(l == r && l == x){
		if(st[curr].vl > vl) st[curr].vl = vl , st[curr].idx = idx;
		return ;
	}
	if(x <= mid) update(x,vl,idx,l,mid,2*curr);
	else update(x,vl,idx,mid+1,r,2*curr + 1);
	st[curr] = merge(st[2*curr + 1] , st[2*curr]);
}

node query(int x , int y , int l = 1 , int r = n  ,int curr = 1){
	int mid = (l+r)/2;
	if( l == x && r == y){
		return st[curr];
	}
	if(y <= mid) return query(x,y,l,mid,2*curr);
	else if(x > mid) return query(x,y,mid+1,r,2*curr + 1);
	return merge(query(x,mid,l,mid,2*curr) , query(mid+1,y,mid+1,r,2*curr + 1));
}

struct edge{
	int x , y , z;
}; 

int32_t main(){
	scanf("%lld%lld" , &n , &D);
	peso.resize(n + 1) , pai.resize(n + 1);
	init(n);
	for(int i = 1 ; i <= n; i ++) scanf("%lld" , &A[i]);
	// boruvka
	int ans = 0;
	int rcnt = 0;
	while(peso[fd(1)] != n){
		for(int i = 0 ; i < 4*N ; i ++){
			st[i].vl = (int) 1e16;
			st[i].idx = -1;
		}
		for(int i = 1 ; i <= n; i ++) best[i] = -1;
		// faz pra esquerda 
		for(int i = 1 ; i <= n; i ++){
			int U = fd(i);
			node W , K;
			W.idx = -1 , W.vl = (int) 1e16;
			K.idx = -1 , K.vl = (int) 1e16;
			if(U > 1) W = query(1 , U-1);
			if(U < n) K = query(U + 1 , n);
			if(W.idx != -1 && K.idx != -1){
				if(W.vl < K.vl) best[i] = W.idx;
				else best[i] = K.idx;
			}
			else if(W.idx != -1) best[i] = W.idx;
			else if(K.idx != -1) best[i] = K.idx;
			update(fd(i) , A[i] - i*D , i);
		}
		for(int i = 0 ; i < 4*N ; i ++){
			st[i].vl = (int) 1e18;
			st[i].idx = -1;
		}
		// faz pra direita
		for(int i = n ; i >= 1; i --){
			int U = fd(i);
			node W , K;
			W.idx = -1 , W.vl = (int) 1e18;
			K.idx = -1 , K.vl = (int) 1e18;
			if(U > 1) W = query(1 , U-1);
			if(U < n) K = query(U + 1 , n);
			int newbest = -1;
			if(W.idx != -1 && K.idx != -1){
				if(W.vl < K.vl) newbest = W.idx;
				else newbest = K.idx;
			}
			else if(W.idx != -1) newbest = W.idx;
			else if(K.idx != -1) newbest = K.idx;
			if(newbest != -1){
				if(best[i] == -1){
					best[i] = newbest;
				}
				else{
					if((A[i] + A[best[i]] + abs(best[i] - i)*D) > (A[i] + A[newbest] + abs(newbest - i)*D)) best[i] = newbest;
				}
			}
			update(fd(i) , A[i] + i*D , i);
		}
		vector<edge> R;
		for(int i = 1 ; i <= n; i ++){
			if(best[i] == -1) continue;
			if(fd(best[i]) != fd(i)){
				R.push_back({i , best[i] ,abs(best[i] - i)*D + A[best[i]] + A[i] });
			}
		}
		sort(R.begin() , R.end() , [&](edge a , edge b){
			return a.z < b.z;
		});
		set<int> WW;
		for(auto w : R){
			if(fd(w.x) != fd(w.y)){
				if(WW.count(fd(w.x))) continue;
				WW.insert(fd(w.x));
				join(w.x , w.y);
				ans += w.z;
			}
		}
	}
	printf("%lld\n" , ans);
}

