    for (int i = 0; i < N; ++i) {
        long long a; cin >> a; A[i] = make_pair(a, i);
        left.set(i, A[i].first - D * i);
        right.set(i, A[i].first + D * i);
    }
    left.build(), right.build();
//    sort(A.begin(), A.end(), greater<pair<long long,int> >());

    // A[v] が大きい法から順に
    vector<Edge> edges;
    for (int i = 0; i < N; ++i) {
