struct UF
{
	int par[200005],rank[200005];
	void init(int n)
	{
		for(int i=0;i<n;i++)
		{
			par[i]=i;
			rank[i]=0;
		}
	}
	int find(int x)
	{
		if(par[x]==x)
		    return x;
		return par[x]=find(par[x]);
	}	
	void unite(int x,int y)
	{
		x=find(x);
		y=find(y);
		if(x==y)
			return;
		if(rank[x]<rank[y])
			par[x]=y;
		else
		{
			par[y]=x;
			if(rank[x]==rank[y])
				rank[x]++;
		}
	}
	bool same(int x,int y)
	{
		return find(x)==find(y);
	}	
}uf;
vector <PP> edge;
void solve(int l,int r)
{
	if(l==r)
	    return;
	//cout<<l<<' '<<r<<endl;
	int m=(l+r)/2;
	long long mn=2e18;
    int pl=-1;
    for(int i=l;i<=m;i++)
    {
    	long long vl=a[i]-d*(long long)i;
    	if(mn>vl)
    	{
    		mn=vl;
    		pl=i;
		}
	}
	mn=2e18;
	int pr=-1;
	for(int i=m+1;i<=r;i++)
	{
		long long vl=a[i]+d*(long long)i;
		if(mn>vl)
		{
			mn=vl;
			pr=i;
		}
	}
	for(int i=l;i<=m;i++)
	{
		long long vl=a[i]-d*(long long)i;
		long long vr=a[pr]+d*(long long)pr;
		edge.push_back(PP(vl+vr,P(i,pr)));
	}
	for(int i=m+1;i<=r;i++)
	{
		long long vl=a[pl]-d*(long long)pl;
		long long vr=a[i]+d*(long long)i;
		edge.push_back(PP(vl+vr,P(pl,i)));
	}
	solve(l,m);
	solve(m+1,r);
}
