template<class Value, class Mod, class Magic, class ApplyMod, class MergeMods>
struct TreeSegment {
	struct Node {
		bool have_mod = false;
		int l = -1, r = -1;
		Value value;
		Mod mod;
	};	

	Magic magic;
	ApplyMod apply_mod;
	MergeMods merge_mods;

	vector<Node> S;
	int n;

	bool __intersects(const int &tl, const int &tr, const int &ql, const int &qr) {
		return !(tr <= ql || qr <= tl);
	}

	int __create_node() {
		S.pb(Node());
		return len(S) - 1;
	}

	Value __get_value(const int &i, const int &tl, const int &tr) {
		if (!S[i].have_mod) return S[i].value;
		return apply_mod(S[i].value, S[i].mod, tl, tr);
	}

	void __recalc_value(const int &i, const int &tl, const int &tr) {
		if (tl + 1 != tr) {
			int mid = (tl + tr) / 2;
			S[i].value = magic(
				__get_value(S[i].l, tl, mid),
				__get_value(S[i].r, mid, tr)
			);
		}
	}

	void __add_mod(const int &i, const int &tl, const int &tr, const Mod &sub) {
		if (S[i].have_mod) {
			S[i].mod = merge_mods(S[i].mod, sub, tl, tr);
		} else {
			S[i].mod = sub;
			S[i].have_mod = true;
		}
	}

	void __push(const int &i, const int &tl, const int &tr) {
		if (S[i].have_mod) {
			S[i].value = apply_mod(S[i].value, S[i].mod, tl, tr);
			if (tl + 1 != tr) {
				int mid = (tl + tr) / 2;
				__add_mod(S[i].l, tl, mid, S[i].mod);
				__add_mod(S[i].r, mid, tr, S[i].mod);
			}
			S[i].have_mod = false;
		}
	}

	int init(const int &tl, const int &tr, const vector<Value> &src) {
		int i = __create_node();
		if (tl + 1 == tr) {
			S[i].value = src[tl];
		} else {
			int mid = (tl + tr) / 2;
			S[i].l = init(tl, mid, src);
			S[i].r = init(mid, tr, src);
			__recalc_value(i, tl, tr);
		}
		return i;
	}

	Value __query(const int &i, const int &tl, const int &tr,
			const int &ql, const int &qr) {
		__push(i, tl, tr);
		if (ql <= tl && tr <= qr) {
			return S[i].value;
		} else {
			int mid = (tl + tr) / 2;
			if (__intersects(tl, mid, ql, qr) && __intersects(mid, tr, ql, qr)) {
				return magic(
					__query(S[i].l, tl, mid, ql, qr),
					__query(S[i].r, mid, tr, ql, qr)
				);
			} else if (__intersects(tl, mid, ql, qr)) {
				return __query(S[i].l, tl, mid, ql, qr);
			} else if (__intersects(mid, tr, ql, qr)) {
				return __query(S[i].r, mid, tr, ql, qr);
			} else {
				return mp((ll)1e18, -1);
				assert(false);
			}
		}
	}

	void __update(const int &i, const int &tl, const int &tr,
			const int &ql, const int &qr, const Mod &mod) {
		__push(i, tl, tr);
		if (ql <= tl && tr <= qr) {
			__add_mod(i, tl, tr, mod);
		} else {
			int mid = (tl + tr) / 2;
			if (__intersects(tl, mid, ql, qr)) {
				__update(S[i].l, tl, mid, ql, qr, mod);	
			}
			if (__intersects(mid, tr, ql, qr)) {
				__update(S[i].r, mid, tr, ql, qr, mod);
			}
			__recalc_value(i, tl, tr);
		}
	}

	template<class Check>
	pair<int, Value> __find_right(const int &i, const int &tl, const int &tr,
			const int &L, const Check &checker, const Value &pref) {
		__push(i, tl, tr);
		if (tr <= L) return mp(-1, pref);
		if (tl + 1 == tr) {
			Value _this = magic(pref, __get_value(i, tl, tr));
			if (checker(_this)) {
				return mp(tl, _this);
			} else {
				return mp(-1, _this);
			}
		} else {
			int mid = (tl + tr) / 2;
			if (L <= tl) {
				Value _left = magic(pref, __get_value(S[i].l, tl, mid));
				if (checker(_left)) {
					return __find_right(S[i].l, tl, mid, L, checker, pref);
				} else {
					return __find_right(S[i].r, mid, tr, L, checker, _left);
				}
			} else {
				auto t = __find_right(S[i].l, tl, mid, L, checker, pref);
				if (t.first != -1) return t;
				return __find_right(S[i].r, mid, tr, L, checker, t.second);
			}	
		}
	}

	template<class Check>
	pair<int, Value> __find_left(const int &i, const int &tl, const int &tr,
			const int &R, const Check &checker, const Value &pref) {
		__push(i, tl, tr);
		if (R < tl) return mp(-1, pref);
		if (tl + 1 == tr) {
			Value _this = magic(pref, __get_value(i, tl, tr));
			if (checker(_this)) {
				return mp(tl, _this);
			} else {
				return mp(-1, _this);
			}
		} else {
			int mid = (tl + tr) / 2;
			if (tr <= R + 1) {
				Value _right = magic(pref, __get_value(S[i].r, mid, tr));
				if (checker(_right)) {
					return __find_left(S[i].r, mid, tr, R, checker, pref);
				} else {
					return __find_left(S[i].l, tl, mid, R, checker, _right);
				}
			} else {
				auto t = __find_left(S[i].r, mid, tr, R, checker, pref);
				if (t.first != -1) return t;
				return __find_left(S[i].l, tl, mid, R, checker, t.second);
			}	
		}
	}

	void init(const vector<Value> &src) {
		n = len(src);
		init(0, len(src), src);
	}

	TreeSegment(const int &n, const Value &def,
			Magic _magic, ApplyMod _apply_mod, MergeMods _merge_mods, Mod)
			: magic(_magic), apply_mod(_apply_mod), merge_mods(_merge_mods) {
		init(vector<Value>(n, def));
	}

	TreeSegment(const vector<Value> &def,
			Magic _magic, ApplyMod _apply_mod, MergeMods _merge_mods, Mod) 
			: magic(_magic), apply_mod(_apply_mod), merge_mods(_merge_mods) {
		init(def);
	}

	Value query(const int &ql, const int &qr) {
		return __query(0, 0, n, ql, qr);
	}

	void update(const int &ql, const int &qr, const Mod &mod) {
		__update(0, 0, n, ql, qr, mod);
	}

	template<class Check>
	int find_right(const int &L, const Check &checker, const Value &start) {
		if (checker(start)) return L - 1;
		int rez = __find_right(0, 0, n, L, checker, start).first;
		return (rez == -1) ? n : rez;
	}

	template<class Check>
	int find_left(const int &R, const Check &checker, const Value &start) {
		if (checker(start)) return R + 1;
		int rez = __find_left(0, 0, n, R, checker, start).first;
		return (rez == -1) ? -1 : rez;
	}
};

int n;
ll D;

vector<int> a;

struct SUS {
	vector<int> up;
	int get_root(int v) {
		if (up[v] == v) return v;
		return up[v] = get_root(up[v]);
	}
	SUS(int n) {
		up.resize(n);
		f(i, n) {
			up[i] = i;
		}
	}
	void merge(int a, int b) {
		a = get_root(a);
		b = get_root(b);
		up[a] = b;
	}
	bool one_comp(int a, int b) {
		return get_root(a) == get_root(b);
	}
};

signed main(signed argc, char *argv[]) {
	scan n, D;
	a.resize(n);
	scan a;

	SUS sus(n);

	ll result = 0;

	while (true) {
		vector<vector<int>> comps(n);
		f(i, n) {
			comps[sus.get_root(i)].pb(i);
		}
		int noempty = 0;
		f(i, n) {
			if (!comps[i].empty()) {
				noempty++;
			}
		}
		if (noempty == 1) break;
		TreeSegment POS(n, mp((ll)1e18, -1), [](pair<ll, int> a, pair<ll, int> b) {
			return min(a, b);
		}, [](pair<ll, int> value, pair<ll, int> mod, int, int) {
			return mod;
		}, [](pair<ll, int> a, pair<ll, int> b, int, int) {
			return b;
		}, mp(1LL, (int)1));

		TreeSegment NEG(n, mp((ll)1e18, -1), [](pair<ll, int> a, pair<ll, int> b) {
			return min(a, b);
		}, [](pair<ll, int> value, pair<ll, int> mod, int, int) {
			return mod;
		}, [](pair<ll, int> a, pair<ll, int> b, int, int) {
			return b;
		}, mp(1LL, (int)1));

		for (int i = 0; i < n; i++) {
			POS.update(i, i + 1, mp(D * (i + 1) + a[i], i));
			NEG.update(i, i + 1, mp(-D * (i + 1) + a[i], i));
		}

		vector<pair<ll, int>> edges(n);
		for (int i = 0; i < len(comps); i++) {
			if (comps[i].empty()) continue;
			edges[i] = mp((ll)1e18, -1);
			for (int j : comps[i]) {
				POS.update(j, j + 1, mp((ll)1e18, -1));
				NEG.update(j, j + 1, mp((ll)1e18, -1));
			}
			for (int j : comps[i]) {
				auto c = NEG.query(0, j);
				auto d = POS.query(j + 1, n);
				c.x += a[j] + (j + 1) * D;
				d.x += a[j] - (j + 1) * D;
				edges[i] = min(edges[i], min(c, d));
			}
			for (int j : comps[i]) {
				POS.update(j, j + 1, mp(D * (j + 1) + a[j], j));
				NEG.update(j, j + 1, mp(-D * (j + 1) + a[j], j));
			}
			assert(edges[i].second != -1);
		}
		for (int i = 0; i < len(comps); i++) {
			if (comps[i].empty()) continue;	
			if (comps[edges[i].second].empty()) continue;
			int a = i;
			int b = edges[i].second;
			if (sus.one_comp(a, b)) continue;
			// print a, b;
			sus.merge(a, b);
			result += edges[i].first;
		}
	}
	print result;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long
const int N = 200005;
vector<int> pai , peso ;
int A[N];
int best[N];
int n , D;
void init(int N){
	for(int i = 0 ; i <= N ; i ++) pai[i] = i , peso[i] = 1;
}
int fd(int x){
	return pai[x] == x ? x : pai[x] = fd(pai[x]);
}
void join(int u , int v){
	u = fd(u) , v = fd(v);
	if(peso[u] > peso[v]) swap(u,v);
	pai[u] = v , peso[v] += peso[u];
}

struct node{
	int vl,  idx;
};

node merge(node a , node b){
	node x;
	if(a.vl < b.vl) x = a;
	else x = b;
	return x;
}


node st[4*N];

void update(int x , int vl , int idx,  int l = 1 , int r = n, int curr = 1){
	int mid = (l+r)/2;
	if(l == r && l == x){
		if(st[curr].vl > vl) st[curr].vl = vl , st[curr].idx = idx;
		return ;
	}
	if(x <= mid) update(x,vl,idx,l,mid,2*curr);
	else update(x,vl,idx,mid+1,r,2*curr + 1);
	st[curr] = merge(st[2*curr + 1] , st[2*curr]);
}

node query(int x , int y , int l = 1 , int r = n  ,int curr = 1){
	int mid = (l+r)/2;
	if( l == x && r == y){
		return st[curr];
	}
	if(y <= mid) return query(x,y,l,mid,2*curr);
	else if(x > mid) return query(x,y,mid+1,r,2*curr + 1);
	return merge(query(x,mid,l,mid,2*curr) , query(mid+1,y,mid+1,r,2*curr + 1));
}

struct edge{
	int x , y , z;
}; 

int32_t main(){
	scanf("%lld%lld" , &n , &D);
	peso.resize(n + 1) , pai.resize(n + 1);
	init(n);
	for(int i = 1 ; i <= n; i ++) scanf("%lld" , &A[i]);
	// boruvka
	int ans = 0;
	int rcnt = 0;
	while(peso[fd(1)] != n){
		for(int i = 0 ; i < 4*N ; i ++){
			st[i].vl = (int) 1e16;
			st[i].idx = -1;
		}
		for(int i = 1 ; i <= n; i ++) best[i] = -1;
		// faz pra esquerda 
		for(int i = 1 ; i <= n; i ++){
			int U = fd(i);
			node W , K;
			W.idx = -1 , W.vl = (int) 1e18;
			K.idx = -1 , K.vl = (int) 1e18;
			if(U > 1) W = query(1 , U-1);
			if(U < n) K = query(U + 1 , n);
			if(W.idx != -1 && K.idx != -1){
				if(W.vl < K.vl) best[i] = W.idx;
				else best[i] = K.idx;
			}
			else if(W.idx != -1) best[i] = W.idx;
			else if(K.idx != -1) best[i] = K.idx;
			update(fd(i) , A[i] - i*D , i);
		}
		for(int i = 0 ; i < 4*N ; i ++){
			st[i].vl = (int) 1e18;
			st[i].idx = -1;
		}
		for(int i = n ; i >= 1; i --){
			int U = fd(i);
			node W , K;
			W.idx = -1 , W.vl = (int) 1e18;
			K.idx = -1 , K.vl = (int) 1e18;
			if(U > 1) W = query(1 , U-1);
			if(U < n) K = query(U + 1 , n);
			int newbest = -1;
			if(W.idx != -1 && K.idx != -1){
				if(W.vl < K.vl) newbest = W.idx;
				else newbest = K.idx;
			}
			else if(W.idx != -1) newbest = W.idx;
			else if(K.idx != -1) newbest = K.idx;
			if(newbest != -1){
				if(best[i] == -1){
					best[i] = newbest;
				}
				else{
					if((A[i] + A[best[i]] + abs(best[i] - i)*D) > (A[i] + A[newbest] + abs(newbest - i)*D)) best[i] = newbest;
				}
			}
			update(fd(i) , A[i] + i*D , i);
		}
		vector<edge> R;
		for(int i = 1 ; i <= n; i ++){
			if(best[i] == -1) continue;
			if(fd(best[i]) != fd(i)){
				R.push_back({i , best[i] ,abs(best[i] - i)*D + A[best[i]] + A[i] });
			}
		}
		sort(R.begin() , R.end() , [&](edge a , edge b){
			return a.z < b.z;
		});
		for(auto w : R){
			if(fd(w.x) != fd(w.y)){
				join(w.x , w.y);
				ans += w.z;
			}
		}
	}
	printf("%lld\n" , ans);
}

