struct point{
	lf x,y;
	lf ang;
	point(){}
	point(lf x,lf y):x(x),y(y){ang=atan2l(y,x);}
	inline point operator=(const point &pt){x=pt.x;y=pt.y;return *this;}
	inline point operator-()const{return point(-x,-y);}
	inline point operator+(const point &pt)const{return point(x+pt.x,y+pt.y);}
	inline point operator-(const point &pt)const{return point(x-pt.x,y-pt.y);}
	inline point operator*(const lf &a)const{return point(x*a,y*a);}
	inline point operator/(const lf &a)const{return point(x/a,y/a);}
	inline point operator^(const lf &ang)const{return point(x*cosl(ang)-y*sinl(ang),x*sinl(ang)+y*cosl(ang));}
	inline point operator+=(const point &pt){return *this=point(x+pt.x,y+pt.y);}
	inline point operator-=(const point &pt){return *this=point(x-pt.x,y-pt.y);}
	inline point operator*=(const lf &a){return *this=point(x*a,y*a);}
	inline point operator/=(const lf &a){return *this=point(x/a,y/a);}
	inline point operator^=(const lf &ang){return *this=point(x*cosl(ang)-y*sinl(ang),x*sinl(ang)+y*cosl(ang));}
	inline lf operator*(const point &pt)const{return x*pt.x+y*pt.y;}//dot
	inline lf operator%(const point &pt)const{return x*pt.y-y*pt.x;}//det
	inline lf length()const{return x*x+y*y;}
	inline lf size()const{return sqrtl(x*x+y*y);}
	inline lf operator^(const point &pt)const{return acosl(*this*pt)/length()/pt.length();}
	inline lf getangle(){return ang=atan2l(y,x);}
	inline lf angle()const{return atan2l(y,x);}
	inline bool operator<(const point &p)const{return ang<p.ang;}
};
