DSU<200005> dsu;
int n,d;
int a[200005];
vector<int> vs[200005];
const int N=1<<18;

struct Segtree{
	pair2<ll> dt[N<<1];
	void change(int to,ll val){
		int now=to+N;
		dt[now]=mak(val,to);
		now>>=1;
		while(now){
			dt[now]=min(dt[now<<1],dt[now<<1|1]);
			now>>=1;
		}
	}
	pair2<ll> qmin(int l,int r,int now=1,int nl=0,int nr=N-1){
		if(nl>=l&&nr<=r){
			return dt[now];
		}
		if(nl>r||nr<l){
			return mak(INF,INF);
		}
		int m=(nl+nr)>>1;
		return min(qmin(l,r,now<<1,nl,m),qmin(l,r,now<<1|1,m+1,nr));
	}
}seg1,seg2;

int main(){
	fio>>n>>d;
	cont(i,n){
		fio>>a[i];
	}
	cont(i,n){
		vs[i].pub(i);
	}
	FILLBIG(seg1.dt);
	FILLBIG(seg2.dt);
	dsu.init();
	cont(i,n){
		seg1.change(i,a[i]-1ll*i*d);
		seg2.change(i,a[i]+1ll*i*d);
	}
	ll ans=0;
	while(dsu.sz[dsu.root(1)]<n){
		vector<pair<pair2<int>,ll>> egs;
		cont(i,n){
			if(dsu.root(i)==i){
				pair2<int> eg=mak(-1,-1);
				ll minx=INF;
				for(int j:vs[i]){
					seg1.change(j,INF);
					seg2.change(j,INF);
				}
				for(int j:vs[i]){
					pair2<ll> p=seg1.qmin(1,j);
					ll val=p.ST+a[j]+(ll)j*d;
					if(val<minx){
						minx=val;
						eg=mak(j,p.ND);
					}
					p=seg2.qmin(j+1,n);
					val=p.ST+a[j]-(ll)j*d;
					if(val<minx){
						minx=val;
						eg=mak(j,p.ND);
					}
				}
				for(int j:vs[i]){
					seg1.change(j,a[j]-(ll)j*d);
					seg2.change(j,a[j]+(ll)j*d);
				}
				egs.emb(eg,minx);
			}
		}
		for(auto i:egs){
			int ri=dsu.root(i.FST),rj=dsu.root(i.SND);
			if(dsu.conn(ri,rj)){
				ans+=i.RD;
				for(int j:vs[ri]){
					vs[rj].push_back(j);
				}
				vs[ri].clear();
			}
		}
	}
	fio<<ans<<ln;
	return 0;
}

