struct MinimumPP {
	using Type = PP;
	static Type Identity() {
		return PP(INFLL, INFLL);
	}
	static Type Operate(const Type& left, const Type& right) {
		return left < right ? left : right;
	}
};


LL N, D;
LL A[200000];
SegmentTree<MinimumPP> Asc(18);
SegmentTree<MinimumPP> Dsc(18);


const LL Huge = INFLL;
int main() {
	cin >> N >> D;
	REP(i, 0, N) {
		cin >> A[i];
		Asc.Update(i, PP(A[i] + i * D, i));
		Dsc.Update(i, PP(A[i] - i * D, i));
	}

	LL sum = 0;
	PriorityQ<pair<LL, PP>> Q;
	auto mn = Asc.Query(1, N);
	Q.push(make_pair(mn.first + A[0], PP(0, mn.second)));
	Asc.Update(0, PP(Huge, 0));
	Dsc.Update(0, PP(Huge, 0));

	int cnt = 1;
	while (cnt < N) {
		auto p = Q.top(); Q.pop();
		LL cost = p.first;
		int from = p.second.first;
		int to = p.second.second;

		if (Asc.Get(to).first >= Huge) {
			auto mn = Asc.Query(from + 1, N) - PP(D * from, 0);
			mn = min(mn, Dsc.Query(0, from) + PP(D * from, 0));

			Q.push(make_pair(mn.first + A[from], PP(from, mn.second)));
			continue;
		}

		Asc.Update(to, PP(Huge, to));
		Dsc.Update(to, PP(Huge, to));
		++cnt;
		sum += cost;

		auto mn2 = Asc.Query(from + 1, N) - PP(D * from, 0);
		mn2 = min(mn2, Dsc.Query(0, from) + PP(D * from, 0));
		if(mn2.first < Huge)Q.push(make_pair(mn2.first + A[from], PP(from, mn2.second)));

		auto mn = Asc.Query(to + 1, N) - PP(D * to, 0);
		mn = min(mn, Dsc.Query(0, to) + PP(D * to, 0));
		Q.push(make_pair(mn.first + A[to], PP(to, mn.second)));

	}
	cout << sum << endl;
	return 0;
}

