struct Edge
{
    int u, v; ll w;
    Edge () {}
    Edge (int u, int v, ll w) : u(u), v(v), w(w) {}
    bool operator < (const Edge &other) const { return w < other.w; }
}edge[N << 2];

struct SEG
{
    struct node
    {
        ll Min; int pos;
        node () {}
        node (ll Min, int pos) : Min(Min), pos(pos) {}
        void init() { Min = INFLL, pos = -1; }
        node operator + (const node &other) const
        {
            node res; res.init();
            if (Min < other.Min)
            {
                res.Min = Min;
                res.pos = pos;
            }
            else
            {
                res.Min = other.Min;
                res.pos = other.pos;
            }
            return res;
        }
    }a[N << 2], res;
    void build(int id, int l, int r)
    {
        a[id].init(); 
        if (l == r) return;
        int mid = (l + r) >> 1;
        build(id << 1, l, mid);
        build(id << 1 | 1, mid + 1, r);
    }
    void update(int id, int l, int r, int pos, ll v)
    {
        if (l == r) 
        {
            a[id] = node(v, pos);
            return;
        }
        int mid = (l + r) >> 1;
        if (pos <= mid) update(id << 1, l, mid, pos, v);
        else update(id << 1 | 1, mid + 1, r, pos, v);
        a[id] = a[id << 1] + a[id << 1 | 1];
    }
    void query(int id, int l, int r, int ql, int qr)
    {
        if (qr < ql) return;
        if (l >= ql && r <= qr)
        {
            res = res + a[id];
            return;
        }
        int mid = (l + r) >> 1;
        if (ql <= mid) query(id << 1, l, mid, ql, qr);
        if (qr > mid) query(id << 1 | 1, mid + 1, r, ql, qr);
    }
}seg[2];

int pre[N];
int find(int x) { return pre[x] == 0 ? x : pre[x] = find(pre[x]); }
ll Kruskal()
{
    memset(pre, 0, sizeof pre);
    sort(edge + 1, edge + 1 + m);
    int cnt = 1;
    ll res = 0;
    for (int i = 1; i <= m; ++i)
    {
        int u = edge[i].u, v = edge[i].v; ll w = edge[i].w;
        int fu = find(u), fv = find(v);
        if (fu == fv) continue;
        pre[fu] = fv;
        ++cnt;
        res += w;
        if (cnt == n) return res;
    }
    return res;
}

