    vll p(N), m(N);
    rep(i,N) {
        p[i] = aa[i].first + D*aa[i].second;
        m[i] = aa[i].first - D*aa[i].second;
    }

    vector<pair<ll,ii>> res;

    SegmentTree<pair<ll,int>> right(N, MINIMUM), left(N, MINIMUM);

    rep(i,N) {
        int val = aa[i].first, at = aa[i].second;
        ll my_plus = val + D*at, my_minus = val - D*at;


        if (i > 0) {
            auto lv = left.query(0, at), rv = right.query(at+1, N);
            if (rv.first != LLONG_MAX){
                res.emplace_back(rv.first + my_minus, ii(rv.second, at));
            }
            if (lv.first != LLONG_MAX){
                res.emplace_back(lv.first + my_plus, ii(lv.second, at));
            }
        }
        right.update(at, pair<ll,int>(my_plus, at));
        left.update(at, pair<ll,int>(my_minus, at));
    }

    return move(res);
}


