void _main() {
    cin >> N >> D;
    rep(i, 0, N) cin >> A[i];

    rep(i, 0, N) {
        uf[i].push_back(i);
        cnt[i] = 1;
        ufst.update(i, { 1, i });
        P[i] = i;
    }

    rep(i, 0, N) lft.update(i, { -1LL * i*D + A[i], i });
    rep(i, 0, N) rht.update(i, { 1LL * i *D + A[i], i });

    ll ans = 0;
    rep(_, 0, N - 1) {
        auto mi = ufst.get(0, N);
        int mii = mi.second;

        fore(i, uf[mii]) lft.update(i, { infl, -1 });
        fore(i, uf[mii]) rht.update(i, { infl, -1 });

        int opt = -1; ll mics = infl;
        fore(i, uf[mii]) {
            auto p = lft.get(0, i);
            ll cst = p.first + 1LL * i * D + A[i];
            if (cst < mics) {
                mics = cst;
                opt = p.second;
            }

            p = rht.get(i + 1, N);
            cst = p.first - 1LL * i * D + A[i];
            if (cst < mics) {
                mics = cst;
                opt = p.second;
