        fore(i, uf[mii]) lft.update(i, { -1LL * i*D + A[i], i });
        fore(i, uf[mii]) rht.update(i, { 1LL * i *D + A[i], i });

        ans += mics;

        int optP = P[opt];

        merge(mii, optP);
    }

    cout << ans << endl;
}

