struct SegmentTree
{
private:
    int N;
    vector<ll> node;
    ll e;

public:
    SegmentTree() {}
    SegmentTree(ll e) : e(e) {}
    void __init__(int sz)
    {
        N = 1;
        while (N < sz)
            N *= 2;
        node.resize(2 * N - 1, e);
    }
    void build(vector<ll> &v)
    {
        int sz = (int)(v.size());
        __init__(sz);
        rep(i, sz)
        {
            node[i + N - 1] = v[i];
        }
        for (int i = N - 2; i >= 0; i--)
        {
            node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }
    void update(int k, ll x)
    {
        k += N - 1;
        node[k] = x;
        while (k > 0)
        {
            k = (k - 1) / 2;
            node[k] = min(node[2 * k + 1], node[2 * k + 2]);
        }
        return;
    }
    ll query(int a, int b) { return query(a, b, 0, 0, N); }
    ll query(int a, int b, int k, int l, int r)
    {
        if (b <= l || r <= a)
            return e;
        if (a <= l && r <= b)
            return node[k];
        ll vl, vr;
        vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
    ll show_one(int i)
    {
        if (0<=i && i<N)
            return node[i + N - 1];
        return e;
    }

    int need()
    {
        int k = 0;
        while (k < N - 1)
        {
            node[k] = min(node[2 * k + 1], node[2 * k + 2]);
            if (node[k] == node[2 * k + 1])
            {
                k = 2 * k + 1;
            }
            else if (node[k] == node[2 * k + 2])
            {
                k = 2 * k + 2;
            }
        }
        return k - N + 1;
    }
    void view(){
        repf(k, N - 1, 2 * N - 1){
            if (node[k]==e)
                cout << "inf ";
            else cout << node[k] << " ";}
        cout << endl;
        return;
    }
};

struct UnionFind
{
    vector<int> root;
    int n;
    void __init__(int sz)
    {
        n = sz;
        root.resize(n, -1);
    }
    int find(int x)
    {
        if (root[x] >= 0)
        {
            root[x] = find(root[x]);
            return root[x];
        }
        return x;
    }
    void unit(int a, int b)
    {
        int ra, rb;
        ra = find(a);
        rb = find(b);
        if (ra == rb)
        {
            return;
        }
        else if (root[ra] <= root[rb])
        {
            root[ra] += root[rb];
            root[rb] = ra;
        }
        else
        {
            root[rb] += root[ra];
            root[ra] = rb;
        }
        return;
    }
    int count()
    {
        set<int> cnt;
        rep(i, n)
            cnt.insert(find(i));
        return cnt.size();
    }
};

