inline void solve(int l,int r)
{
	if(l==r) return;
	int mid=(l+r)/2;
	int minv1=INF,pos1=-1;
	for(int i=l;i<=mid;i++){
		if(a[i]-d*i<minv1){
			minv1=a[i]-d*i;
			pos1=i;
		}
	}
	int minv2=INF,pos2=-1;
	for(int i=mid+1;i<=r;i++){
		if(a[i]+d*i<minv2){
			minv2=a[i]+d*i;
			pos2=i;
		}
	}
	for(int i=l;i<=mid;i++){
		e.push_back(make_pair(a[i]-d*i+minv2,make_pair(i,pos2)));
	}
	for(int i=mid+1;i<=r;i++){
		e.push_back(make_pair(a[i]+d*i+minv1,make_pair(i,pos1)));
	}
	solve(l,mid);
	solve(mid+1,r);
}

