	while(N2<N) N2<<=1;
	REP(i,2){
		REP(j,N2*2-1){
			seg[i][j]=P(INF,-1);
		}
	}
	sort(A,A+N);
	REP(i,N){
		P l,r;
		l=r=P(INF,-1);
		edge el,er;
		el=er=edge(-1,-1,INF);
		if (A[i].second>0){
			l=query(0,0,A[i].second,0,0,N2);
		}
		if (A[i].second<N-1){
			r=query(1,A[i].second+1,N,0,0,N2);
		}
