  int x, y;
  ll w;
};

using P = pair<ll, int>;

auto op = [](const P& a, const P& b) {
  return min(a, b);
};

int main() {
  int N;
  ll D;
  while (cin >> N >> D) {
    vector<ll> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    SegmentTree<P> segL(N, op, P(INF, -1));
    SegmentTree<P> segR(N, op, P(INF, -1));
    for (int i = 0; i < N; i++) {
      segL.update(i, P(-i * D + A[i], i));
      segR.update(i, P(+i * D + A[i], i));
    }
    UnionFind uf(N);
    int components = N;
    ll res = 0;
    while (components >= 2) {
      vec<int, 2> groups(N);
      for (int i = 0; i < N; i++)
        groups[uf.root(i)].push_back(i);
      vector<Edge> edges;
      for (int r = 0; r < N; r++) {
        for (int i : groups[r]) {
          segL.update(i, P(INF, -1));
          segR.update(i, P(INF, -1));
        }
        Edge e = {-1, -1, INF};
        for (int i : groups[r]) {
          P p(INF, -1);
          if (i > 0) {
            auto q = segL.query(0, i);
            if (q.snd >= 0)
              p = min(p, P(q.fst + i * D + A[i], q.snd));
          }
          if (i < N - 1) {
            auto q = segR.query(i + 1, N);
            if (q.snd >= 0)
              p = min(p, P(q.fst - i * D + A[i], q.snd));
          }
          if (p.fst < e.w) {
            e.w = p.fst;
            e.x = i;
            e.y = p.snd;
          }
        }
        edges.push_back(e);
        for (int i : groups[r]) {
          segL.update(i, P(-i * D + A[i], i));
          segR.update(i, P(+i * D + A[i], i));
        }
      }
      for (auto& e : edges) {
        if (uf.unite(e.x, e.y)) {
          res += e.w;
          --components;
        }
      }
    }
    cout << res << endl;
  }
  return 0;
}

