  ll root(ll v) {
    if (par[v] == v) return v;
    return par[v] = root(par[v]);
  }
};

struct Edge {
  ll a, b, c;
};
bool operator<(const Edge& e1, const Edge& e2) {
  return e1.c < e2.c;
}

void solve() {
  ll n, D; cin >> n >> D;
  vector<ll> a(n); cin >> a;
  vector<Edge> edges;
  rep(i, n) {
    {
      ll to = i, cost = linf;
      rep(j, i) {
        if (i == j) continue;
        ll c = abs(i - j) * D + a[i] + a[j];
        if (c < cost) {
          cost = c;
          to = j;
        }
      }
      edges.pb({i, to, cost});
    }
    {
      ll to = i, cost = linf;
      rep(j, i+1, n) {
        if (i == j) continue;
        ll c = abs(i - j) * D + a[i] + a[j];
        if (c < cost) {
          cost = c;
          to = j;
        }
      }
      edges.pb({i, to, cost});
    }
  }
  sort(all(edges));
  UnionFind uf(n);
  ll ans = 0;
  each(e, edges) {
    if (uf.isUnited(e.a, e.b)) continue;
    uf.unite(e.a, e.b);
    ans += e.c;
  }
  cout << ans << endl;
}

