seg operator + (seg x,seg y)
{
	seg rt;
	rt.mn=min(x.mn,y.mn);
	rt.id=x.mn==rt.mn?x.id:y.id;
	return rt;
}

void build(int l,int r,int rt)
{
	if(l==r)
	{
		t0[rt]=(seg){l,a[l]-l*D};
		t1[rt]=(seg){l,a[l]+l*D};
		return;
	}
	build(l,mid,lch);
	build(mid+1,r,rch);
	t0[rt]=t0[lch]+t0[rch];
	t1[rt]=t1[lch]+t1[rch];
}

void ins(int l,int r,int rt,int x,int tp)
{
	if(l==r)
	{
		if(tp)
		{
			t0[rt]=(seg){l,a[l]-l*D};
			t1[rt]=(seg){l,a[l]+l*D};
		}
		else
		{
			t0[rt]=(seg){l,INF};
			t1[rt]=(seg){l,INF};
		}
		return;
	}
	if(x<=mid) ins(l,mid,lch,x,tp);
	else ins(mid+1,r,rch,x,tp);
	t0[rt]=t0[lch]+t0[rch];
	t1[rt]=t1[lch]+t1[rch];
}

seg Ql(int l,int r,int rt,int x)
{
	if(x==1) return (seg){0,INF};
	if(r<=x) return t0[rt];
	if(x<=mid) return Ql(l,mid,lch,x);
	return Ql(l,mid,lch,x)+Ql(mid+1,r,rch,x);
}

seg Qr(int l,int r,int rt,int x)
{
	if(x==n) return (seg){0,INF};
	if(l>=x) return t1[rt];
	if(x>mid) return Qr(mid+1,r,rch,x);
	return Qr(l,mid,lch,x)+Qr(mid+1,r,rch,x);
}	

int getfa(int x)
