	build(1,n,1);
	rep(i,1,n) fa[i]=i;
	while(cnt<n-1)
	{
		trf(),top=0;
		rep(i,1,n)
		{
			int sz=vt[i].size()-1;
			rep(j,0,sz) ins(1,n,1,vt[i][j],0);
			rep(j,0,sz)
			{
				seg tmp=Ql(1,n,1,vt[i][j]);
				tmp=tmp+Qr(1,n,1,vt[i][j]);
				if(tmp.mn<INF) dat[++top]=(data){vt[i][j],tmp.id};
			}
			rep(j,0,sz) ins(1,n,1,vt[i][j],1);
		}
		sort(dat+1,dat+1+top,cmp);
		rep(i,1,top) merge(dat[i].x,dat[i].y);
	}
	printf("%lld\n",ans);
	return 0;
}

