	REP(i, N) ss.insert(pll((N - i - 1) * D + A[i], i));
	for (int i = N - 1; i > 0; i--) {
		auto it = ss.begin();
		if (it->se == i) ++it;
		itv_ss.insert(pii(it->se, i));
		ss.erase(pll((N - i - 1) * D + A[i], i));
	}

	vector<ll3> v;
	for (pii cur : itv_ss) v.emplace_back(abs(cur.fi - cur.se) * D + A[cur.fi] + A[cur.se], cur.fi, cur.se);
	sort(ALL(v));

