    //for (int i=1;i<n;i++) printf("%d ",walk(1,1,n-1)), printf("%lld %lld\n",ans,T[1].mn);
    for (int i=1;i<n;i++) walk(1,1,n-1);
    //printf("%d\n",s.size());
    printf("%lld\n",ans);
    return 0;
}

