typedef long long ll;
typedef pair<ll,ll> pll;
pll dat[1000000];
ll u;
ll inf=1000000000000000000;
ll par[200010];
ll len[200010];
void init(ll n){
  for(ll i=0;i<n;i++){
    par[i]=i;
    len[i]=0;
  }
}
ll root(ll n){
  if(par[n]==n)return n;
  return par[n]=root(par[n]);
}
void unit(ll a,ll b){
  a=root(a);
  b=root(b);
  if(a==b)return;
  if(len[a]>len[b])par[b]=a;
  else{
    par[a]=b;
    if(len[a]==len[b])len[b]++;
  }
}
void add(ll n,ll x){
  ll now=n+u-1;
  dat[now]=make_pair(x,now-u+1);
  while(now>0){
    now=(now-1)/2;
    dat[now]=min(dat[2*now+1],dat[2*now+2]);
  }
}
pll que(ll a,ll b,ll k,ll l,ll r){
  if(a>=r||b<=l)return make_pair(inf,0);
  if(a<=l&&b>=r)return dat[k];
  pll c=que(a,b,2*k+1,l,(l+r)/2);
  pll d=que(a,b,2*k+2,(l+r)/2,r);
  return min(c,d);
}
