void dac(int l, int r) {
    if (l + 1 >= r) return;
    int m = (l + r) >> 1;
    dac(l, m), dac(m, r);
    PLI left = {1LL << 60, 0}, right = {1LL << 60, 0};
    for (int i = l; i < m; i++) left = min(left, PLI{A[i] - i * d, i});
    for (int i = m; i < r; i++) right = min(right, PLI{A[i] + i * d, i});
    for (int i = l; i < m; i++) E.emplace_back(right.first + A[i] - i * d, i, right.second);
    for (int i = m; i < r; i++) E.emplace_back(left.first + A[i] + i * d, i, left.second);
}
