	dp[1][n]=a[n];
	for(int i=n-1;i>=1;i--)
	{
		dp[1][i]=min(dp[1][i+1]+d,a[i]);
	}
	for(int i=2;i<n;i++)
	{
		res+=min(dp[0][i],dp[1][i]);
		//cout<<dp[0][i]<<" "<<dp[1][i]<<endl;
	}
	cout<<res;
	return 0;
}

