int _main()
{
    ll n; llin(n);
    ll d; llin(d);
    V<ll> alist; llina(alist, n);

    V<ll> costs;
    rep (i, n) costs.pb(i * d + alist[i]);
    V<ll> rev_costs;
    rep (i, n) rev_costs.pb((n - i) * d + alist[i]);

    set<t3> linkset;

    ll mincost = 1e18;
    ll minidx = -1LL;
    srep (i, 1LL, n) {
        if (rev_costs[i-1LL] < mincost) {
            mincost = rev_costs[i-1LL];
            minidx = i-1LL;
        }
        linkset.insert(t3(abs(i - minidx) * d + alist[i] + alist[minidx],
                          minidx, i));
    }

    mincost = 1e18;
    minidx = -1LL;
    rrep (i, n-1LL) {
        if (costs[i+1LL] < mincost) {
            mincost = costs[i+1LL];
            minidx = i+1LL;
        }
        linkset.insert(t3(abs(i - minidx) * d + alist[i] + alist[minidx],
                          i, minidx));
    }

    debug_printf("---- linkset\n"); debug_print(linkset);

    UnionFind uf(n);
    ll cnt = 0LL;
    ll ans = 0LL;

    for (auto link : linkset) {
        ll cost = get<0>(link);
        ll idx1 = get<1>(link);
        ll idx2 = get<2>(link);
        if (uf.root(idx1) != uf.root(idx2)) {
            uf.unite(idx1, idx2);
            cnt++;
            ans += cost;
        }
        if (cnt >= n - 1LL) {
            break;
        }
    }

    assert(cnt == n - 1LL);

    cout << ans << endl;

    return 0;
}

