struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) { //ｘの入ってる集合と yの入ってる集合を併合
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) { //xとyが同じ集合に入っているかどうかを判定
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	bool isroot(int x) {
		return data[x] < 0;
	}
	int size(int x) {
		return -data[root(x)];
	}
};


int Prim(BiDGraph g, int s = 0) {//連結グラフの最小全域木　プリム法
	priority_queue<pair<int, pll>, vector<pair<int, pll>>, greater<pair<int, pll>>> cand;
	vector<bool> al(g.vn);
	int alcou = 0;
	int sum = 0;
	BiDGraph MST(g.vn);
	for (pll ed : g.g[s]) {
		cand.push({ ed.second,{ s, ed.first } });
	}
	alcou = 1;
	al[s] = true;
	while (alcou < g.vn) {
		pair<int, pll> cur = cand.top();
		cand.pop();
		if (al[cur.second.second]) {
			continue;
		}
		MST.con(cur.second.first, cur.second.second);
		sum += cur.first;
		al[cur.second.second] = true;
		alcou++;

		for (pll ed : g.g[cur.second.second]) {
			if(al[ed.first] == false)
				cand.push({ ed.second,{ cur.second.second,ed.first } });
		}
	}
	return sum;
}

signed main(void) {
	int n, d;

	cin >> n >> d;
	vector<int> a(n), Aar(n), Bar(n);
	BiDGraph g(n);


	REP(i, n) {
		cin >> a[i];
		Aar[i] =  d * (i + 1) + a[i];
		Bar[i] =  -d * (i + 1) + a[i];
	}

	auto addedge = [](int n, int d, BiDGraph& g, vector<int>& Aar, vector<int>& Bar) {

		vector<int> rui(n + 1);
		set<pll> bset;
		segtree B(n);

		REP(i, n) {
			bset.insert({ Bar[i] , i });
			B.update(i, Bar[i]);

			rui[i + 1] = rui[i] + Aar[i];
		}
		{
			int Minval = INF, Minind = n;
			for (int i = n - 2; 0 <= i; i--) {

				if (Aar[i + 1] < Minval) {
					Minind = i + 1;
					Minval = Aar[i + 1];
				}

				g.con(i, Minind, Minval + Bar[i]);

			}
		}
		int border = n - 1;
		while (border > 0) {

			int Minval = B.query(0, n);

			auto Minitr = bset.lower_bound(MP(Minval, -1));

			int Minind = Minitr->second;
			bset.erase(Minitr);
			if (border > Minind) {
				rep(i, Minind + 1, border + 1) {
					g.con(Minind, i, Minval + Aar[i]);
				}

				border = Minind;
			}
			B.update(Minind, INF);
		}
	};

	addedge(n,d,g, Aar,Bar);


	int ans = Prim(g);

	cout << ans << endl;

	return 0;
}

