	for(int i = 0; i < N; i++){
		cin >> A[i]; 
		L[i] = A[i] + D * i; 
		R[i] = A[i] + D * (N-1-i); 
	}
	long long int mx = L[N-1]; int idx = N-1; 
	for(int i = N-2; i >= 0; i--){
		long long cost = mx - D * i + A[i];
		E.push_back(make_pair(cost, make_pair(i, idx))); 
		if(L[i] < mx){
			mx = L[i]; idx = i; 
		}
