struct APM
{
    int x,y;
    long long cost;

    bool operator <(const APM &e)const
    {
        return cost<e.cost;
    }

}apm[2*Nmax];

inline void Union(int x,int y)
{
    t[y]=x;
}

int Find(int x)
{
    int rad=x,y;

    while(t[rad])
        rad=t[rad];

    while(x!=rad)
    {
        y=t[x];
        t[x]=rad;
        x=y;
    }
    return rad;
}

int main()
{
    cin>>n>>d;

    for(int i=1;i<=n;i++)
        cin>>a[i];

    int minim,pmin;
    minim=a[1];
    pmin=1;

    for(int i=2;i<=n;i++)
    {
        minim+=d;
        apm[++lg]={i,pmin,a[i]+minim};
        if(a[i]<=minim)
        {
            minim=a[i];
            pmin=i;
        }
