ll stresses() {
	edges.clear();

	for (int i = 0; i < n; i++) {
		dist[i] = { INF, INF };
		used[i] = 0;
	}
	dist[0] = { 0, 0 };

	ll ans = 0;
	for (int i = 0; i < n; i++) {
		pair<ll, ll> mn = { INF, INF };
