		for (int j = 0; j < n; j++) {
			dist[j] = min(dist[j], make_pair(abs(mn.second - j) * d + vec[j] + vec[mn.second], mn.second));
		}
	}

	return ans;
}

bool check_pillar() {
	for (int i = 0; i < n; i++) {
		ll cnt = 0;
		for (auto to : gr[i]) {
			if (gr[to].size() >= 3) cnt++;
		}
