}

void input() {
	cin >> n >> d;
	vec.resize(n);
	for (int i = 0; i < n; i++) cin >> vec[i];
}

void rand_test() {
	n = 500, d = rand() % 500 + 1;
	vec.resize(n);
	for (int i = 0; i < n; i++) vec[i] = rand() % 500 + 1;
}

vector<vector<ll>> g;
vector<ll> good;

ll dst(int i, int j) {
	return vec[i] + vec[j] + d * abs(i - j);
}

ll sol() {
	g.clear();
	good.clear();
	set<pair<ll, ll>> s;
	s.insert({ vec[0], 0 });
	ll curAdd = 0;
	g.resize(n);
	for (int i = 1; i < n; i++) {
		curAdd += d;

		pair<ll, ll> v = *(s.begin());
		g[i].push_back(v.second);
		g[v.second].push_back(i);
		v.first += d;

		s.insert({ vec[i] - curAdd, i });
	}

	ll cur = 0;
	vector<bool> used(n);
	while (true) {
		good.push_back(cur);
		bool fl = false;
		used[cur] = 1;

		ll mx = -1;
		for (auto to : g[cur]) {
			if (!used[to] && g[to].size() >= 2) {
				fl = true;
				mx = max(mx, to);
			}
		}

		if (mx != -1) cur = mx;
		if (fl == false) {
			ll mx = -1;
			for (auto to : g[cur]) {
				if (!used[to]) {
					mx = max(mx, to);
				}
			}

			if (mx != -1) good.push_back(mx);
			break;
		}
	}

	sort(good.begin(), good.end());
	vector<ll> nw = good;
	good.clear();
	for (int i = 0; i < nw.size(); i++) {
		while (good.size() >= 2) {
			if (dst(good[good.size() - 2], good.back()) >= dst(good[good.size() - 2], nw[i])) {
				good.pop_back();
			}
			else {
				break;
			}
		}
		good.push_back(nw[i]);
	}
	ll ans = 0;
	for (int i = 0; i < good.size() - 1; i++) {
		ll v = good[i], u = good[i + 1];
		ans += (vec[v] + vec[u] + d * abs(u - v));
		for (int j = v + 1; j <= u - 1; j++) {
			ans += min(vec[v] + vec[j] + d * abs(v - j), vec[u] + vec[j] + d * abs(u - j));
		}
	}

	return ans;
}

