template <typename T, typename F>
class SegmentTree {
  private:
    T e;
    F op;
    ll n;
    vector<T> dat;

  public:
    SegmentTree(F f, T _e, vector<T> v) : op(f), e(_e) {
        int _n = v.size();
        n = 1;
        while(n < _n)
            n *= 2;
        dat.resize(2 * n - 1, e);
        REP(i, _n)
        dat[n + i - 1] = v[i];
        for(int i = n - 2; i >= 0; i--)
            dat[i] = op(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    SegmentTree(F f, T _e, int _n) : op(f), e(_e) {
        n = 1;
        while(n < _n)
            n *= 2;
        dat.resize(2 * n - 1, e);
        for(int i = n - 2; i >= 0; i--)
            dat[i] = op(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    void update(int i, T x) {
        i += n - 1;
        dat[i] = x;
        while(i > 0) {
            i = (i - 1) / 2;
            dat[i] = op(dat[i * 2 + 1], dat[i * 2 + 2]);
        }
    }
    T query(int l, int r) {
        //[l,r)でのクエリ処理
        T left = e, right = e;
        l += n - 1;
        r += n - 1;
        while(l < r) {
            if((l & 1) == 0)
                left = op(left, dat[l]);
            if((r & 1) == 0)
                right = op(dat[r - 1], right);
            l = l / 2;
            r = (r - 1) / 2;
        }
        return op(left, right);
    }
};

class UnionFind {
    vector<int> data;
    int num;

  public:
    UnionFind(int size) : data(size, -1), num(size) {}
    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if(x != y) {
            if(data[y] < data[x])
                swap(x, y);
            data[x] += data[y];
            data[y] = x;
            num--;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
    int numSet() {
        return num;
    }
};

void solve() {
    ll n, d;
    cin >> n >> d;

    vec<ll> a(n);
    REP(i, n) { cin >> a[i]; }

    vec<P> al(n), ar(n);
    REP(i, n) {
        al[i] = {a[i] + d * (n - 1 - i), i};
        ar[i] = {a[i] + d * i, i};
    }

    auto op = [](P a, P b) { return min(a, b); };
    SegmentTree<P, decltype(op)> segl(op, {INF, INF}, al);
    SegmentTree<P, decltype(op)> segr(op, {INF, INF}, ar);

    vec<tuple<ll, ll, ll>> es;

    REP(i, n) {
        if(i > 0) {
            auto bl = segl.query(0, i);
            es.push_back({bl.first + a[i] - (n - 1 - i) * d, bl.second, i});
        }
        if(i < n - 1) {
            auto br = segr.query(i + 1, n);
            es.push_back({br.first + a[i] - i * d, br.second, i});
        }
    }

    sort(all(es));
    UnionFind uni(n);

    ll ans = 0;
    for(auto [cap, u, v] : es) {
        if(uni.unionSet(u, v)) {
            ans += cap;
        }
    }
    cout << ans << en;
}

