// 拡張ユークリッド互除法 (入力 : 整数 a, n, 出力 : GCD(a, n) と xa + yb = GCD(a, n) を満たす整数 x, y)
template<typename Ty> void ExEuclid(Ty a, Ty b, Ty& gcd, Ty& x, Ty& y) {

	Ty r1, r2, r3, x1, x2, x3, y1, y2, y3, q;

	r1 = a; x1 = 1; y1 = 0;
	r2 = b; x2 = 0; y2 = 1;

	while (r2 != 0) {

		r3 = r1 % r2;
		q = r1 / r2;

		x3 = x1 - q * x2;
		y3 = y1 - q * y2;

		r1 = r2; r2 = r3;
		x1 = x2; x2 = x3;
		y1 = y2; y2 = y3;

	}

	gcd = r1; x = x1; y = y1;
	if (gcd < 0) { gcd *= -1; x *= -1; y *= -1; };
}

// a と m は互いに素が前提
template<typename Ty> Ty invmod(Ty a, Ty m) {
	Ty gcd, x, q;
	ExEuclid(a, -m, gcd, x, q);
	if (gcd != 1) return -1;

	return x;
}

ll nPkModP(ll n, ll k) {
	return modfac[n] * modinv[k] % MOD;
}

bool isDuplicated(const vector<ll>& v) {
	vector<bool> flags(1000100, false);
	for (int i = 0; i < v.size(); i++) {
		if (flags[v[i]]) return true;
		flags[v[i]] = true;
	}
	return false;
}

vector<ll> cand;

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N, M;
	cin >> N >> M;
	vector<ll> A(N), B(M);
	cin >> A >> B;

	// ラインに同じ数字が 2 つ以上ある
	if (isDuplicated(A) || isDuplicated(B)) {
		cout << 0 << endl;
		return 0;
	}

	cand = vector<ll>(1000100, 1); cand[0] = 0;
	map<ll, ll> cnt;
	// 縦横両方に存在する数字は自動的に確定する
	REP(i, N) REP(j, M) {
		if (A[i] == B[j]) cand[A[i]] = 0;
		else cnt[min(A[i], B[j])]++;
	}
	REP(i, 1000050) cand[i + 1] += cand[i];

	ll T = N * M;
	// n! mod MOD
	{
		modfac[0] = 1;
		ll x = 1;
		for (ll n = 1; n <= T; n++) {
			x *= n;
			x %= MOD;
			modfac[n] = x;
		}
	}
	// (n!)^-1 mod MOD
	{
		modinv[T] = (invmod(modfac[T], MOD) + MOD) % MOD;
		for (ll k = T - 1; k >= 0; k--) {
			modinv[k] = modinv[k + 1] * (k + 1) % MOD;
		}
	}

	ll ans = 1;
	ll numCandidates = 0; // 割当場所候補数
	ll prev = 0; 
	for (auto e : cnt) {
		ll ub = e.first; // 上限
		numCandidates += cand[ub] - cand[prev];
		prev = ub;
		ll numToAssign = e.second;
		if (numCandidates < numToAssign) {

			cout << 0 << endl;
			return 0;
		}
		ans *= modfac[numCandidates] * modinv[numCandidates - numToAssign] % MOD;
		ans %= MOD;
		numCandidates -= numToAssign;
	}

	cout << ans << endl;

	return 0;
}

