struct SegmentTree {
	int n;
	vector<pair<int, int>> t;

	void pull(int v) {
		t[v] = min(t[2 * v + 1], t[2 * v + 2]);
	}

	void build(int v, int l, int r, vector<int> &a) {
		if (l + 1 == r) {
			t[v] = {a[l], l};
		} else {
			int m = (r + l) >> 1;
			build(2 * v + 1, l, m, a);
			build(2 * v + 2, m, r, a);
			pull(v);
		}
	}

	SegmentTree() {}

	SegmentTree(vector<int> &a) {
		t.clear();
		n = (int)a.size();
		t.resize(4 * n);
		build(0, 0, n, a);
	}

	void set(int v, int l, int r, int pos, int val) {
		if (l + 1 == r) {
			t[v] = {val, pos};
		} else {
			int m = (r + l) >> 1;
			if (pos < m) {
				set(2 * v + 1, l, m, pos, val);
			} else {
				set(2 * v + 2, m, r, pos, val);
			}
			pull(v);
		}
	}

	void set(int pos, int val) {
		set(0, 0, n, pos, val);
	}

	void query(int v, int l, int r, int ql, int qr, pair<int, int> &ans) {
		if (qr <= l || r <= ql) {
			return;
		} else if (ql <= l && r <= qr) {
			ans = min(ans, t[v]);
		} else {
			int m = (r + l) >> 1;
			query(2 * v + 1, l, m, ql, qr, ans);
			query(2 * v + 2, m, r, ql, qr, ans);
		}
	}

	int min_ind(int l, int r) {
		if (l >= r) {
			return -1;
		} else {
			pair<int, int> ans = {INF, -1};
			query(0, 0, n, l, r, ans);
			return ans.second;
		}
	}
};

int n, D;
