void it() {
	for (int i = 0; i < n; i++) {
		comp[i] = DSU::get(i);
		by_comp[comp[i]].push_back(i);
	}
	vector<int> li(n);
	vector<int> ri(n);
	for (int i = 0; i < n; i++) {
		li[i] = -(i * D) + a[i];
		ri[i] = (i * D) + a[i];
	}
	{	
		L = SegmentTree(li);
		R = SegmentTree(ri);
	}
	for (int some = 0; some < n; some++) {
		for (auto i : by_comp[some]) {
			L.set(i, INF);
			R.set(i, INF);
		}
		int best = INF;
		int best_j = -1;
		int best_i = -1;
		for (auto i : by_comp[some]) {
			int minl = L.min_ind(0, i);
			if (minl != -1 && best > (i * D) + a[i] + li[minl]) {
				best = (i * D) + a[i] + li[minl];
				best_j = minl;
				best_i = i;
			}
			int minr = R.min_ind(i + 1, n);
