  REP(i,N){
    pos[i] = MP(xs[i] + i * D, i);
    neg[i] = MP(xs[i] - i * D, i);
  }
  SORT(pos);
  SORT(neg);

  UnionFind uf(N);
  LL ans = 0;
  VI iter(N);
  priority_queue<PLL,vector<PLL>,greater<PLL>> pq;
  REP(i,N){
    int& ix = iter[i];
    while(ix < N && neg[ix].SS >= pos[i].SS) ++ix;
    if(ix < N){
      pq.push(MP(pos[i].FF + neg[ix].FF, i));
    }
  }

int cnt = 0;
  while(!pq.empty()){
    auto p = pq.top();
    pq.pop();
    int i = p.SS;
    int& ix = iter[i];
    if(uf.find(pos[i].SS) !=  uf.find(neg[ix].SS)){
      ans += p.FF;
      uf.unite(pos[i].SS, neg[ix].SS);
      ++cnt;
      if(cnt == N-1){
        break;
      }
    }
    ++ix;
    while(ix < N && neg[ix].SS >= pos[i].SS) ++ix;
    if(ix < N)
      pq.push(MP(pos[i].FF + neg[ix].FF, i));
  }
  cout << ans << endl;

