pair<long long,long long> seg_tree[2][seg_size * 2+1];
pair<long long, long long> seg_find(int now, int w_l, int w_r, int n_l, int n_r,int setting) {
	if (w_l <= n_l && n_r <= w_r) return seg_tree[setting][now];
	if (w_r <= n_l || n_r <= w_l) return make_pair(LONG_INF, -1);
	pair<long long, long long> a = seg_find(now * 2, w_l, w_r, n_l, (n_l + n_r) / 2, setting);
	pair<long long, long long> b = seg_find(now * 2 + 1, w_l, w_r, (n_l + n_r) / 2, n_r, setting);
	if (a.first < b.first) return a;
	else return b;
}
void seg_set(int now) {
	REP(q, 2) {
		if (seg_tree[q][now * 2].first < seg_tree[q][now * 2 + 1].first) {
			seg_tree[q][now] = seg_tree[q][now * 2];
		}
		else {
			seg_tree[q][now] = seg_tree[q][now * 2 + 1];
		}
	}
	if (now != 1) seg_set(now / 2);
	return;
}
vector<tuple<int, int, int>> edges;
int union_find[300000] = {};
int union_search(int a) {
	if (union_find[a] == a) return a;
	return union_find[a] = union_search(union_find[a]);
}
int union_merge(int a, int b) {
	a = union_search(a);
	b = union_search(b);
	union_find[a] = b;
	return 0;
}
