lin calc(int i, int j)
{
    return abs(i-j) * d + a[i] + a[j];
}

lin add(int i)
{
    rest.erase(i);

    for(auto j : rest)
    {
        lin dist = calc(i,j);
        auto iter = path.find(dist);
        if(iter != end(path))
            path[dist].push(make_pair(i,j));
        else
        {
            queue<pair<int,int>> vii;
            vii.push(make_pair(i,j));
            path[dist] = vii;
        }
    }

    tree.emplace(i);
}

