        auto vii = path.begin();
        auto dist = vii->first;
        auto p = vii->second.front();
        vii->second.pop();
        if(vii->second.size() <= 0)
            path.erase(dist);

        auto iter1 = tree.find(p.first);
        auto iter2 = tree.find(p.second);
        if(iter1 != tree.end() && iter2 != tree.end())
            continue;
        else if(iter1 != tree.end())
        {
            add(p.second);
            res += dist;
        }
        else if(iter2 != tree.end())
