int main() {
	ios_base::sync_with_stdio(false);
	int N, D; cin >> N >> D;
	vi A(N); rep(i, N) cin >> A[i];
	int am = distance(begin(A), min_element(begin(A), end(A)));
	ll ans = 0;
	int li = am - 1, ri = am + 1;
	int lmi = am, rmi = am;
	vi par(N, -1);
	par[am] = am;
	rep(i, N - 1) {
		ll rcost = ri >= N ? INFll : ll(ri - rmi) * D + A[ri] + A[rmi];
		ll lcost = li < 0 ? INFll : ll(lmi - li) * D + A[li] + A[lmi];
		if (rcost < lcost) {
			ans += rcost;
			par[ri] = rmi;
			if (A[ri] - A[rmi] < ll(ri - rmi) * D) {
				int root = ri;
				for (int k = ri - 1; k > rmi; k--) {
					ll rcost = ll(rmi - k) * D + A[rmi] + A[k];
					ll lcost = ll(i - root) * D + A[k] + A[root];
					if (lcost < rcost) {
						ans -= rcost - lcost;
					}
					if (A[k] - A[root] < ll(k - root) * D) root = k;
				}
				rmi = ri;
			}
			ri++;
		}
		else {
			ans += lcost;
			par[li] = lmi;
			if (A[li] - A[lmi] < ll(lmi - li) * D) {
				int root = li;
				for (int k = li + 1; k < lmi; k++) {
					ll rcost = ll(k - lmi) * D + A[lmi] + A[k];
					ll lcost = ll(root - k) * D + A[k] + A[root];
					if (rcost < lcost) {
						ans -= lcost - rcost;
					}
					if (A[k] - A[root] < ll(root - k) * D) root = k;
				}
				lmi = li;
			}
			li--;
		}
	}
	cout << ans << endl;
	return 0;
}

