int N;
ll D;
ll A[202020];
ll LT[202020],RT[202020],V[202020];
int le[202020],ri[202020];

void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>D;

	FOR(i,N) {
		cin>>A[i+1];
		LT[i+1]=i*D+A[i+1];
		RT[i+1]=i*D-A[i+1];
	}
	LT[0]=LT[N+1]=1LL<<60;
	RT[0]=RT[N+1]=-1LL<<60;

	FOR(i,N+2) le[i]=i-1, ri[i]=i+1;
	set<pair<ll,int>> S;
	FOR(i,N+1) {
		V[i]=LT[i+1]-RT[i];
		S.insert({V[i],i});
	}

	ll ret=0;
	while(S.size()>2) {
		ret+=S.begin()->first;
		x=S.begin()->second;
		y=ri[x];
		S.erase(S.begin());
		S.erase({V[y],y});

		int xx=le[x];
		S.erase({V[xx],xx});

		LT[x]=min(LT[x],LT[y]);
		RT[x]=max(RT[x],RT[y]);
		ri[x]=ri[y];
		le[ri[x]]=x;

		V[xx]=LT[x]-RT[xx];
		S.insert({V[xx],xx});
		V[x]=LT[ri[x]]-RT[x];
		S.insert({V[x],x});
	}

	assert(S.begin()->second==0 || ri[S.begin()->second]==N+1);
	assert(S.rbegin()->second==0 || ri[S.rbegin()->second]==N+1);

	cout<<ret<<endl;





}


