      }
      tie(rightmin, rminidx) = seg_right.get_min_with_idx(nowidx + 1, N);
      if (rightmin != INF){ // INFなら、基点となる都市より規模の大きい都市なので、無視
        edge_candidates.push(make_tuple(abs(nowidx - rminidx)*D + nowcost + rightmin - rminidx*D, nowidx, rminidx)); //(コスト, a_idx, adj_idx)
      }
    }
//   cout << leftmin << ' ' << lminidx << ' ';
//   cout << rightmin << ' ' << rminidx << endl;
    seg_left.erase(nowidx);
    seg_right.erase(nowidx);
  }

  //5. 1つずつtop()->pop()して、Uniteする（Uniteできたらans+=コスト, できなかったら無視）

  // check
 /*ll aa, bb, cc;
