class LazySegmentTree {
public:
	int n;
  vector<pll> node, lazy;
	bool ismax; //trueなら最大値、falseなら最小値

  LazySegmentTree(vl a, bool _ismax) {
		ismax = _ismax;
		int _n = a.size();
		n = 1; while (n < _n) n *= 2;
		node.resize(2 * n - 1);
        fill(all(node), pll(INF * (1 - (int)ismax * 2), -1));
		lazy.resize(2 * n - 1);
		for (int i = 0; i < _n; i++) node[i + n - 1] = pll(a[i], i);
		for (int i = n - 2; i >= 0; i--) {
			if (ismax) node[i] = max(node[i * 2 + 1], node[i * 2 + 2]);
			else node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);
		}
	}

	// k番目のノードについて遅延評価を行う
	inline void eval(int k, int l, int r) {
		if (lazy[k].first != 0) {
			node[k] = node[k] + lazy[k];
			if (r - l > 1) {
				lazy[2 * k + 1] = lazy[2*k + 1] + lazy[k]; /////
				lazy[2 * k + 2] = lazy[2*k + 1] + lazy[k]; /////
			}
			lazy[k] = pll(0, 0);
		}
	}

	void add(int a, int b, ll x, int k, int l, int r) {
		// k 番目のノードに対して遅延評価を行う
		eval(k, l, r);
		if (b <= l || r <= a) return;
		if (a <= l && r <= b) {
			lazy[k].first += x; //////
			eval(k, l, r);
		}
		else {
			add(a, b, x, 2 * k + 1, l, (l + r) / 2);
			add(a, b, x, 2 * k + 2, (l + r) / 2, r);
			if (ismax) node[k] = max(node[2 * k + 1], node[2 * k + 2]);
			else node[k] = min(node[2 * k + 1], node[2 * k + 2]);
		}
	}

  pll getmax(int a, int b, int k, int l, int r) {
		eval(k, l, r);
		if (b <= l || r <= a) return (ismax ? pll(-INF, -1) : pll(INF, -1));
		if (a <= l && r <= b) return node[k];
		pll resl = getmax(a, b, 2 * k + 1, l, (l + r) / 2);
		pll resr = getmax(a, b, 2 * k + 2, (l + r) / 2, r);
		if (ismax) return max(resl, resr);
		else return min(resl, resr);
	}

};



