  for(Int i=0;i<n;i++) cin>>a[i];
  Kruskal<Int> ks(n);
  using P = pair<Int, Int>;

  const Int INF = 1e18;
  vector<P> ls(n,P(INF,-1)),rs(n,P(INF,-1)),dp(n);
  function<void(Int, Int)> dfs=
    [&](Int l,Int r)->void{
      if(l+1==r){
        dp[l]=P(a[l],l);
        return;
      }
      Int m=(l+r)>>1;      
      dfs(l,m);
      dfs(m,r);
      P x(INF,-1),y(INF,-1);
      for(Int i=l,j=m;i<m||j<r;){
        if(i<m&&(j==r||dp[i].first<=dp[j].first)){
          Int k=dp[i++].second;
          chmin(rs[k],y);
          chmin(x,P(a[k]-k*d,k));
        }else{
          Int k=dp[j++].second;
          chmin(ls[k],x);
          chmin(y,P(a[k]+k*d,k));
        }
      }

      inplace_merge(dp.begin()+l,dp.begin()+m,dp.begin()+r);
    };  
  dfs(0,n);

  auto add_edge=
    [&](Int x,Int y){
      if(x<0||y<0) return;
      Int c=abs(x-y)*d+a[x]+a[y];
      ks.add_edge(x,y,c);
    };
  for(Int i=0;i<n;i++) add_edge(ls[i].second,i);
  for(Int i=0;i<n;i++) add_edge(i,rs[i].second);

  cout<<ks.build()<<endl;
  return 0;
}

