	ll ret=0;
	for (int i=0;i<edge.size();i++){
		P p=edge[i].second;
		if (!uf.same(p.first,p.second)){
			uf.unite(p.first,p.second);
			ret+=edge[i].first;
		}
	}
	printf("%lld",ret);
}

