    for(int j = -1, i = n;i >= 1;i--) {
        int ptr = 0;
        for(auto it = top.begin();it != top.end() && ptr < 20;it++, ptr++) {
            int j = it->second;
            ed.push_back({1ll * abs(i - j) * d + a[i] + a[j], {i, j}});
        }
        top.insert({1ll * i * d + a[i], i});
    }

    sort(ed.begin(), ed.end());

    ll res = 0;
    int cc = n;

    for(pair< ll, pii > e : ed) {
        int u, v;
        tie(u, v) = e.second;
        if(find(u) != find(v)) {
            res += e.first;
            merge(u, v);
            cc--;
        }
    }

#ifdef TEST
    cout << "cc = " << cc << "\n";
#endif

    cout << res << "\n";

    return 0;
}

