				if (top[j].sc != v && (match.count(v) == 0 || match[v].fs > dis(top[j].fs, i))) {
					match[v] = PLL(dis(top[j].fs, i), top[j].fs);
					break;
				}
			}
			REP(j, 2){
				if (top[j].fs == -1 || A[top[j].fs]+D*top[j].fs > A[i]+i*D) {
					if (j == 0 && top[j].sc != v) { top[1] = top[0]; }
					top[j] = PLL(i, v);
					break;
				}
			}
		}
		for (auto x : match) {
			if(uf.unite(x.fs, x.sc.sc)) res += x.sc.fs;
			updated = 1;
		}
	}
	return res;
}

