      if (l < 0) return r;
      if (r < 0 || -l * d + a[l] < -r * d + a[r]) return l;
      return r;
    };
    auto f2 = [](int l, int r) {
      if (l < 0) return r;
      if (r < 0 || l * d + a[l] < r * d + a[r]) return l;
      return r;
    };
    seg[0] = seg[1] = SegmentTree<int>(n, f, -1);
    seg[2] = seg[3] = SegmentTree<int>(n, f2, -1);
  }
  for (int i = 0; i < n; ++i) seg[1].update(i, i);
  for (int i = 0; i < n; ++i) seg[3].update(i, i);
  for (int i = 0; i < n; ++i) {
