    for (int j = 0; j < 2; ++j) {
      int y = seg[j].query(0, x);
      if (y >= 0) pq.push({(x - y) * d + a[x] + a[y], x, y});
      y = seg[j + 2].query(x + 1, n);
      if (y >= 0) pq.push({(y - x) * d + a[x] + a[y], y, x});
    }
    seg[1].update(x, -1);
    seg[0].update(x, x);
    seg[3].update(x, -1);
    seg[2].update(x, x);
  }
  long long res = 0;
  Unionfind uf(n);
  while (pq.size()) {
