    rep(i, N) { cin >> A[i]; }

    vector<Edge> edges;

    REP(i, 0, N)
    REP(j, i + 1, N)
    {
        const ll cost = abs(i - j) * D + A[i] + A[j];
        edges.push_back(Edge(i, j, cost));
    }

    const ll ans = kruscal(N, edges);
    cout << ans << endl;

    return 0;
}

