void Update(pll *seg, int k, pll x) {
  k += size-1;
  seg[k] = x;
  while (k > 0) {
    k = (k-1)/2;
    seg[k] = min(seg[k*2+1], seg[k*2+2]);
  }
}

pll GetMin(pll *seg, int wishl, int wishr, int k, int watchl, int watchr) {
  int mid;
  pll lval, rval;
  if (wishr <= watchl || watchr <= wishl) return pll(INF, INF);
  if (wishl <= watchl && watchr <= wishr) return seg[k]; 

  mid = (watchl+watchr)/2;
  lval = GetMin(seg, wishl, wishr, k*2+1, watchl, mid);
  rval = GetMin(seg, wishl, wishr, k*2+2, mid, watchr);
  return min(lval, rval);
}

using Edge = pair<LL, pii>;

struct UfData {
  int parsz;
  // LL w;
  UfData() : parsz(-1) {
    // w = 0;
  }

  void Merge(const UfData &d, int u, int v) {
    parsz += d.parsz;
    // w += d.w;
  }
};

struct UnionFind {
  vector<UfData> dat;

  UnionFind() {}
  UnionFind(int n) {
    Init(n);
  }

  void Init(int n) {
    dat.assign(n, UfData());
  }

  int Root(int v) {
    if (dat[v].parsz < 0) return v;
    return dat[v].parsz = Root(dat[v].parsz);
  }

  bool Unite(int u, int v) {
    int p = Root(u);
    int q = Root(v);
    if (p == q) return false;

    if (dat[p].parsz > dat[q].parsz) {
      swap(p, q);
      swap(u, v);
    }

    dat[p].Merge(dat[q], u, v);
    dat[q].parsz = p;

    return true;
  }

  bool Same(int u, int v) {
    return Root(u) == Root(v);
  }

  int Size(int v) {
    return -dat[Root(v)].parsz;
  }

  UfData& Data(int v) {
    return dat[Root(v)];
  }
};

signed main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);

  cin >> N >> D;
  size = 1;
  while (size < N) size <<= 1;

  rep(i, N) {
    cin >> A[i];
    Update(seg1,  i, pll(A[i]+i*D, -i));
    Update(seg2, i, pll(A[i]+(N-i)*D, i));
  }

  vector<Edge> es;
  rep(v, N) {
    //cout << "v: " << v << endl;
    pll p = GetMin(seg1, v+1, N, 0, 0, size);
    //cout << p.X << ", " << p.Y << endl;
    if (p.X != INF) {
      es.eb(Edge(A[v]+A[-p.Y]+abs(v+p.Y)*D, pii(v, -p.Y)));
    }
    pll q = GetMin(seg2, 0, v, 0, 0, size);
    //cout << q.X << ", " << q.Y << endl;
    if (q.X != INF) {
      es.eb(Edge(A[v]+A[q.Y]+abs(v-q.Y)*D, pii(v, q.Y)));
    }
  }
  sort(all(es));

  LL ans = 0;
  UnionFind uf(N);
  for (Edge &e : es) {
    LL c = e.X;
    int u, v;
    tie(u, v) = e.Y;
    //cout << "c:" << c << " - " << u << ", " << v << endl;
    if (uf.Same(u, v)) continue;
    ans += c;
    uf.Unite(u, v);
  }
  cout << ans << "\n";
}

