struct QuickFind{
	vector<int> par;
	vector<vector<int>> group;
	QuickFind(int n) : par(n),group(n){
		for(int i = 0;i < n;i++){
			par[i] = i;
			group[i].push_back(i);
		}
	}
	int find(int x){
		return par[x];
	}
	void unite(int x,int y){
		x = par[x],y = par[y];
		if(x == y) return;
		if(group[x].size() < group[y].size()) swap(x,y);
		for(int v : group[y]) par[v] = x;
		group[x].insert(group[x].end(),group[y].begin(),group[y].end());
		group[y].clear();
		par[y] = x;
	}
	bool same(int x,int y){
		return par[x] == par[y];
	}
};

struct RMQIndex{
	using P = pair<int,int>;
	int seg,init;
	vector<P> dat;

	RMQIndex(int n,int init) : init(init),seg(1){
		while(seg < n) seg *= 2;
		dat.resize(seg * 2 - 1);
		for(int i = 0;i < seg;i++) dat[i + seg - 1] = make_pair(init,i);
		for(int i = seg - 2;i >= 0;i--) dat[i] = min(dat[i * 2 + 1],dat[i * 2 + 2]);
	}
	void update(int i,int x){
		dat[i + seg - 1] = make_pair(x,i);
		i += seg - 1;
		while(i){
			i = (i - 1) / 2;
			dat[i] = min(dat[i * 2 + 1],dat[i * 2 + 2]); //do
		}
	}
	P get(int a = 0,int b = -1,int k = 0,int l = 0,int r = -1){
		if(b == -1) b = seg;
		if(r == -1) r = seg;
		if(b <= l || r <= a) return make_pair(init,a);
		if(a <= l && r <= b) return dat[k];
		return min(get(a,b,k * 2 + 1,l,(l + r) / 2),get(a,b,k * 2 + 2,(l + r) / 2,r)); //do
	}
};

signed main(){
	int n,d,a[200010],ans = 0;
	cin >> n >> d;
	for(int i = 0;i < n;i++) cin >> a[i];
	QuickFind qf(n);
	vector<RMQIndex> rmq(2,RMQIndex(n,INF));
	for(int i = 0;i < n;i++){
		rmq[0].update(i,a[i] - d * i);
		rmq[1].update(i,a[i] + d * i);
	}
	while(1){
		bool update = false;
		for(int i = 0;i < n;i++){
			if(qf.group[i].empty()) continue;
			P mi(INF,INF);
			for(int v : qf.group[i]){
				rmq[0].update(v,INF);
				rmq[1].update(v,INF);
			}
			for(int v : qf.group[i]){
				P p = rmq[0].get(0,v),q = rmq[1].get(v + 1);
				chmin(mi,min(P(p.first + d * v + a[v],p.second),P(q.first - d * v + a[v],q.second)));
			}
			for(int v : qf.group[i]){
				rmq[0].update(v,a[v] - d * v);
				rmq[1].update(v,a[v] + d * v);
			}
			//cout << i << " " << mi.first << " " << mi.second << endl;
			if(mi.second < n && !qf.same(i,mi.second)){
				qf.unite(i,mi.second);
				ans += mi.first;
				update = true;
			}
		}
		if(!update) break;
	}
	cout << ans << endl;
}

