struct Edge
{
	int u,v,w;
}edge[N*LOGN*10];
bool cmp(const Edge a,const Edge b)
{
	if (a.w<b.w) return true;
	else return false;
}
void Add(int u,int v)
{
	int w=abs(u-v)*d+a[u]+a[v];
	tot++;
	nxt[tot]=first[u];
	first[u]=tot;
	edge[tot]=(Edge){u,v,w};
	return;
}
int Build(int l,int r,int flag)
{
	if (l==r) return l;
	int mid=(l+r)>>1;
	int minl=Build(l,mid,-1),minr=Build(mid+1,r,1);
	for (int i=l;i<=mid;i++) Add(i,minr);
	for (int i=mid+1;i<=r;i++) Add(i,minl);
	int minlr=inf,point=0;
	for (int i=l;i<=r;i++) 
	    if (i*d*flag+a[i]<minlr) point=i,minlr=i*d*flag+a[i];
	return point;
}
int Get(int x)
{
	if (x==fa[x]) return x;
	else return fa[x]=Get(fa[x]);
}
void Join(int x,int y)
{
	fa[x]=y;
	return;
}
long long Krus()
{
	long long ret=0;
	for (int i=1;i<=n;i++) fa[i]=i;
	sort(edge+1,edge+tot+1,cmp);
	for (int i=1;i<=tot;i++)
	{
		int u=edge[i].u,v=edge[i].v;
		int f1=Get(u),f2=Get(v);
		if (f1!=f2)
		{
			cnt++;
			ret+=1LL*edge[i].w;
			Join(f1,f2);
		}
	}
	return ret;
}
