struct union_find_tree {
    std::vector<int> par, size;
    union_find_tree(int n) : par(n), size(n) {
        for (int i = 0; i < n; i++) {
            par[i] = i;
            size[i] = 1;
        }
    }
    int get_root(int i) {
        if (par[i] == i) { return i; }
        else { return par[i] = get_root(par[i]); }
    }
    void unite(int i, int j) {
        if ((i = get_root(i)) == (j = get_root(j))) { return; }
        if (size[i] < size[j]) { std::swap(i, j); }
        par[j] = i;
        size[i] += size[j];
    }
    bool are_same(int i, int j) { return get_root(i) == get_root(j); }
    int get_size(int i) { return size[get_root(i)]; }
};

template<typename M>
struct segment_tree {
    using T = typename M::T;
    int n;
    std::vector<T> data;
    segment_tree(int n) : n(n), data(n << 1, M::id()) {}
    segment_tree(const std::vector<T> &src) : n(src.size()), data(n << 1) {
        std::copy(src.begin(), src.end(), data.begin() + n);
        for (int i = n - 1; i > 0; i--) { data[i] = M::op(data[i << 1 | 0], data[i << 1 | 1]); }
    }
    void set(int i, const T &x) {
        data[i += n] = x;
        while (i >>= 1) { data[i] = M::op(data[i << 1 | 0], data[i << 1 | 1]); }
    }
    const T &operator[](int i) const { return data[i + n]; }
    T get_sum(int l, int r) const {
        T a = M::id(), b = M::id();
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) { a = M::op(a, data[l++]); }
            if (r & 1) { b = M::op(data[--r], b); }
        }
        return M::op(a, b);
    }
};

