template <typename T>
struct SegmentTree { // on monoid
	int n;
	vector<T> a;
	T unit; // unit
	function<T (T,T)> append; // associative
	SegmentTree() = default;
	SegmentTree(int a_n, T a_unit, function<T (T,T)> a_append):unit(a_unit), append(a_append){
		n = pow(2,ceil(log2(a_n)));
		a.resize(2*n-1, a_unit);
	}
	void point_update(int i, T z) {
//		a[i+n-1] = append(a[i+n-1],z);
		a[i+n-1] = z;
		for (i = (i+n)/2; i > 0; i /= 2) {
			a[i-1] = append(a[2*i-1], a[2*i]);
		}
	}
	T range_concat(int l, int r) {
		return range_concat(0, 0, n, l, r);
	}
	T range_concat(int i, int il, int ir, int l, int r) {
		if (l <= il and ir <= r) {
			return a[i];
		} else if (ir <= l or r <= il) {
			return unit;
		} else {
			return append(
					range_concat(2*i+1, il, (il+ir)/2, l, r),
					range_concat(2*i+2, (il+ir)/2, ir, l, r));
		}
	}
	void build(int i, int il, int ir, const vector<T> &v){
		if(ir - il==1){
			if(il<n)a[i] = v[il];
			else a[i] = unit;
		}else{
			int im = (il+ir)/2;
			build(v,i*2+1,il,im);
			build(v,i*2+2,im,ir);
			a[i] = append(a[i*2+1],a[i*2+2]);
		}
	}
	void build(const vector<T> &v){
		build(0,0,n,v);
	}
	void write(){
		for(int i = 0;i < n;i++){
			T t = range_concat(i,i+1);
			if(t.val==inf<Int>())cerr<<"*"<<" ";
			else cerr<<t.val<<" ";
		}
		cerr<<endl;
	}
};
