    sort(all(a));

    auto op = [](P a, P b) { return min(a, b); };
    SegmentTree<P, decltype(op)> segl(op, {INF, INF}, n);
    SegmentTree<P, decltype(op)> segr(op, {INF, INF}, n);

    vec<tuple<ll, ll, ll>> es;

    REP(i, n) {
        if(a[i].second > 0) {
            auto b = segl.query(0, a[i].second);
            if(b.second != INF) {
                es.push_back({b.first + a[i].first - d * (n - 1 - a[i].second), a[i].second, b.second});
            }
        }
        if(a[i].second < n - 1) {
            auto b = segr.query(a[i].second + 1, n);
            if(b.second != INF) {
                es.push_back({b.first + a[i].first - d * a[i].second, a[i].second, b.second});
            }
        }
        segl.update(a[i].second, make_pair(a[i].first + d * (n - 1 - a[i].second), a[i].second));
        segr.update(a[i].second, make_pair(a[i].first + d * a[i].second, a[i].second));
    }

    sort(all(es));
    UnionFind uni(n);

    ll ans = 0;
    for(auto [cap, u, v] : es) {
        if(uni.unionSet(u, v)) {
            ans += cap;
        }
    }
    cout << ans << en;
}

