struct quickfind {
  vector<int> par;
  vector<vector<int>> vs;
  quickfind() {}
  quickfind(int n) : par(n), vs(n) {
    REP(i, n) par[i] = i, vs[i].push_back(i);
  }
  int root(int a) { return par[a]==a ? a : par[a] = root(par[a]); }
  bool unite(int a, int b) {
    a = root(a), b = root(b);
    if(a == b) return false;
    if(vs[a].size() > vs[b].size()) swap(a, b);
    par[b] = a;
    for(int x: vs[b]) vs[a].push_back(x);
    vs[b].clear();
    return true;
  }
  int same(int a, int b) { return root(a) == root(b); }
  int size(int a) { return vs[root(a)].size(); }
};

