    seg1.update(i, {a[i]-i*d, i});
    seg2.update(i, {a[i]+i*d, i});
  }

  ll ans = 0;
  quickfind qf(n);
  while(qf.size(0) != n) {
    // cout << "sz=" << qf.size(0) << endl;
    vector<pair<PII,ll>> es;
    REP(i, n) if(qf.root(i) == i) {
      PII e(-1, -1);
