struct UnionFind {
    vector<ll> par;

    UnionFind(ll n) : par(n, -1) { }
    void init(ll n) { par.assign(n, -1); }

    ll root(ll x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(ll x, ll y) {
        return root(x) == root(y);
    }

    bool merge(ll x, ll y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    ll size(ll x) {
        return -par[root(x)];
    }
};

vpl edgs;
vl A;
ll N, D;

void addEdge(ll l, ll r){
    if(r-l <= 1) return;
    ll m = (l+r)/2;
    ll ridx = -1, rmin = LINF;
    FOR(i, m, r){
        if(chmin(rmin, A[i]+i*D)) ridx = i;
    }
    FOR(i, l, m) edgs.pb({i, ridx});

    ll lidx = -1, lmin = LINF;
    FOR(i, l, m){
        if(chmin(lmin, A[i]-i*D)) lidx = i;
    }
    FOR(i, m, r) edgs.pb({i, lidx});
    addEdge(l, m);
    addEdge(m, r);
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> D;
    A = vl(N); rep(i, N) cin >> A[i];
    addEdge(0, N);

    multimap<ll, PL> m;
    for(auto e : edgs){
        ll c = A[e.ff] + A[e.ss] + D*abs(e.ff-e.ss);
        m.insert({c, e});
    }

    ll ans = 0;
    auto uf = UnionFind(N);
    FORMAP(it, m){
        ll f = it->ss.ff, s = it->ss.ss;
        if(uf.issame(f, s)) continue;
        uf.merge(f, s);
        ans += it->ff;
    }
    cout << ans << endstr;
    return 0;
}

