signed main(void) 
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll n, d;
  cin >> n >> d;
  vector<ll> a(n);
  REP(i, n) cin >> a[i];

  vector<bool> flag1(n);
  vector<ll> b(n), pfxb(n+1);
  REP(i, n) b[i] = a[i]-i*d;
  pfxb[0] = LLINF;
  REP(i, n) {
    if(b[i] < pfxb[i]) {
      flag1[i] = 1;
      pfxb[i+1] = b[i];
    } else {
      pfxb[i+1] = pfxb[i];
    }
  }

  vector<bool> flag2(n);
  vector<ll> c(n), sfxc(n+1);
  REP(i, n) c[i] = a[i]+i*d;
  sfxc[n] = LLINF;
  for(ll i=n-1; i>=0; --i) {
    if(c[i] < sfxc[i+1]) {
      flag2[i] = 1;
      sfxc[i] = c[i];
    } else {
      sfxc[i] = sfxc[i+1];
    }
  }

  ll prev = -1, ret = 0;
  REP(i, n) {
    if(flag1[i] && flag2[i]) {
      if(prev != -1) ret += a[i] + a[prev] + d * (i-prev);
      prev = i;
    } else {
      ll t1 = pfxb[i] + a[i] + i*d;
      ll t2 = sfxc[i] + a[i] - i*d;
      ret += min(t1, t2);
    }
  }
  cout << ret << endl;

  return 0;
}

