int n;

ll D;

ll a[MAX_N];

pii t[2][4 * MAX_N];

void build(int v, int LG, int RG)
{
    if (LG == RG)
    {
        t[0][v] = mp(a[LG] - LG * D, LG);
        t[1][v] = mp(a[LG] + LG * D, LG);
        return;
    }
    int MG = (LG + RG) / 2;
    build(v * 2, LG, MG);
    build(v * 2 + 1, MG + 1, RG);
    t[0][v] = min(t[0][v * 2], t[0][v * 2 + 1]);
    t[1][v] = min(t[1][v * 2], t[1][v * 2 + 1]);
}

void update(int v, int LG, int RG, int pos)
{
    if (LG == RG)
    {
        t[0][v].X = t[1][v].X = INF;
        t[0][v].Y = t[1][v].Y = INF;
        return;
    }
    int MG = (LG + RG) / 2;
    if (pos <= MG)
    {
        update(v * 2, LG, MG, pos);
    }
    else
    {
        update(v * 2 + 1, MG + 1, RG, pos);
    }
    t[0][v] = min(t[0][v * 2], t[0][v * 2 + 1]);
    t[1][v] = min(t[1][v * 2], t[1][v * 2 + 1]);
}

pii get(int v, int LG, int RG, int l, int r, int fl)
{
    if (r < l)
    {
        pii res = mp(INF, INF);
        return res;
    }
    if (LG == l && RG == r)
    {
        return t[fl][v];
    }
    int MG = (LG + RG) / 2;
    return min(get(v * 2, LG, MG, l, min(MG, r), fl), get(v * 2 + 1, MG + 1, RG, max(MG + 1, l), r, fl));
}

set<int> lv;
