void updateSuf(int v)
{
    pii newV = get(1, 1, n, v + 1, n, 1);
    //cerr << newV.X << ' ' << newV.Y << '\n';
    if (newV.Y != INF && -v * D + a[v] + a[newV.Y] + newV.Y * D < minCost[newV.Y])
    {
        rv.er(mp(minCost[newV.Y], newV.Y));
        minCost[newV.Y] = -v * D + a[v] + a[newV.Y] + newV.Y * D;
        rv.is(mp(minCost[newV.Y], newV.Y));
    }
    set<int>::iterator it = suf.upper_bound(v);
    it--;
    int cur = *it;
    set<int>::iterator it1 = it;
    it1++;
    int r = n;
    if (it1 != suf.end())
    {
        r = *it1 - 1;
    }
    newV = get(1, 1, n, *it + 1, r, 1);
    //cerr << newV.X << ' ' << newV.Y << '\n';
    if (newV.Y != INF && -(*it) * D + a[(*it)] + a[newV.Y] + newV.Y * D < minCost[newV.Y])
    {
        rv.er(mp(minCost[newV.Y], newV.Y));
        minCost[newV.Y] = -(*it) * D + a[(*it)] + a[newV.Y] + newV.Y * D;
        rv.is(mp(minCost[newV.Y], newV.Y));
    }
    if (-v * D + a[v] >= -cur * D + a[cur])
    {
        return;
    }
    newV = get(1, 1, n, cur + 1, n, 1);
    //cerr << newV.X << ' ' << newV.Y << '\n';
    if (newV.Y != INF && -cur * D + a[cur] + a[newV.Y] + newV.Y * D < minCost[newV.Y])
    {
        rv.er(mp(minCost[newV.Y], newV.Y));
        minCost[newV.Y] = -cur * D + a[cur] + a[newV.Y] + newV.Y * D;
        rv.is(mp(minCost[newV.Y], newV.Y));
    }
    int l = v + 1;
    while (true)
    {
        it = suf.upper_bound(v);
        if (it == suf.end())
        {
            break;
        }
        cur = *it;
        if (-v * D + a[v] <= -cur * D + a[cur])
        {
            set<int>::iterator it1 = it;
            it1++;
            int r = n;
            if (it1 != suf.end())
            {
                r = *it1 - 1;
            }
            pii change = get(1, 1, n, l, r, 1);
            if (change.Y != INF && -v * D + a[v] + a[change.Y] + change.Y * D < minCost[change.Y])
            {
                rv.er(mp(minCost[change.Y], change.Y));
                minCost[change.Y] = -v * D + a[v] + a[change.Y] + change.Y * D;
                rv.is(mp(minCost[change.Y], change.Y));
            }
            l = r + 2;
            suf.er(cur);
        }
        else
        {
            break;
        }
    }
    it1 = suf.upper_bound(v);
    r = n;
    if (it1 != suf.end())
    {
        r = *it1 - 1;
    }
    pii change = get(1, 1, n, v + 1, r, 1);
    if (change.Y != INF && -v * D + a[v] + a[change.Y] + change.Y * D < minCost[change.Y])
    {
        rv.er(mp(minCost[change.Y], change.Y));
        minCost[change.Y] = -v * D + a[v] + a[change.Y] + change.Y * D;
        rv.is(mp(minCost[change.Y], change.Y));
    }
    suf.is(v);
}

void updatePref(int v)
{
    pii newV = get(1, 1, n, 1, v - 1, 1);
    //cerr << newV.X << ' ' << newV.Y << '\n';
    if (newV.Y != INF && v * D + a[v] + a[newV.Y] - newV.Y * D < minCost[newV.Y])
    {
        rv.er(mp(minCost[newV.Y], newV.Y));
        minCost[newV.Y] = v * D + a[v] + a[newV.Y] - newV.Y * D;
        rv.is(mp(minCost[newV.Y], newV.Y));
    }
    if (pref.empty())
    {
        pii newV = get(1, 1, n, 1, v - 1, 0);
        if (newV.Y != INF && v * D + a[v] + a[newV.Y] - newV.Y * D < minCost[newV.Y])
        {
            rv.er(mp(minCost[newV.Y], newV.Y));
            minCost[newV.Y] = v * D + a[v] + a[newV.Y] - newV.Y * D;
            rv.is(mp(minCost[newV.Y], newV.Y));
        }
        pref.is(v);
        return;
    }
    set<int>::iterator it = pref.upper_bound(v);
    int cur;
    if (it != pref.end())
    {
        cur = *it;
        set<int>::iterator it1 = it;
        int l = 1;
        if (it1 != pref.begin())
        {
            it1--;
            l = *it1 + 1;
        }
        pii newV = get(1, 1, n, l, *it - 1, 0);
        if (newV.Y != INF && (*it) * D + a[(*it)] + a[newV.Y] - newV.Y * D < minCost[newV.Y])
        {
            rv.er(mp(minCost[newV.Y], newV.Y));
            minCost[newV.Y] = (*it) * D + a[(*it)] + a[newV.Y] - newV.Y * D;
            rv.is(mp(minCost[newV.Y], newV.Y));
        }
        if (v * D + a[v] >= cur * D + a[cur])
        {
            return;
        }
        newV = get(1, 1, n, 1, cur - 1, 0);
        if (newV.Y != INF && cur * D + a[cur] + a[newV.Y] - newV.Y * D < minCost[newV.Y])
        {
            rv.er(mp(minCost[newV.Y], newV.Y));
            minCost[newV.Y] = cur * D + a[cur] + a[newV.Y] - newV.Y * D;
            rv.is(mp(minCost[newV.Y], newV.Y));
        }
    }
    //cerr << "LUL 1\n";
    int r = v - 1;
    while (true)
    {
        it = pref.upper_bound(v);
        if (it == pref.begin())
        {
            break;
        }
        it--;
        cur = *it;
        //cerr << cur << '\n';
        if (v * D + a[v] <= cur * D + a[cur])
        {
            set<int>::iterator it1 = it;
            int l = 1;
            if (it1 != pref.begin())
            {
                it--;
                l = *it1 + 1;
            }
            pii change = get(1, 1, n, l, r, 0);
            if (change.Y != INF && v * D + a[v] + a[change.Y] - change.Y * D < minCost[change.Y])
            {
                rv.er(mp(minCost[change.Y], change.Y));
                minCost[change.Y] = v * D + a[v] + a[change.Y] - change.Y * D;
                rv.is(mp(minCost[change.Y], change.Y));
            }
            r = l - 2;
            pref.er(cur);
        }
        else
        {
            break;
        }
    }
    set<int>::iterator it1 = pref.upper_bound(v);
    int l = 1;
    if (it1 != pref.begin())
    {
        it1--;
        l = *it1 + 1;
    }
    pii change = get(1, 1, n, l, v - 1, 0);
    if (change.Y != INF && v * D + a[v] + a[change.Y] - change.Y * D < minCost[change.Y])
    {
        rv.er(mp(minCost[change.Y], change.Y));
        minCost[change.Y] = v * D + a[v] + a[change.Y] - change.Y * D;
        rv.is(mp(minCost[change.Y], change.Y));
    }
    pref.is(v);
}

int solve()
{
    cin >> n >> D;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
    }
    for (int i = 1; i <= n; ++i)
    {
        minCost[i] = INF;
    }
    build(1, 1, n);
    minCost[1] = 0;
    lv.is(1);
    pref.is(1);
    suf.is(1);
    update(1, 1, n, 1);
    pii cur = get(1, 1, n, 2, n, 1);
    rv.is(mp(-1 * D + a[1] + cur.X, cur.Y));
    minCost[cur.Y] = -1 * D + a[1] + cur.X;
    while ((int)lv.size() < n)
    {
        pii it = *rv.begin();
        //cerr << it.X << ' ' << it.Y << '\n';
        rv.er(it);
        ans += it.X;
        update(1, 1, n, it.Y);
        /*cerr << "HERE 1\n";
        for (pii it : rv)
        {
            cerr << it.X << ' ' << it.Y << '\n';
        }*/
        updateSuf(it.Y);
        /*cerr << "HERE 2\n";
        for (pii it : rv)
        {
            cerr << it.X << ' ' << it.Y << '\n';
        }*/
        updatePref(it.Y);
        /*cerr << "HERE 3\n";
        for (pii it : rv)
        {
            cerr << it.X << ' ' << it.Y << '\n';
        }*/
        lv.is(it.Y);
    }
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define N 200010
#define INFLL 0x3f3f3f3f3f3f3f3f
int n, m;
ll d, a[N];
struct Edge
{
	int u, v; ll w;
	Edge() {}
	Edge(int u, int v, ll w) : u(u), v(v), w(w) {}
	bool operator < (const Edge &other) const { return w < other.w; }
}edge[N * 15];

void add(int l, int r)
{
	if (l == r) return;
	int mid = (l + r) >> 1;
	ll Min = INFLL; int pos = -1; 
	for (int i = l; i <= mid; ++i) 
	{
		ll f = a[i] - d * i;
		if (f < Min)
		{
			Min = f;
			pos = i;
		}
	}
	for (int i = mid + 1; i <= r; ++i)
		edge[++m] = Edge(pos, i, a[pos] + a[i] + d * (i - pos));
	Min = INFLL; pos = -1;
	for (int i = mid + 1; i <= r; ++i)
	{
		ll f = a[i] + d * i;
		if (f < Min)
		{
			Min = f;
			pos = i;
		}
	}
	for (int i = l; i <= mid; ++i) 
		edge[++m] = Edge(pos, i, a[pos] + a[i] + d * (pos - i));
	add(l, mid);
	add(mid + 1, r);
}

int pre[N];
int find(int x) { return pre[x] == 0 ? x : pre[x] = find(pre[x]); }
ll Kruskal()
{
	memset(pre, 0, sizeof pre);
	sort(edge + 1, edge + 1 + m);
	int cnt = 1;
	ll res = 0;
	for (int i = 1; i <= m; ++i)
	{
		int u = edge[i].u, v = edge[i].v; ll w = edge[i].w;
		int fu = find(u), fv = find(v);
		if (fu == fv) continue;
		pre[fu] = fv;
		res += w;
		++cnt;
		if (cnt == n) return res;
	}
	return res;
}

int main()
{
	while (scanf("%d%lld", &n, &d) != EOF)
	{
		m = 0;
		for (int i = 1; i <= n; ++i) scanf("%lld", a + i);
		add(1, n);
		printf("%lld\n", Kruskal());
	}
	return 0;
}

