        LL w=s.begin()->first;
        int u=s.begin()->second.first, v=s.begin()->second.second;
        if ( !uf.same(u,v) ) {
            ans+=w;
            uf.unite(u,v);
        } 
        s.erase(s.begin());
    }

    W(ans);
}

