ll myf(int i, int j){
	return d*(ll)abs(i-j)+arr[i]+arr[j];
}
int main(void){
	scanf("%d %lld",&n,&d);
	for(int i=1;i<=n;i++) scanf("%lld",&arr[i]);
	for(int i=1;i<=n;i++) dis[i]=INF;
	dis[1]=0LL;
	pq.push(make_pair(-dis[1],1));
	while(!pq.empty()){
		pair<ll,int> t = pq.top(); pq.pop();
		int x = t.second; ll w = -t.first; nq[x]=1;
		if(dis[x]!=w) continue;
		for(int i=2;i<=n;i++){
			if(i==x) continue;
			if(nq[i]) continue;
			ll ww = myf(x,i);
			if(dis[i]>ww){
				dis[i]=ww;
				pq.push(make_pair(-dis[i],i));
			}
		}
	}
