    for (int i = 0; i < n; i++)
        scanf("%ld", &a[i]);

    vector<long> b(n);
    for (int i = 0; i < n; i++)
        b[i] = a[i] + i * d;

    set<pair<long, int>> pairs;
    for (int i = 1; i < n; i++)
        pairs.insert(make_pair(b[i], i));

    long cost = 0;
    int j = 0;
