    while (!pairs.empty()) {
        const int i = pairs.begin()->second;
        cost += abs(i - j) * d + a[i] + a[j];
        pairs.erase(pairs.begin());
        for (k++; k < i; k++) {
            cost += min(abs(i - k) * d + a[i] + a[k], abs(j - k) * d + a[j] + a[k]);
            pairs.erase(make_pair(b[k], k));
        }
        if (a[i] < a[j] + abs(i - j) * d)
            j = i;
    }

    printf("%ld\n", cost);

    return 0;
