	for(LL i=mid+1;i<=ub;i++)
	{
		if(a[i]+d*i<mn)//右边是编号较大的一组，所以是加 
		{
			mn=a[i]+d*i;
			rbest=i;
		}
	}
	for(LL i=lb;i<=mid;i++)
	{
		LL val1=a[i]-d*i,val2=a[rbest]+d*rbest;
		v.pb({val1+val2,{i,rbest}});
	}
	for(LL i=mid+1;i<=ub;i++)
	{
		LL val1=a[i]+d*i,val2=a[lbest]-d*lbest;
		v.pb({val1+val2,{lbest,i}});
	}
	solve(lb,mid);
	solve(mid+1,ub);
} 

