  UnionFind UF(N);
  ll ans = 0;
  ll cost, sidx, adjidx;
  while (not edge_candidates.empty()){
//    cout << 'a' << endl;
    tie(cost, sidx, adjidx) = edge_candidates.top();
//    cout << cost << ' ' << sidx << ' ' << adjidx << endl;
    edge_candidates.pop();
    if (UF.unite(sidx, adjidx)){ //uniteが成功したら=まだ接続されていなかったら
      ans += cost;
    } //接続されていたら無視する
  }

//  cout << "end" << endl;
