struct union_find{
	typedef unsigned size_type;
	vector<int> par;
	size_type grs;
	explicit union_find(size_type n = 0){ init(n); }
	void init(size_type n){
		par.assign(n, -1);
		grs = n;
	}
	size_type find(size_type x){
		if(par[x] < 0){ return x; }
		return par[x] = find(par[x]);
	}
	size_type size(size_type x){
		return -par[find(x)];
	}
	size_type groups(){
		return grs;
	}
	bool unite(size_type x, size_type y){
		x = find(x);
		y = find(y);
		if(x == y){ return false; }
		if(par[x] < par[y]){ swap(x, y); }
		par[y] += par[x];
		par[x] = y;
		--grs;
		return true;
	}
	bool same(size_type x, size_type y){
		return find(x) == find(y);
	}
	bool is_root(size_type x){
		return find(x) == x;
	}
};

void mainmain(){
	const LL INF = 1LL << 60;

	int n;
	LL d;
	scanf("%d%lld", &n, &d);
	vector<LL> as(n);
	for(int i = 0; i < n; ++i){ scanf("%lld", &as[i]); }

	union_find uf(n);
	LL ans = 0;

	vector<pll> dp1, dp2;
	vector<pll> top2;
	vector<tuple<LL,int,int>> es;
	auto disj = [](const pll &p1, const pll &p2){ return p1.second == p2.second; };
	while(uf.groups() > 1){
		dp1.assign(n, pll(INF, -1));
		dp2.assign(n, pll(INF, -1));

		top2.clear();
		for(int i = n - 1; i >= 0; --i){
			int u = uf.find(i);
			for(cauto t : top2){
				if(t.second != u){
					dp1[i] = pll(t.first + as[i] - i * d, t.second);
					break;
				}
			}
			pll p(as[i] + i * d, u);
			top2.insert(lower_bound(ALL(top2), p), p);
			top2.erase(unique(ALL(top2), disj), top2.end());
		}
		top2.clear();
		for(int i = 0; i < n; ++i){
			int u = uf.find(i);
			for(cauto t : top2){
				if(t.second != u){
					dp2[i] = pll(t.first + as[i] + i * d, t.second);
					break;
				}
			}
			pll p(as[i] - i * d, u);
			top2.insert(lower_bound(ALL(top2), p), p);
			top2.erase(unique(ALL(top2), disj), top2.end());
		}

		es.clear();
		for(int i = 0; i < n; ++i){
			pll p = min(dp1[i], dp2[i]);
			if(p.second >= 0){
				es.emplace_back(p.first, i, p.second);
			}
		}
		sort(ALL(es));
		for(cauto t : es){
			if(uf.unite(get<1>(t), get<2>(t))){
				ans += get<0>(t);
			}
		}
	}
	printf("%lld\n", ans);
}



