#define INF 10000000000000000LL

struct segtree {
	ll N, dat[2 * 300000];
	segtree() {}
	segtree(ll n) {
		N = 1;
		while (N < n) N *= 2;
		for (ll i = 0; i < 2 * N - 1; i++)
			dat[i] = INF;
	}
	// update k th element
	void update(ll k, ll a) {
		k += N - 1; // leaf
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}
	// min [a, b)
	ll query(ll a, ll b) { return query(a, b, 0, 0, N); }
	ll query(ll a, ll b, ll k, ll l, ll r) {
		if (r <= a || b <= l) return INF;
		if (a <= l && r <= b) return dat[k];
		ll m = (l + r) / 2;
		return min(query(a, b, k * 2 + 1, l, m), query(a, b, k * 2 + 2, m, r));
	}
};
class Graph {
public:
	ll vn;
	vector<vector<pll>> g;

	Graph(ll n) {
		vn = n;
		g.resize(n);
	}
	virtual void con(ll a, ll b, ll w) = 0;
};
class BiDGraph : public Graph {//無向
public:
	BiDGraph(ll n) : Graph(n) {}

	void con(ll a, ll b, ll w = 1) {
		g[a].push_back({ b,w });
		g[b].push_back({ a, w });
	}
};

struct UnionFind {
	vector<ll> data;
	UnionFind(ll size) : data(size, -1) { }
	bool unionSet(ll x, ll y) { //ｘの入ってる集合と yの入ってる集合を併合
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(ll x, ll y) { //xとyが同じ集合に入っているかどうかを判定
		return root(x) == root(y);
	}
	ll root(ll x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	bool isroot(ll x) {
		return data[x] < 0;
	}
	ll size(ll x) {
		return -data[root(x)];
	}
};


ll Prim(BiDGraph g, ll s = 0) {//連結グラフの最小全域木　プリム法
	priority_queue<pair<ll, pll>, vector<pair<ll, pll>>, greater<pair<ll, pll>>> cand;
	vector<bool> al(g.vn);
	ll alcou = 0;
	ll sum = 0;
	BiDGraph MST(g.vn);
	for (pll ed : g.g[s]) {
		cand.push({ ed.second,{ s, ed.first } });
	}
	alcou = 1;
	al[s] = true;
	while (alcou < g.vn) {
		pair<ll, pll> cur = cand.top();
		cand.pop();
		if (al[cur.second.second]) {
			continue;
		}
		MST.con(cur.second.first, cur.second.second);
		sum += cur.first;
		al[cur.second.second] = true;
		alcou++;

		for (pll ed : g.g[cur.second.second]) {
			if(al[ed.first] == false)
				cand.push({ ed.second,{ cur.second.second,ed.first } });
		}
	}
	return sum;
}

signed main(void) {
	ll n, d;

	cin >> n >> d;
	vector<ll> a(n), Aar(n), Bar(n);
	BiDGraph g(n);


	REP(i, n) {
		cin >> a[i];
		Aar[i] =  d * (i + 1) + a[i];
		Bar[i] =  -d * (i + 1) + a[i];
	}

	auto addedge = [](ll n, ll d, BiDGraph& g, vector<ll>& Aar, vector<ll>& Bar) {

		vector<ll> rui(n + 1);
		set<pll> bset;
		segtree B(n);

		REP(i, n) {
			bset.insert({ Bar[i] , i });
			B.update(i, Bar[i]);

			rui[i + 1] = rui[i] + Aar[i];
		}
		{
			set<pll> cand;
			for (ll i = n - 2; 0 <= i; i--) {
				if (cand.size() == 20) {
					ll Worst = cand.rbegin()->first;
					if(Worst > Aar[i + 1]){
						cand.erase(cand.lower_bound({Worst, -1}));
						cand.insert({ Aar[i + 1], i + 1 });
					}
				}
				else {
					cand.insert({ Aar[i + 1], i + 1 });
				}
				for(auto itr : cand)
					g.con(i, itr.second,itr.first + Bar[i]);

			}
		}
		ll border = n - 1;
		while (border > 0) {

			ll Minval = B.query(0, n);

			auto Minitr = bset.lower_bound(MP(Minval, -1));

			ll Minind = Minitr->second;
			bset.erase(Minitr);
			if (border > Minind) {
				rep(i, Minind + 1, border + 1) {
					g.con(Minind, i, Minval + Aar[i]);
				}

				border = Minind;
			}
			B.update(Minind, INF);
		}
	};

	addedge(n,d,g, Aar,Bar);


	ll ans = Prim(g);

	cout << ans << endl;

	return 0;
}

