const ll INF = 1e17;

const pli id(INF, -1);

class segment_tree
{
	using T = pli;
	T op(T a, T b) const {
		return min(a, b);
	}

	int expand(int x) {
		int res;
		for (res = 1; res < x; res <<= 1);
		return res;
	}
	const int n;
	vector<T> dat;
public:
	segment_tree(int n_)
		: n(expand(n_)), dat(n + n_, id) {}
	segment_tree(int n_, T val_)
		: segment_tree(vector<T>(n_, val_)) {}
	segment_tree(const vector<T>& dat_)
		: n(expand(dat_.size())), dat(n) {
		copy(dat_.begin(), dat_.end(), back_inserter(dat));
		for (int i = n - 1; i > 0; --i)
			dat[i] = op(dat[i << 1], dat[(i << 1) | 1]);
	}
	void update(int p, T val) {
		dat[p += n] = val;
		while (p >>= 1) dat[p] = op(dat[p << 1], dat[(p << 1) | 1]);
	}
	T find(int l, int r) const {
		T res1 = id, res2 = id;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) res1 = op(res1, dat[l++]);
			if (r & 1) res2 = op(dat[--r], res2);
		}
		return op(res1, res2);
	}
};

class quick_find {
	vector<int> rt;
public:
	vector<vector<int>> vs;
	quick_find(int n) : rt(n), vs(n) {
		for (int i = 0; i < n; i++) rt[i] = i, vs[i].push_back(i);
	}
	int find(int a) {
		return rt[a];
	}
	bool same(int a, int b) {
		return rt[a] == rt[b];
	}
	void unite(int a, int b) {
		a = rt[a], b = rt[b];
		if (a == b) return;
		if (vs[a].size() < vs[b].size()) swap(a, b);
		for (auto& v : vs[b]) rt[v] = a;
		copy(vs[b].begin(), vs[b].end(), back_inserter(vs[a]));
	}
	int size(int a) {
		return vs[rt[a]].size();
	}
};

int main()
{
	int N;
	ll D;
	cin >> N >> D;
	vector<ll> A(N);
	for (int i = 0; i < N; i++) {
		cin >> A[i];
	}
	ll res = 0;
	quick_find uf(N);
	segment_tree lst(N), rst(N);
	for (int i = 0; i < N; i++) {
		lst.update(i, make_pair(A[i] - i * D, i));
		rst.update(i, make_pair(A[i] + i * D, i));
	}
	while (uf.size(0) < N) {
		vector<tuple<ll, int, int>> es;
		for (int i = 0; i < N; i++) if (uf.find(i) == i) {
			for (auto v : uf.vs[i]) {
				lst.update(v, make_pair(INF, -1));
				rst.update(v, make_pair(INF, -1));
			}
			ll c = INF;
			int to = -1;
			for (auto v : uf.vs[i]) {
				int u = lst.find(0, v).second;
				if (u != -1) {
					ll cost = A[v] + A[u] + abs(v - u) * D;
					if (cost < c) {
						c = cost;
						to = u;
					}
				}
				u = rst.find(v, N).second;
				if (u != -1) {
					ll cost = A[v] + A[u] + abs(v - u) * D;
					if (cost < c) {
						c = cost;
						to = u;
					}
				}
			}
			for (auto v : uf.vs[i]) {
				lst.update(v, make_pair(A[v] - v * D, v));
				rst.update(v, make_pair(A[v] + v * D, v));
			}
			es.emplace_back(c, i, uf.find(to));
		}
		sort(es.begin(), es.end());
		for (auto e : es) {
			int u, v; ll c;
			tie(c, u, v) = e;
			if (uf.same(u, v)) continue;
			uf.unite(u, v);
			res += c;
		}
	}
	cout << res << endl;
	return 0;
}

