		b[i] = a[i] + i * d;
		c[i] = a[i] - i * d;
	}
	ll min_c = c[1];
	ll min_j = 1;
	REP(i, 2, n) {
		pq.push({ i, min_j, min_c + b[i] });
		if (min_c > c[i]) {
			min_c = c[i];
			min_j = i;
		}
	}
	ll min_b = b[n];
	ll min_i = n;
	PER(j, n - 1, 1) {
		pq.push({ j, min_i, min_b + c[j] });
		if (min_b > b[j]) {
			min_b = b[j];
			min_i = j;
		}
	}
	ll ans = 0;
	while (!pq.empty()) {
		edge cur = pq.top();
		pq.pop();
		if (same(cur.from, cur.to)) {
			continue;
		}else {
			ans += cur.cost;
			unite(cur.from, cur.to);
		}
	}
	cout << ans << endl;
}

