#define ll long long
#define N 200010
#define INF 0x3f3f3f3f3f3f3f3f
int n, d, a[N];

struct SEG
{
	struct node
	{
		int pos; ll Min;
		node() {} 
		node(int pos, ll Min) : pos(pos), Min(Min) {}
		void init() { pos = -1, Min = INF; }
		node operator + (const node &other) const
		{
			node res = node(-1, INF);
			if (Min < other.Min)
			{
				res.Min = Min;
				res.pos = pos;
			}
			else
			{
				res.Min = other.Min;
				res.pos = other.pos;
			}
			return res;
		}
	}a[N << 2], res;
	void build(int id, int l, int r)
	{
		a[id].init();
		if (l == r) 
		{
			a[id].pos = l;
			return;
		}
		int mid = (l + r) >> 1;
		build(id << 1, l, mid);
		build(id << 1 | 1, mid + 1, r);
	}
	void update(int id, int l, int r, int pos, ll val)
	{
		if (l == r)
		{
			a[id].Min = val;
			return;
		}
		int mid = (l + r) >> 1;
		if (pos <= mid) update(id << 1, l, mid, pos, val);
		else update(id << 1 | 1, mid + 1, r, pos, val);
		a[id] = a[id << 1] + a[id << 1 | 1];
	}
	void query(int id, int l, int r, int ql, int qr)
	{
		if (qr < ql) return;
		//printf("%d %d %d %d\n", l, r, ql, qr);
		if (l >= ql && r <= qr) 
		{
			res = res + a[id];
			return;
		}
		int mid = (l + r) >> 1;
		if (ql <= mid) query(id << 1, l, mid, ql, qr);
		if (qr > mid) query(id << 1 | 1, mid + 1, r, ql, qr);
	}
}seg[2];

int pre[N];
int find(int x) { return pre[x] == 0 ? x : pre[x] = find(pre[x]); }

struct node
{
	ll v; int x, y;
	node() {}
	node (int x, int y, ll v) : x(x), y(y), v(v) {}
	bool operator < (const node &other) const { return v > other.v; }
};

priority_queue <node> pq;
void add(int x)
{
	for (int i = 0; i < 2; ++i) seg[i].res.init();
	seg[0].query(1, 1, n, 1, x - 1);
	seg[1].query(1, 1, n, x + 1, n);
	if (seg[0].res.Min == INF && seg[1].res.Min == INF) return; 
	ll tmpl = 1ll * a[x] + 1ll * x * d + seg[0].res.Min;
	ll tmpr = 1ll * a[x] - 1ll * x * d + seg[1].res.Min;
	if (tmpl < tmpr) pq.push(node(x, seg[0].res.pos, tmpl));
	else pq.push(node(x, seg[1].res.pos, tmpr)); 
}

int main()
{
	while (scanf("%d%d", &n, &d) != EOF)
	{
		for (int i = 1; i <= n; ++i) scanf("%d", a + i);
		for (int i = 0; i < 2; ++i) seg[i].build(1, 1, n);
		for (int i = 1; i <= n; ++i)
		{
			seg[0].update(1, 1, n, i, 1ll * a[i] - 1ll * i * d);
			seg[1].update(1, 1, n, i, 1ll * a[i] + 1ll * i * d);
		}
		memset(pre, 0, sizeof pre);
		ll res = 0; 
		seg[1].res.init();
		seg[1].query(1, 1, n, 2, n);
		while (!pq.empty()) pq.pop();
		pq.push(node(1, seg[1].res.pos, 1ll * a[1] - d + seg[1].res.Min));
		seg[0].update(1, 1, n, 1, INF);
		seg[1].update(1, 1, n, 1, INF);
		int cnt = 1;
		while (cnt < n)
		{
			node top = pq.top(); pq.pop();
			int fx = find(top.x), fy = find(top.y);
			//printf("%d %d %lld\n", top.x, top.y, top.v);
			if (fx != fy)
			{
				res += top.v;
				pre[fx] = fy;
				++cnt;
				seg[0].update(1, 1, n, top.y, INF);
				seg[1].update(1, 1, n, top.y, INF);
				add(top.y);
			}
			add(top.x); 
		}
		printf("%lld\n", res);
	}
	return 0;
}

#include <bits/stdc++.h>
#define int long long
#define INF 1000000000000000007
using namespace std;

int n,d,p[200010],a[200010];
vector<pair<int,pair<int,int> > > edges;

int find_set(int x)
{
	if(p[x]==x) return x;
	else return p[x]=find_set(p[x]);
}

bool unite(int x,int y)
{
	int rootx=find_set(x),rooty=find_set(y);
	if(rootx==rooty) return false;
	else{
		p[rooty]=rootx;
		return true;
	}
}

void solve(int l,int r)
{
	if(l>=r) return;
	int m=(l+r)/2;

	int minv1=INF,pos1=-1;
	for(int i=l;i<=m;i++){
		int val=a[i]-d*i;
		if(val<minv1){
			minv1=val;
			pos1=i;
		}
	}

	int minv2=INF,pos2=-1;
	for(int i=m+1;i<=r;i++){
		int val=a[i]+d*i;
		if(val<minv2){
			minv2=val;
			pos2=i;
		}
	}

	for(int i=l;i<=m;i++){
		edges.push_back(make_pair(minv2+a[i]-d*i,make_pair(i,pos2)));
	}
	for(int i=m+1;i<=r;i++){
		edges.push_back(make_pair(minv1+a[i]+d*i,make_pair(pos1,i)));
	}
	solve(l,m);
	solve(m+1,r);
}

signed main()
{
	ios::sync_with_stdio(false);
	cin>>n>>d;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		p[i]=i;
	}
	solve(1,n);
	int cnt=0,ans=0;
	sort(edges.begin(),edges.end());
	for(int i=0;i<edges.size()&&cnt<n-1;i++){
		if(unite(edges[i].second.first,edges[i].second.second)){
			ans+=edges[i].first;
			cnt++;
		}
	}
	cout<<ans<<endl;
	return 0;
}

