typedef long long LL;
const LL MAX=1e9;
const LL N=200005;
LL n,d;
LL a[N];
struct qt
{
	LL c,id;
	qt () {};
	qt (LL _c,LL _id)	{c=_c;id=_id;}
};
struct qq
{
	LL l,r;
	qt c[2];
	LL s1,s2;
}tr[N*2];LL num;
qt Merge (qt x,qt y)	{return x.c<y.c?x:y;}
void bt (LL l,LL r)
{
	LL now=++num;
	tr[now].l=l;tr[now].r=r;
	if (l==r)	
	{
		tr[now].c[0].c=a[l]-l*d;
		tr[now].c[1].c=a[l]+l*d;
		tr[now].c[0].id=l;
		tr[now].c[1].id=l;
		return ;
	}
	LL mid=(l+r)>>1;
	tr[now].s1=num+1;bt(l,mid);
	tr[now].s2=num+1;bt(mid+1,r);
	tr[now].c[0]=Merge(tr[tr[now].s1].c[0],tr[tr[now].s2].c[0]);
	tr[now].c[1]=Merge(tr[tr[now].s1].c[1],tr[tr[now].s2].c[1]);
}
vector<int> vec[N];
qt t[N];//这个连通块连谁最好 
LL tot=0;
LL fa[N];
LL find_fa (LL x)	{return fa[x]==x?x:fa[x]=find_fa(fa[x]);}
qt get (LL now,LL l,LL r,LL o)
{
	if (l>r)	return qt(MAX,MAX);
	if (tr[now].l==l&&tr[now].r==r)	return tr[now].c[o];
	LL s1=tr[now].s1,s2=tr[now].s2;
	LL mid=(tr[now].l+tr[now].r)>>1;
	if (r<=mid) return get(s1,l,r,o);
	else if (l>mid) return get(s2,l,r,o);
	else return Merge(get(s1,l,mid,o),get(s2,mid+1,r,o));
}
int main()
{
	scanf("%lld%lld",&n,&d);
	for (LL u=1;u<=n;u++) scanf("%lld",&a[u]);
	bt(1,n);
	tot=n;
	for (LL u=1;u<=n;u++) 	
	{
		vec[u].push_back(u);
		qt x=get(1,1,u-1,0),y=get(1,u+1,n,1);
		x.c=x.c+a[u]+u*d;
		y.c=y.c+a[u]-u*d;
		t[u]=Merge(x,y);
		fa[u]=u;
		//printf("YES:%lld %lld %lld %lld\n",u,t[u].id,x.id,y.id);
	}
	LL ans=0;
	while (tot!=1)
	{	
		for (LL i=1;i<=n;i++)
		{
			if (find_fa(i)!=i) continue;
			LL x=find_fa(t[i].id);
			if (x==i) continue;//已经连过了 
			ans=ans+t[i].c;
			fa[i]=x;
			printf("link%lld %lld\n",i,x);
			LL siz=vec[i].size();
			for (LL j=0;j<siz;j++)	vec[x].push_back(vec[i][j]);
		}
		tot=0;
		for (LL i=1;i<=n;i++)
		{
			if (find_fa(i)!=i) continue;
			tot++;
			LL siz=vec[i].size();
			sort(vec[i].begin(),vec[i].end());
			LL lst=0,j=0;
			qt now=qt(MAX,MAX),x,y;
			t[i]=qt(MAX,MAX);
			for (LL u=0;u<siz;u++)
			{
				if (u==siz-1||vec[i][u+1]!=vec[i][u]+1)//需要合并 
				{
					x=get(1,lst+1,vec[i][j]-1,0);
					y=get(1,vec[i][j],vec[i][u],1);
					//printf("YES:%lld %lld %lld\n",lst+1,vec[i][j]-1LL,x.id);
					now=Merge(now,x);
					qt lalal;
					lalal.id=now.id;
					lalal.c=y.c+now.c;
					t[i]=Merge(t[i],lalal);
					j=u+1;lst=vec[i][u];
				}
			}
			now=qt(MAX,MAX);
			lst=n+1;j=siz-1;
			for (LL u=siz-1;u>=0;u--)
			{
				if (u==0||vec[i][u-1]!=vec[i][u]-1)//需要合并 
				{
					x=get(1,vec[i][j]+1,lst-1,1);
					y=get(1,vec[i][u],vec[i][j],0);
					now=Merge(now,x);
					qt lalal;
					lalal.id=now.id;
					lalal.c=y.c+now.c;
					t[i]=Merge(t[i],lalal);
					j=u-1;lst=vec[i][u];
				}
			}
			printf("%lld %lld\n",i,t[i].id);
		}
		system("pause");
	}
	printf("%lld\n",ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;
#define fr(i,n) for(int i=0;i<n;i++)

ll par[200010],ranki[200010]; 

void init(int n){
  fr(i,n){
    par[i]=i;
    ranki[i]=0;
  }
}

int find(int x){
  if(par[x]==x) return x;
  else return par[x]=find(par[x]);
}

void unit(int x,int y){
  x=find(x);
  y=find(y);
  if(x==y) return;
  if(ranki[x]<ranki[y]) par[x]=y;
  else par[y]=x;
  if(ranki[x]==ranki[y]) ranki[x]++;
}

bool same(int x,int y){
  return find(x)==find(y);
}


struct road{
  ll dm,cd,ct;
  bool operator<(const road& right) const{
    return ct<right.ct;
  }
};
vector<road> roads;


int main(){
  ll n,d,a[200010],ans=0,cnt=0;
  cin>>n>>d;
  fr(i,n) cin>>a[i];
  priority_queue<P,vector<P>,greater<P>> q;
  fr(i,n){
    while(!q.empty()){
      ll j=q.top().second;
      if(a[j]>a[i]){
        q.pop();
        continue;
      }
      else{
        roads.push_back((road){i,j,a[i]+a[j]+d*(i-j)});
        break;
      }
    }
    q.push(make_pair(a[i]-d*i,i));
  }
  while(!q.empty()) q.pop();
  for(int i=n-1;i>=0;i--){
    while(!q.empty()){
      ll j=q.top().second;
      if(a[j]>a[i]){
        q.pop();
        continue;
      }
      else{
        roads.push_back((road){i,j,a[i]+a[j]+d*(j-i)});
        break;
      }
    }
    q.push(make_pair(a[i]+d*i,i));
  }
  init(n);
//  for(auto it=roads.begin();it!=roads.end();it++) cout<<(*it).dm<<" "<<(*it).cd<<" "<<(*it).ct<<endl;
  sort(roads.begin(),roads.end());
  for(auto it=roads.begin();cnt<n-1;it++){
    road r=*it;
    if(same(r.dm,r.cd)) continue;
    unit(r.dm,r.cd);
    ans+=r.ct;
    cnt++;
  }
  cout<<ans<<endl;
}

