namespace io {
    // TYPE ID (StackOverflow)

    template<class T> struct like_array : is_array<T>{};
    template<class T, size_t N> struct like_array<array<T,N>> : true_type{};
    template<class T> struct like_array<vector<T>> : true_type{};
    template<class T> bool is_like_array(const T& a) { return like_array<T>::value; }

    // I/O 

    void setIn(string s) { freopen(s.c_str(),"r",stdin); }
    void setOut(string s) { freopen(s.c_str(),"w",stdout); }
    void setIO(string s = "") {
        ios_base::sync_with_stdio(0); cin.tie(0);
        if (sz(s)) { setIn(s+".in"), setOut(s+".out"); }
    }

    // INPUT 

    template<class T> void re(T& x) { cin >> x; }
    template<class Arg, class... Args> void re(Arg& first, Args&... rest);
    void re(double& x) { string t; re(t); x = stod(t); }
    void re(ld& x) { string t; re(t); x = stold(t); }

    template<class T> void re(complex<T>& x);
    template<class T1, class T2> void re(pair<T1,T2>& p);
    template<class T> void re(vector<T>& a);
    template<class T, size_t SZ> void re(array<T,SZ>& a);

    template<class Arg, class... Args> void re(Arg& first, Args&... rest) { re(first); re(rest...); }
    template<class T> void re(complex<T>& x) { T a,b; re(a,b); x = cd(a,b); }
    template<class T1, class T2> void re(pair<T1,T2>& p) { re(p.f,p.s); }
    template<class T> void re(vector<T>& a) { F0R(i,sz(a)) re(a[i]); }
    template<class T, size_t SZ> void re(array<T,SZ>& a) { F0R(i,SZ) re(a[i]); }

    // OUTPUT 

    template<class T1, class T2> ostream& operator<<(ostream& os, const pair<T1,T2>& a) {
        os << '{' << a.f << ", " << a.s << '}'; return os;
    }
    template<class T> ostream& printArray(ostream& os, const T& a, int SZ) {
        os << '{';
        F0R(i,SZ) {
            if (i) {
                os << ", ";
                if (is_like_array(a[i])) cout << "\n";
            }
            os << a[i];
        }
        os << '}';
        return os;
    }
    template<class T, size_t SZ> ostream& operator<<(ostream& os, const array<T,SZ>& a) {
        return printArray(os,a,SZ);
    }
    template<class T> ostream& operator<<(ostream& os, const vector<T>& a) {
        return printArray(os,a,sz(a));
    }
    template<class T> ostream& operator<<(ostream& os, const set<T>& a) {
        os << vector<T>(all(a)); return os;
    }
    template<class T1, class T2> ostream& operator<<(ostream& os, const map<T1,T2>& a) {
        os << vector<pair<T1,T2>>(all(a)); return os;
    }

    template<class T> void pr(const T& x) { cout << x << '\n'; }
    template<class Arg, class... Args> void pr(const Arg& first, const Args&... rest) { 
        cout << first << ' '; pr(rest...); 
    }
}

using namespace io;

template<int SZ> struct DSU {
    int par[SZ], sz[SZ];
    DSU() {
        F0R(i,SZ) par[i] = i, sz[i] = 1;
    }

    int get(int x) { // path compression
    	if (par[x] != x) par[x] = get(par[x]);
    	return par[x];
    }

    bool unite(int x, int y) { // union-by-rank
    	x = get(x), y = get(y);
    	if (x == y) return 0;
    	if (sz[x] < sz[y]) swap(x,y);
    	sz[x] += sz[y], par[y] = x;
    	return 1;
    }
};

DSU<MX> Z;
pair<pl,pl> bes;
int N,D;
pl mn[MX];
ll ans;
vi A;

bool done() {
    F0R(i,N) if (Z.get(i) != Z.get(0)) return false;
    return true;
}

pl getmn(int co) {
    if (bes.f.s == co) return bes.s;
    return bes.f;
}

pl modify(pl a, ll b) {
    a.f += b; return a;
}

void ad(pl x) {
    if (x < bes.f) {
        if (x.s != bes.f.s) bes.s = bes.f;  
        bes.f = x;
        return;
    } 
    if (x.s == bes.f.s) return;
    ckmin(bes.s,x);
}

void solve() {
    F0R(i,N) mn[i] = {INF,INF};
    bes = {{INF,INF},{INF,INF}};
    F0R(i,N) {
        int co = Z.get(i);
        ckmin(mn[co],modify(getmn(co),(ll)D*i+A[i]));
        ad({A[i]-(ll)D*i,co});
    }
    bes = {{INF,INF},{INF,INF}};
    F0Rd(i,N) {
        int co = Z.get(i);
        ckmin(mn[co],modify(getmn(co),-(ll)D*i+A[i]));
        ad({A[i]+(ll)D*i,co});
    }
    //F0R(i,N) pr(i,Z.get(i),mn[i]);
    //pr("");
    F0R(i,N) if (Z.get(i) == i) if (Z.unite(i,mn[i].s)) ans += mn[i].f;
}

int main() {
    // you should actually read the stuff at the bottom
    setIO(); re(N,D); A.resz(N); re(A);
    while (!done()) solve();
    pr(ans);
    // you should actually read the stuff at the bottom
}

