using namespace std; 
int fa[5*N],a[N],n,m;
ll ans;
struct node
{
	int L,R;
	ll val;
	node(ll x,int y,int z){val=x,L=y,R=z;}
	bool operator < (const node &x) const
	{
		return val<x.val;
	}
};
int search(int x)
{
	if(fa[x]==-1)return x;
	return fa[x]=search(fa[x]);
}
vector<node> v;
void solve(int l,int r)
{
	if(l==r)return;
	int mid=(l+r)>>1,min_l,mn=-1,min_r;
	for(int i=l;i<=mid;i++)
	{
		if(mn==-1||mn>a[i])
		min_l=i,mn=a[i];
	}
	mn=-1;
	for(int i=mid+1;i<=r;i++)
	{
		if(mn==-1||mn>a[i])
		min_r=i,mn=a[i];
		ll tmp=(ll)a[i]+(ll)a[min_l]+m*(ll)(i-min_l);
		v.pb(node(tmp,min_l,i));
	}
	for(int i=l;i<=mid;i++)
	{
		ll tmp=(ll)a[i]+(ll)a[min_r]+m*(ll)(min_r-i);
		v.pb(node(tmp,i,min_r));
	}
	solve(l,mid);
	solve(mid+1,r);
}
int main()
{
	memset(fa,-1,sizeof(fa));
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
	scanf("%d",a+i);
	solve(1,n);
	sort(v.begin(),v.end());
	n--;
	for(int i=0;;i++)
	{

		int x=search(v[i].L),y=search(v[i].R);
		if(x==y)continue;
		ans+=v[i].val;n--;
		if(!n)
		{
			printf("%lld\n",ans);
			return 0;
		}
		fa[x]=y;
	}
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
int n;
const int maxN = 2 * (int)1e5 + 100;
pair < ll, int > t[2][4 * maxN];
ll val[2][maxN];
void build(int v, int tl, int tr, int ind) {
    if (tl == tr) {
        t[ind][v] = make_pair(val[ind][tl], tl);
        return ;
    }
    int tm = (tl + tr) / 2;
    build(v + v, tl, tm, ind);
    build(v + v + 1, tm + 1, tr, ind);
    t[ind][v] = min(t[ind][v + v], t[ind][v + v + 1]);
}
void upd(int v, int tl, int tr, ll val, int pos, int ind) {
    if (tl == tr) {
        t[ind][v] = make_pair(val, pos);
        return ;
    }
    int tm = (tl + tr) / 2;
    if (pos <= tm) upd(v + v, tl, tm, val, pos, ind);
    else if (pos > tm) upd(v + v + 1, tm + 1, tr, val, pos, ind);
    t[ind][v] = min(t[ind][v + v], t[ind][v + v + 1]);
}
pair < ll, int > get(int v, int tl, int tr, int l, int r, int ind) {
    if (tl == l && tr == r) {
        return t[ind][v];
    }
    int tm = (tl + tr) / 2;
    if (r <= tm) return get(v + v, tl, tm, l, r, ind);
    else if (l > tm) return get(v + v + 1, tm + 1, tr, l, r, ind);
    else return min(get(v + v, tl, tm, l, tm, ind), get(v + v + 1, tm + 1, tr, tm + 1, r, ind));
}
ll D;
ll a[maxN];
ll ans = 0;
int sz[maxN];
int p[maxN];
int get(int a) {
    if (a == p[a]) return a;
    p[a] = get(p[a]);
    return p[a];
}
bool unite(int a, int b) {
    a = get(a);
    b = get(b);
    if (a == b) return false;
    if (sz[a] > sz[b]) swap(a, b);
    sz[b] += sz[a];
    p[a] = b;
    return true;
}
const ll INF = (ll)1e18;
vector < int > comps[maxN];
pair < int, int > mi[maxN];
void solve() {
    for (int i = 1; i <= n; i++) {
        comps[i].clear();
    }
    for (int i = 1; i <= n; i++) {
        comps[get(i)].push_back(i);
    }
    for (int i = 1; i <= n; i++) {
        if (comps[i].empty()) continue;
        for (int v : comps[i]) {
            for (int j = 0; j < 2; j++) {
                upd(1, 1, n, INF, v, j);
            }
        }
        pair < ll, int > mn = make_pair(INF, -1);
        for (int v : comps[i]) {
            auto t1 = get(1, 1, n, 1, v, 0);
            auto t2 = get(1, 1, n, v, n, 1);
            mn = min(mn, {t1.first + val[1][v], t1.second});
            mn = min(mn, {t2.first + val[0][v], t2.second});
        }
        for (int v : comps[i]) {
            for (int j = 0; j < 2; j++) {
                upd(1, 1, n, val[j][v], v, j);
            }
        }
        mi[i] = mn;
    }
    for (int i = 1; i <= n; i++) {
        //cout << i << " " << mi[i].second << " " << mi[i].first << " " << val[i][0]
        if (unite(i, mi[i].second)) {
            ans += mi[i].first;
        }
    }
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    //freopen("input.txt", "r", stdin);
    cin >> n;
    for (int i = 1; i <= n; i++) {
        p[i] = i;
        sz[i] = 1;
    }
    cin >> D;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        val[0][i] = -i * D + a[i];
        val[1][i] = i * D + a[i];
    }
    for (int i = 0; i < 2; i++) build(1, 1, n, i);
    while (true) {
        bool ok = false;
        for (int i = 1; i <= n; i++) {
            if (sz[i] == n) {
                ok = true;
                break;
            }
        }
        if (ok) break;
        solve();
    }
    cout << ans;
    return 0;
}

