const ll INF = 1LL << 61;

const int MAX_N = 212345;
ll A[MAX_N];

struct Edge {
  int a;
  int b;
  ll w;
  bool operator < (const Edge& o) const {
    return w < o.w;
  }
};

int main2() {
  int N = nextInt();
  ll D = nextInt();
  REP(i, N) A[i] = nextInt();

  // ブルーフカ法
  ll ans = 0;
  UnionFind uf(N);
  while (uf.size(0) < N) {

    vector<Edge> best_l(N, {0, 0, INF});
    {
      vector<pair<ll, int>> mins; // A[i]-i*D, i
      REP(i, N) {
        int ci = uf.root(i);
        for (auto m : mins) {
          int j = m.second;
          int cj = uf.root(j);
          if (cj != ci) {
            Edge e = {i, j, A[i] + A[j] + (i-j)*D};
            if (best_l[ci].w > e.w) {
              best_l[ci] = e;
            }
          }
        }
        ll w = A[i]-D*i;
        bool bat = false;
        REP(k, mins.size()) {
          if (uf.root(mins[k].second) == ci) {
            bat = true;
            if (mins[k].first > w) {
              mins[k] = {w, i};
            }
            break;
          }
        }
        if (!bat) {
          mins.push_back({w, i});
        }
        sort(ALL(mins));
        if (mins.size() > 2) mins.resize(2);
      }
    }
    vector<Edge> best_r(N, {0, 0, INF});
    {
      vector<pair<ll, int>> mins; // A[i]-i*D, i
      for (int i = N-1; i >= 0; i--) {
        int ci = uf.root(i);
        for (auto m : mins) {
          int j = m.second;
          int cj = uf.root(j);
          if (cj != ci) {
            Edge e = {i, j, A[i] + A[j] + (j-i)*D};
            if (best_l[ci].w > e.w) {
              best_l[ci] = e;
            }
          }
        }
        ll w = A[i]+D*i;
        bool bat = false;
        REP(k, mins.size()) {
          if (uf.root(mins[k].second) == ci) {
            bat = true;
            if (mins[k].first > w) {
              mins[k] = {w, i};
            }
            break;
          }
        }
        if (!bat) {
          mins.push_back({w, i});
        }
        sort(ALL(mins));
        if (mins.size() > 2) mins.resize(2);
      }
    }

    vector<Edge> es;
    REP(i, N) {
      Edge best = best_l[i].w < best_r[i].w ? best_l[i] : best_r[i];
      if (best.w < INF) {
       es.push_back(best);
        // cout << uf.size(0) << " : " << best.a << " " << best.b << " " << best.w << endl;
      }
    }
    sort(ALL(es));
    for (Edge e : es) {
      if (uf.link(e.a, e.b)) {
        ans += e.w;
      }
    }
  }

  cout << ans << endl;
  return 0;
}

