        vl.push_back(A[i]-D*i);
        vr.push_back(A[i]+D*i);
    }
    segtree<ll> sgtl(N, vl);
    segtree<ll> sgtr(N, vr);
    for(int i = 0; i < N; i++){
        sgtl.update(i, i);
        sgtr.update(i, i);
    }
    UnionFind uf(N);
    search(0, N-1, sgtl, sgtr);
    ll ans = 0;
    int sz = v.size();
    for(int i = 0; i < sz; i++){
        p.push_back(P(weight(u[i], v[i]), i));
    }
    sort(p.begin(), p.end());
    for(int j = 0; j < sz; j++){
        int i = p[j].second;
        if(!uf.findSet(u[i], v[i])){
            ans += weight(u[i], v[i]);
            uf.unionSet(u[i], v[i]);
        }
    }
    cout << ans << endl;
}

