struct edge{	
	ll from;  long long to; long long cost;
	bool operator<(const edge& rhs) const {
		return cost > rhs.cost;
	}
};

ll const MAX = 4e5 + 5;
priority_queue<edge> pq;
ll a[MAX], b[MAX], c[MAX];

ll parent[MAX];
ll rk[MAX];

void init(ll n) {
	for (ll i = 1; i <= n; i++) {
		parent[i] = i;
		rk[i] = 1;
	}
}

ll find(ll x) {
	if (parent[x] == x) {
		return x;
	}
	parent[x] = find(parent[x]);
	return parent[x];
}

bool same(ll x, ll y) {
	return find(x) == find(y);
}

void unite(ll x, ll y) {
	if (!same(x, y)) {
		x = parent[x];
		y = parent[y];
		if (rk[x] < rk[y]) {
			parent[x] = y;
		}
		else {
			parent[y] = x;
			if (rk[x] == rk[y]) {
				rk[x]++;
			}
		}
	}
}



int main(){
	ll n, d;
	cin >> n >> d;
	init(n);
	REP(i, 1, n) {
		cin >> a[i];
		b[i] = a[i] + i * d;
		c[i] = a[i] - i * d;
	}
	ll min_c = c[1];
	ll min_j = 1;
	REP(i, 2, n) {
		pq.push({ i, min_j, min_c + b[i] });
		if (min_c > c[i]) {
			min_c = c[i];
			min_j = i;
		}
	}
	ll min_b = b[n];
	ll min_i = n;
	PER(j, n - 1, 1) {
		pq.push({ j, min_i, min_b + c[j] });
		if (min_b > b[j]) {
			min_b = b[j];
			min_i = j;
		}
	}
	ll ans = 0;
	while (!pq.empty()) {
		edge cur = pq.top();
		pq.pop();
		if (same(cur.from, cur.to)) {
			continue;
		}else {
			ans += cur.cost;
			unite(cur.from, cur.to);
		}
	}
	cout << ans << endl;
}

