		rst.update(i, make_pair(A[i] + (N - i) * D, i));
	}
	int lv = lst.getversion(), rv = rst.getversion();
	while (uf.size(0) < N) {
		vector<tuple<ll, int, int>> es;
		for (int i = 0; i < N; i++) if (uf.find(i) == i) {
			int lver = lv, rver = rv;
			for (auto v : uf.vs[i]) {
				lst.update(v, make_pair(INF, -1), lver);
				lver = lst.getversion();
				rst.update(v, make_pair(INF, -1), rver);
				rver = rst.getversion();
			}
			ll c = INF;
			int to = -1;
			for (auto v : uf.vs[i]) {
				int u = lst.find(0, v, lver).second;
				if (u != -1) {
					ll cost = A[v] + A[u] + abs(v - u) * D;
					if (cost < c) {
						c = cost;
						to = u;
					}
				}
				u = rst.find(v, N, rver).second;
				if (u != -1) {
					ll cost = A[v] + A[u] + abs(v - u) * D;
					if (cost < c) {
						c = cost;
						to = u;
					}
				}
			}
			es.emplace_back(c, i, uf.find(to));
		}
		sort(es.begin(), es.end());
		for (auto e : es) {
			int u, v; ll c;
			tie(c, u, v) = e;
			if (uf.same(u, v)) continue;
			uf.unite(u, v);
			res += c;
		}
	}
	cout << res << endl;
	return 0;
}

