struct Node{
    bool operator<(const struct Node &arg) const{
        return weight < arg.weight;
    };
    ull from,to,weight;
};

ull parent[200000],height[200000];

ull getParent(ull id){
    if(parent[id] == id)return id;
    else{
        return parent[id] = getParent(parent[id]);
    }
}

bool isSame(ull a, ull b){
    return getParent(a) == getParent(b);
}

void unite(ull a,ull b){
    ull a_parent = getParent(a);
    ull b_parent = getParent(b);

    if(a_parent == b_parent)return;

    if(height[a_parent] > height[b_parent]){
        parent[b_parent] = a_parent;
    }else{
        if(height[a_parent] == height[b_parent])height[b_parent]++;
        parent[a_parent] = b_parent;
    }
}

ull i,j,k;
ull N,D;
ull A[200000];
inline void solve(){
  INPUT2(N,D);
  INPUTS(i,N,A);
  Node nodes[N*N];
  for(ull i = 0; i < N; i++){
    parent[i] = i;
    height[i] = 0;
  }
  REP(i,N)REP(j,N){
    nodes[i*N+j].from=i;
    nodes[i*N+j].to=j;
    nodes[i*N+j].weight=(i>j?i-j:j-i)*D+A[i]+A[j];
  }
  sort(nodes,nodes+N*N);

  ull sum = 0;
  for(ull i = 0; i < N*N; i++){
    if(!isSame(nodes[i].from,nodes[i].to)){
      sum += nodes[i].weight;
      unite(nodes[i].from,nodes[i].to);
    }
  }
  OUTPUT(sum);
}

int main(int argc,char**argv){
  BEGIN;
  solve();
  END;
}

