void add(int l,int r)
{
	if(r-l<=1) return;
	int m=l+r+1>>1;
	int minx=inf,tl,tr;
	for(int i=l;i<m;i++)
	{
		if(a[i]-i*d<minx)
		{
			minx=a[i]-i*d;
			tl=i;
		}
	}
	minx=inf;
	for(int i=m;i<r;i++)
	{
		if(a[i]+i*d<minx)
		{
			minx=a[i]+i*d;
			tr=i;
		}
	}
	for(int i=l;i<m;i++)
	{
		vec.push_back(mp(cost(i,tr),mp(i,tr)));
	}
	for(int i=m;i<r;i++)
	{
		vec.push_back(mp(cost(tl,i),mp(tl,i)));
	}
	add(l,m);
	add(m,r);
}

