void ins(int x,int tp){
	if (tp==1){
		if (x>1){
			pa tmp=T1::que(1,n,1,1,x-1);
			if (tmp.fi>=INF) return;
			tmp.fi+=1ll*x*D+a[x];
			Q.push(mp(tmp,mp(x,tp)));
		}
	}
	else{
		if (x<n){
			pa tmp=T2::que(1,n,1,x+1,n);
			if (tmp.fi>=INF) return;
			tmp.fi+=a[x]-1ll*x*D;
			Q.push(mp(tmp,mp(x,tp)));
		}
	}
}
void prim(){
	T1::build(1,n,1);
	T2::build(1,n,1);
	u[1]=1;
	T1::upd(1,n,1,1,INF);
	T2::upd(1,n,1,1,INF);
	ins(1,1);
	ins(1,2);
	while (!Q.empty()){
		pair<pa,pair<int,int> > t=Q.top();
		Q.pop();
		LL c=t.fi.fi;
		int y=t.fi.se;
		int x=t.se.fi;
