void make_cost_aidxs(V<t2> &cost_aidxs, SegmentTree<ll> &seg, ll aidx_cidx[],
                    const V<ll> &alist, ll n, ll d, bool reverse)
{
    rep (i, n) {
        ll j = (reverse ? (n-i-1LL) : i);
        ll cost = d * j + alist[i];
        cost_aidxs.pb(t2(cost, i));
    }

    sort(cost_aidxs);

    debug_printf("---- cost_aidxs reverse=%d\n", reverse); debug_print(cost_aidxs);

    rep (i, n) {
        ll idx = get<1>(cost_aidxs[i]);
        // seg : (cidx, aidx)
        seg.update(i, idx);
        aidx_cidx[idx] = i;
    }

    rep (i, n) debug_printf("---- seg %lld = %lld\n", i, seg.query(i, i+1));
    debug_printf("---- seg(0, 3) = %lld\n", seg.query(0, 3));
}

void push_v(const V<ll> &alist, priority_queue_incr<t3> &q,
            V<t2> &cost_aidxs, V<t2> &cost_aidxs_rev,
            SegmentTree<ll> &seg, SegmentTree<ll>& seg_rev,
            const ll aidx_cidx[], const ll aidx_cidx_rev[],
            ll n, ll d, ll aidx)
{
    // seg : (cidx, aidx)
    seg.update(aidx_cidx[aidx], -1LL);
    seg_rev.update(aidx_cidx_rev[aidx], 1e18);

    ll left = 1LL;
    ll right = n;
    ll now = (left + right) / 2LL;
    ll cidx = 1e18;
    for ( ; left <= right; now = (left + right) / 2LL) {
        // seg : (cidx, aidx)
        ll max_aidx = seg.query(0LL, now);
        if (aidx < max_aidx) {
            cidx = min(cidx, now - 1LL);
            right = now - 1LL;
        }
        else {
            left = now + 1LL;
        }
    }

    ll cand_aidx1 = -1LL;
    ll cand_cost1 = 1e18;
    if (cidx < 1e18) {
        cand_aidx1 = get<1>(cost_aidxs[cidx]);
        cand_cost1 = abs(cand_aidx1 - aidx) * d + alist[aidx] + alist[cand_aidx1];
    }
    debug_printf("cand_aidx1 = %lld / cand_cost1 = %lld\n",
                 cand_aidx1, cand_cost1);

    left = 1LL;
    right = n;
    now = (left + right) / 2LL;
    cidx = 1e18;
    for ( ; left <= right; now = (left + right) / 2LL) {
        ll min_aidx = seg_rev.query(0LL, now);
        if (aidx > min_aidx) {
            cidx = min(cidx, now - 1LL);
            right = now - 1LL;
        }
        else {
            left = now + 1LL;
        }
    }

    ll cand_aidx2 = -1LL;
    ll cand_cost2 = 1e18;
    if (cidx < 1e18) {
        cand_aidx2 = get<1>(cost_aidxs_rev[cidx]);
        cand_cost2 = abs(cand_aidx2 - aidx) * d + alist[aidx] + alist[cand_aidx2];
    }
    debug_printf("cand_aidx2 = %lld / cand_cost2 = %lld\n",
                 cand_aidx2, cand_cost2);

    if (cand_cost1 < cand_cost2) {
        q.push(t3(cand_cost1, aidx, cand_aidx1));
        return;
    }
    if (cand_cost2 < cand_cost1) {
        q.push(t3(cand_cost2, aidx, cand_aidx2));
        return;
    }
    if (cand_cost1 < 1e18) {
        q.push(t3(cand_cost1, aidx, cand_aidx1));
        return;
    }
}

