    B.update(i, tmp);
    mpb[tmp] = i;
  }
  unordered_map<ll, int> mpc;
  for(int i=n-1; i>=1; i--) {
    ll tmp = a[i]+(n-i)*d;
    C.update(i, tmp);
    mpc[tmp] = i;
  }

