		segtree A(n),B(n);

		REP(i, n) {
			aset.insert({ Aar[i] , i });
			bset.insert({ Bar[i] , i });
			B.update(i, Bar[i]);
			A.update(i, Aar[i]);

			rui[i + 1] = rui[i] + Aar[i];
		}
		{
			int Minval = INF, Minind = n;
			for (int i = n - 2; 0 <= i; i--) {

				if (Aar[i + 1] < Minval) {
					Minind = i + 1;
