    forn(i, n) {
        cin >> a[i];
    }

    vector<ll> ra = a;
    reverse(all(ra));

    min_holder frw(d, a);
    min_holder bckw(d, ra);

    frw.add_to_set(0);
    bckw.add_to_set(n - 1);

    vector<bool> took(n, false);
    took[0] = true;

    ll ans = 0;
    for (int i = 0; i < n - 1; i++) {
        auto p1 = frw.get_min_edge();
        auto p2 = bckw.get_min_edge();
        p2.ff = n - 1 - p2.ff;
        p2.ss = n - 1 - p2.ss;

        ll p1cost = (p1.ff == n || !took[p1.ff] ? INF : a[p1.ff] + a[p1.ss] + d * abs(p1.ss - p1.ff));
        ll p2cost = (p2.ff == -1 || !took[p2.ff] ? INF : a[p2.ff] + a[p2.ss] + d * abs(p2.ss - p2.ff));

        int to_a;
        if (p1cost < p2cost) {
            to_a = p1.ss;
            ans += p1cost;
        } else {
            to_a = p2.ss;
            ans += p2cost;
