const int maxn = 200200;
using plli = pair<long long, int>;
plli tr[maxn<<2];
plli operator + (plli a, plli b){
  if(a.first < b.first) return a;
  return b;
}
void Create(){
  for(int i = 0; i < maxn<<2; i++) tr[i] = make_pair(1ll<<62, -1);
}
void update(int id, int l, int r, int p, long long x, int wx){
  if(l == r){
    if(tr[id].first > x) tr[id] = make_pair(x, wx);
  } else {
    int mid = (l+r)/2;
    if(p <= mid) update(id<<1, l, mid, p, x, wx);
    else update(id<<1|1, mid+1, r, p, x, wx);
    tr[id] = tr[id<<1] + tr[id<<1|1];
  }
}
plli get(int id, int l, int r, int x, int y){
  if(l > y || r < x) return make_pair(1ll<<62, -1);
  if(x <= l && r <= y) return tr[id];
  int mid = (l + r)/2;
  return get(id<<1, l, mid, x, y) + get(id<<1|1, mid + 1, r, x, y);
}
int u[maxn], who[maxn];
long long best[maxn];
void init(){
  for(int i = 0; i < maxn; i++) u[i] = i;
}
void Setup(){
  for(int i = 0; i < maxn; i++) best[i] = 1ll<<62, who[i] = -1;
}
int find(int x){
  if(x == u[x]) return x;
  return u[x] = find(u[x]);
}
int main(){
  int n; long long d; cin >> n >> d;
  vector<int> a(n); for(int & i : a) cin >> i;
  init();
  int comp = n;
  long long ans = 0;
  while(comp != 1){
    Setup();
    Create();
    for(int i = 0; i < n; i++){
      int id = find(i);
      plli myR = make_pair(1ll<<62, -1);
      if(id) myR = myR + get(1, 0, n, 0, id - 1);
      myR = myR + get(1, 0, n, id + 1, n);
      long long realCost = d * i + a[i] + myR.first;
      if(best[id] > realCost){
        best[id] = realCost;
        who[id] = myR.second;
      }
      update(1, 0, n, id, -d * i + a[i], i);
    }
    Create();
    for(int i = n-1; i >= 0; i--){
      int id = find(i);
      plli myR = make_pair(1ll<<62, -1);
      if(id) myR = myR + get(1, 0, n, 0, id - 1);
      myR = myR + get(1, 0, n, id + 1, n);
      long long realCost = -d * i + a[i] + myR.first;
      if(best[id] > realCost){
        best[id] = realCost;
        who[id] = myR.second;
      }
      update(1, 0, n, id, d * i + a[i], i);
    }
    for(int i = 0; i < n; i++) if(who[i] != -1){
      int id = find(i), idWho = find(who[i]);
      if(id != idWho){
        ans += best[id];
        comp--;
        u[id] = idWho;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

