void solve(int l, int r) {
    if (l == r)  return;
    int mid = (l + r) >> 1, pl = 0, pr = 0;
    num ml = 5e18, mr = 5e18;
    circ (i, l, mid) {
        num cur = w[i] - d * i;
        if (cur < ml) {
