    circ (i, mid + 1, r) {
        num cur = w[i] + d * i;
        if (cur < mr) {
            pr = i;
            mr = cur;
        }
    }
    circ (i, mid + 1, r) {
        dat.push_back(edge(pl, i, ml + w[i] + d * i));
    }
    circ (i, l, mid) {
        dat.push_back(edge(i, pr, mr + w[i] - d * i));
    }
    solve(l, mid);
    solve(mid + 1, r);
}

