const int N = 1 << 18;

pii mi[2][2 * N];

pii getmi(int l, int r, int t) {
  l += N;
  r += N;
  pii res(1e18, 0);
  while (l <= r) {
    if (l & 1) {
      res = min(res, mi[t][l]);
      ++l;
    }
    if (!(r & 1)) {
      res = min(res, mi[t][r]);
      --r;
    }
    l /= 2;
    r /= 2;
  }
  return res;
}

