struct SegmentTree {
	using P = std::pair<i64, int>;
	std::vector<P> seg;
	int sz = 1;

	const P e = {1LL << 60, -1};

	SegmentTree(int n) {
		while(sz < n) sz <<= 1;
		seg.assign(sz * 2, e);
	}
	void set(int k, P x) {
		k += sz;
		seg[k] = x;

		while(k >>= 1) seg[k] = std::min(seg[2 * k + 0], seg[2 * k + 1]);
	}
	P get(int a, int b) {
		P L = e, R = e;
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if(a & 1) L = std::min(L, seg[a++]);
			if(b & 1) R = std::min(seg[--b], R);
		}
		return std::min(L, R);
	}
	P operator[](int k) {
		return seg[k + sz];
	}
};

struct UnionFind {
	std::vector<int> data;

	UnionFind(int n) {
		data.assign(n, -1);
	}
	bool unite(int x, int y) {
		x = find(x); y = find(y);
		if(x == y) return false;
		if(data[x] > data[y]) std::swap(x, y);
		data[x] += data[y];
		data[y] = x;
		return true;
	}
	int find(int k) {
		if(data[k] < 0) return k;
		return data[k] = find(data[k]);
	}
};

