#define INF LLONG_MAX
class SegmentTree{
public:

  int n;
  vector<pair<ll,int>> tree;

  SegmentTree(int size){
    n=1;
    while(n<size) n*=2;

    tree.resize(2*n-1,make_pair(INF,-1));
    for(int i=n-1;i<2*n-1;i++) tree[i].second=i-(n-1);
  }

  /*SegmentTree(vector<int> v){
    int vSize=v.size();
    n=1;
    while(n<vSize) n*=2;

    tree.resize(2*n-1,INF);

    for(int i=0;i<vSize;i++) tree[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--) tree[i]=min(tree[2*i+1],tree[2*i+2]);
  }*/

  void update(int index,ll value){
    index+=n-1;

    tree[index].first=value;
    while(index>0){
      index=(index-1)/2;
      if(tree[2*index+1].first<tree[2*index+2].first) tree[index]=tree[2*index+1];
      else tree[index]=tree[2*index+2];
    }
  }

  pair<ll,int> getMin(int a,int b,int k,int l,int r){
    if(r<0) r=n;

    if(r<=a||b<=l) return make_pair(INF,-1);
    else if(a<=l&&r<=b) return tree[k];
    else{
      pair<ll,int> lval=getMin(a,b,2*k+1,l,(l+r)/2);
      pair<ll,int> rval=getMin(a,b,2*k+2,(l+r)/2,r);
      if(lval.first<rval.first) return lval;
      else return rval;
    }
  }
};

class DisjointSet{
public:
  vector<int> rank,p;

  DisjointSet() {}
  DisjointSet(int size){
    rank.resize(size,0);
    p.resize(size,0);
    for(int i=0;i<size;i++) makeSet(i);
  }

  void makeSet(int x){
    p[x]=x;
    rank[x]=0;
  }

  bool same(int x,int y){
    return findSet(x)==findSet(y);
  }

  void unite(int x,int y){
    link(findSet(x),findSet(y));
  }

  void link(int x,int y){
    if(rank[x]<rank[y]){
      p[y]=x;
    }else{
      p[x]=y;
      if(rank[x]==rank[y]){
        rank[y]++;
      }
    }
  }

  int findSet(int x){
    if(x!=p[x]){
      p[x]=findSet(p[x]);
    }
    return p[x];
  }
};

class Edge{
public:
  int source,target;
  ll cost;
  Edge(int source=0,int target=0,ll cost=0):
  source(source),target(target),cost(cost){}
  bool operator < (const Edge &e) const{
    return cost < e.cost;
  }
};

ll kruskal(int N,vector<Edge> edges){
  ll totalCost=0;
  sort(edges.begin(),edges.end());
  DisjointSet dset=DisjointSet(N+1);

  for(int i=0;i<N;i++) dset.makeSet(i);

  int source,target;
  for(int i=0;i<edges.size();i++){
    Edge e=edges[i];
    if(!dset.same(e.source,e.target)){
      // MST.push_back(e);
      totalCost+=e.cost;
      //cout<<totalCost<<endl;
      dset.unite(e.source,e.target);
    }
  }
  return totalCost;
}

