struct LazySegmentTree {
private:
  int n;
  vector<pair<ll,int>> node;
  vector<ll> di;
  vector<ll> lazy;

public:
  LazySegmentTree(vector<ll> v,vector<ll> w) {
    int sz = (int)v.size();
    n = 1; while(n < sz) n *= 2;
    di=w;
    node.resize(2*n-1,{INF,0});
    lazy.resize(2*n-1, INF);
    for(int i=0; i<sz; i++) node[i+n-1] = {v[i],i};
    for(int i=n-2; i>=0; i--){
      if(node[i*2+1].first+di[node[i*2+1].second]<node[i*2+2].first+di[node[i*2+2].second]) node[i] = node[i*2+1];
      else node[i]=node[i*2+2];
    }
  }

  void eval(int k, int l, int r) {
    if(lazy[k] != INF) {
      node[k].first = min(node[k].first,lazy[k]);
      if(r - l > 1) {
        lazy[2*k+1] = min(lazy[2*k+1],lazy[k]);
        lazy[2*k+2] = min(lazy[2*k+2],lazy[k]);
      }
      lazy[k] = INF;
    }
  }

  void add(int a, int b, ll x, int k=0, int l=0, int r=-1) {
    if(r < 0) r = n;
    eval(k, l, r);
    if(b <= l || r <= a) return;
    if(a <= l && r <= b) {
      lazy[k] = min(lazy[k],x);
      eval(k, l, r);
    }else {
      add(a, b, x, 2*k+1, l, (l+r)/2);
      add(a, b, x, 2*k+2, (l+r)/2, r);
      if(node[k*2+1].first+di[node[k*2+1].second]<node[k*2+2].first+di[node[k*2+2].second]) node[k] = node[k*2+1];
      else node[k]=node[k*2+2];
      // cout << k SP node[k].first << endl;
    }
  }

  void use(int k){
    di[k]=INF;
    k+=n-1;
    do{
      k/=2;
      if(node[k*2+1].first+di[node[k*2+1].second]<node[k*2+2].first+di[node[k*2+2].second]) node[k] = node[k*2+1];
      else node[k]=node[k*2+2];
    }while(k>0);
  }

  pair<ll,int> getmin(int a, int b, int k=0, int l=0, int r=-1) {
    if(r < 0){
      // cout << "!!!" << endl;
      pair<ll,int> ret=getmin(a,b,k,l,n);
      // cout <<  ret.second << endl;
      return {ret.first+di[ret.second],ret.second};
    }
    if(b <= l || r <= a) return {INF,0};
    eval(k, l, r);
    if(a <= l && r <= b) return node[k];
    pair<ll,int> vl = getmin(a, b, 2*k+1, l, (l+r)/2);
    pair<ll,int> vr = getmin(a, b, 2*k+2, (l+r)/2, r);
    // cout << k << " ";
    if(vl.first+di[vl.second]<vr.first+di[vr.second]){
      // cout << vl.first+di[vl.second] << endl;
      return vl;
    }else{
      // cout << vl.first+di[vr.second] << endl;
      return vr;
    }
  }

  void disp(){
    for(int i=0;i<2*n-1;i++){
      cout << node[i].first << " ";
    }
    cout << endl;
    for(int i=0;i<2*n-1;i++){
      cout << node[i].second << " ";
    }
    cout << endl;
    for(int i=0;i<di.size();i++){
      cout << di[i] << " ";
    }
    cout << endl;
  }
};

