    vector<tuple<Int, int, int>> edges;
    auto add_edge = [&](int i, int j) {
        if (i == -1 || j == -1) return;
        edges.emplace_back(abs(i-j)*D+A[i]+A[j], i, j);
    };
    auto maxval = make_pair((Int)1e18, -1);
    using SegTree = SegTreeMin<pair<Int, int>>;
    auto S = SegTree(N, maxval);
    auto T = SegTree(N, maxval);
    for (int i = 0; i < N; i++) {
        auto p = S.query(0, I[i]);
        auto q = T.query(I[i], N);
        add_edge(I[i], p.second);
        add_edge(I[i], q.second);
        S.set(I[i], make_pair(-D * I[i] + A[I[i]], I[i]));
        T.set(I[i], make_pair(D * I[i] + A[I[i]], I[i]));
    }
    S = SegTree(N, maxval);
    T = SegTree(N, maxval);
    for (int i = N-1; i >= 0; i--) {
        auto p = S.query(0, I[i]);
        auto q = T.query(I[i], N);
        add_edge(I[i], p.second);
        add_edge(I[i], q.second);
        S.set(I[i], make_pair(-D * I[i] + A[I[i]], I[i]));
        T.set(I[i], make_pair(D * I[i] + A[I[i]], I[i]));
    }
    sort(begin(edges), end(edges));
