using namespace std;

ll INF = LLONG_MAX/4;
struct Monoid_Struct {
  using T = pair<int, ll>; // type or class of monoid
  T operator()(const T& left, const T& right) {
    return left.second < right.second ? left : right; // definition of operator
  }
  static constexpr T identity() { return (pair<int, ll>){-1, INF}; }
};

template<class Monoid>
class SegTree {
private:
  using T = typename Monoid::T;
  Monoid op;
  const int n;
  vector<T> t;

  void propagate_to(int i) { t[i] = op(t[2*i], t[2*i+1]); }

public:
  SegTree(int n_) : n(n_), t(2*n, op.identity()) {}
  SegTree(const vector<T>& v) : n(v.size()), t(2*n) {
    copy(begin(v), end(v), begin(t) + n);
    for (int i = n-1; i > 0; --i) {
      propagate_to(i);
    }
  }

  void set(int i, const T& x) {
    t[i += n] = x;
    while (i >>= 1) {
      propagate_to(i);
    }
  }

  T get(int i) { return t[i + n]; }

  T accumulate(int l, int r) {
    T accl = op.identity(), accr = op.identity();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) accl = op(accl, t[l++]);
      if (r & 1) accr = op(t[r-1], accr);
    }
    return op(accl, accr);
  }
};

int main() {
  int n;
  ll d;
  scan(n, d);
  vll a(n);
  scan(a);
  vector<pair<int, ll> > lefts(n), rights(n);
  rep (i, n) {
    lefts[i].first = i;
    rights[i].first = i;
    lefts[i].second = a[i] + d * (n-1 - i);
    rights[i].second = a[i] + d * i;
  }

  SegTree<Monoid_Struct> seg_left(lefts);
  SegTree<Monoid_Struct> seg_right(rights);
  vvi forests(n, vi(2));
  rep (i, n) {
    forests[i][0] = i;
    forests[i][1] = i+1;
  }
  set<vll> edges;
  while (true) {
    //debug(forests);
    int m = forests.size();
    if (m == 1) {
      break;
    }
    vi min_nodes(m, -1);
    rep (i, m) {
      ll left_cost = INF;
      ll right_cost = INF;
      auto p_left = seg_left.accumulate(0, forests[i][0]);
      int min_left = p_left.first;
      int min_left_right = seg_right.accumulate(forests[i][0], forests[i][1]).first;
      if (0 <= min_left && min_left < n) {
        left_cost = a[min_left] + a[min_left_right] + d*(min_left_right - min_left);
      }
      auto p_right = seg_right.accumulate(forests[i][1], n);
      int min_right = p_right.first;
      int min_right_left = seg_left.accumulate(forests[i][0], forests[i][1]).first;
      if (0 <= min_right && min_right < n) {
        right_cost = a[min_right] + a[min_right_left] + d*(min_right - min_right_left);
      }
      //debug3(a[i], left_cost, right_cost);
      if (left_cost > right_cost) {
        min_nodes[i] = min_right;
        edges.insert({right_cost, min_right_left, min_right});
      } else {
        min_nodes[i] = min_left;
        edges.insert({left_cost, min_left, min_left_right});
      }
    }
    //debug(min_nodes);
    vvi next_forests;
    vi forest = {0, -1};
    int max_index = 0;
    rep (i, m) {
      if (max_index + 1 == forests[i][0] && forests[i][1] <= min_nodes[i]) {
        forest[1] = forests[i][0];
        next_forests.push_back(forest);
        forest[0] = forests[i][0];
      }
      max_index = max(max_index, forests[i][1] - 1);
      int mn_max = (*(upper_bound(all(forests), (vi){min_nodes[i], n+10}) - 1))[1] - 1;
      max_index = max(max_index, mn_max);
    }
    forest[1] = n;
    next_forests.push_back(forest);
    swap(forests, next_forests);
  }
  assert((int)edges.size() == n-1);

  ll ans = 0;
  for (auto&& e : edges) {
    ans += e[0];
  }
  print(ans);

  return 0;
}

