LL f( int a, int b ) {
    if ( a>b ) swap(a,b);
    return (LL)(b-a)*D + A[a] + A[b];
}

void solve( int l, int r ) {
    if ( l+1==r ) return;
    solve(l,(l+r)/2);
    solve((l+r)/2,r);
    // merge
    // Ai - Di, Aj + Dj
    int m=(l+r)/2;
    int x,y;
    {
        LL mi=1e18;
        for ( int i=l; i<m; i++ ) {
            LL me=(LL)-D*i+A[i];
            if ( chmin(mi,me) ) x=i;
        }
    }
    {
        LL mi=1e18;
        for ( int i=m; i<r; i++ ) {
            LL me=(LL)D*i+A[i];
            if ( chmin(mi,me) ) y=i;
        }
    }
    for ( int i=m; i<r; i++ ) {
        s.push_back({f(x,i), {x,i}});
    }
    for ( int i=l; i<m; i++ ) {
        if ( i!=x ) s.push_back({f(i,y), {i,y}});
    }
}


struct UnionFind {
    int n, num;
    vector<int> sz, par;
    UnionFind() {}
    UnionFind(int n_) : n(n_), num(n_), sz(n_, 1), par(n_, 0) { iota(par.begin(), par.end(), 0); }
    int find(int x) { return x==par[x] ? x : par[x]=find(par[x]); }
    bool same(int x, int y) { return find(x) == find(y); }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return;
        if (sz[x] < sz[y]) swap(x, y);
        sz[x] += sz[y];
        par[y] = x;
        num--;
    }
    int size(int x) { return sz[find(x)]; }
    int count() const { return num; }
};

