// Union-Find木
// 初期化 UF(N); Nは要素数
// 結合 unite(x,y); 同じ集合か判定 same(x,y);
// 集合の数 count
struct UF{
  vector<int> par,sizes;
  int cnt;
  UF(int N) : par(N),sizes(N, 1),cnt(N){ for(int i=0; i<N; i++) par[i]=i; }

  int find(int x){ return par[x]==x ? x : par[x] = find(par[x]); }

  bool same(int x,int y){ return find(x) == find(y); }

  int size(int x){ return sizes[find(x)]; }

  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(sizes[x] < sizes[y]) swap(x,y);
    par[y] = x;
    sizes[x] += sizes[y];
    cnt--;
  }

  int count() const{return cnt;}
};

void solve(){
  inl(N,D);
  vl A(N);in(A);
  set<P> left,right;

  // left A - D * i
  // right A + D * i
  rep1(i , N - 1){
    right.emplace(A[i] + D * i , i);
  }

  Edges<ll> es;
  auto add = [&](int i,int j){
    ll c = A[i] + A[j] + abs(i - j) * D;
    es.eb(i , j , c);
  };

  rep(i , N){
    trc(sz(left) , sz(right));
    if(!left.empty()){
      auto it = left.begin();
      trc(i , it->second);
      add(i , it->second);
    }
    if(!right.empty()){
      auto it = right.begin();
      trc(i , it->second);
      add(i , it->second);
    }

    if(i != N - 1){
      right.erase(P(A[i + 1] + D * (i + 1), i + 1));
      left.emplace(A[i] - D * i , i);
    }
  }

  each(x,es)trc(x.src,x.to,x.cost);
  ll ans = 0;
  UF uf(N);
  sort(all(es) , [&](auto a,auto b){return a.cost < b.cost;});
  //sort(all(es) , )
  each(e , es){
    if(uf.same(e.src , e.to)) continue;
    ans += e.cost;
    uf.unite(e.src,e.to);
  }

  out(ans);



}

