const int maxn=200010;

struct UF
{
	int par[maxn],Rank[maxn];

	inline void INIT(int n)
	{
		rep(i,n) par[i]=i,Rank[i]=0;
	}

	inline int Find(int x)
	{
		if(par[x]==x) return x;
		return par[x]=Find(par[x]);
	}

	inline void unite(int x,int y)
	{
		x=Find(x);y=Find(y);

		if(x==y) return;
		else if(Rank[x]<Rank[y]) par[x]=y;
		else
		{
			par[y]=x;
			if(Rank[x]==Rank[y]) Rank[x]++;
		}
	}

	inline bool same(int x,int y)
	{
		return Find(x)==Find(y);
	}
} uf;

LL n,d,a[maxn],ans;
vector<pair<LL,pair<int,int> > > edge;

inline void sol(int l,int r)
{
	if(l==r) return;

	int m=(l+r)/2;

	LL mn=LINF;
	int pl=-1;

	repa1(i,l,m)
	{
		LL v=a[i]-d*LL(i);
		if(mn>v)
		{
			mn=v;
			pl=i;
		}
	}

	mn=LINF;
	int pr=-1;

	repa1(i,m+1,r)
	{
		LL v=a[i]+d*LL(i);
		if(mn>v)
		{
			mn=v;
			pr=i;
		}
	}

	repa1(i,l,m)
	{
		LL vl=a[i]-d*LL(i),vr=a[pr]+d*LL(pr);
		edge.push_back({vl+vr,{i,pr}});
	}

	repa1(i,m+1,r)
	{
		LL vl=a[pl]-d*LL(pl),vr=a[i]+d*LL(i);
		edge.push_back({vl+vr,{pl,i}});
	}

	sol(l,m);
	sol(m+1,r);
}

