	const auto cost = [&a, &d, &n](const usize l, const usize r)->u64 {
		if (l == n || r == n) return ::std::numeric_limits<u64>::max();
		return d*difference(l, r) + a[l] + a[r];
	};
	u64 ans = 0;
	usize cnt = 0, looper = 0;
	while(cnt!=n-1)
	{
		::std::vector<usize> near(n, n);
		::std::array<usize, 3> top = { n,n,n };
		for (const auto i : rep<>(0, n)) {
			if (!uf.same(i, top[0])) {
				near[i] = top[0];
			}
			else {
				near[i] = top[1];
			}
			top[2] = i;
			::std::sort(top.begin(), top.end(),
				[&cost, &i](usize l, usize r) {return cost(i, l) < cost(i, r);});
			if (uf.same(top[0], top[1])) {
				top[1] = top[2];
			}
		}
		top = { n,n,n };
		for (const auto i : revrep<>(0, n)) {
			if (!uf.same(i, top[0])) {
				if (cost(i, near[i]) > cost(i, top[0]))
					near[i] = top[0];
			}
			else {
				if (cost(i, near[i]) > cost(i, top[1]))
					near[i] = top[1];
			}
			top[2] = i;
			::std::sort(top.begin(), top.end(),
				[&cost, &i](usize l, usize r) {return cost(i, l) < cost(i, r);});
			if (uf.same(top[0], top[1])) {
				top[1] = top[2];
			}
		}
		::std::vector<usize> next(n);
		::std::iota(next.begin(), next.end(), 0);
		for (const auto i : rep<>(0, n)) {
			const auto r = uf.find(i);
			if (r != i) {
				next[i] = n;
				if (cost(i, near[i]) < cost(next[r], near[next[r]])) {
					next[r] = i;
				}
			}
		}
		0;
		for (const auto i : rep<>(0, n)) {
			if (next[i] != n) {
				const usize e = next[i];
				if (!uf.same(e, near[e])) {
					uf.unite(e, near[e]);
					++cnt;
					ans += cost(e, near[e]);
				}
			}
		}
		++looper;
	}
	::std::cout << ans << ::std::endl;
	return 0;
}

