struct UnionFind {
	vector<int> par, rank;

	UnionFind(int n) {
		par.resize(n);
		rank.resize(n);
		REP(i, n) {
		 par[i] = i;
		 rank[i] = 0;
		}
	}

	int operator[] (int x) {
		return find(x);
	}

	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return;

		if (rank[x] < rank[y]) swap(x, y);

		par[y] = x;
		if (rank[x] == rank[y]) rank[x]++;
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}

};

using pll = pair<ll, ll>;
using ll3 = tuple<ll, ll, ll>;

ll N, D;

vector<pii> solve(UnionFind &uf, vector<ll> &A) {
	set<pll> ss;
	REP(i, N) ss.insert(pll(i * D + A[i], i));
	auto bit = ss.begin();
	vector<set<pll>::iterator> v(N, bit);

	vector<pii> pairv;

	REP(i, N) {
		while (bit != ss.end() && bit->se <= i) ++bit;

		auto it = v[uf[i]];
		if (it == ss.end()) continue;
		if (it->se < bit->se) it = bit;
		while (it != ss.end() && (uf[it->se] == uf[i] || it->se <= i)) ++it;
		v[uf[i]] = it;
		if (it == ss.end()) continue;
		pairv.emplace_back(i, it->se);
	}

	return pairv;
}

int main() {
	cin >> N >> D;
	vector<ll> A(N), RA;
	REP(i, N) scanf("%lld", &A[i]);
	RA = A; reverse(ALL(RA));

	UnionFind uf(N);
	ll ans = 0;

	while (true) {
		vector<pii> pairv[2] { solve(uf, A), solve(uf, RA) };
		for (pii &cur : pairv[1]) {
			cur.fi = N - cur.fi - 1;
			cur.se = N - cur.se - 1;
		}

		vector<ll3> v;
		REP(i, 2) for (pii &cur : pairv[i])
			v.emplace_back(abs(cur.fi - cur.se) * D + A[cur.fi] + A[cur.se], cur.fi, cur.se);
		sort(ALL(v));

		for (ll3 & cur : v) {
			ll cost, x, y;
			tie(cost, x, y) = cur;
			if (uf[x] == uf[y]) puts("K");
		}

		bool loop = false;
		for (ll3 &cur : v) {
			ll cost, x, y;
			tie(cost, x, y) = cur;
			if (uf[x] == uf[y]) continue;
			uf.unite(x, y);
			loop = true;
			ans += cost;
		}

		if (!loop) break;
	}

	cout << ans << endl;

	return 0;
}

