  vector<vector<PII>> g(2*n);
  // i <-> i+n
  REP(i, n) {
    g[i].push_back({i+n, a[i]});
    g[i+n].push_back({i, a[i]});
  }
  // i <-> i+1
  REP(i, n-1) {
    g[n+i].push_back({n+i+1, d});
    g[n+i+1].push_back({n+i, d});
  }
  // グラフに色を塗って全域木の候補の辺を特定
  ll ret = 0;
  vector<ll> dist(2*n, INF), col(2*n, -1);
  struct node {
    ll dist, vertex, col;
    node() {}
    node(ll a, ll b, ll c) : dist(a), vertex(b), col(c) {}
    bool operator<(node nd) const { return dist > nd.dist; }
  };
  priority_queue<node> que;
  REP(i, n) que.push(node(0, i, i));
  while(que.size()) {
    node p = que.top(); que.pop();
    if(dist[p.vertex] == INF) {
      dist[p.vertex] = p.dist;
      col[p.vertex] = p.col;
      for(auto to: g[p.vertex]) {
        que.push(node(p.dist+to.second, to.first, p.col));
      }
    } else {
      if(p.col != col[p.vertex]) {
        ret += dist[p.vertex] + p.dist;
      }
    }
  }
  cout << ret/2 << endl;

  return 0;
}

