class Dsu{
private:
	int sz;
	int fa[maxn];
public:
	inline void init(int n){
		sz=n;
		FOR(i,0,sz) fa[i]=i;
		return;
	}
	inline int find(int x){return (x==fa[x])?(x):(fa[x]=find(fa[x]));}
	inline void combine(int x,int y){
		x=find(x);y=find(y);
		fa[x]=y;
		return;
	}
}dsu;

