vector<Edge> vec;

inline void solve(int l,int r){
	if(l==r) return;
	int md=(l+r)>>1;
	solve(l,md);
	solve(md+1,r);
	int va=r,vs=l;
	REP(i,l+1,md) if(a[i]-d*i<=a[vs]-d*i) vs=i;
	FOR(i,md+1,r) if(a[i]+d*i<=a[va]+d*i) va=i;
	REP(i,l,md)	vec.PB(Edge((va-i)*d+a[va]+a[i],va,i));
	REP(i,md+1,r) vec.PB(Edge((i-vs)*d+a[vs]+a[i],vs,i));
	return;
}

