struct UF{
	int n;
	vector<int>parent,rank;
	UF(int n_=0):n(n_),parent(n_),rank(n_,0)
	{
		for(int i=0;i<n_;i++)parent[i]=i;
	}
	int find(int a)
	{
		return parent[a]!=a?parent[a]=find(parent[a]):a;
	}
	bool same(int a,int b)
	{
		return find(a)==find(b);
	}
	bool unite(int a,int b)
	{
		a=find(a),b=find(b);
		if(a==b)return false;
		if(rank[a]<rank[b])
		{
			parent[a]=b;
		}
		else
		{
			parent[b]=a;
			if(rank[a]==rank[b])rank[a]++;
		}
		return true;
	}
};
int n;
long d,a[2<<17];
main()
{
	cin>>n>>d;
	for(int i=0;i<n;i++)cin>>a[i];
	priority_queue<pair<long,pair<int,int> > >P;
	vector<int>L;
	int x=n-1;
	L.push_back(n-1);
	for(int i=n-2;i>=0;i--)
	{
		if(d*(x-i)+a[x]>a[i])
		{
			L.push_back(i);
			x=i;
		}
	}
	for(int i=0;i<n-1;i++)
	{
		while(L.back()<=i)L.pop_back();
		P.push(make_pair(-d*(L.back()-i)-a[i]-a[L.back()],make_pair(i,L.back())));
	}
	vector<int>R;
	x=0;
	R.push_back(0);
	for(int i=1;i<n;i++)
	{
		if(d*(i-x)+a[x]>a[i])
		{
			R.push_back(i);
			x=i;
		}
	}
	for(int i=n-1;i>0;i--)
	{
		while(R.back()>=i)R.pop_back();
		P.push(make_pair(-d*(i-R.back())-a[i]-a[R.back()],make_pair(i,R.back())));
	}
	UF uf(n);
	long ans=0;
	while(!P.empty())
	{
		long cost=-P.top().first;
		int x=P.top().second.first,y=P.top().second.second;
