#define int long long
#define REP(i,a,b) for(i=a;i<b;i++)
#define rep(i,n) REP(i,0,n)
using namespace std;

struct UF {
	int par[200000];
	UF() { for (int i = 0; i < 200000; i++) par[i] = i; }
	int root(int x) { if (par[x] == x) return x; return par[x] = root(par[x]); }
	void unit(int x, int y) { x = root(x); y = root(y); par[x] = y; }
	bool same(int x, int y) { return root(x) == root(y); }
};

int n, d;
int a[200000];
int bestR[200000];
int bestL[200000];

void chmax(int &a, int b) { a = max(a, b); }
void chmin(int &a, int b) { a = min(a, b); }
int cal(int i, int j) { return abs(i - j) * d + a[i] + a[j]; }

void calcR(int lx, int rx, int ly, int ry) {
	if (lx >= rx) return;

	int m = (lx + rx) / 2;

	int i, it = max(ly, m + 1);
	REP(i, it, ry) {
		if (cal(m, i) < cal(m, it)) it = i;
 	}

 	bestR[m] = it;
 	calcR(lx, m, ly, it + 1);
 	calcR(m + 1, rx, it, ry);
}

void calcL(int lx, int rx, int ly, int ry) {
	if (lx >= rx) return;

	int m = (lx + rx) / 2;

	int i, it = ly;
	REP(i, ly, min(ry, m)) {
		if (cal(m, i) < cal(m, it)) it = i;
	}
	bestL[m] = it;
	calcL(lx, m, ly, it + 1);
	calcL(m + 1, rx, it, ry);
}

signed main() {
	int i;

	cin >> n >> d;
	rep(i, n) cin >> a[i];
	calcR(0, n - 1, 0, n);	//引数rx = nとするとバグるので注意
	calcL(1, n, 0, n);		//引数lx = 0とするとバグるので注意

	typedef tuple<int, int, int> T;
	vector<T> edges;

	REP(i, 0, n - 1) {
		edges.push_back(T(cal(i, bestR[i]), i, bestR[i]));
	}
	REP(i, 1, n) {
		edges.push_back(T(cal(i, bestL[i]), i, bestL[i]));
	}

	sort(edges.begin(), edges.end());

	static UF uf;
	int sumCost = 0;
	rep(i, edges.size()) {
		int cst = get<0>(edges[i]);
		int u = get<1>(edges[i]);
		int v = get<2>(edges[i]);
		if (!uf.same(u, v)) {
			uf.unit(u, v);
			sumCost += cst;
		}
	}
	cout << sumCost << endl;
	return 0;
}

