inline ll cost(int i,int j)
{
	return 1LL*a[i]+1LL*a[j]+1LL*(j-i)*d;
}

void add(int l,int r)
{
	if(r-l<=1) return;
	int m=l+r+1>>1;
	ll minx=inf,tl,tr;
	for(int i=l;i<m;i++)
	{
		if(1LL*a[i]-1LL*i*d<minx)
		{
			minx=1LL*a[i]-1LL*i*d;
			tl=i;
		}
	}
	minx=1LL*inf*inf;
	for(int i=m;i<r;i++)
	{
		if(1LL*a[i]+1LL*i*d<minx)
		{
			minx=1LL*a[i]+1LL*i*d;
			tr=i;
		}
	}
	for(int i=l;i<m;i++)
	{
		vec.push_back(mp(cost(i,tr),mp(i,tr)));
	}
	for(int i=m;i<r;i++)
	{
		vec.push_back(mp(cost(tl,i),mp(tl,i)));
	}
	add(l,m);
	add(m,r);
}

