const int INF = 1e9 + 10;
const ll MOD = 1e9 + 7;

const int MAXN = 2e5 + 5;

int a[MAXN], l[MAXN], r[MAXN];
ll l_val[MAXN], r_val[MAXN];
set<pair<ll, int> > st;

void solve(){
	int n, d;
	scanf("%d%d", &n, &d);
	REP(i, 0, n) {
		scanf("%d", &a[i]);
	}
	REP(i, 0, n) {
		l[i] = r[i] = i;
		l_val[i] = r_val[i] = a[i];
	}
	REP(i, 1, n) {
		st.insert(mp((ll)l_val[i] + (ll)r_val[i - 1], i - 1));
	}
	ll ans = 0ll;
	while(!st.empty()) {
		ans += st.begin()->_1 + d;

		int pos = st.begin()->_2;
		st.erase(st.begin());

		int _l = l[pos];
		int _r = r[pos + 1];

		r[_l] = _r;
		l[_r] = _l;

		ll l_val_new = min(l_val[_l], l_val[pos + 1] + (ll)d * (ll)(pos + 1 - _l));
		ll r_val_new = min(r_val[_r], r_val[pos] + (ll)d * (ll)(_r - pos));

		if (l_val_new < l_val[_l] && _l > 0) {
			st.erase(mp(r_val[_l - 1] + l_val[_l], _l - 1));
			l_val[_l] = l_val_new;
			st.insert(mp(r_val[_l - 1] + l_val[_l], _l - 1));
		}

		if (r_val_new < r_val[_r] && _r < n - 1) {
			st.erase(mp(r_val[_r] + l_val[_r + 1], _r));
			r_val[_r] = r_val_new;
			st.insert(mp(r_val[_r] + l_val[_r + 1], _r));
		}
	}
	cout << ans << endl;
}   

int main(){

    //freopen(file".in", "r", stdin); freopen(file".out", "w", stdout);
    int t = 1;
    //cin >> t;
    while(t--){
        solve();    
    }
}

