    st.insert(PL(n, INF));
    st2.insert(PL(-1, INF));
    st2.insert(PL(n, INF));
    VL tmp(b);
    REP(i,n) tmp[i] += c[0];
    tmp[0] = INF;

    LazySegmentTree segtree(tmp);

    REP(i,n) tmp[i] = INF + c[i];
    tmp[0] = 1e18;
    LazySegmentTree segtree2(tmp);
    st2.insert(PL(n, INF));


    // REP(i,n){
    //     REP(j,n) cout << abs(i - j) * d + a[i] + a[j] << " ";
    //     cout << endl;
    // }

    // cout << endl;
