        ans += p.first;
        int x = p.second;
        segtree.add(x, x + 1, INF);
        segtree2.add(x, x + 1, INF);
        auto itr = st.lower_bound(PL(x, 0));
        itr--;
        if (itr->second > c[x]){
            auto itr2 = st.lower_bound(PL(x, 0));
            segtree.add(x + 1, itr2->first, c[x] - itr->second);
