const ll MAX_N=1<<20;
//セグメント木を持つグローバル配列
ll n,dat1[2*MAX_N-1],dat2[2*MAX_N-1];
//初期化
void init1(ll n_){
    //簡単のため要素数を2のべき乗に
    n=1;
    while(n<n_)n*=2;
    //全ての値をinfに
    for(ll i=0;i<2*n-1;i++)dat1[i]=inf;
}
//k番目の値(0-indexed)をaに変更
void update1(ll k,ll a){
    //葉の節点
    k+=n-1;
    dat1[k]=a;
    //登りながら更新
    while(k>0){
        k=(k-1)/2;
        dat1[k]=min(dat1[k*2+1],dat1[k*2+2]);
    }
}
//[a,b)の最小値を求める
//後ろの方の引数は、計算の簡単のための引数
//kは節点の番号、l,rはその節点が[l,r)に対応づいていることを表す。
ll query1(ll a,ll b,ll k,ll l,ll r){
    //[a,b)と[l,r)が交差しなければinf
    if(r<=a||b<=l)return inf;
    //[a,b)が[l,r)を完全に含んでいれば、この節点の値
    if(a<=l&&r<=b)return dat1[k];
    else{
        //そうでなければ、2つの子の最小値
        ll vl=query1(a,b,k*2+1,l,(l+r)/2);
        ll vr=query1(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
}
//[a,b)の最小値
ll que1(ll a,ll b){
    return query1(a,b,0,0,n);
}
//初期化
void init2(ll n_){
    //簡単のため要素数を2のべき乗に
    n=1;
    while(n<n_)n*=2;
    //全ての値をinfに
    for(ll i=0;i<2*n-1;i++)dat2[i]=inf;
}
//k番目の値(0-indexed)をaに変更
void update2(ll k,ll a){
    //葉の節点
    k+=n-1;
    dat2[k]=a;
    //登りながら更新
    while(k>0){
        k=(k-1)/2;
        dat2[k]=min(dat2[k*2+1],dat2[k*2+2]);
    }
}
//[a,b)の最小値を求める
//後ろの方の引数は、計算の簡単のための引数
//kは節点の番号、l,rはその節点が[l,r)に対応づいていることを表す。
ll query2(ll a,ll b,ll k,ll l,ll r){
    //[a,b)と[l,r)が交差しなければinf
    if(r<=a||b<=l)return inf;
    //[a,b)が[l,r)を完全に含んでいれば、この節点の値
    if(a<=l&&r<=b)return dat2[k];
    else{
        //そうでなければ、2つの子の最小値
        ll vl=query2(a,b,k*2+1,l,(l+r)/2);
        ll vr=query2(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
}
//[a,b)の最小値
ll que2(ll a,ll b){
    return query2(a,b,0,0,n);
}
