class unionfind {
	vector<int> par, rank;

public:
	void init(int n) {
		par.resize(n);
		rank.resize(n);

		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return ;

		if (rank[x] < rank[y]) par[x] = y;
		else {
			par[y] = x;
			if (rank[x] == rank[y]) ++rank[x];
		}
	}

	bool same(int x, int y) { return (find(x) == find(y)); }
} uf;

const int SZ = 1 << 20;

template<class T>
struct segtree {
	vector<pair<T,int>> dat;

	const T INF = numeric_limits<T>::max();

	void init() {
		dat.resize(SZ * 2);
		rep(i, SZ * 2) dat[i] = mp(INF, -1);
	}

	void update(int pos, T x) {
		pos += SZ - 1;
		dat[pos] = mp(x, pos - (SZ - 1));

		while (pos > 0) {
			pos = (pos - 1) / 2;
			dat[pos] = min(dat[pos * 2 + 1], dat[pos * 2 + 2]);
		}
	}

	pair<T,int> get(int a, int b, int k = 0, int l = 0, int r = SZ) {
		if (b <= l || r <= a) return mp(INF, -1);
		if (a <= l && r <= b) return dat[k];
		return min(get(a, b, k * 2 + 1, l, (l + r) / 2), get(a, b, k * 2 + 2, (l + r) / 2, r));
	}
};

int main() {
	int N, D; cin >> N >> D;
	V<int> A(N);
	rep(i, N) cin >> A[i];

	segtree<ll> segl, segr;
	segl.init(); segr.init();

	V<pii> vec(N);
	rep(i, N) vec[i] = mp(A[i], i);
	sort(ALL(vec));

	V<pair<ll, pii>> edges;

	for (auto pr : vec) {
		int p = pr.se;
		auto tl = segl.get(0, p);
		if (tl.fi != segl.INF) {
			edges.eb(A[p] + (ll)D * p + tl.fi, mp(p, tl.se));
		}
		auto tr = segr.get(p+1, N);
		if (tr.fi != segr.INF) {
			edges.eb(A[p] - (ll)D * p + tr.fi, mp(p, tr.se));
		}

		segl.update(p, A[p] - (ll)D * p);
		segr.update(p, A[p] + (ll)D * p);
	}

	sort(ALL(edges));
	uf.init(N);
	ll ans = 0;
	for (auto e : edges) {
		if (!uf.same(e.se.fi, e.se.se)) {
			uf.unite(e.se.fi, e.se.se);
			ans += e.fi;
		}
	}	
	cout << ans << endl;
	return 0;
}

