class UnionFind{
	vector<int> par,siz;
	//0-indexed
	void init(int n){
		component = n;
		par.resize(n);
		for(int i=0;i<n;++i)par[i]=i;
		siz.resize(n,1);
		msiz = 1;
	}
public:
	int msiz,component;
	UnionFind(int n_){init(n_);}
	int root(int x){
		if(par[x]==x)return x;
		return par[x] = root(par[x]);
	}
	void unite(int x,int y){
		x = root(x);
		y = root(y);
		if(x==y)return;
		siz[y] += siz[x];
		siz[x] = 0;
		par[x] = y;
		msiz = max(msiz,siz[y]);
		component--;
	}
	int size(int x){
		return siz[root(x)];
	}
	bool same(int x,int y){
		return root(x)==root(y);
	}
};


