	for(int i=0;i<N;i++) cin>>A[color[i]=i];
	solve(0,N-1);
	sort(E.begin(),E.end());
	for(auto e: E) {
		tie(w,u,v)=e;
		if(find_(u)!=find_(v)) {
			union_(u,v);
			ans+=w;
		}
	}
	cout<<ans<<'\n';
	return 0;
}

