using namespace std;

class UF {
private:
  vector<int> data; // parent or size
  vector<int> next;
  vector<int> last;
  void init(int n) {
    data.assign(n, -1);
    next.assign(n, -1);
    last.resize(n);
    for (int i = 0; i < n; ++i) {
      last[i] = i;
    }
  }

public:
  UF() {}
  UF(int n) {
    init(n);
  }
  int root(int x) {
    if (data[x] < 0) return x;
    return data[x] = root(data[x]);
  }
  bool unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y); // data[x] and data[y] are negative.
    data[x] += data[y];
    data[y] = x;
    next[last[x]] = y;
    last[x] = last[y];
    return true;
  }
  int size(int x) {
    return -data[root(x)];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int get_next(int x) {
    return next[x];
  }
};

struct Monoid_Struct {
  using T = pair<int, ll>; // type or class of monoid
  T operator()(const T& left, const T& right) {
    return left.second < right.second ? left : right; // definition of operator
  }
  static constexpr T identity() { return (pair<int, ll>){-1, LLONG_MAX/4}; }
};

template<class Monoid>
class SegTree {
private:
  using T = typename Monoid::T;
  Monoid op;
  const int n;
  vector<T> t;

  void propagate_to(int i) { t[i] = op(t[2*i], t[2*i+1]); }

public:
  SegTree(int n_) : n(n_), t(2*n, op.identity()) {}
  SegTree(const vector<T>& v) : n(v.size()), t(2*n) {
    copy(begin(v), end(v), begin(t) + n);
    for (int i = n-1; i > 0; --i) {
      propagate_to(i);
    }
  }

  void set(int i, const T& x) {
    t[i += n] = x;
    while (i >>= 1) {
      propagate_to(i);
    }
  }

  T get(int i) { return t[i + n]; }

  T accumulate(int l, int r) {
    T accl = op.identity(), accr = op.identity();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) accl = op(accl, t[l++]);
      if (r & 1) accr = op(t[r-1], accr);
    }
    return op(accl, accr);
  }
};

ll INF = LLONG_MAX/4;
int main() {
  ll n, d;
  scan(n, d);
  vll a(n);
  scan(a);
  vector<pair<int, ll> > lefts(n), rights(n);
  rep (i, n) {
    lefts[i].first = i;
    rights[i].first = i;
    lefts[i].second = a[i] + d * (n-1 - i);
    rights[i].second = a[i] + d * i;
  }

  SegTree<Monoid_Struct> seg_left(lefts), seg_right(rights);
  vvi forests(n, vi(2));
  rep (i, n) {
    forests[i][0] = i;
    forests[i][1] = i+1;
  }
  set<vll> edges;
  while (true) {
    //debug(forests);
    int m = forests.size();
    if (m == 1) { break; }
    vi min_nodes(m, -1);
    rep (i, m) {
      ll left_cost = INF;
      ll right_cost = INF;
      int min_left = seg_left.accumulate(0, forests[i][0]).first;
      int min_left_right = seg_right.accumulate(forests[i][0], forests[i][1]).first;
      if (min_left != -1) {
        left_cost = a[min_left] + a[min_left_right] + d*(min_left_right - min_left);
      }
      int min_right = seg_right.accumulate(forests[i][1], n).first;
      int min_right_left = seg_left.accumulate(forests[i][0], forests[i][1]).first;
      if (min_right != -1) {
        right_cost = a[min_right] + a[min_right_left] + d*(min_right - min_right_left);
      }
      //debug3(a[i], left_cost, right_cost);
      if (left_cost > right_cost) {
        min_nodes[i] = min_right;
        edges.insert({right_cost, min_right_left, min_right});
      } else {
        min_nodes[i] = min_left;
        edges.insert({left_cost, min_left, min_left_right});
      }
    }
    //debug(min_nodes);
    vvi next_forests;
    vi forest = {0, -1};
    int max_index = 0;
    rep (i, m) {
      if (i == max_index + 1 && min_nodes[i] > i) {
        forest[1] = i;
        next_forests.push_back(forest);
        forest[0] = i;
      }
      max_index = max(max_index, i);
      max_index = max(max_index, min_nodes[i]);
    }
    forest[1] = m;
    next_forests.push_back(forest);
    swap(forests, next_forests);
  }

  ll ans = 0;
  UF uf(n);
  for (auto&& e : edges) {
    if (uf.same(e[1], e[2])) { continue; }
    uf.unite(e[1], e[2]);
    ans += e[0];
  }
  print(ans);

  return 0;
}

