        }

        p = st_right->query(A[i].first + 1, N);
        if (p != inf) {
            edges[A[i].first].push_back({p.first, p.second + A[i].second - A[i].first * D});
            edges[p.first].push_back({A[i].first, p.second + A[i].second - A[i].first * D});
