namespace Segtree{
	#define ls cur<<1
	#define rs cur<<1|1
	void pushup(int cur){
		t[cur].sx=min(t[ls].sx,t[rs].sx);
		t[cur].sy=min(t[ls].sy,t[rs].sy);
		t[cur].tx=min(t[ls].tx,t[rs].tx);
		t[cur].ty=min(t[ls].ty,t[rs].ty);
		t[cur].val=min(t[ls].val,t[rs].val);
		if(t[ls].sy.fst+t[rs].tx.fst<t[cur].val.fst)
			t[cur].val=mp(t[ls].sy.fst+t[rs].tx.fst,t[rs].tx.snd);
		if(t[rs].sx.fst+t[ls].ty.fst<t[cur].val.fst)
			t[cur].val=mp(t[rs].sx.fst+t[ls].ty.fst,t[ls].ty.snd);
	}
	void build(int cur,int l,int r){
		if(l==r){
			t[cur].val=mp(Inf,Inf);
			if(l==1){
				t[cur].sx=mp(1LL*l*d+a[l],l);
				t[cur].sy=mp(-1LL*l*d+a[l],l);
				t[cur].tx=mp(Inf,Inf);
				t[cur].ty=mp(Inf,Inf);
			}
			else{
				t[cur].sx=mp(Inf,Inf);
				t[cur].sy=mp(Inf,Inf);
				t[cur].tx=mp(1LL*l*d+a[l],l);
				t[cur].ty=mp(-1LL*l*d+a[l],l);
			}
			return;
		}
		int mid=l+r>>1;
		build(ls,l,mid);build(rs,mid+1,r);
		pushup(cur);
	}
	void update(int cur,int l,int r,int k){
		if(l==r){
			swap(t[cur].sx,t[cur].tx);
			swap(t[cur].sy,t[cur].ty);
			return;
		}
		int mid=l+r>>1;
		if(k<=mid)update(ls,l,mid,k);
		else update(rs,mid+1,r,k);
		pushup(cur); 
	}
}

