  INPUT2(N,D);
  INPUTS(i,N,A);
  Node nodes[N*N];
  for(ull i = 0; i < N; i++){
    parent[i] = i;
    height[i] = 0;
  }
  REP(i,N)REP(j,N){
    nodes[i*N+j].from=i;
    nodes[i*N+j].to=j;
    nodes[i*N+j].weight=abs(i-j)*D+A[i]+A[j];
  }
  sort(nodes,nodes+N*N);

  ull sum = 0;
  for(ull i = 0; i < N*N; i++){
    if(!isSame(nodes[i].from,nodes[i].to)){
      sum += nodes[i].weight;
      unite(nodes[i].from,nodes[i].to);
    }
  }
  OUTPUT(sum);
}

