// ref: https://ei1333.github.io/luzhiled/snippets/structure/union-find.html
struct UnionFind {
    vector< int > data;

    UnionFind(int sz) {
        data.assign(sz, -1);
    }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y) return (false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }

    int find(int k) {
        if(data[k] < 0) return (k);
        return (data[k] = find(data[k]));
    }

    int size(int k) {
        return (-data[find(k)]);
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }
};


int main(){
    cin.tie(nullptr);ios::sync_with_stdio(false);
    ll N, D; cin >> N >> D;
    vector<ll> A(N);
    rep(i, 0, N) cin >> A[i];

    vector<pll> le(N), ri(N);
    rep(i, 0, N) le[i] = pll(A[i] - D * i, i);
    rep(i, 0, N) ri[i] = pll(A[i] + D * i, i);
    SparseTable<pll> sl(le), sr(ri);
    UnionFind uf(N);
    ll ans = 0;
    while(uf.size(0) < N){
        set<pii> st; // edge set for merge
        int l = 0;
        // search minimum cost edge for each connected component
        while(l < N){
            int r = l;
            while(r < N and uf.same(l, r)) r++;
            pll lp(INFLL, INF), rq(INFLL, INF), cp(INFLL, INF), cq(INFLL, INF);
            if(0 < l){
                lp = sl.rmq(0, l);
                cp = sr.rmq(l, r);
            }
            if(r < N){
                rq = sr.rmq(r, N);
                cq = sl.rmq(l, r);
            }
            if(lp.first == INFLL and rq.first == INFLL) continue;
            if(lp.first + cp.first < rq.first + cq.first){
                st.emplace(lp.second, cp.second);
            }else{
                st.emplace(rq.second, cq.second);
            }
            l = r;
        }
        // merge
        for(auto& e: st){
            int l = e.first, r = e.second;
            if(uf.same(l, r)) continue;
            uf.unite(l, r);
            ans += D * abs(l - r) + A[l] + A[r];
        }
    }
    cout << ans << endl;

    return 0;
}

