void update(int node, int start, int end, int idx){
    if(start > end || idx < start || end < idx) return;
    if(start == end){
        seg[node][0] = idx;
        seg[node][1] = idx;
        return;
    }
    int mid = (start + end) >> 1;
    update(node << 1, start, mid, idx);
    update(node << 1 | 1, mid + 1, end, idx);
    for(int typ = 0; typ < 2; typ ++){
        if(a[seg[node << 1][typ]][typ] <= a[seg[node << 1 | 1][typ]][typ]){
            seg[node][typ] = seg[node << 1][typ];
        }else{
            seg[node][typ] = seg[node << 1 | 1][typ];
        }
    }
}
int query(int node, int start, int end, int l, int r, int typ){
    if(start > end || r < start || end < l) return 0;
    if(l <= start && end <= r){
        return seg[node][typ];
    }
    int mid = (start + end) >> 1;
    int q1 = query(node << 1, start, mid, l, r, typ);
    int q2 = query(node << 1 | 1, mid + 1, end, l, r, typ);
    if(a[q1][typ] <= a[q2][typ]){
        return q1;
    }else{
        return q2;
    }
}
