inline void maintain(int i){
	for(int j=0;j<4;++j)t[i].m[j]=min(t[i<<1].m[j],t[i<<1|1].m[j]);
	t[i].al=min(min(t[i<<1].al,t[i<<1|1].al),min(F(t[i<<1].m[0],t[i<<1|1].m[3]),
		F(t[i<<1].m[2],t[i<<1|1].m[1])));
}
