namespace T1{
	pa T[800010];
	void build(int l,int r,int rt){
		if (l==r){
			T[rt]=mp(a[l]-1ll*l*D,l);
			return;
		}
		int m=l+r>>1;
		build(l,m,rt<<1);
		build(m+1,r,rt<<1|1);
		T[rt]=min(T[rt<<1],T[rt<<1|1]);
	}
	void upd(int l,int r,int rt,int x,LL y){
		if (l==r){
			T[rt]=mp(y,x);
			return;
		}
		int m=l+r>>1;
		if (x<=m) upd(l,m,rt<<1,x,y);
		else upd(m+1,r,rt<<1|1,x,y);
		T[rt]=min(T[rt<<1],T[rt<<1|1]);
	}
	void que(int l,int r,int rt,int L,int R){
		if (T[rt]>=tmp) return;
		if (l>=L && r<=R){tmp=T[rt];return;}
		int m=l+r>>1;
		if (L<=m) que(l,m,rt<<1,L,R);
		if (R>m) que(m+1,r,rt<<1|1,L,R);
	}
};

