void ins(int x,int tp){
	if (tp==1){
		if (x>1){
			tmp=mp(INF,0);
			T1::que(1,n,1,1,x-1);
			if (tmp.fi>=INF) return;
			tmp.fi+=1ll*x*D+a[x];
			Q.push(node(tmp.fi,tmp.se,x));
		}
	}
	else{
		if (x<n){
			tmp=mp(INF,0);
			T2::que(1,n,1,x+1,n);
			if (tmp.fi>=INF) return;
			tmp.fi+=a[x]-1ll*x*D;
			Q.push(node(tmp.fi,tmp.se,x));
		}
	}
}
