inline void solve(int l, int r)
{
    if(l==r)
        return;
    int m=l+r>>1, pl=-1, pr=-1;
    ll mnl=INF, mnr=INF;
    for(int i=l; i<=m; i++)
    {
        ll vl=A[i]-1LL*D*i;
        if(mnl>vl)
            mnl=vl, pl=i;
    }
    for(int i=m+1; i<=r; i++)
    {
        ll vr=A[i]+1LL*D*i;
        if(mnr>vr)
            mnr=vr, pr=i;
    }
    for(int i=l; i<=m; i++)
    {
        ll vl=A[i]-1LL*D*i;
        e.pb(mp(vl+mnr, mp(i, pr)));
    }
    for(int i=m+1; i<=r; i++)
    {
        ll vr=A[i]+1LL*D*i;
        e.pb(mp(mnl+vr, mp(pl, i)));
    }
    solve(l, m);
    solve(m+1, r);
}

