int pa[maxn],sz[maxn];
struct edge{
    int u,v;
    long long w;
    bool operator <(const edge &x){
        return w<x.w;
    }
    edge(int _u,int _v,long long _w):
        u(_u), v(_v), w(_w) {}
};
int fi(int x){
    return x==pa[x]?x:pa[x]=fi(pa[x]);
}
vector<edge> e;
void kruskal(){
    sort(e.begin(),e.end());
    long long sum=0;
    for(auto j:e){
        int u=fi(j.u),v=fi(j.v);
        if(u==v)continue;
        if(sz[u]<sz[v])swap(u,v);
        sz[u]+=sz[v];
        pa[v]=u;
        sum+=j.w;
    }
    printf("%lld\n",sum);
    exit(0);
}
int n,d,a[maxn];
void dc(int l,int r){
    if(l==r)return;
    int mid=(l+r)>>1;
    dc(l,mid);dc(mid+1,r);
    long long ma=inf,c;
    int idx=-1;
    for(int i=l;i<=mid;i++){
        c=a[i]-1LL*d*i;
        if(c<ma){
            ma=c;
            idx=i;
        }
    }
    int idx2=-1;
    ma=inf;
    for(int i=mid+1;i<=r;i++){
        c=a[i]+1LL*d*i;
        if(c<ma){
            ma=c;
            idx2=i;
        }
    }
    for(int i=l;i<=mid;i++)
        e.push_back(edge(i,idx2,0LL+a[i]+a[idx2]+1LL*d*(idx2-i)));
    for(int i=mid+1;i<=r;i++)
        e.push_back(edge(i,idx,0LL+a[i]+a[idx]+(1LL*d*(i-idx))));
    return;
}

