		up(id);
	}
	void update(ll x,ll l,ll r,ll id)
	{
		if(l==r) 
		{
			tree[id].init();
			tree[id].asmall=make_pair(a[l]-D*l,l);
			tree[id].abig=make_pair(a[l]+D*l,l);
			return ;
		}
		if(x<=mid) update(x,l,mid,lc);
		else update(x,mid+1,r,rc);
		up(id);
	}
	pair<ll,ll> query()
	{
		return tree[1].ans;
	}
}trcyx;
int main()
{
	ll n;scanf("%lld",&n);scanf("%lld",&D);
	memset(a,0x3f,sizeof(a));
	for(ll i=1;i<=n;i++) scanf("%lld",&a[i]);
	trcyx.init(1,nn,1);
	ll ans=0;  
	trcyx.update(1,1,nn,1);
	for(ll i=1;i<n;i++) 
	{
		pair<ll,ll> op=trcyx.query();
		ans+=op.first;//cout<<op.second;
		trcyx.update(op.second,1,nn,1);
	}
	cout<<ans;
	return 0;  
}

#include<cstdio>
