ll voronoi(WeightedGraph<ll>& g){
    using P = pair<ll, pii>;
    priority_queue<
        P,
        vector<P> ,
        greater<P>
    > pq;
    int n = g.size() / 2;
    vector<int> used(2 * n, 0), dist(2 * n, 0);
    int cnt = 1;
    ll ans = 0;
    rep(i, 0, n) pq.push(mp(0, pii(i, -1)));
    while(!pq.empty()){
        auto cur = pq.top(); pq.pop();
        ll v = cur.second.first;
        if(used[v]){
            ll u = cur.second.second;
            if(used[v] > used[u]) ans += dist[v] + cur.first;
            continue;
        }
        used[v] = cnt; cnt++;
        dist[v] = cur.first;
        for(auto uc: g[v]){
            ll u = uc.to;
            ll c = uc.cost;
            pq.emplace(dist[v] + c, pii(u, v));
        }
    }
    return ans;
}

