// F(component-size, belongs) -> vector<(cost, to)>
template<typename T, typename F> T boruvka(int n, F f) {
    vector<int> rev(n), belong(n);
    unionfind uf(n);
    T ret = T();
    while (uf.size(0) != n) {
        int ptr = 0;
        rep(i, n) {
            if (uf.root(i) == i) {
                belong[i] = ptr++;
                rev[belong[i]] = i;
            }
        }
        for (int i = 0; i < n; i++) {
            belong[i] = belong[uf.root(i)];
        }
        auto v = f(ptr, belong);
        bool update = false;
        for (int i = 0; i < ptr; i++) {
            if (~v[i].second && uf.unite(rev[i], rev[v[i].second])) {
                ret += v[i].first;
                update = true;
            }
        }
        if (!update) return -1;
    }
    return ret;
}


