        if (A[i] < mina) {
            mina = A[i];
            minnum = i;
        }
    }
    ll ans = 0;
    ll cost = mina + D;
    PER(i, minnum - 1, -1) {
        ans += cost + A[i];
        cost = min(cost + D, A[i] + D);
    }
    cost = mina + D;
    REP(i, minnum + 1, N) {
        ans += cost + A[i];
        cost = min(cost + D, A[i] + D);
    }
    cout << ans << endl;
}

