class UnionFind{
	vi p,s;
public:
	UnionFind(void){}
	UnionFind(int N){p=vi(N);s=vi(N,1);fr(i,N){p[i]=i;}}
	void extend(int N){
		foor(i,p.size(),N){
			p<<i;
			s<<1;
		}
	}
	int find(int i){
		extend(i);
		return p[i]=p[i]==i?i:find(p[i]);
	}
	void unite(int a,int b){
		extend(a);
		extend(b);
		if((a=find(a))!=(b=find(b))){
			if(s[a]>s[b]){
				swap(a,b);
			}
			s[b]+=s[a];
			p[a]=b;
		}
	}
	void unite(pii p){return unite(p.first,p.second);}
	bool same(int a,int b){
		extend(a);
		extend(b);
		return find(a)==find(b);
	}
	bool same(pii p){return same(p.first,p.second);}
	int size(int x){
		extend(x);
		return s[find(x)];
	}
};
