struct iv {int i,v;};
struct segtree {
    typedef iv T;
    const T DEF = {-1,INF};
    T f(T a, T b) {
        if (a.v <= b.v)
            return a;
        else
            return b;
    }

    int n=1; V<T> t;
    void calc(int i) {t[i] = f(t[2*i], t[2*i+1]);}
    segtree(V<T> a) { // build segtree of vector a
        while (n < S(a)) n *= 2;
        t = V<T>(2*n, DEF); copy(ALL(a), &t[n]);
        for (int i=n; i-->1;) calc(i);
    }
    void modify(int i, T val) { // set position i
        for (t[i+=n] = val; i/=2;) calc(i);
    }
    T query(int l, int r) { // query range [l,r)
        T accL = DEF, accR = DEF;
        for (l+=n, r+=n; l<r; l/=2, r/=2) {
            if (l&1) accL = f(accL, t[l++]);
            if (r&1) accR = f(t[--r], accR);
        }
        return f(accL, accR);
    }
};

