	for (auto &x : A) cin >> x;
	VoronoiMST<int64_t> mst(2*N);
	for (int64_t i = 0; i < N; i++) {
		mst.add_edge(i, i+N, A[i]);
		if (i < N-1)
			mst.add_edge(i+N, i+N+1, D);
	}
	vector<int64_t> st(N);
	iota(st.begin(), st.end(), 0);
	mst.build(st);
	cout << mst.weight() << endl;
}

