  cin >> N >> D;
  vector<long long> A(N), M(N);
  for(int i = 0; i < N; ++i) cin >> A[i];
  vector<Edge> E;
  solve(E,A,D,0);
  reverse(A.begin(), A.end());
  solve(E,A,D,1);
