#define LL long long
using namespace std;
const LL Maxn = 200010;
const LL inf = 1ll<<60; ///
LL n, D, a[Maxn];
LL fa[Maxn];
bool v[Maxn];
pair <LL, LL> seg[Maxn<<2], none;
LL ff(LL x) { return fa[x] == x ? x : fa[x] = ff(fa[x]); }
vector <LL> vec[Maxn];
struct lnode {
	LL x, y, d;
	bool operator<(const lnode &A) const { return d < A.d; }
}lis[Maxn<<1]; LL ll;
pair <LL, LL> _min(pair <LL, LL> x, pair <LL, LL> y) { return x < y ? x : y; }
pair <LL, LL> qry(LL now, LL L, LL R, LL l, LL r) {
	if(l > r) return none;
	if(L == l && R == r) return seg[now];
	LL mid = L+R>>1, lc = now<<1, rc = now<<1|1;
	if(r <= mid) return qry(lc, L, mid, l, r);
	else if(l > mid) return qry(rc, mid+1, R, l, r);
	else return _min(qry(lc, L, mid, l, mid), qry(rc, mid+1, R, mid+1, r));
}
void chg(LL now, LL L, LL R, LL x, LL k) {
	if(L == R){ seg[now].first = k; return; }
	LL mid = L+R>>1, lc = now<<1, rc = now<<1|1;
	if(x <= mid) chg(lc, L, mid, x, k);
	else chg(rc, mid+1, R, x, k);
	seg[now] = _min(seg[lc], seg[rc]);
}
void build_tree1(LL now, LL L, LL R) {
	if(L < R){
		LL mid = L+R>>1, lc = now<<1, rc = now<<1|1;
		build_tree1(lc, L, mid);
		build_tree1(rc, mid+1, R);
		seg[now] = _min(seg[lc], seg[rc]);
	} else {
		seg[now].first = a[L]-L*D;
		seg[now].second = L;
	}
}
void build_tree2(LL now, LL L, LL R) {
	if(L < R){
		LL mid = L+R>>1, lc = now<<1, rc = now<<1|1;
		build_tree2(lc, L, mid);
		build_tree2(rc, mid+1, R);
		seg[now] = _min(seg[lc], seg[rc]);
	} else {
		seg[now].first = a[L]+L*D;
		seg[now].second = L;
	}
}
int main() {
	LL i, j, k;
	scanf("%lld%lld", &n, &D);
	for(i = 1; i <= n; i++) scanf("%lld", &a[i]);
	for(i = 1; i <= n; i++) fa[i] = i;
	none.first = inf; none.second = 0;
	LL sum = n, ans = 0;
	while(sum > 1){
		for(i = 1; i <= n; i++) vec[i].clear();
		for(i = 1; i <= n; i++) vec[ff(i)].push_back(i);
		ll = 0;
		build_tree1(1, 1, n);
		for(i = 1; i <= n; i++){
			if(vec[i].size() == 0) continue;
			for(j = 0; j < vec[i].size(); j++){
				LL x = vec[i][j];
				chg(1, 1, n, x, inf);
			}
			for(j = 0; j < vec[i].size(); j++){
				LL x = vec[i][j];
				pair <LL, LL> p = qry(1, 1, n, 1, x-1);
				if(p.first != inf){
					ll++;
					lis[ll].x = p.second; lis[ll].y = x; lis[ll].d = (x-p.second)*D+a[p.second]+a[x];
				}
			}
			for(j = 0; j < vec[i].size(); j++){
				LL x = vec[i][j];
				chg(1, 1, n, x, a[x]-x*D);
			}
		}
		build_tree2(1, 1, n);
		for(i = 1; i <= n; i++){
			if(vec[i].size() == 0) continue;
			for(j = 0; j < vec[i].size(); j++){
				LL x = vec[i][j];
				chg(1, 1, n, x, inf);
			}
			for(j = 0; j < vec[i].size(); j++){
				LL x = vec[i][j];
				pair <LL, LL> p = qry(1, 1, n, x+1, n);
				if(p.first != inf){
					ll++;
					lis[ll].x = p.second; lis[ll].y = x; lis[ll].d = (p.second-x)*D+a[p.second]+a[x];
				}
			}
			for(j = 0; j < vec[i].size(); j++){
				LL x = vec[i][j];
				chg(1, 1, n, x, a[x]+x*D);
			}
		}
		for(i = 1; i <= n; i++) v[i] = false;
		sort(lis+1, lis+ll+1);
		for(i = 1; i <= ll; i++){
			if(v[ff(lis[i].y)] == true) continue;
			LL fx = ff(lis[i].x), fy = ff(lis[i].y);
			v[ff(lis[i].y)] = true;
			if(fx != fy){
				fa[fx] = fy;
				ans += lis[i].d;
			}
		}
		sum = 0;
		for(i = 1; i <= n; i++) if(fa[i] == i) sum++;
	}
	printf("%lld\n", ans);
	return 0;
}

#include <cstdio>
#include <iostream>
#include <cstring>
#define MN 201000

typedef long long ll;
int fa[MN];
int c1[MN], c2[MN];
int Min[MN];
ll D; int a[MN];
int X[MN], Y[MN];
int x[MN], y[MN];
ll ans = 0;
int bl;
int n;

int Abs(int a) {return a > 0 ? a : -a;}
ll F(int i) {return i ?  i * D + a[i] : 1e18;}
ll G(int i) {return i ? -i * D + a[i] : 1e18;}
ll H(int i, int j) {if(i == 0 || j == 0) return 1e18; return Abs(i - j) * D + a[i] + a[j];}

void add(int *c, int x, int v, int type)
{
	for(int i = x; i <= n; i += i & -i)
	{
		if(!type) if(F(v) < F(c[i])) c[i] = v;
		if( type) if(G(v) < G(c[i])) c[i] = v;
	}
}

int query(int *c, int x, int type)
{
	int ans = 0;
	for(int i = x; i; i -= i & -i)
	{
		if(!type) if(F(c[i]) < F(ans)) ans = c[i];
		if( type) if(G(c[i]) < G(ans)) ans = c[i];
	}
	return ans;
}

int Find(int x) {return fa[x] == x ? x : fa[x] = Find(fa[x]);}

void solve()
{
	memset(x, 0, sizeof x);
	memset(y, 0, sizeof y); 
	memset(c1, 0, sizeof c1);
	memset(c2, 0, sizeof c2);
	memset(Min, 0, sizeof Min);
	for(int i = 1; i <= n; i++)
	{
		int u = Find(i);
		int x = query(c1, u - 1, 1);
		int y = query(c2, n - u, 1);
		if(G(x) > G(y)) x = y;
		if(H(x, i) <= H(Min[i], i)) Min[i] = x;
		add(c1, u, i, 1);
		add(c2, n - u + 1, i, 1);
	}
	memset(c1, 0, sizeof c1);
	memset(c2, 0, sizeof c2);
	for(int i = n; i >= 1; i--)
	{
		int u = Find(i);
		int x = query(c1, u - 1, 0);
		int y = query(c2, n - u, 0);
		if(F(x) > F(y)) x = y;
		if(H(x, i) <= H(Min[i], i)) Min[i] = x;
		add(c1, u, i, 0);
		add(c2, n - u + 1, i, 0);
	}
	for(int i = 1; i <= n; i++)
	{
		int u = Find(i);
		if(H(i, Min[i]) < H(x[u], y[u])) x[u] = i, y[u] = Min[i];
	}
	int tot = 0;
	for(int i = 1; i <= n; i++)
	{
		int u = Find(i);
		++tot; X[tot] = x[u]; Y[tot] = y[u];
	}
	for(int i = 1; i <= tot; i++)
	{
		int x = Find(X[i]), y = Find(Y[i]);
		if(x == y) continue;
		ans += H(X[i], Y[i]);
		fa[x] = y;
		bl--;
	}
}

int main()
{
	scanf("%d%lld", &n, &D);
	for(int i = 1; i <= n; i++) scanf("%d", &a[i]), fa[i] = i;
	bl = n;
	while(bl > 1) solve();
	printf("%lld\n", ans);
}

#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define N 200010
#define INF 0x3f3f3f3f3f3f3f3f
int n, d, a[N];

struct SEG
{
	struct node
	{
		int pos; ll Min;
		node() {} 
		node(int pos, ll Min) : pos(pos), Min(Min) {}
		void init() { pos = -1, Min = INF; }
		node operator + (const node &other) const
		{
			node res = node(-1, INF);
			if (Min < other.Min)
			{
				res.Min = Min;
				res.pos = pos;
			}
			else
			{
				res.Min = other.Min;
				res.pos = other.pos;
			}
			return res;
		}
	}a[N << 2], res;
	void build(int id, int l, int r)
	{
		a[id].init();
		if (l == r) 
		{
			a[id].pos = l;
			return;
		}
		int mid = (l + r) >> 1;
		build(id << 1, l, mid);
		build(id << 1 | 1, mid + 1, r);
	}
	void update(int id, int l, int r, int pos, ll val)
	{
		if (l == r)
		{
			a[id].Min = val;
			return;
		}
		int mid = (l + r) >> 1;
		if (pos <= mid) update(id << 1, l, mid, pos, val);
		else update(id << 1 | 1, mid + 1, r, pos, val);
		a[id] = a[id << 1] + a[id << 1 | 1];
	}
	void query(int id, int l, int r, int ql, int qr)
	{
		if (qr < ql) return;
		//printf("%d %d %d %d\n", l, r, ql, qr);
		if (l >= ql && r <= qr) 
		{
			res = res + a[id];
			return;
		}
		int mid = (l + r) >> 1;
		if (ql <= mid) query(id << 1, l, mid, ql, qr);
		if (qr > mid) query(id << 1 | 1, mid + 1, r, ql, qr);
	}
}seg[2];

struct node
{
	ll v; int x, y;
	node() {}
	node (int x, int y, ll v) : x(x), y(y), v(v) {}
	bool operator < (const node &other) const { return v > other.v; }
};

priority_queue <node> pq;
void add(int x)
{
	for (int i = 0; i < 2; ++i) seg[i].res.init();
	seg[0].query(1, 1, n, 1, x - 1);
	seg[1].query(1, 1, n, x + 1, n);
	if (seg[0].res.Min == INF && seg[1].res.Min == INF) return; 
	ll tmpl = 1ll * a[x] + 1ll * x * d + seg[0].res.Min;
	ll tmpr = 1ll * a[x] - 1ll * x * d + seg[1].res.Min;
	if (tmpl < tmpr) pq.push(node(x, seg[0].res.pos, tmpl));
	else pq.push(node(x, seg[1].res.pos, tmpr)); 
}
int vis[N];

int main()
{
	while (scanf("%d%d", &n, &d) != EOF)
	{
		for (int i = 1; i <= n; ++i) scanf("%d", a + i);
		for (int i = 0; i < 2; ++i) seg[i].build(1, 1, n);
		for (int i = 1; i <= n; ++i)
		{
			seg[0].update(1, 1, n, i, 1ll * a[i] - 1ll * i * d);
			seg[1].update(1, 1, n, i, 1ll * a[i] + 1ll * i * d);
		}
		ll res = 0; 
		memset(vis, 0, sizeof vis);
		vis[1] = 1;
		seg[1].res.init();
		seg[1].query(1, 1, n, 2, n);
		while (!pq.empty()) pq.pop();
		pq.push(node(1, seg[1].res.pos, 1ll * a[1] - d + seg[1].res.Min));
		seg[0].update(1, 1, n, 1, INF);
		seg[1].update(1, 1, n, 1, INF);
		int cnt = 1;
		while (cnt < n)
		{
			node top = pq.top(); pq.pop();
			int x = top.x, y = top.y;
			if (vis[y] == 0) 
			{
				res += top.v;
				vis[y] = 1;
				++cnt;
				seg[0].update(1, 1, n, y, INF);
				seg[1].update(1, 1, n, y, INF);
				add(y);
			}
			add(x); 
		}
		printf("%lld\n", res);
	}
	return 0;
}

