template <int N> struct DSU {
    int fa[N], dep[N];
    list<int> el[N];
    void init() {
        for (int i = 0; i < N; i++)
            el[i].push_back(i);
        iota(fa, fa + N, 0);
        fill(dep, dep + N, 1);
    }
    int seek(int x) { return fa[x] == x ? x : fa[x] = seek(fa[x]); }
    bool merge(int a, int b) {
        // cout << "merge" << ' ' << a << ' ' << b << endl;
        int f1 = seek(a), f2 = seek(b);
        if (f1 != f2) {
            if (dep[f1] < dep[f2]) {
                fa[f1] = f2;
                el[f2].splice(el[f2].end(), el[f1]);
            } else if (dep[f1] > dep[f2]) {
                fa[f2] = f1;
                el[f1].splice(el[f1].end(), el[f2]);
            } else {
                fa[f1] = f2;
                el[f2].splice(el[f2].end(), el[f1]);
                dep[f2]++;
            }
            return true;
        } else {
            return false;
        }
    }
    DSU() { init(); }
};
