    vector<ll> cost1(n);
    vector<ll> cost2(n);
    for (int i = 0; i < n; i++) {
        cin >> V[i];
        cost1[i] = i * d + V[i];
        cost2[i] = -i * d + V[i];
    }
    seg1.build(cost1);
    seg2.build(cost2);
    ll ans = 0;
    while (true) {
        set<int> st;
        for (int i = 0; i < n; i++)
            st.insert(dsu.seek(i));
        if (st.size() == 1)
            break;
        vector<pair<ll, int>> dis(n, make_pair(INF, -1));
        for (int i : st) {
            for (auto j : dsu.el[i]) {
                seg1.upd(j, seg1.ID);
                seg2.upd(j, seg2.ID);
            }
            for (int j : dsu.el[i]) {
                auto cost1 = seg1.query(j + 1, n);
                cost1.first += -j * d + V[j];
                dis[i] = min(dis[i], cost1);

                auto cost2 = seg2.query(0, j - 1);
                cost2.first += j * d + V[j];
                dis[i] = min(dis[i], cost2);
            }
            for (auto j : dsu.el[i]) {
                seg1.upd(j, make_pair(cost1[j], j));
                seg2.upd(j, make_pair(cost2[j], j));
            }
        }
        for (int i : st) {
            if (dis[i].second != -1) {
                int fa1 = dsu.seek(i);
                int fa2 = dsu.seek(dis[i].second);
                if (fa1 != fa2) {
                    dsu.merge(fa1, fa2);
                    ans += dis[i].first;
                }
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

