    void input() {
        cin >> N;
        cin >> D;
        A.resize(N);
        rep(i, 0, N) cin >> A[i];
    }

    void add_edge() {
        int pt = 0;
        ll ecost = A[pt] + D;

        for (int i = 1; i < N; ++i) {
            if (ecost < A[i - 1] + D) {
//                edges.emplace_back(pt, i, );
            } else {
                pt = i - 1;
                ecost = A[pt] + D;
            }
            edges.emplace_back(pt, i, A[i] + ecost);
            ecost += D;
        }

        pt = N - 1;
        ecost = A[pt] + D;

        for (int i = N - 2; i >= 0; --i) {
            if (ecost < A[i + 1] + D) {

            } else {
                pt = i + 1;
                ecost = A[pt] + D;
            }
            edges.emplace_back(pt, i, A[i] + ecost);
            ecost += D;
        }
    }


    void solve() {
        input();
        add_edge();

        UnionFind uf(N);

        sort(all(edges), [](edge a, edge b) {
