  while (cin >> N >> D) {
    vector<ll> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    map<ll, int> num;
    {
      for (ll x : A) num[x] = 0;
      int id = 0;
      for (auto& e : num) e.snd = id++;
    }
    vector<Edge> edges;
    auto op = [&](const P& a, const P& b) {
      return min(a, b);
    };
    SegmentTree<P> segL(N, op, P(INF, -1));
    for (int i = 0; i < N; i++) {
      int x = num[A[i]];
      auto p = segL.query(0, x + 1);
      if (p.snd >= 0) {
        edges.push_back(Edge{i, p.snd, p.fst + i * D + A[i]});
      }
      segL.update(x, P(-i * D + A[i], i));
    }
    SegmentTree<P> segR(N, op, P(INF, -1));
    for (int i = N - 1; i >= 0; i--) {
      int x = num[A[i]];
      auto p = segR.query(0, x + 1);
      if (p.snd >= 0) {
        edges.push_back(Edge{i, p.snd, p.fst - i * D + A[i]});
      }
      segR.update(x, P(i * D + A[i], i));
    }
    ll res = minimumSpanningTree(N, edges);
    cout << res << endl;
  }
  return 0;
}

