  rep(i,n){ cin>>a[i]; }

  VoronoiMST<ll> vo(a);
  for(int i=1; i<n; i++){ vo.add_edge(i-1,i,d); }
  auto G = vo.build();

  Kruskal<ll> ks(n);
  for(int v=0; v<n; v++){
    for(auto e:G[v]){
      int u=e.F; ll c=e.S;
      if(v<u){ ks.add_edge(v,u,c); }
    }
  }
  ll ans=ks.build();
  cout << ans << endl;
  return 0;
}

