        lf[i] = mn + msk;

        ll msked = a[i] - msk;
        if (msked < mn) {
            mn = msked;
        }
    }

    mn = oo;
    msk = 0;

    for (int i = n - 1; i >= 0; --i) {
        if (i + 1 != n) msk += d;

        rf[i] = mn + msk;

        ll msked = a[i] - msk;
        if (msked < mn) {
            mn = msked;
        }
    }

    for (int i = 1; i + 1 < n; ++i) {
        ll plus = min(lf[i], rf[i]);
        ll minus = a[i];
        if (minus > plus) ans += plus - minus;
    }
    cout << ans;
}

