typedef int32_t i32;
typedef int64_t i64;

typedef struct edge {
  i32 a, b;
  i64 c;
} edge;

int cmp (const void *a, const void *b) {
  i64 d = ((edge *)a)->c - ((edge *)b)->c;
  return d == 0 ? 0 : d < 0 ? -1 : 1;
}

void build (const i32 *a, const i32 l, const i32 r, const i32 d, heap * const h) {
  if (r - l <= 1) return;
  i32 m = (l + r) / 2;
  build (a, l, m, d, h);
  build (a, m, r, d, h);
  i32 min = l;
  for (i32 i = l + 1; i < m; ++i) {
    i64 x = (i64) d * (i - min) + a[min];
    i64 y = a[i];
    if (x > y) {
      min = i;
    }
  }
  for (i32 i = m; i < r; ++i) {
    push (h, &((edge){min, i, (i64) d * (i - min) + a[min] + a[i]}));
  }
  min = r - 1;
  for (i32 i = r - 2; i >= m; --i) {
    i64 x = (i64) d * (min - i) + a[min];
    i64 y = a[i];
    if (x > y) {
      min = i;
    }
  }
  for (i32 i = m - 1; i >= l; --i) {
    push (h, &((edge){i, min, (i64) d * (min - i) + a[min] + a[i]}));
  }
}

void run (void) {
  i32 n, d;
  scanf ("%" SCNi32 "%" SCNi32, &n, &d);
