}

void enumerate(int *a,int l,int r,int d,heap *h){
  if(r-l<=1) return;
  int m=(l+r)/2;
  enumerate(a,l,m,d,h);
  enumerate(a,m,r,d,h);
  int64 cost=a[l]+d;
  int index=l;
  int i;
  for(i=l+1;i<m;i++){
    if(cost>a[i]){
      cost=a[i];
      index=i;
    }
    cost+=d;
  }
  for(i=m;i<r;i++){
    push(h,&((edge){index,i,cost+a[i]}));
    cost+=d;
  }
  cost=a[r-1]+d;
  index=r-1;
  for(i=r-2;i>=m;i--){
    if(cost>a[i]){
      cost=a[i];
      index=i;
    }
    cost+=d;
  }
  for(i=m-1;i>=l;i--){
    push(h,&((edge){index,i,cost+a[i]}));
    cost+=d;
  }
}

