} segment_node;

void func_segment_node (void *c, const void *a, const void *b) {
  const segment_node *p = (const segment_node *)a;
  const segment_node *q = (const segment_node *)b;
  *(segment_node *)c = p->val < q->val ? *p : *q;
}

