} edge;

int cmp_edge (const void *a, const void *b) {
  i64 d = ((edge *)a)->c - ((edge *)b)->c;
  return d == 0 ? 0 : d < 0 ? -1 : 1;
}

void run (void) {
  i32 n, d;
  scanf ("%" SCNi32 "%" SCNi32, &n, &d);
  i32 *a = (i32 *) calloc (n, sizeof (i32));
  index_val *p = (index_val *) calloc (n, sizeof (index_val));
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, a + i);
    p[i] = (index_val){i, a[i]};
  }
  qsort (p, n, sizeof (index_val), cmp_index_val);
  const segment_node ini = {n, (i64)(n + 2) * 1000000000 + 1};
  segment_tree *l = new_segment_tree (&ini, n, sizeof (segment_node), func_segment_node);
  segment_tree *r = new_segment_tree (&ini, n, sizeof (segment_node), func_segment_node);
  for (i32 i = 0; i < n; ++i) {
    update_tmp (l, i, &((segment_node){i, a[i] + (i64)(n - 1 - i) * d}));
    update_tmp (r, i, &((segment_node){i, a[i] + (i64)i * d}));
  }
  update_all (l);
  update_all (r);
  edge *e = (edge *) calloc (2 * n, sizeof (edge));
  i32 len = 0;
  for (i32 i = 0; i < n; ++i) {
    i32 v = p[i].index;
    if (v > 0) {
      segment_node t;
      find (l, 0, v, &t);
      e[len++] = (edge){v, t.index, p[i].val + t.val - (i64) (n - 1 - v) * d};
    }
    if (v + 1 < n) {
      segment_node t;
      find (r, v + 1, n, &t);
      e[len++] = (edge){v, t.index, p[i].val + t.val - (i64) v * d};
    }
    update (l, v, &ini);
    update (r, v, &ini);
  }
  qsort (e, len, sizeof (edge), cmp_edge);
  i64 sum = 0;
  UnionFind *u = newUnionFind (n);
  for (i32 i = 0; i < len; ++i) {
    if (same (u, e[i].a, e[i].b)) continue;
    unite (u, e[i].a, e[i].b);
    sum += e[i].c;
  }
  printf ("%" PRIi64 "\n", sum);
}

