//i番目の値をxに更新する
void update(int i, seg_tree_valtype val, seg_tree *t){
	if(i < 0 || t->n <= i){
		printf("In function 'update':\nrefered out of array\n");
	}
	i += t->N - 1;
	t->dat[i] = val;
	while(i > 0){
		i = (i - 1) / 2;
		t->dat[i] = (t->f)(t->dat[2 * i + 1], t->dat[2 * i + 2]);
	}
}

seg_tree_valtype query_sub(int a, int b, int k, int l, int r, seg_tree *t){
	if(r <= a || b <= l){
		return t->e;
	}
	else if(a <= l && r <= b){
		return t->dat[k];
	}
	else{
		int h = (l + r) / 2;
		seg_tree_valtype vl = query_sub(a, b, 2 * k + 1, l, h, t);
		seg_tree_valtype vr = query_sub(a, b, 2 * k + 2, h, r, t);
		return (t->f)(vl, vr);
	}
}

