      //printf("%lld %lld %lld\n",g[i].st,g[i].fi,g[i].val);
      r+=g[i].val;
      c++;
      uni(g[i].st,g[i].fi);
      if(c==n-1){break;}
    }
    printf("%lld\n",r);
    return 0;
}

#include<stdio.h>
