#include<inttypes.h>

typedef struct UnionFind {
  int32_t *parent;
  int32_t size;
} UnionFind;

void initUnionFind (UnionFind *u) {
  for (int32_t i = 0; i < u->size; ++i){
    u->parent[i] = -1;
  }
}

UnionFind* newUnionFind (const int32_t size) {
  UnionFind *u = (UnionFind *) calloc (1, sizeof (UnionFind));
  u->parent = (int32_t *) calloc (size, sizeof (int32_t));
  u->size = size;
  initUnionFind (u);
  return u;
}

void freeUnionFind (UnionFind *u) {
  free (u->parent);
  free (u);
}

int32_t root (UnionFind *u, int32_t x) {
  if (u->parent[x] < 0) return x;
  return u->parent[x] = root (u, u->parent[x]);
}

int same (UnionFind *u, int32_t x, int32_t y) {
  return root (u, x) == root (u, y);
}

int32_t getSize(UnionFind *u, int32_t x) {
  return - (u->parent[root (u, x)]);
}

void unite(UnionFind *u, int32_t x, int32_t y) {
  x = root (u, x);
  y = root (u, y);
  if (x == y) return;
  if (u->parent[x] > u->parent[y]) {
    int32_t swap = x;
    x = y;
    y = swap;
  }
  u->parent[x] += u->parent[y];
  u->parent[y] = x;
}

typedef struct binaryHeap{
  void *array;
  size_t heap_size;
  size_t max_size;
  size_t val_size;
  int (*cmp) (const void *, const void *);
} heap;

heap* new_binary_heap (const size_t val_size, int (*cmpF) (const void *, const void *)) {
  heap *h = (heap *) calloc (1, sizeof (heap));
  h->array = malloc (val_size * (1 + 1));
  h->heap_size = 0;
  h->max_size = 1;
  h->val_size = val_size;
  h->cmp = cmpF;
  return h;
}

static inline void heap_func_swap (void * restrict a, void * restrict b, size_t val_size) {
  if ((val_size & 7) == 0) {
    uint64_t *p = (uint64_t *) a;
    uint64_t *q = (uint64_t *) b;
    val_size /= sizeof (uint64_t);
    while (val_size--) {
      uint64_t tmp = *p;
      *p++ = *q;
      *q++ = tmp;
    }
  } else {
    uint8_t *p = (uint8_t *) a;
    uint8_t *q = (uint8_t *) b;
    while (val_size--) {
      uint8_t tmp = *p;
      *p++ = *q;
      *q++ = tmp;
    }
  }
}

static inline void heap_func_copy (void * restrict dst, const void * restrict src, size_t val_size) {
  if ((val_size & 7) == 0) {
    uint64_t *p = (uint64_t *) src;
    uint64_t *q = (uint64_t *) dst;
    val_size /= sizeof (uint64_t);
    while (val_size--) {
      *q++ = *p++;
    }
  } else {
    uint8_t *p = (uint8_t *) src;
    uint8_t *q = (uint8_t *) dst;
    while (val_size--) {
      *q++ = *p++;
    }
  }
}

void push (heap *h, const void *val) {
  if (h->heap_size == h->max_size) {
    h->max_size = 2 * h->max_size + 1;
    h->array = realloc (h->array, h->val_size * (h->max_size + 1));
  }
  h->heap_size++;
  uint8_t *array = (uint8_t *) h->array;
  size_t k = h->heap_size;
  const size_t val_size = h->val_size;
  int (*cmp) (const void *, const void *) = h->cmp;
  heap_func_copy(array + k * val_size, val, val_size);
  while (k > 1) {
    size_t parent = k / 2;
    if (cmp (array + parent * val_size, array + k * val_size) <= 0) {
      return;
    }
    heap_func_swap (array + parent * val_size, array + k * val_size, val_size);
    k = parent;
  }
}

void pop (heap *h, void *res) {
  uint8_t *array = (uint8_t *) h->array;
  const size_t val_size = h->val_size;
  if (res != NULL) {
    heap_func_copy (res, array + val_size, val_size);
  }
  heap_func_copy (array + val_size, array + val_size * h->heap_size, val_size);
  h->heap_size--;
  int (* const cmp) (const void *, const void *) = h->cmp;
  const size_t n = h->heap_size;
  size_t k = 1;
  while (2 * k  + 1 <= n) {
    int c = cmp (array + val_size * 2 * k, array + val_size * (2 * k + 1));
    size_t next = 2 * k + (c <= 0 ? 0 : 1);
    if (cmp (array + val_size * k, array + val_size * next) <= 0) return;
    heap_func_swap (array + val_size * k, array + val_size * next, val_size);
    k = next;
  }
  if (2 * k <= n && cmp (array + val_size * k, array + val_size * 2 * k) > 0) {
    heap_func_swap (array + val_size * k, array + val_size * 2 * k, val_size);
  }
}

typedef int32_t i32;
typedef int64_t i64;

typedef struct edge {
  i32 a, b;
  i64 c;
} edge;

int cmp (const void *a, const void *b) {
  i64 d = ((edge *)a)->c - ((edge *)b)->c;
  return d == 0 ? 0 : d < 0 ? -1 : 1;
}

void build (const i32 *a, const i32 l, const i32 r, const i32 d, heap * const h) {
  if (r - l <= 1) return;
  i32 m = (l + r) / 2;
  build (a, l, m, d, h);
  build (a, m, r, d, h);
  i64 cost = a[l];
  i32 min = l;
  for (i32 i = l + 1; i < m; ++i) {
    cost += d;
    i64 y = a[i];
    if (cost > y) {
      cost = y;
      min = i;
    }
  }
  for (i32 i = m; i < r; ++i) {
    cost += d;
    push (h, &((edge){min, i, cost + a[i]}));
  }
  cost = a[r - 1];
  min = r - 1;
  for (i32 i = r - 2; i >= m; --i) {
    cost += d;
    i64 y = a[i];
    if (cost > y) {
      cost = y;
      min = i;
    }
  }
  for (i32 i = m - 1; i >= l; --i) {
    cost += d;
    push (h, &((edge){i, min, cost + a[i]}));
  }
}

void run (void) {
  i32 n, d;
  scanf ("%" SCNi32 "%" SCNi32, &n, &d);
  i32 *a = (i32 *) calloc (n, sizeof (i32));
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, a + i);
  }
  heap *h = new_binary_heap (sizeof (edge), cmp);
  build (a, 0, n, d, h);
  UnionFind *u = newUnionFind (n);
  i64 sum = 0;
  i32 cnt = n - 1;
  while (cnt > 0) {
    edge e;
    pop (h, &e);
    if (same (u, e.a, e.b)) continue;
    sum += e.c;
    unite (u, e.a, e.b);
    cnt--;
  }
  printf ("%" PRIi64 "\n", sum);
}

int main (void) {
  run ();
  return 0;
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Queue;

public class Main {

	public static void main(String... args) throws IOException {

		// 標準入力を取得
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line = br.readLine();
		int N = Integer.parseInt(line.split(" ")[0]);
		int D = Integer.parseInt(line.split(" ")[1]);

		List<String> strs = Arrays.asList(br.readLine().split(" "));
		List<Integer> aList = new ArrayList<Integer>();
		List<Integer> aListIndexKey = new ArrayList<Integer>();

		for (int i = 0; i < strs.size(); i++) {
			aList.add(Integer.parseInt(strs.get(i)));
			aListIndexKey.add(Integer.parseInt(strs.get(i)));
		}

		// 計算済みコストをキャッシュ
		Map<String, Integer> cacheCosts = new HashMap<String, Integer>();

		// 2次元目には、接続元ノード, 接続先ノード, コストが格納される
		List<Edge>[] edgeList = new List[N];
		for (int i = 0; i < N; i++) {
			edgeList[i] = new ArrayList<Edge>();
		}

		// 橋一覧（島インデックス:島インデックス）
		List<String> bridgeList = new ArrayList<String>();

		// 全島を走査
		int size = aList.size();
		for (int i = 0; i < size; i++) {

			// 最小コストを初期化
			int minCost = 0;
			int minIndex = 0;

			// 自分の島より左側の島たちのみ処理
			for (int j = 0; j < i; j++) {

				// 最小コストかを判断
				Integer cost = cacheCosts.get(j + ":" + i);
				if (cost == null) {
					cost = Math.abs(i - j) * D + aListIndexKey.get(i) + aListIndexKey.get(j);
					cacheCosts.put(j + ":" + i, cost);
					cacheCosts.put(i + ":" + j, cost);
				}

				// 既知最小コスト以下の場合は最小コストに設定
				if (minCost == 0 || minCost > cost) {
					minCost = cost;
					minIndex = j;
				}
			}

			// 既に橋一覧に登録されていたら無視
			if (i != minIndex && !bridgeList.contains(minIndex + ":" + i)) {

				// 橋一覧に追加
				bridgeList.add(minIndex + ":" + i);
				edgeList[i].add(new Edge(i, minIndex, minCost));
				edgeList[minIndex].add(new Edge(minIndex, i, minCost));
			}

			// 自分の島より右側の島たちのみ処理
			for (int j = i + 1; j < size; j++) {

				// 最小コストかを判断
				Integer cost = cacheCosts.get(i + ":" + j);
				if (cost == null) {
					cost = Math.abs(i - j) * D + aListIndexKey.get(i) + aListIndexKey.get(j);
					cacheCosts.put(i + ":" + j, cost);
					cacheCosts.put(j + ":" + i, cost);
				}

				// 既知最小コスト以下の場合は最小コストに設定
				if (minCost == 0 || minCost > cost) {
					minCost = cost;
					minIndex = j;
				}
			}

			// 既に橋一覧に登録されていたら無視
			if (i != minIndex && !bridgeList.contains(i + ":" + minIndex)) {

				// 橋一覧に追加
				bridgeList.add(i + ":" + minIndex);
				edgeList[i].add(new Edge(i, minIndex, minCost));
				edgeList[minIndex].add(new Edge(minIndex, i, minCost));
			}
		}

		int ans = prim(N, edgeList);
		System.out.println(ans); //最小全域木の重み
	}

	//プリム法[最小全域木(Minimum Spannig Tree)]
	static int prim(int n, List<Edge>[] edges) {
		boolean[] done = new boolean[n]; //訪問フラグ

		Queue<Edge> q = new PriorityQueue<Edge>();
		q.add(new Edge(0, 0, 0)); //０から(ダミー)

		int totalCost = 0; //最小全域木の重み
		while (!q.isEmpty()) {
			Edge e = q.poll(); //最小コストの辺を取り出す
			if (done[e.target]) {
				continue;
			}

			done[e.target] = true; //訪問済にする
			totalCost += e.cost;
			q.addAll(edges[e.target]); //隣接しているすべての辺を追加
		}

		return totalCost;
	}
}

//辺情報の構造体
class Edge implements Comparable<Edge> {
	public int source = 0; //接続元ノード
	public int target = 0; //接続先ノード
	public int cost = 0; //重み

	public Edge(int source, int target, int cost) {
		this.source = source;
		this.target = target;
		this.cost = cost;
	}

	@Override
	public int compareTo(Edge o) {
		return this.cost - o.cost;
	}

	@Override
	public String toString() { //デバッグ用
		return "source = " + source + ", target = " + target + ", cost = " + cost;
	}
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static class Edge
	{
		int x, y;
		long c;
		static int[] a;
		static long D;

		public Edge(int x, int y)
		{
			this.x = x; this.y = y; this.c = cost(x, y, a, D);
		}
	}

	static void solve()
	{
		int n = ni(), D = ni();
		int[] a = na(n);
		Edge.a = a;
		Edge.D = D;
		Edge[] res = dfs(0, n, a, D);
		long ans = 0;
		for(Edge e : res){
			ans += e.c;
		}
		out.println(ans);
	}

	static Edge[] dfs(int l, int r, int[] a, long D)
	{
		if(r-l <= 1)return new Edge[0];
		int h = l+r>>1;
		// [l,h), [h,r)

		long min = Long.MAX_VALUE;
		int argr =-1;
		for(int i = h;i < r;i++){
			long oc = a[i] + (i-h)*D;
			if(oc < min){
				min = oc;
				argr = i;
			}
		}

		long minl = Long.MAX_VALUE;
		int argl = -1;
		for(int i = l;i < h;i++){
			long v = (h-i)*D + a[i];
			if(v < minl){
				minl = v;
				argl = i;
			}
		}

		Edge[] es = new Edge[(r-l)*2];
		int p = 0;

		for(int i = h;i < r;i++){
			es[p++] = new Edge(argl, i);
		}
		for(int i = l;i < h;i++){
			es[p++] = new Edge(i, argr);
		}

		Edge[] les = dfs(l, h, a, D);
		Edge[] res = dfs(h, r, a, D);

		for(Edge e : les)es[p++] = e;
		for(Edge e : res)es[p++] = e;

		es = Arrays.copyOf(es, p);
		Arrays.sort(es, new Comparator<Edge>() {
			public int compare(Edge x, Edge y) {
				return Long.compare(x.c, y.c);
			}
		});

		DJSet ds = new DJSet(r-l);
		Edge[] ret = new Edge[r-l-1];
		int rp = 0;
		for(Edge e : es){
			if(!ds.union(e.x-l, e.y-l)){
				ret[rp++] = e;
			}
		}
		assert rp == ret.length;
		return ret;
	}

	static long cost(int x, int y, int[] a, long D)
	{
		return Math.abs(x-y)*D + a[x]+a[y];
	}

		public static class DJSet {
			public int[] upper;

			public DJSet(int n) {
				upper = new int[n];
				Arrays.fill(upper, -1);
			}

			public int root(int x) {
				return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
			}

			public boolean equiv(int x, int y) {
				return root(x) == root(y);
			}

			public boolean union(int x, int y) {
				x = root(x);
				y = root(y);
				if (x != y) {
					if (upper[y] < upper[x]) {
						int d = x;
						x = y;
						y = d;
					}
					upper[x] += upper[y];
					upper[y] = x;
				}
				return x == y;
			}

			public int count() {
				int ct = 0;
				for (int u : upper)
					if (u < 0)
						ct++;
				return ct;
			}
		}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

