    public class Prim {
        protected final static int INF = 1_000_000_000;

        class State implements Comparable<State> {
            int x, y;

            State(int x, int y) {
                this.x = x;
                this.y = y;
            }

            public int compareTo(State s) {
                int c1 = edge[x][y], c2 = edge[s.x][s.y];
                if (c1 < c2) return -1;
                else if (c1 > c2) return 1;
                else return 0;
            }
        }

        int[][] edge;

        Prim(int[][] edge) {
            this.edge = edge;
        }

        PrimResult doit() {
            int n = edge.length;
            PrimResult res = new PrimResult(n);

            UnionFindTree uft = new UnionFindTree(n);
            PriorityQueue<State> pq = new PriorityQueue<State>();

            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                    pq.add(new State(i, j));

            while (!pq.isEmpty()) {
                State s = pq.poll();
                if (uft.same(s.x, s.y)) continue;

                uft.unite(s.x, s.y);
                res.sum += edge[s.x][s.y];
                res.connected[s.x].add(s.y);
                res.connected[s.y].add(s.x);
            }

            return res;
        }
    }

    class PrimResult {
        ArrayList<Integer>[] connected;
        int sum;

        @SuppressWarnings("unchecked")
        PrimResult(int n) {
            connected = new ArrayList[n];
            for (int i = 0; i < n; i++)
                connected[i] = new ArrayList<Integer>();
        }
    }
