    public static class UnionFind{  
        int parent[];
        int rank[];

        public UnionFind(int n){
            parent = new int[n];
            rank   = new int[n];

            for(int i = 0;i < n;i++){
                parent[i] = i;
                rank[i]   = 0;
            }        
        }

        boolean same(int x,int y){
            return find(x) == find(y);
        }

        public int find(int x){
            if(parent[x] == x){
               return x;
            }else{
               return parent[x] = find(parent[x]);   
            }        
        }

        public void union(int x,int y){
            x = find(x);
            y = find(y);

            if(x != y){
                if(rank[x] > rank[y]){
                   parent[y] = x; 
                }else{
                   parent[x] = y;
                   if(rank[x] == rank[y]){
                       rank[y]++;
                   }
                }            
            }

            return;
        }

        public int count(int n){
            int ret = 0;
            for(int i = 0;i < n;i++){
                if(i == find(i)){
                    ret++;
                }
            }
            return ret;
        }

      } 

    void candidate_edges(int s, int t, long[] a, long d){
        if(t<=s) return;
        int mid = (s+t)/2;
        int id = -1;
        long dist = inf;
        for(int i = mid+1; i <= t; i++){
            long tmp = Math.abs(i-s)*d + a[i] + a[s];
            if(tmp<=dist){
                dist = tmp;
                id = i;
            }
        }
        for(int i = s; i <= mid; i++){
            edge.add(new int[]{i,id});
        }
        id = -1;
        dist = inf;
        for(int i = s; i <= mid; i++){
            long tmp = Math.abs(i-t)*d + a[i] + a[t];
            if(tmp<=dist){
                dist = tmp;
                id = i;
            }
        }
        for(int i = mid+1; i <= t; i++){
            edge.add(new int[]{i,id});
        }
        candidate_edges(s,mid,a,d);
        candidate_edges(mid+1,t,a,d);
    }

