    for (int i = 0; i < n; i++) {
      long min = I;
      int minj = -1;
      for (int j = 0; j < n; j++) {
        if (d[j] < min && !done[j]) {
          min = d[j];
          minj = j;
        }
      }
      if (minj == -1)
        break;
      done[minj] = true;
      for (int j = 0; j < n; j++) {
        long len = Math.abs(minj - j) * D + a[minj] + a[j];
        if (!done[j] && len < d[j]) {
          d[j] = len;
        }
      }
    }

    long ret = 0;
    for (int i = 0; i < n; i++) {
      ret += d[i];
    }
    return ret;
  }


