        }

    }
    static class Segment implements Cloneable {
        private Segment left;
        private Segment right;
        private long a;
        private long b = (long) 1e18;
        private long min = a + b;
        private int index;

        private void kill() {
            a = (long) 1e18;
            min = a + b;
        }

        public void updateB(long x) {
            b = Math.min(b, x);
            if (a + b < min) {
                min = a + b;
                if (left != null) {
                    if (a == left.a) {
                        index = left.index;
                    } else {
                        index = right.index;
                    }
                }
            }
        }

        public void pushUp() {
            min = Math.min(left.min, right.min);
            a = Math.min(left.a, right.a);
            if (min == left.min) {
                index = left.index;
            } else {
                index = right.index;
            }
        }

        public void pushDown() {
            left.updateB(b);
            right.updateB(b);
        }

        public Segment(int l, int r, long[] a) {
            if (l < r) {
                int m = (l + r) >> 1;
                left = new Segment(l, m, a);
                right = new Segment(m + 1, r, a);
                pushUp();
            } else {
                this.a = a[l];
                this.min = this.a + b;
                index = l;
            }
        }

        private boolean covered(int ll, int rr, int l, int r) {
            return ll <= l && rr >= r;
        }

        private boolean noIntersection(int ll, int rr, int l, int r) {
            return ll > r || rr < l;
        }

        public void update(int ll, int rr, int l, int r, long x) {
            if (noIntersection(ll, rr, l, r)) {
                return;
            }
            if (covered(ll, rr, l, r)) {
                updateB(x);
                return;
            }
            pushDown();
            int m = (l + r) >> 1;
            left.update(ll, rr, l, m, x);
            right.update(ll, rr, m + 1, r, x);
            pushUp();
        }

        public void kill(int ll, int rr, int l, int r) {
            if (noIntersection(ll, rr, l, r)) {
                return;
            }
            if (covered(ll, rr, l, r)) {
                kill();
                return;
            }
            pushDown();
            int m = (l + r) >> 1;
            left.kill(ll, rr, l, m);
            right.kill(ll, rr, m + 1, r);
            pushUp();
        }

        public void query(int ll, int rr, int l, int r, Recorder ans) {
            if (noIntersection(ll, rr, l, r)) {
                return;
            }
            if (covered(ll, rr, l, r)) {
                ans.add(min, index);
                return;
            }
            pushDown();
            int m = (l + r) >> 1;
            left.query(ll, rr, l, m, ans);
            right.query(ll, rr, m + 1, r, ans);
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
}

import java.io.*;
import java.util.*;
import java.util.function.BinaryOperator;
import java.util.function.Function;
import java.util.function.IntFunction;

public class Main {

    static int N, D;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        D = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static City INF = new City(-1, Long.MAX_VALUE);

    static long solve() {
        // 解説のやりかた
        // 各都市の左右一つを選んでクラスカル法
        BinaryOperator<City> merge = (a, b) -> a.cost < b.cost ? a : b;
        RangeGetObj<City> lseg = new RangeGetObj<>(N, INF, merge, City[]::new);
        for (int i = 0; i < N; i++) {
            long cost = (long)D * (N-i-1) + A[i];
            lseg.update(i, new City(i, cost));
        }
        RangeGetObj<City> rseg = new RangeGetObj<>(N, INF, merge, City[]::new);
        for (int i = 0; i < N; i++) {
            long cost = (long)D * i + A[i];
            rseg.update(i, new City(i, cost));
        }

        PriorityQueue<Road> q = new PriorityQueue<>(Comparator.comparingLong(r -> r.cost));

        // Aが大きいもの順に実行
        //   Aより小さいもの、という制限がついている
        int[][] B = new int[N][2];
        for (int i = 0; i < N; i++) {
            B[i][0] = i;
            B[i][1] = A[i];
        }
        Arrays.sort(B, Comparator.comparingInt(b -> -b[1]));
        for (int bi = 0; bi < N; bi++) {
            int i = B[bi][0];
            int a = B[bi][1];

            City lc = lseg.query(0, i);
            if( lc != INF ) {
                q.add( new Road(i, lc.i, cost(i, lc.i)) );
            }
            City rc = rseg.query(i+1, N);
            if( rc != INF ) {
                q.add( new Road(i, rc.i, cost(i, rc.i)) );
            }

            lseg.update(i, INF);
            rseg.update(i, INF);
        }

        UnionFind uf = new UnionFind(N);

        int cnt = 0;
        long ans = 0;
        while(true) {
            Road road = q.poll();
            if( !uf.isSame(road.from, road.to) ) {
                uf.unite(road.from, road.to);
                ans += road.cost;
                cnt++;

                if( cnt == N-1 ) {
                    break;
                }
            }
        }
        return ans;
    }

    static long cost(int a, int b) {
        return (long)A[a] + A[b] + (long)Math.abs(a-b) * D;
    }

    static class City {
        int i;
        long cost;

        public City(int i, long cost) {
            this.i = i;
            this.cost = cost;
        }

        public String toString() {
            return "City(" + i + ", " + cost + ")";
        }
    }

    static class Road {
        int from, to;
        long cost;

        public Road(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
    }

    static class RangeGetObj<A> {

        int size;
        A[] tree;
        A identity;
        BinaryOperator<A> merge;

        RangeGetObj(int size, A identity, BinaryOperator<A> merge, IntFunction<A[]> mkArr) {
            this.size = 1;
            while( this.size < size ) this.size *= 2;
            this.tree = mkArr.apply(this.size*2);
            this.identity = identity;
            this.merge = merge;
            Arrays.fill(tree, identity);
        }

        void update(int idx, A a) {
            idx += size;
            tree[idx] = a;

            while(idx > 0) {
                idx /= 2;
                tree[idx] = merge.apply(tree[idx*2], tree[idx*2+1]);
            }
        }

        // [from, to)
        A query(int from, int to) {
            return _query(from, to, 1, 0, size);
        }

        private A _query(int from, int to, int idx, int l, int r) {
            if (r <= from || to <= l) return identity;

            if (from <= l && r <= to) {
                return tree[idx];

            } else {
                int mid = (l+r)/2;
                A vl = _query(from, to, idx*2, l, mid);
                A vr = _query(from, to, idx*2+1, mid, r);
                return merge.apply(vl, vr);
            }
        }

        A get(int idx) {
            return tree[idx+size];
        }
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int root(int i) {
            if( parent[i] == i ) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if( ri == rj ) return ri;

            if( rank[ri] < rank[rj] ) {
                parent[ri] = rj;
                return rj;

            } else {
                parent[rj] = ri;
                if( rank[ri] == rank[rj] ) {
                    rank[ri]++;
                }
                return ri;
            }
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

