/**
 * メインクラス
 * @author Yuichiro.Yamashita
 *
 */
public class Main {

	/**
	 * メインメソッド
	 * @param args
	 * @throws IOException
	 */
	public static void main(String[] args) throws IOException {

		// ============================================================
		// 標準入力を変数に設定
		// ============================================================

		// 標準入力を取得
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] line = br.readLine().split(" ");

		// 都市数 N
		int n = Integer.parseInt(line[0]);

		// 建設コスト算出で使用する係数 D
		int d = Integer.parseInt(line[1]);

		// 各都市の建設コスト
		line = br.readLine().split(" ");
		long[] a = new long[line.length];
		for (int i = 0; i < line.length; i++) {
			a[i] = Integer.parseInt(line[i]);
		}

		// ============================================================
		// メイン処理
		// ============================================================

		// Union-Find木を初期化
		UnionFindTree unionFindTree = new UnionFindTree(n);

		// 回答を初期化
		long answer = 0;

		// 全てのノードが接続されるまでループ
		while (unionFindTree.size(0) != n) {
			long[] val1 = new long[n + 2];
			long[] val2 = new long[n + 2];
			long[] valL = new long[n + 2];
			long[] valR = new long[n + 2];
			Arrays.fill(valL, Long.MAX_VALUE / 2);
			Arrays.fill(valR, Long.MAX_VALUE / 2);
			Arrays.fill(val1, Long.MAX_VALUE / 2);
			Arrays.fill(val2, Long.MAX_VALUE / 2);
			int[] indexL = new int[n + 2];
			int[] indexR = new int[n + 2];
			for (int i = 0; i < n; i++) {
				if (valL[unionFindTree.root(i) + 1] > a[i] - i * d) {
					valL[unionFindTree.root(i) + 1] = a[i] - i * d;
					indexL[unionFindTree.root(i) + 1] = i;
				}
				if (valR[unionFindTree.root(i) + 1] > a[i] + i * d) {
					valR[unionFindTree.root(i) + 1] = a[i] + i * d;
					indexR[unionFindTree.root(i) + 1] = i;
				}
				val1[unionFindTree.root(i) + 1] = Math.min(val1[unionFindTree.root(i) + 1], a[i] + i * d);
				val2[unionFindTree.root(i) + 1] = Math.min(val2[unionFindTree.root(i) + 1], a[i] - i * d);
			}

			int[] minL = new int[n + 2];
			int[] minR = new int[n + 2];

			for (int i = 1; i <= n; i++) {
				minL[i] = valL[minL[i - 1]] >= valL[i] ? i : minL[i - 1];
			}

			minR[n + 1] = n + 1;
			for (int i = n; i >= 1; i--) {
				minR[i] = valR[minR[i + 1]] >= valR[i] ? i : minR[i + 1];
			}

			for (int i = 1; i <= n; i++) {
				if (unionFindTree.root(i - 1) != i - 1)
					continue;
				long cl = valL[minL[i - 1]] + val1[i];
				long cr = valR[minR[i + 1]] + val2[i];
				if (cl <= cr) {
					if (!unionFindTree.same(i - 1, minL[i - 1] - 1)) {
						answer += cl;
						unionFindTree.union(i - 1, minL[i - 1] - 1);
					}
				} else {
					if (!unionFindTree.same(i - 1, minR[i + 1] - 1)) {
						answer += cr;
						unionFindTree.union(i - 1, minR[i + 1] - 1);
					}
				}
			}
		}

		// ============================================================
		// 結果出力
		// ============================================================

		// 結果出力
		System.out.println(answer);
	}
}

/**
 * Union-Find木
 * @author Yuichiro.Yamashita
 *
 */
class UnionFindTree {

	// ノードの親ノードを格納する変数
	// 但し自らが親ノードの場合はその配下に接続されたノード数を負数で保持
	private int[] data;

	/**
	 * コンストラクタ
	 * @param size
	 */
	public UnionFindTree(final int size) {
		data = new int[size];
		clear();
	}

	/**
	 * 全てのデータを初期化
	 * ※全ノードを根とする
	 * ※根ノードについてはその配下にあるノード数を負数で管理するため
	 * ※値に -1 を設定する
	 */
	public void clear() {
		Arrays.fill(data, -1);
	}

	/**
	 * ルートノードを取得
	 * @param x
	 * @return
	 */
	public int root(final int x) {

		// 負数を保持している場合は自らがルートノード
		if (data[x] < 0) {
			return x;

			// それ以外の場合はルートノードを検索して返却
		} else {
			return root(data[x]);
		}
	}

	/**
	 * ノードの結合を実施
	 * @param x
	 * @param y
	 */
	public void union(int x, int y) {

		// 引数の根を取得
		x = root(x);
		y = root(y);

		// 根が異なる場合
		if (x != y) {

			// 根のインデックスが小さいノードをルートに設定する
			if (data[y] < data[x]) {
				final int t = x;
				x = y;
				y = t;
			}

			// xに接続されているノード数を負の数で表現
			data[x] += data[y];

			// yの親ノードをxに設定
			data[y] = x;
		}
	}

	/**
	 * xとyが同じ木に属しているかを判定
	 * @param x
	 * @param y
	 * @return
	 */
	public boolean same(final int x, final int y) {
		return root(x) == root(y);
	}

	/**
	 * xに接続されているノード数を返却
	 * @param x
	 * @return
	 */
	public int size(int x) {

		// 接続ノード数は負数で表現されているため 符号変換して返却
		return -data[root(x)];
	}
}

import java.io.*;
import java.util.*;
import java.util.function.BinaryOperator;
import java.util.function.Function;
import java.util.function.IntFunction;

public class Main {

    static int N, D;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        D = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static City INF = new City(-1, Long.MAX_VALUE);

    static long solve() {
        // 解説のやりかた
        // 各都市の左右一つを選んでクラスカル法
        BinaryOperator<City> merge = (a, b) -> a.cost < b.cost ? a : b;
        RangeGetObj<City> lseg = new RangeGetObj<>(N, INF, merge, City[]::new);
        for (int i = 0; i < N; i++) {
            long cost = D * (N-i-1) + A[i];
            lseg.update(i, new City(i, cost));
        }
        RangeGetObj<City> rseg = new RangeGetObj<>(N, INF, merge, City[]::new);
        for (int i = 0; i < N; i++) {
            long cost = D * i + A[i];
            rseg.update(i, new City(i, cost));
        }

        PriorityQueue<Road> q = new PriorityQueue<>(Comparator.comparingLong(r -> r.cost));

        // Aが大きいもの順に実行
        //   Aより小さいもの、という制限がついている
        int[][] B = new int[N][2];
        for (int i = 0; i < N; i++) {
            B[i][0] = i;
            B[i][1] = A[i];
        }
        Arrays.sort(B, Comparator.comparingInt(b -> -b[1]));
        for (int bi = 0; bi < N; bi++) {
            int i = B[bi][0];
            int a = B[bi][1];

            City lc = lseg.query(0, i);
            if( lc != INF ) {
                q.add( new Road(i, lc.i, cost(i, lc.i)) );
            }
            City rc = rseg.query(i+1, N);
            if( rc != INF ) {
                q.add( new Road(i, rc.i, cost(i, rc.i)) );
            }

            lseg.update(i, INF);
            rseg.update(i, INF);
        }

        UnionFind uf = new UnionFind(N);

        int cnt = 0;
        long ans = 0;
        while(true) {
            Road road = q.poll();
            if( !uf.isSame(road.from, road.to) ) {
                uf.unite(road.from, road.to);
                ans += road.cost;
                cnt++;

                if( cnt == N-1 ) {
                    break;
                }
            }
        }
        return ans;
    }

    static Road cheapest(int i, RangeGetObj<City> lseg, RangeGetObj<City> rseg) {
        City lCity = lseg.query(0, i);
        City rCity = rseg.query(i+1, N);

        Road lRoad = lCity == INF ? null : new Road(i, lCity.i, cost(i, lCity.i));
        Road rRoad = rCity == INF ? null : new Road(i, rCity.i, cost(i, rCity.i));

        if( lRoad != null && rRoad != null ) {
            return lRoad.cost < rRoad.cost ? lRoad : rRoad;
        } else if( lRoad != null ) {
            return lRoad;
        } else {
            return rRoad;
        }
    }

    static long cost(int a, int b) {
        return (long)A[a] + A[b] + (long)Math.abs(a-b) * D;
    }

    static class City {
        int i;
        long cost;

        public City(int i, long cost) {
            this.i = i;
            this.cost = cost;
        }

        public String toString() {
            return "City(" + i + ", " + cost + ")";
        }
    }

    static class Road {
        int from, to;
        long cost;

        public Road(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
    }

    static class RangeGetObj<A> {

        int size;
        A[] tree;
        A identity;
        BinaryOperator<A> merge;

        RangeGetObj(int size, A identity, BinaryOperator<A> merge, IntFunction<A[]> mkArr) {
            this.size = 1;
            while( this.size < size ) this.size *= 2;
            this.tree = mkArr.apply(this.size*2);
            this.identity = identity;
            this.merge = merge;
            Arrays.fill(tree, identity);
        }

        void update(int idx, A a) {
            idx += size;
            tree[idx] = a;

            while(idx > 0) {
                idx /= 2;
                tree[idx] = merge.apply(tree[idx*2], tree[idx*2+1]);
            }
        }

        // [from, to)
        A query(int from, int to) {
            return _query(from, to, 1, 0, size);
        }

        private A _query(int from, int to, int idx, int l, int r) {
            if (r <= from || to <= l) return identity;

            if (from <= l && r <= to) {
                return tree[idx];

            } else {
                int mid = (l+r)/2;
                A vl = _query(from, to, idx*2, l, mid);
                A vr = _query(from, to, idx*2+1, mid, r);
                return merge.apply(vl, vr);
            }
        }

        A get(int idx) {
            return tree[idx+size];
        }
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int root(int i) {
            if( parent[i] == i ) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if( ri == rj ) return ri;

            if( rank[ri] < rank[rj] ) {
                parent[ri] = rj;
                return rj;

            } else {
                parent[rj] = ri;
                if( rank[ri] == rank[rj] ) {
                    rank[ri]++;
                }
                return ri;
            }
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int d = sc.nextInt();
		Map<Integer,Integer> cityMap = new HashMap<Integer,Integer>();

		for(int i = 0; i < n; i++) {
			cityMap.put(i, sc.nextInt());
		}

		List<Entry<Integer,Integer>> cityList = new ArrayList<Entry<Integer,Integer>>(cityMap.entrySet());

		Collections.sort(cityList, new Comparator<Entry<Integer,Integer>>() {
			public int compare(Entry<Integer,Integer> obj1, Entry<Integer,Integer> obj2) {
					return obj1.getValue().compareTo(obj2.getValue());
			}
		});

		// 確定した一番左のインデックス
		int lIndex = cityList.get(0).getKey();
		// ここより左側に橋を架けるとき基準にするべきインデックス
		int minIndex = cityList.get(0).getKey();
		// ここより右側に橋を架けるとき基準にするべきインデックス
		int maxIndex = cityList.get(0).getKey();
		// 確定した一番右のインデックス
		int uIndex = cityList.get(0).getKey();

		Map<Integer, Integer> keepMinMaxMap = new HashMap<Integer, Integer>();
		int amt = 0;
		for(int i = 1; i < n; i++) {
			Entry<Integer, Integer> cityE = cityList.get(i);
			int index = cityE.getKey();
			int value = cityE.getValue();
			if (index < lIndex) {
				int minIndexValue = cityMap.get(minIndex);
				int far = minIndex - index;
				if(value - minIndexValue > far * d) {
					// 全部minIdexから！
					for(int j = lIndex - 1; j >= index; j--) {
						if(keepMinMaxMap.containsKey(j)) {
							minIndex = keepMinMaxMap.get(j);
							minIndexValue = cityMap.get(minIndex);
						}
						int minFar = minIndex - j;
						amt += minFar * d + cityMap.get(j) + minIndexValue;
					}
				} else {
					// いい感じの位置を探す
					int evenFar = (value - minIndexValue) / d;
					// これから先でkeyから先はvalueがminIndexになる
					int key;
					if( (value - minIndexValue) % d == 0 && evenFar != 0) {
						key = evenFar;
					} else {
						key = evenFar + 1;
					}
					keepMinMaxMap.put(index - key, index);
					int keepIndex = index;
					for(int j = lIndex - 1; j > index; j--) {
						if(keepMinMaxMap.containsKey(j)) {
							minIndex = keepMinMaxMap.get(j);
							minIndexValue = cityMap.get(minIndex);
						}
						int jValue = cityMap.get(j);
						int minFar = minIndex - j;
						int currentFar = j - index;
						int keepVal = 0;
						if(evenFar <= minFar - currentFar) {
							// ここから
							amt += currentFar * d + jValue + value;
							// minとつなぐところを変えたほうがいいか
							int diff = (currentFar * d) - jValue;
							if(diff > 0 && diff > keepVal) {
								keepVal = diff;
								keepIndex = j;
							}
						} else {
							// minから
							amt += minFar * d + jValue + minIndexValue;
						}
					}
					// min～をつなぐためにつなぐところ決め
					if(keepIndex == index && keepMinMaxMap.containsKey(keepIndex)) {
						minIndex = keepMinMaxMap.get(keepIndex);
						minIndexValue = cityMap.get(minIndex);
					}
					amt += (minIndex - keepIndex) * d + cityMap.get(keepIndex) + minIndexValue;
				}
				lIndex = index;
			} else if(uIndex < index) {
				int maxIndexValue = cityMap.get(maxIndex);
				int far = index - maxIndex;
				if(value - maxIndexValue > far * d) {
					// 全部maxIdexから！
					for(int j = uIndex + 1; j <= index; j++) {
						if(keepMinMaxMap.containsKey(j)) {
							maxIndex = keepMinMaxMap.get(j);
							maxIndexValue = cityMap.get(maxIndex);
						}
						int maxFar = j - maxIndex;
						amt += maxFar * d + cityMap.get(j) + maxIndexValue;
					}
				} else {
					// いい感じの位置を探す
					int evenFar = (value - maxIndexValue) / d;
					// これから先でkeyから先はvalueがmaxIndexになる
					int key;
					if ((value - maxIndexValue) % d == 0 && evenFar != 0) {
						key = evenFar;
					} else {
						key = evenFar + 1;
					}
					keepMinMaxMap.put(index + key, index);
					int keepIndex = index;
					for(int j = uIndex + 1; j < index; j++) {
						if(keepMinMaxMap.containsKey(j)) {
							maxIndex = keepMinMaxMap.get(j);
							maxIndexValue = cityMap.get(maxIndex);
						}
						int jValue = cityMap.get(j);
						int maxFar = j - maxIndex;
						int currentFar = index - j;
						int keepVal = 0;
						if(evenFar <= maxFar - currentFar) {
							// ここから
							amt += currentFar * d + jValue + value;
							// maxとつなぐところを変えたほうがいいか
							int diff = (currentFar * d) - jValue;
							if(diff > 0 && diff > keepVal) {
								keepVal = diff;
								keepIndex = j;
							}
						} else {
							// minから
							amt += maxFar * d + jValue + maxIndexValue;
						}
					}
					// max～をつなぐためにつなぐところ決め
					if(keepIndex == index && keepMinMaxMap.containsKey(keepIndex)) {
						maxIndex = keepMinMaxMap.get(keepIndex);
						maxIndexValue = cityMap.get(maxIndex);
					}
					amt += (keepIndex - maxIndex) * d + cityMap.get(keepIndex) + maxIndexValue;
				}
				uIndex = index;
			} else {
				// minとmaxの間はもう決まってる
				continue;
			}

			if(lIndex == 0 && uIndex == n) {
				break;
			}
		}

		System.out.println(amt);

	}
}

import java.io.OutputStream;
