import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static class Edge
	{
		int x, y;
		long c;
		static int[] a;
		static long D;

		public Edge(int x, int y)
		{
			this.x = x; this.y = y; this.c = cost(x, y, a, D);
		}
	}

	static void solve()
	{
		int n = ni(), D = ni();
		int[] a = na(n);
		Edge.a = a;
		Edge.D = D;
		Edge[] res = dfs(0, n, a, D);
		long ans = 0;
		for(Edge e : res){
			ans += e.c;
		}
		out.println(ans);
	}

	static Edge[] dfs(int l, int r, int[] a, long D)
	{
		if(r-l <= 1)return new Edge[0];
		int h = l+r>>1;
		// [l,h), [h,r)

		long min = Long.MAX_VALUE;
		int argr =-1;
		for(int i = h;i < r;i++){
			long oc = a[i] + (i-h)*D;
			if(oc < min){
				min = oc;
				argr = i;
			}
		}

		long minl = Long.MAX_VALUE;
		int argl = -1;
		for(int i = l;i < h;i++){
			long v = (h-i)*D + a[i];
			if(v < minl){
				minl = v;
				argl = i;
			}
		}

		Edge[] es = new Edge[(r-l)*2];
		int p = 0;

		for(int i = h;i < r;i++){
			es[p++] = new Edge(argl, i);
		}
		for(int i = l;i < h;i++){
			es[p++] = new Edge(i, argr);
		}

		Edge[] les = dfs(l, h, a, D);
		Edge[] res = dfs(h, r, a, D);
		for(Edge e : les)es[p++] = e;
		for(Edge e : res)es[p++] = e;

		mergesort(es, 0, p);

		DJSet ds = new DJSet(r-l);
		Edge[] ret = new Edge[r-l-1];
		int rp = 0;
		for(int i = 0;i < p;i++){
			Edge e = es[i];
			if(!ds.union(e.x-l, e.y-l)){
				ret[rp++] = e;
			}
		}
		assert rp == ret.length;
		return ret;
	}

	private static Edge[] stemp = new Edge[400005];

	public static void mergesort(Edge[] a, int s, int e)
	{
		if(e - s <= 1)return;
		int h = s+e>>1;
		mergesort(a, s, h);
		mergesort(a, h, e);
		int p = 0;
		int i= s, j = h;
		for(;i < h && j < e;)stemp[p++] = a[i].c < a[j].c ? a[i++] : a[j++];
		while(i < h)stemp[p++] = a[i++];
		while(j < e)stemp[p++] = a[j++];
		System.arraycopy(stemp, 0, a, s, e-s);
	}

	static long cost(int x, int y, int[] a, long D)
	{
		return Math.abs(x-y)*D + a[x]+a[y];
	}

		public static class DJSet {
			public int[] upper;

			public DJSet(int n) {
				upper = new int[n];
				Arrays.fill(upper, -1);
			}

			public int root(int x) {
				return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
			}

			public boolean equiv(int x, int y) {
				return root(x) == root(y);
			}

			public boolean union(int x, int y) {
				x = root(x);
				y = root(y);
				if (x != y) {
					if (upper[y] < upper[x]) {
						int d = x;
						x = y;
						y = d;
					}
					upper[x] += upper[y];
					upper[y] = x;
				}
				return x == y;
			}

			public int count() {
				int ct = 0;
				for (int u : upper)
					if (u < 0)
						ct++;
				return ct;
			}
		}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
