public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            TaskE solver = new TaskE();
            solver.solve(1, in, out);
            out.close();
        }
    }
    static class TaskE {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            long d = in.readInt();
            long[] a = new long[n + 1];
            long[] leftCost = new long[n + 1];
            long[] rightCost = new long[n + 1];
            for (int i = 1; i <= n; i++) {
                a[i] = in.readInt();
                leftCost[i] = a[i] - i * d;
                rightCost[i] = a[i] + i * d;
            }

            Segment left = new Segment(1, n, leftCost);
            Segment right = new Segment(1, n, rightCost);

            left.update(1, 1, 1, n, -leftCost[1]);


            long ans = 0;
            for (int i = 1; i <= n; i++) {
                Recorder forLeft = new Recorder();
                Recorder forRight = new Recorder();
                left.query(1, n, 1, n, forLeft);
                right.query(1, n, 1, n, forRight);

                if (forLeft.val > forRight.val) {
                    Recorder tmp = forLeft;
                    forLeft = forRight;
                    forRight = tmp;
                }

                ans += forLeft.val;
                left.kill(forLeft.index, forLeft.index, 1, n);
                right.kill(forLeft.index, forLeft.index, 1, n);
                left.update(1, forLeft.index - 1, 1, n, rightCost[forLeft.index]);
                right.update(forLeft.index + 1, n, 1, n, leftCost[forLeft.index]);
            }

            out.println(ans);
        }

    }
    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(long c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }
    static class Segment implements Cloneable {
        private Segment left;
        private Segment right;
        private long a;
        private long b = (long) 1e18;
        private long min = a + b;
        private int index;
        private int minAIndex;

        private void kill() {
            a = (long) 1e18;
            min = a + b;
        }

        public void updateB(long x) {
            b = Math.min(b, x);
            if (a + b < min) {
                min = a + b;
                if (left != null) {
                    if (a == left.a) {
                        index = left.minAIndex;
                    } else {
                        index = right.minAIndex;
                    }
                }
            }
        }

        public void pushUp() {
            min = Math.min(left.min, right.min);
            a = Math.min(left.a, right.a);
            if (min == left.min) {
                index = left.index;
            } else {
                index = right.index;
            }
            if (a == left.a) {
                minAIndex = left.minAIndex;
            } else {
                minAIndex = right.minAIndex;
            }
        }

        public void pushDown() {
            left.updateB(b);
            right.updateB(b);
        }

        public Segment(int l, int r, long[] a) {
            if (l < r) {
                int m = (l + r) >> 1;
                left = new Segment(l, m, a);
                right = new Segment(m + 1, r, a);
                pushUp();
            } else {
                this.a = a[l];
                this.min = this.a + b;
                minAIndex = index = l;
            }
        }

        private boolean covered(int ll, int rr, int l, int r) {
            return ll <= l && rr >= r;
        }

        private boolean noIntersection(int ll, int rr, int l, int r) {
            return ll > r || rr < l;
        }

        public void update(int ll, int rr, int l, int r, long x) {
            if (noIntersection(ll, rr, l, r)) {
                return;
            }
            if (covered(ll, rr, l, r)) {
                updateB(x);
                return;
            }
            pushDown();
            int m = (l + r) >> 1;
            left.update(ll, rr, l, m, x);
            right.update(ll, rr, m + 1, r, x);
            pushUp();
        }

        public void kill(int ll, int rr, int l, int r) {
            if (noIntersection(ll, rr, l, r)) {
                return;
            }
            if (covered(ll, rr, l, r)) {
                kill();
                return;
            }
            pushDown();
            int m = (l + r) >> 1;
            left.kill(ll, rr, l, m);
            right.kill(ll, rr, m + 1, r);
            pushUp();
        }

        public void query(int ll, int rr, int l, int r, Recorder ans) {
            if (noIntersection(ll, rr, l, r)) {
                return;
            }
            if (covered(ll, rr, l, r)) {
                ans.add(min, index);
                return;
            }
            pushDown();
            int m = (l + r) >> 1;
            left.query(ll, rr, l, m, ans);
            right.query(ll, rr, m + 1, r, ans);
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
    static class Recorder {
        long val;
        int index;
        {
            prepare();
        }

        public void prepare() {
            val = (long) 1e18;
            index = -1;
        }

        public void add(long v, int i) {
            if (v < val) {
                val = v;
                index = i;
            }
        }

        public String toString() {
            return String.format("%d=%d", index, val);
        }

    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int d = sc.nextInt();
		Map<Integer,Integer> cityMap = new HashMap<Integer,Integer>();

		for(int i = 0; i < n; i++) {
			cityMap.put(i, sc.nextInt());
		}

		List<Entry<Integer,Integer>> cityList = new ArrayList<Entry<Integer,Integer>>(cityMap.entrySet());

		Collections.sort(cityList, new Comparator<Entry<Integer,Integer>>() {
			public int compare(Entry<Integer,Integer> obj1, Entry<Integer,Integer> obj2) {
					return obj1.getValue().compareTo(obj2.getValue());
			}
		});

		// 確定した一番左のインデックス
		int lIndex = cityList.get(0).getKey();
		// ここより左側に橋を架けるとき基準にするべきインデックス
		int minIndex = cityList.get(0).getKey();
		// ここより右側に橋を架けるとき基準にするべきインデックス
		int maxIndex = cityList.get(0).getKey();
		// 確定した一番右のインデックス
		int uIndex = cityList.get(0).getKey();

		Map<Integer, Integer> keepMinMaxMap = new HashMap<Integer, Integer>();
		long amt = 0;
		for(int i = 1; i < n; i++) {
			Entry<Integer, Integer> cityE = cityList.get(i);
			int index = cityE.getKey();
			int value = cityE.getValue();
			if (index < lIndex) {
				int minIndexValue = cityMap.get(minIndex);
				int far = minIndex - index;
				if(value - minIndexValue > far * d) {
					// 全部minIdexから！
					for(int j = lIndex - 1; j >= index; j--) {
						if(keepMinMaxMap.containsKey(j)) {
							minIndex = keepMinMaxMap.get(j);
							minIndexValue = cityMap.get(minIndex);
						}
						int minFar = minIndex - j;
						amt += minFar * d + cityMap.get(j) + minIndexValue;
					}
				} else {
					// いい感じの位置を探す
					int evenFar = (value - minIndexValue) / d;
					// これから先でkeyから先はvalueがminIndexになる
					int key;
					if( (value - minIndexValue) % d == 0 && evenFar != 0) {
						key = evenFar;
					} else {
						key = evenFar + 1;
					}
					keepMinMaxMap.put(index - key, index);
					int keepIndex = index;
					for(int j = lIndex - 1; j > index; j--) {
						if(keepMinMaxMap.containsKey(j)) {
							minIndex = keepMinMaxMap.get(j);
							minIndexValue = cityMap.get(minIndex);
						}
						int jValue = cityMap.get(j);
						int minFar = minIndex - j;
						int currentFar = j - index;
						int keepVal = 0;
						if(evenFar <= minFar - currentFar) {
							// ここから
							amt += currentFar * d + jValue + value;
							// minとつなぐところを変えたほうがいいか
							int diff = (currentFar * d) - jValue;
							if(diff > 0 && diff > keepVal) {
								keepVal = diff;
								keepIndex = j;
							}
						} else {
							// minから
							amt += minFar * d + jValue + minIndexValue;
						}
					}
					// min～をつなぐためにつなぐところ決め
					if(keepMinMaxMap.containsKey(keepIndex)) {
						minIndex = keepMinMaxMap.get(keepIndex);
						minIndexValue = cityMap.get(minIndex);
					}
					amt += (minIndex - keepIndex) * d + cityMap.get(keepIndex) + minIndexValue;
				}
				lIndex = index;
			} else if(uIndex < index) {
				int maxIndexValue = cityMap.get(maxIndex);
				int far = index - maxIndex;
				if(value - maxIndexValue > far * d) {
					// 全部maxIdexから！
					for(int j = uIndex + 1; j <= index; j++) {
						if(keepMinMaxMap.containsKey(j)) {
							maxIndex = keepMinMaxMap.get(j);
							maxIndexValue = cityMap.get(maxIndex);
						}
						int maxFar = j - maxIndex;
						amt += maxFar * d + cityMap.get(j) + maxIndexValue;
					}
				} else {
					// いい感じの位置を探す
					int evenFar = (value - maxIndexValue) / d;
					// これから先でkeyから先はvalueがmaxIndexになる
					int key;
					if ((value - maxIndexValue) % d == 0 && evenFar != 0) {
						key = evenFar;
					} else {
						key = evenFar + 1;
					}
					keepMinMaxMap.put(index + key, index);
					int keepIndex = index;
					for(int j = uIndex + 1; j < index; j++) {
						if(keepMinMaxMap.containsKey(j)) {
							maxIndex = keepMinMaxMap.get(j);
							maxIndexValue = cityMap.get(maxIndex);
						}
						int jValue = cityMap.get(j);
						int maxFar = j - maxIndex;
						int currentFar = index - j;
						int keepVal = 0;
						if(evenFar <= maxFar - currentFar) {
							// ここから
							amt += currentFar * d + jValue + value;
							// maxとつなぐところを変えたほうがいいか
							int diff = (currentFar * d) - jValue;
							if(diff > 0 && diff > keepVal) {
								keepVal = diff;
								keepIndex = j;
							}
						} else {
							// minから
							amt += maxFar * d + jValue + maxIndexValue;
						}
					}
					// max～をつなぐためにつなぐところ決め
					if(keepIndex == index && keepMinMaxMap.containsKey(keepIndex)) {
						maxIndex = keepMinMaxMap.get(keepIndex);
						maxIndexValue = cityMap.get(maxIndex);
					}
					amt += (keepIndex - maxIndex) * d + cityMap.get(keepIndex) + maxIndexValue;
				}
				uIndex = index;
			} else {
				// minとmaxの間はもう決まってる
				continue;
			}

			if(lIndex == 0 && uIndex == n) {
				break;
			}
		}

		System.out.println(amt);

	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Queue;

public class Main {

	public static void main(String... args) throws IOException {

		// 標準入力を取得
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line = br.readLine();
		int N = Integer.parseInt(line.split(" ")[0]);
		int D = Integer.parseInt(line.split(" ")[1]);

		List<String> strs = Arrays.asList(br.readLine().split(" "));
		List<Integer> aList = new ArrayList<Integer>();
		List<Integer> aListIndexKey = new ArrayList<Integer>();

		for (int i = 0; i < strs.size(); i++) {
			aList.add(Integer.parseInt(strs.get(i)));
			aListIndexKey.add(Integer.parseInt(strs.get(i)));
		}

		// 計算済みコストをキャッシュ
		Map<String, Integer> cacheCosts = new HashMap<String, Integer>();

		// 2次元目には、接続元ノード, 接続先ノード, コストが格納される
		List<Edge>[] edgeList = new List[N];
		for (int i = 0; i < N; i++) {
			edgeList[i] = new ArrayList<Edge>();
		}

		// 橋一覧（島インデックス:島インデックス）
		List<String> bridgeList = new ArrayList<String>();

		// 全島を走査
		int size = aList.size();
		for (int i = 0; i < size; i++) {

			// 最小コストを初期化
			int minCost = 0;
			int minIndex = 0;

			// 自分の島より左側の島たちのみ処理
			for (int j = 0; j < i; j++) {

				// 最小コストかを判断
				Integer cost = cacheCosts.get(j + ":" + i);
				if (cost == null) {
					cost = Math.abs(i - j) * D + aListIndexKey.get(i) + aListIndexKey.get(j);
					cacheCosts.put(j + ":" + i, cost);
				}

				// 既知最小コスト以下の場合は最小コストに設定
				if (minCost == 0 || minCost > cost) {
					minCost = cost;
					minIndex = j;
				}
			}

			// 既に橋一覧に登録されていたら無視
			if (i != minIndex && !bridgeList.contains(minIndex + ":" + i)) {

				// 橋一覧に追加
				bridgeList.add(minIndex + ":" + i);
				edgeList[i].add(new Edge(i, minIndex, minCost));
				edgeList[minIndex].add(new Edge(minIndex, i, minCost));
			}

			// 自分の島より右側の島たちのみ処理
			for (int j = i + 1; j < size; j++) {

				// 最小コストかを判断
				Integer cost = cacheCosts.get(i + ":" + j);
				if (cost == null) {
					cost = Math.abs(i - j) * D + aListIndexKey.get(i) + aListIndexKey.get(j);
					cacheCosts.put(i + ":" + j, cost);
					cacheCosts.put(j + ":" + i, cost);
				}

				// 既知最小コスト以下の場合は最小コストに設定
				if (minCost == 0 || minCost > cost) {
					minCost = cost;
					minIndex = j;
				}
			}

			// 既に橋一覧に登録されていたら無視
			if (i != minIndex && !bridgeList.contains(i + ":" + minIndex)) {

				// 橋一覧に追加
				bridgeList.add(i + ":" + minIndex);
				edgeList[i].add(new Edge(i, minIndex, minCost));
				edgeList[minIndex].add(new Edge(minIndex, i, minCost));
			}
		}

		int ans = prim(N, edgeList);
		System.out.println(ans); //最小全域木の重み
	}

	//プリム法[最小全域木(Minimum Spannig Tree)]
	static int prim(int n, List<Edge>[] edges) {
		boolean[] done = new boolean[n]; //訪問フラグ

		Queue<Edge> q = new PriorityQueue<Edge>();
		q.add(new Edge(0, 0, 0)); //０から(ダミー)

		int totalCost = 0; //最小全域木の重み
		while (!q.isEmpty()) {
			Edge e = q.poll(); //最小コストの辺を取り出す
			if (done[e.target]) {
				continue;
			}

			done[e.target] = true; //訪問済にする
			totalCost += e.cost;
			q.addAll(edges[e.target]); //隣接しているすべての辺を追加
		}

		return totalCost;
	}
}

//辺情報の構造体
class Edge implements Comparable<Edge> {
	public int source = 0; //接続元ノード
	public int target = 0; //接続先ノード
	public int cost = 0; //重み

	public Edge(int source, int target, int cost) {
		this.source = source;
		this.target = target;
		this.cost = cost;
	}

	@Override
	public int compareTo(Edge o) {
		return this.cost - o.cost;
	}

	@Override
	public String toString() { //デバッグ用
		return "source = " + source + ", target = " + target + ", cost = " + cost;
	}
}

import java.util.Arrays;

public class Main {
  private static void solve() {
    int n = ni();
    long d = ni();

    long[][] b = new long[n][2];
    for (int i = 0; i < n; i++) {
      b[i][0] = i;
      b[i][1] = ni();
    }
    Arrays.sort(b, (o1, o2) -> Long.signum(o1[1] - o2[1]));

    SegmentTreeRMQPos stl = new SegmentTreeRMQPos(n);
    SegmentTreeRMQPos str = new SegmentTreeRMQPos(n);


    int[] from = new int[n * 2];
    int[] to = new int[n * 2];
    long[] w = new long[n * 2];
    int ptr = 0;
    for (long[] v : b) {
      int i = (int) v[0];
      long l = stl.minx(0, i);
      int lp = stl.minpos;
      long r = str.minx(i + 1, n);
      int rp = str.minpos;

      if (l < Long.MAX_VALUE / 2) {
        from[ptr] = i;
        to[ptr] = lp;
        w[ptr] = l + i * d + v[1];
        ptr++;
      }
      if (r < Long.MAX_VALUE / 2) {
        from[ptr] = i;
        to[ptr] = rp;
        w[ptr] = r - i * d + v[1];
        ptr++;
      }

      stl.update(i, v[1] - i * d);
      str.update(i, v[1] + i * d);
    }

    System.out.println(kruskal(from, to, w, n));
  }

  public static long kruskal(int[] one, int[] other, long[] w, int n) {
    DisjointSet ds = new DisjointSet(n);
    int p = one.length;
    Integer[] ord = new Integer[p];
    for (int i = 0; i < p; i++)
      ord[i] = i;
    Arrays.sort(ord, (o1, o2) -> Long.compare(w[o1], w[o2]));

    long d = 0;
    for (int i = 0; i < ord.length; i++) {
      int cur = (int) ord[i];
      if (!ds.equiv(one[cur], other[cur])) {
        ds.union(one[cur], other[cur]);
        d += w[cur];
      }
    }
    return d;

  }

  static class SegmentTreeRMQPos {
    public int M, H, N;
    public long[] st;
    public int[] pos;

    public SegmentTreeRMQPos(int n) {
      N = n;
      M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
      H = M >>> 1;
      st = new long[M];
      pos = new int[M];
      for (int i = 0; i < N; i++)
        pos[H + i] = i;
      Arrays.fill(st, 0, M, Long.MAX_VALUE);
      for (int i = H - 1; i >= 1; i--)
        propagate(i);
    }


    public void update(int pos, long x) {
      st[H + pos] = x;
      for (int i = (H + pos) >>> 1; i >= 1; i >>>= 1)
        propagate(i);
    }

    private void propagate(int i) {
      if (st[2 * i] <= st[2 * i + 1]) {
        st[i] = st[2 * i];
        pos[i] = pos[2 * i];
      } else {
        st[i] = st[2 * i + 1];
        pos[i] = pos[2 * i + 1];
      }
    }

    public int minpos;
    public long minval;

    public long minx(int l, int r) {
      minval = Long.MAX_VALUE;
      minpos = -1;
      if (l >= r)
        return minval;
      while (l != 0) {
        int f = l & -l;
        if (l + f > r)
          break;
        long v = st[(H + l) / f];
        if (v < minval) {
          minval = v;
          minpos = pos[(H + l) / f];
        }
        l += f;
      }

      while (l < r) {
        int f = r & -r;
        long v = st[(H + r) / f - 1];
        if (v < minval) {
          minval = v;
          minpos = pos[(H + r) / f - 1];
        }
        r -= f;
      }
      return minval;
    }
  }



  public static class DisjointSet {
    public int[] upper;

    public DisjointSet(int n) {
      upper = new int[n];
      Arrays.fill(upper, -1);
    }

    public int root(int x) {
      return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
    }

    public boolean equiv(int x, int y) {
      return root(x) == root(y);
    }

    public boolean union(int x, int y) {
      x = root(x);
      y = root(y);
      if (x != y) {
        if (upper[y] < upper[x]) {
          int d = x;
          x = y;
          y = d;
        }
        upper[x] += upper[y];
        upper[y] = x;
      }
      return x == y;
    }

    public int[][] toBucket() {
      int n = upper.length;
      int[][] ret = new int[n][];
      int[] rp = new int[n];
      for (int i = 0; i < n; i++) {
        if (upper[i] < 0)
          ret[i] = new int[-upper[i]];
      }
      for (int i = 0; i < n; i++) {
        int r = root(i);
        ret[r][rp[r]++] = i;
      }
      return ret;
    }
  }

