		}

		public boolean unite(int a, int b) {
			int pa = get(a);
			int pb = get(b);
			if (pa == pb) {
				return false;
			}
			if (sz[pa] < sz[pb]) {
				p[pa] = pb;
				sz[pb] += sz[pa];
			} else {
				p[pb] = pa;
				sz[pa] += sz[pb];
			}
			groups--;
			return true;
		}
	}

	public class Edge implements Comparable<Edge> {
		long w;
		int grl;
		int grr;

		public Edge(long w, int grl, int grr) {
			this.w = w;
			this.grl = grl;
			this.grr = grr;
		}

		@Override
		public int compareTo(Edge o) {
			if (w > o.w) {
				return 1;
			}
			if (w < o.w) {
				return -1;
			}
			if (grl != o.grl) {
				return grl - o.grl;
			}
			return grr - o.grr;
		}
	}

	public class Pair {
		long x;
		int gr;

		public Pair(long x, int gr) {
			this.x = x;
			this.gr = gr;
		}

		public Pair clone() {
			return new Pair(x, gr);
		}
	}

	public void solve() {
		int n = in.nextInt();
		long d = in.nextLong();
		DSU dsu = new DSU(n);
		long ans = 0;
		long[] minus = new long[n];
		long[] plus = new long[n];
		for (int i = 0; i < minus.length; i++) {
			long x = in.nextLong();
			plus[i] = x + i * d;
			minus[i] = x - i * d;
		}
		while (dsu.groups > 1) {
			Pair[] minl = new Pair[n];
			Pair[] minl2 = new Pair[n];
			Pair[] minr = new Pair[n];
			Pair[] minr2 = new Pair[n];
			minl[0] = new Pair(Long.MAX_VALUE / 2, -1);
			minl2[0] = new Pair(Long.MAX_VALUE / 2, -1);
			minr[n - 1] = new Pair(Long.MAX_VALUE / 2, -1);
			minr2[n - 1] = new Pair(Long.MAX_VALUE / 2, -1);
			for (int i = 0; i < n - 1; i++) {
				minl[i + 1] = minl[i].clone();
				minl2[i + 1] = minl2[i].clone();
				int gr = dsu.get(i);
				if (minus[i] < minl[i + 1].x || (minus[i] == minl[i + 1].x && gr < minl[i + 1].gr)) {
					if (gr != minl[i + 1].gr) {
						minl2[i + 1] = minl[i + 1].clone();
					}
					minl[i + 1].x = minus[i];
					minl[i + 1].gr = gr; 
				} else if (gr != minl[i + 1].gr && (minus[i] < minl2[i + 1].x || (minus[i] == minl2[i + 1].x && gr < minl2[i + 1].gr))) {
					minl2[i + 1].x = minus[i];
					minl2[i + 1].gr = gr;
				}
			}
			for (int i = n - 1; i > 0; i--) {
				minr[i - 1] = minr[i].clone();
				minr2[i - 1] = minr2[i].clone();
				int gr = dsu.get(i);
				if (plus[i] < minr[i - 1].x || (plus[i] == minr[i - 1].x && gr < minr[i - 1].gr)) {
					if (gr != minr[i - 1].gr) {
						minr2[i - 1] = minr[i - 1].clone();
					}
					minr[i - 1].x = plus[i];
					minr[i - 1].gr = gr; 
				} else if (gr != minr[i - 1].gr && (plus[i] < minr2[i - 1].x || (plus[i] == minr2[i - 1].x && gr < minr2[i - 1].gr))) {
					minr2[i - 1].x = plus[i];
					minr2[i - 1].gr = gr;
				}
			}
			HashMap<Integer, Edge> map = new HashMap<>();
			for (int i = 0; i < minus.length; i++) {
				int grl = dsu.get(i);
				int grr = -1;
				long x = minus[i];
				if (minr[i].gr != grl) {
					if (minr[i].x < Long.MAX_VALUE / 2) {
						x += minr[i].x;
						grr = minr[i].gr;
					} else {
						continue;
					}
				} else {
					if (minr2[i].x < Long.MAX_VALUE / 2) {
						x += minr2[i].x;
						grr = minr2[i].gr;
					} else {
						continue;
					}
				}
				Edge e = new Edge(x, grl, grr);
				if (!map.containsKey(grl)) {
					map.put(grl, e);
				} else {
					if (map.get(grl).compareTo(e) > 0) {
						map.put(grl, e);
					}
				}
			}
			for (int i = 0; i < minus.length; i++) {
				int grr = dsu.get(i);
				int grl = -1;
				long x = plus[i];
				if (minl[i].gr != grr) {
					if (minl[i].x < Long.MAX_VALUE / 2) {
						x += minl[i].x;
						grl = minl[i].gr;
					} else {
						continue;
					}
				} else {
					if (minl2[i].x < Long.MAX_VALUE / 2) {
						x += minl2[i].x;
						grl = minl2[i].gr;
					} else {
						continue;
					}
				}
				Edge e = new Edge(x, grl, grr);
				if (!map.containsKey(grr)) {
					map.put(grr, e);
				} else {
					if (map.get(grr).compareTo(e) > 0) {
						map.put(grr, e);
					}
				}
			}
			for (int i : map.keySet()) {
				Edge e = map.get(i);
				if (dsu.unite(e.grl, e.grr)) {
					ans += e.w;
				}
			}
		}
		out.println(ans);
	}

