public class Main {
  private static void solve() {
    int n = ni();
    long d = ni();
    int[] a = na(n);

    int[] right = new int[n];
    int[] left = new int[n];

    left[1] = 0;
    for (int i = 2; i < n; i++) {
      long d1 = d * (i - left[i - 1]) + a[left[i - 1]];
      long d2 = d + a[i - 1];
      left[i] = d1 > d2 ? i - 1 : left[i - 1];
    }

    right[n - 2] = n - 1;
    for (int i = n - 3; i >= 0; i--) {
      long d1 = d * (right[i + 1] - i) + a[right[i + 1]];
      long d2 = d + a[i + 1];
      right[i] = d1 > d2 ? i + 1 : right[i + 1];
    }

    int[] from = new int[n * 2 - 2];
    int[] to = new int[n * 2 - 2];
    long[] w = new long[n * 2 - 2];
    int ptr = 0;
    for (int i = 1; i < n; i++, ptr++) {
      from[ptr] = i;
      to[ptr] = left[i];
      w[ptr] = Math.abs(i - left[i]) * d + a[i] + a[left[i]];
    }
    for (int i = 0; i < n - 1; i++, ptr++) {
      from[ptr] = i;
      to[ptr] = right[i];
      w[ptr] = Math.abs(i - right[i]) * d + a[i] + a[right[i]];
    }
    System.out.println(kruskal(from, to, w, n));
  }

  public static long kruskal(int[] one, int[] other, long[] w, int n) {
    DisjointSet ds = new DisjointSet(n);
    int p = one.length;
    Integer[] ord = new Integer[p];
    for (int i = 0; i < p; i++)
      ord[i] = i;
    Arrays.sort(ord, (o1, o2) -> Long.compare(w[o1], w[o2]));

    long d = 0;
    for (int i = 0; i < ord.length; i++) {
      int cur = (int) ord[i];
      if (!ds.equiv(one[cur], other[cur])) {
        ds.union(one[cur], other[cur]);
        d += w[cur];
      }
    }
    return d;

  }

  public static class DisjointSet {
    public int[] upper;

    public DisjointSet(int n) {
      upper = new int[n];
      Arrays.fill(upper, -1);
    }

    public int root(int x) {
      return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
    }

    public boolean equiv(int x, int y) {
      return root(x) == root(y);
    }

    public boolean union(int x, int y) {
      x = root(x);
      y = root(y);
      if (x != y) {
        if (upper[y] < upper[x]) {
          int d = x;
          x = y;
          y = d;
        }
        upper[x] += upper[y];
        upper[y] = x;
      }
      return x == y;
    }

    public int[][] toBucket() {
      int n = upper.length;
      int[][] ret = new int[n][];
      int[] rp = new int[n];
      for (int i = 0; i < n; i++) {
        if (upper[i] < 0)
          ret[i] = new int[-upper[i]];
      }
      for (int i = 0; i < n; i++) {
        int r = root(i);
        ret[r][rp[r]++] = i;
      }
      return ret;
    }
  }

