import java.util.Arrays;

class DisjointSet {
  public int[] upper; // minus:num_element(root) plus:root(normal)

  public DisjointSet(int n)
  {
      upper = new int[n];
      Arrays.fill(upper, -1);
  }

  public int root(int x)
  {
      return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
  }

  public boolean equiv(int x, int y)
  {
      return root(x) == root(y);
  }

  public boolean union(int x, int y)
  {
      x = root(x);
      y = root(y);
      if(x != y) {
          if(upper[y] < upper[x]) {
              int d = x; x = y; y = d;
          }
          upper[x] += upper[y];
          upper[y] = x;
      }
      return x == y;
  }
}

class SegmentTreeRMQLPos {
  public int M, H, N;
  public long[] st;
  public int[] pos;

  public SegmentTreeRMQLPos(int n)
  {
      N = n;
      M = Integer.highestOneBit(Math.max(N-1, 1))<<2;
      H = M>>>1;
      st = new long[M];
      pos = new int[M];
      for(int i = 0;i < N;i++)pos[H+i] = i;
      Arrays.fill(st, 0, M, Long.MAX_VALUE);
      for(int i = H-1;i >= 1;i--)propagate(i);
  }

  public SegmentTreeRMQLPos(long[] a)
  {
      N = a.length;
      M = Integer.highestOneBit(Math.max(N-1, 1))<<2;
      H = M>>>1;
      st = new long[M];
      pos = new int[M];
      for(int i = 0;i < N;i++){
          st[H+i] = a[i];
          pos[H+i] = i;
      }
      Arrays.fill(st, H+N, M, Long.MAX_VALUE);
      for(int i = H-1;i >= 1;i--)propagate(i);
  }

  public void update(int pos, long x)
  {
      st[H+pos] = x;
      for(int i = (H+pos)>>>1;i >= 1;i >>>= 1)propagate(i);
  }

  private void propagate(int i)
  {
      if(st[2*i] <= st[2*i+1]){
          st[i] = st[2*i];
          pos[i] = pos[2*i];
      }else{
          st[i] = st[2*i+1];
          pos[i] = pos[2*i+1];
      }
  }

  public int minpos;
  public long minval;

  public long minx(int l, int r){
      minval = Long.MAX_VALUE;
      minpos = -1;
      if(l >= r)return minval;
      while(l != 0){
          int f = l&-l;
          if(l+f > r)break;
          long v = st[(H+l)/f];
          if(v < minval){
              minval = v;
              minpos = pos[(H+l)/f];
          }
          l += f;
      }

      while(l < r){
          int f = r&-r;
          long v = st[(H+r)/f-1];
          if(v < minval){
              minval = v;
              minpos = pos[(H+r)/f-1];
          }
          r -= f;
      }
      return minval;
  }

  public long min(int l, int r){ 
      minpos = -1;
      minval = Long.MAX_VALUE;
      min(l, r, 0, H, 1);
      return minval;
  }

  private void min(int l, int r, int cl, int cr, int cur)
  {
      if(l <= cl && cr <= r){
          if(st[cur] < minval){
              minval = st[cur];
              minpos = pos[cur];
          }
      }else{
          int mid = cl+cr>>>1;
          if(cl < r && l < mid)min(l, r, cl, mid, 2*cur);
          if(mid < r && l < cr)min(l, r, mid, cr, 2*cur+1);
      }
  }
}


