    int[] a = na(n);
    int[][] p = new int[n][2];
    for (int i = 0; i < n; i ++) {
      p[i][0] = i;
      p[i][1] = a[i];
    }
    Arrays.sort(p, (o1, o2) ->o1[1] - o2[1]);
    SegmentTreeRMQLPos[] st = {new SegmentTreeRMQLPos(n), new SegmentTreeRMQLPos(n)};

    int[] from = new int[n * 3];
    int[] to = new int[n * 3];
    long[] w = new long[n * 3];

    int ptr = 0;
    for (int k = 0; k < 2; k ++) {

      int e = k == 0 ? 0 : n - 1;
      for (int i = 0; i < n; i ++) {
        int j = p[i][0];
        long ret = st[k].min(Math.min(e, j), Math.max(e, j) + 1);
        long l = k == 0 ? (n - j - 1) : j;
        if (st[k].minpos >= 0) {
          from[ptr] = j;
          to[ptr] = st[k].minpos;
          w[ptr] = ret - l * d + a[j];
          ptr ++;
        }
        st[k].update(j, a[j] + l * d);
      }
    }

    DisjointSet ds = new DisjointSet(n);
    long[][] idx = new long[ptr][2];
    for (int i = 0; i < ptr; i ++) {
