import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int d = sc.nextInt();
		Map<Integer,Integer> cityMap = new HashMap<Integer,Integer>();
		Map<int[], Long> wayMap = new HashMap<int[], Long>();

		for(int i = 0; i < n; i++) {
			cityMap.put(i, sc.nextInt());
		}

		List<Entry<Integer,Integer>> cityList = new ArrayList<Entry<Integer,Integer>>(cityMap.entrySet());
		List<Entry<Integer,Integer>> cityListAsc = new ArrayList<Entry<Integer,Integer>>(cityMap.entrySet());

		Collections.sort(cityListAsc, new Comparator<Entry<Integer,Integer>>() {
			public int compare(Entry<Integer,Integer> obj1, Entry<Integer,Integer> obj2) {
					return obj1.getValue().compareTo(obj2.getValue());
			}
		});

		long amt = 0;
		for (int i = 0; i < n; i++) {
			// これ
			Entry<Integer, Integer> iE = cityList.get(i);
			// これの小さい順
			int iHie = cityListAsc.indexOf(iE);
			long minCost = -1;
			int[] minWay = new int[2];
			for (int j = 0; j < n; j++) {
				if(i==j) {
					// 左右の変わり目
					if(minCost > 0) {
						wayMap.put(minWay, minCost);
					}
					minCost = -1;
					minWay = new int[2];
					continue;
				}
				// こっち
				Entry<Integer, Integer> jE = cityList.get(j);
				// こっちの小さい順
				int jHie = cityListAsc.indexOf(jE);
				if(iHie < jHie) {
					continue;
				}
				long cost = Math.abs(i-j) * d + iE.getValue() + jE.getValue();

				if(minCost < 0 || cost < minCost) {
					minWay[0] = i;
					minWay[1] = j;
					minCost = cost;
				}
			}
			if(minCost > 0) {
				wayMap.put(minWay, minCost);
			}
		}

		List<Entry<int[], Long>> wayListAsc = new ArrayList<Entry<int[], Long>>(wayMap.entrySet());
		Collections.sort(wayListAsc, new Comparator<Entry<int[], Long>>() {
			public int compare(Entry<int[], Long> obj1, Entry<int[], Long> obj2) {
					return obj1.getValue().compareTo(obj2.getValue());
			}
		});

		// 経路探索用の木
		UnionFindTree ufTree = new UnionFindTree(n);
		for(Entry<int[], Long> e : wayListAsc) {
			int[] key = e.getKey();
			if(!ufTree.same(key[0], key[1])) {
				ufTree.union(key[0], key[1]);
				amt += e.getValue();
			}
		}

		System.out.println(amt);

	}



}

class UnionFindTree {

    private int[] parent;    //親ノード
    private int[] rank;      //高さ or 次数

    /**<h1>コンストラクタ</h1>
     * <p></p>
     * @param size ： ノード数
     */
    public UnionFindTree(int size) {
        parent = new int[size];
        rank = new int[size];

        for (int i = 0; i < size; i++) {
            makeSet(i);
        }
    }

    /**<h1>ノードを作成する</h1>
     * <p>作成されたノードはルートとなる。
     * <br>元のサイズより大きいノードを指定した場合エラー。</p>
     * @param x ： ノード
     */
    public void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    /**<h1>x, y の属している木を結合する</h1>
     * <p>同じ木の場合は何もしない。</p>
     * @param x ： ノード1
     * @param y ： ノード2
     */
    public void union(int x, int y) {
        final int xRoot = find(x);
        final int yRoot = find(y);

        if (rank[xRoot] > rank[yRoot]) {
            parent[yRoot] = xRoot;        //x の木に結合
        }
        else if(rank[xRoot] < rank[yRoot]) {
            parent[xRoot] = yRoot;        //y の木に結合
        }
        else if (xRoot != yRoot) {        //同じ高さで根が違うとき
            parent[yRoot] = xRoot;        //x の木に結合
            rank[xRoot]++;                //x の木の高さを加算
        }
    }

    /**<h1>属している木のルートを返す</h1>
     * <p>検索したノードは経路圧縮が行われる。</p>
     * @param x ： ノード
     * @return<b>int</b> ： ルートのノード
     */
    public int find(int x) {
        if (x != parent[x]) {    //根でないとき
            parent[x] = find(parent[x]);    //直接、根に繋ぐ(経路圧縮)
        }
        return parent[x];
    }

    /**<h1>同じ木に属しているかどうかを返す</h1>
     * <p>同じルートを持っているかで判別する。</p>
     * @param x ： ノード1
     * @param y ： ノード2
     * @return<b>boolean</b> ： true = 同じ木に属している
     */
    public boolean same(int x, int y) {
        return find(x) == find(y);
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {

	private static long costArray[][];
	private static long minCost[];

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		String[] nd = br.readLine().split(" ");
		int n = Integer.parseInt(nd[0]);
		int d = Integer.parseInt(nd[1]);

		String[] sa = br.readLine().split(" ");
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = Integer.parseInt(sa[i]);
		}
		br.close();

		costArray = new long[n][n];
		minCost = new long[n];
		for (int i = 0; i < n; i++) {
			minCost[i] = Long.MAX_VALUE;
			for (int j = 0; j < n; j++) {
				costArray[i][j] = calcCost(i, j, d, a[i], a[j]);
				if (costArray[i][j] < minCost[i]) {
					minCost[i] = costArray[i][j];
				}
			}
		}

		Arrays.parallelSort(minCost);
		long sum = 0L;
		for (int i = 1; i < n; i++) {
			sum += minCost[i];
		}
		System.out.println(sum);
	}

	private static long calcCost(int i, int j, int d, int ai, int aj) {
		if (i == j) {
			return Long.MAX_VALUE;
		}
		if (costArray[j][i] != 0) {
			return costArray[j][i];
		}
		long val = i - j;
		val = Math.abs(val);
		val *= d;
		val += (ai + aj);
		return val;
	}
}

import java.util.*;

public class Main {
	static class Edge {
		long Ai, Aj;
		int i, j;
		long cost;

		public Edge(long ai, long aj, int i, int j) {
			Ai = ai;
			Aj = aj;
			this.i = i;
			this.j = j;
			cost = Math.abs(i - j) * Main.D + Ai + Aj;
		}
	}

	int N;
	static long D;
	List<Long> A;
	List<Edge> edges;

	void calc() {
		Queue<Edge> queue = new PriorityQueue<>(new Comparator<Edge>() {
			@Override
			public int compare(Edge o1, Edge o2) {
				if (o1.cost < o2.cost) {
					return -1;
				} else if (o1.cost > o2.cost) {
					return 1;
				} else {
					return 0;
				}
			}
		});

		for (int i = 1; i < A.size(); ++i) {
			queue.add(new Edge(A.get(0), A.get(i), 0, i));
		}
		edges = new ArrayList<>();
		Set<Integer> remainSet = new HashSet<>();
		for (int i = 1; i < A.size(); ++i) {
			remainSet.add(i);
		}
		while (!remainSet.isEmpty()) {
			// まず，edgeの中から最も短いものを取得する
			Edge edge = queue.poll();
			// edgeは，両端が処理済み or どちらかが新しいはず
			if (!remainSet.contains(edge.i) && !remainSet.contains(edge.j)) {
				// すでにつながっている
				continue;
			}
			int newIndex = -1;
			if (remainSet.contains(edge.i)) {
				newIndex = edge.i;
			} else {
				newIndex = edge.j;
			}
			edges.add(edge);
			remainSet.remove(newIndex);
			// newIndexからつながる辺を求める
			for (Integer dst : remainSet) {
				queue.add(new Edge(A.get(newIndex), A.get(dst), newIndex, dst));
			}
		}
	}

	long getCost() {
		long sum = 0;
		for (Edge edge : edges) {
			sum += edge.cost;
		}
		return sum;
	}

	Main() {
		Scanner in = new Scanner(System.in);
		String[] tokens = in.nextLine().split(" ");
		N = Integer.parseInt(tokens[0]);
		D = Long.parseLong(tokens[1]);
		tokens = in.nextLine().split(" ");
		A = new ArrayList<>(N);
		for (int i = 0; i < N; ++i) {
			A.add(Long.parseLong(tokens[i]));
		}
		in.close();
	}

	public static void main(String[] args) {
		Main ins = new Main();
		ins.calc();
		System.out.println(ins.getCost());
	}
}

