public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    ArrayList<int[]> edge = new ArrayList<>();

    void solve(){
        int n = ni();
        long d = nl();
        long[] a = new long[n];
        for(int i = 0; i < n; i++){
            a[i] = nl();
        }
        candidate_edges(0, n-1, a, d);
        long[][] e = new long[edge.size()][3];
        int j = 0;
        for(int[] r : edge){
            e[j][0] = r[0];
            e[j][1] = r[1];
            e[j][2] = Math.abs(r[0]-r[1])*d + a[r[0]] + a[r[1]];
            j++;
        }
        Arrays.sort(e, new Comparator<long[]>() {
            public int compare(long[] a, long[] b) {
                return Long.compare(a[2],b[2]);
            }
        });

        UnionFind uf = new UnionFind(n);
        long ans = 0;
        for(int i = 0; i < edge.size(); i++){
            if(uf.same((int)e[i][0], (int)e[i][1])) continue;
            ans += e[i][2];
            uf.union((int)e[i][0], (int)e[i][1]);
        }
        out.println(ans);
    }

    public static class UnionFind{  
        int parent[];
        int rank[];

        public UnionFind(int n){
            parent = new int[n];
            rank   = new int[n];

            for(int i = 0;i < n;i++){
                parent[i] = i;
                rank[i]   = 0;
            }        
        }

        boolean same(int x,int y){
            return find(x) == find(y);
        }

        public int find(int x){
            if(parent[x] == x){
               return x;
            }else{
               return parent[x] = find(parent[x]);   
            }        
        }

        public void union(int x,int y){
            x = find(x);
            y = find(y);

            if(x != y){
                if(rank[x] > rank[y]){
                   parent[y] = x; 
                }else{
                   parent[x] = y;
                   if(rank[x] == rank[y]){
                       rank[y]++;
                   }
                }            
            }

            return;
        }

        public int count(int n){
            int ret = 0;
            for(int i = 0;i < n;i++){
                if(i == find(i)){
                    ret++;
                }
            }
            return ret;
        }

      } 

    void candidate_edges(int s, int t, long[] a, long d){
        if(t<=s) return;
        int mid = (s+t)/2;
        int id = -1;
        long dist = inf;
        for(int i = mid+1; i <= t; i++){
            long tmp = Math.abs(i-s)*d + a[i] + a[s];
            if(tmp<=dist){
                dist = tmp;
                id = i;
            }
        }
        for(int i = s; i <= mid; i++){
            edge.add(new int[]{i,id});
        }
        id = -1;
        dist = inf;
        for(int i = s; i <= mid; i++){
            long tmp = Math.abs(i-t)*d + a[i] + a[t];
            if(tmp<=dist){
                dist = tmp;
                id = i;
            }
        }
        for(int i = mid+1; i <= t; i++){
            edge.add(new int[]{i,id});
        }
        candidate_edges(s,mid,a,d);
        candidate_edges(mid+1,t,a,d);
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int d = sc.nextInt();
		Map<Integer,Integer> cityMap = new HashMap<Integer,Integer>();
		Map<int[], Long> wayMap = new HashMap<int[], Long>();

		for(int i = 0; i < n; i++) {
			cityMap.put(i, sc.nextInt());
		}

		List<Entry<Integer,Integer>> cityList = new ArrayList<Entry<Integer,Integer>>(cityMap.entrySet());

		long amt = 0;
		for (int i = 0; i < n; i++) {
			// これ
			Entry<Integer, Integer> iE = cityList.get(i);
			long minCost = -1;
			int[] minWay = new int[2];
			for (int j = 0; j < n; j++) {
				if(i==j) {
					// 左右の変わり目
					if(minCost > 0) {
						wayMap.put(minWay, minCost);
					}
					minCost = -1;
					minWay = new int[2];
					continue;
				}
				// こっち
				Entry<Integer, Integer> jE = cityList.get(j);
				if(iE.getValue() < jE.getValue()) {
					continue;
				}
				long cost = Math.abs(i-j) * d + iE.getValue() + jE.getValue();

				if(minCost < 0 || cost < minCost) {
					minWay[0] = i;
					minWay[1] = j;
					minCost = cost;
				}
			}
			if(minCost > 0) {
				wayMap.put(minWay, minCost);
			}
		}

		List<Entry<int[], Long>> wayListAsc = new ArrayList<Entry<int[], Long>>(wayMap.entrySet());
		Collections.sort(wayListAsc, new Comparator<Entry<int[], Long>>() {
			public int compare(Entry<int[], Long> obj1, Entry<int[], Long> obj2) {
					return obj1.getValue().compareTo(obj2.getValue());
			}
		});

		// 経路探索用の木
		UnionFindTree ufTree = new UnionFindTree(n);
		for(Entry<int[], Long> e : wayListAsc) {
			int[] key = e.getKey();
			if(!ufTree.same(key[0], key[1])) {
				ufTree.union(key[0], key[1]);
				amt += e.getValue();
			}
		}

		System.out.println(amt);

	}



}

class UnionFindTree {

    private int[] parent;    //親ノード
    private int[] rank;      //高さ or 次数

    /**<h1>コンストラクタ</h1>
     * <p></p>
     * @param size ： ノード数
     */
    public UnionFindTree(int size) {
        parent = new int[size];
        rank = new int[size];

        for (int i = 0; i < size; i++) {
            makeSet(i);
        }
    }

    /**<h1>ノードを作成する</h1>
     * <p>作成されたノードはルートとなる。
     * <br>元のサイズより大きいノードを指定した場合エラー。</p>
     * @param x ： ノード
     */
    public void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    /**<h1>x, y の属している木を結合する</h1>
     * <p>同じ木の場合は何もしない。</p>
     * @param x ： ノード1
     * @param y ： ノード2
     */
    public void union(int x, int y) {
        final int xRoot = find(x);
        final int yRoot = find(y);

        if (rank[xRoot] > rank[yRoot]) {
            parent[yRoot] = xRoot;        //x の木に結合
        }
        else if(rank[xRoot] < rank[yRoot]) {
            parent[xRoot] = yRoot;        //y の木に結合
        }
        else if (xRoot != yRoot) {        //同じ高さで根が違うとき
            parent[yRoot] = xRoot;        //x の木に結合
            rank[xRoot]++;                //x の木の高さを加算
        }
    }

    /**<h1>属している木のルートを返す</h1>
     * <p>検索したノードは経路圧縮が行われる。</p>
     * @param x ： ノード
     * @return<b>int</b> ： ルートのノード
     */
    public int find(int x) {
        if (x != parent[x]) {    //根でないとき
            parent[x] = find(parent[x]);    //直接、根に繋ぐ(経路圧縮)
        }
        return parent[x];
    }

    /**<h1>同じ木に属しているかどうかを返す</h1>
     * <p>同じルートを持っているかで判別する。</p>
     * @param x ： ノード1
     * @param y ： ノード2
     * @return<b>boolean</b> ： true = 同じ木に属している
     */
    public boolean same(int x, int y) {
        return find(x) == find(y);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * メインクラス
 * @author Yuichiro.Yamashita
 *
 */
public class Main {

	/**
	 * メインメソッド
	 * @param args
	 * @throws IOException
	 */
	public static void main(String[] args) throws IOException {

		// ============================================================
		// 標準入力を変数に設定
		// ============================================================

		// 標準入力を取得
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] line = br.readLine().split(" ");

		// 都市数 N
		int n = Integer.parseInt(line[0]);

		// 建設コスト算出で使用する係数 D
		int d = Integer.parseInt(line[1]);

		// 各都市の建設コスト
		line = br.readLine().split(" ");
		long[] a = new long[line.length];
		for (int i = 0; i < line.length; i++) {
			a[i] = Integer.parseInt(line[i]);
		}

		// ============================================================
		// メイン処理
		// ============================================================

		// Union-Find木を初期化
		UnionFindTree unionFindTree = new UnionFindTree(n);

		// 回答を初期化
		long answer = 0;

		// 全てのノードが接続されるまでループ
		while (unionFindTree.size(0) != n) {
			long[] val1 = new long[n + 2];
			long[] val2 = new long[n + 2];
			long[] valL = new long[n + 2];
			long[] valR = new long[n + 2];
			Arrays.fill(valL, Long.MAX_VALUE / 2);
			Arrays.fill(valR, Long.MAX_VALUE / 2);
			Arrays.fill(val1, Long.MAX_VALUE / 2);
			Arrays.fill(val2, Long.MAX_VALUE / 2);
			int[] indexL = new int[n + 2];
			int[] indexR = new int[n + 2];
			for (int i = 0; i < n; i++) {
				if (valL[unionFindTree.root(i) + 1] > a[i] - i * d) {
					valL[unionFindTree.root(i) + 1] = a[i] - i * d;
					indexL[unionFindTree.root(i) + 1] = i;
				}
				if (valR[unionFindTree.root(i) + 1] > a[i] + i * d) {
					valR[unionFindTree.root(i) + 1] = a[i] + i * d;
					indexR[unionFindTree.root(i) + 1] = i;
				}
				val1[unionFindTree.root(i) + 1] = Math.min(val1[unionFindTree.root(i) + 1], a[i] + i * d);
				val2[unionFindTree.root(i) + 1] = Math.min(val2[unionFindTree.root(i) + 1], a[i] - i * d);
			}

			int[] minL = new int[n + 2];
			int[] minR = new int[n + 2];

			for (int i = 1; i <= n; i++) {
				if (valL[minL[i - 1]] >= valL[i]) {
					minL[i] = i;
				} else {
					minL[i] = minL[i - 1];
				}
			}

			minR[n + 1] = n + 1;
			for (int i = n; i >= 1; i--) {
				if (valR[minR[i + 1]] >= valR[i]) {
					minR[i] = i;
				} else {
					minR[i] = minR[i + 1];
				}
			}

			for (int i = 1; i <= n; i++) {
				if (unionFindTree.root(i - 1) != i - 1)
					continue;
				long cl = valL[minL[i - 1]] + val1[i];
				long cr = valR[minR[i + 1]] + val2[i];
				if (cl <= cr) {
					if (!unionFindTree.same(i - 1, minL[i - 1] - 1)) {
						answer += cl;
						unionFindTree.union(i - 1, minL[i - 1] - 1);
					}
				} else {
					if (!unionFindTree.same(i - 1, minR[i + 1] - 1)) {
						answer += cr;
						unionFindTree.union(i - 1, minR[i + 1] - 1);
					}
				}
			}
		}

		// ============================================================
		// 結果出力
		// ============================================================

		// 結果出力
		System.out.println(answer);
	}
}

/**
 * Union-Find木
 * @author Yuichiro.Yamashita
 *
 */
class UnionFindTree {

	// ノードの親ノードを格納する変数
	// 但し自らが親ノードの場合はその配下に接続されたノード数を負数で保持
	private int[] data;

	/**
	 * コンストラクタ
	 * @param size
	 */
	public UnionFindTree(final int size) {
		data = new int[size];
		clear();
	}

	/**
	 * 全てのデータを初期化
	 * ※全ノードを根とする
	 * ※根ノードについてはその配下にあるノード数を負数で管理するため
	 * ※値に -1 を設定する
	 */
	public void clear() {
		Arrays.fill(data, -1);
	}

	/**
	 * ルートノードを取得
	 * @param x
	 * @return
	 */
	public int root(final int x) {

		// 負数を保持している場合は自らがルートノード
		if (data[x] < 0) {
			return x;

			// それ以外の場合はルートノードを検索して返却
		} else {
			return root(data[x]);
		}
	}

	/**
	 * ノードの結合を実施
	 * @param x
	 * @param y
	 */
	public void union(int x, int y) {

		// 引数の根を取得
		x = root(x);
		y = root(y);

		// 根が異なる場合
		if (x != y) {

			// 根のインデックスが小さいノードをルートに設定する
			if (data[y] < data[x]) {
				final int t = x;
				x = y;
				y = t;
			}

			// xに接続されているノード数を負の数で表現
			data[x] += data[y];

			// yの親ノードをxに設定
			data[y] = x;
		}
	}

	/**
	 * xとyが同じ木に属しているかを判定
	 * @param x
	 * @param y
	 * @return
	 */
	public boolean same(final int x, final int y) {
		return root(x) == root(y);
	}

	/**
	 * xに接続されているノード数を返却
	 * @param x
	 * @return
	 */
	public int size(int x) {

		// 接続ノード数は負数で表現されているため 符号変換して返却
		return -data[root(x)];
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    static PrintWriter out = new PrintWriter(System.out);
    static Scanner sc = new Scanner(System.in);
    static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    Node[] plusTree, minusTree; // plus records A+Di, minus records A-Di
    Node maxiNode;
    int N=1;
    int[] id;
    public static void main(String[] args) throws IOException {
        Main main = new Main();
//        main.solve();
//        out.flush();
        System.out.println(main.solve());
    }
    long solve() throws IOException {
        Long INF = Long.MAX_VALUE/2;
        maxiNode = new Node(INF,-1);
        String[] buf = reader.readLine().split(" ");
        int n = Integer.parseInt(buf[0]); long D = Long.parseLong(buf[1]);
        while(N<n) N *= 2;
        plusTree = new Node[2*N-1]; minusTree = new Node[2*N-1];
        for(int i=0;i<2*N-1;i++){
            plusTree[i] = new Node(INF,-1);
            minusTree[i] = new Node(INF,-1);
        }
        buf = reader.readLine().split(" ");
        long[] arr = new long[n];
        int[][] idxVal = new int[n][];
        for(int i=0;i<n;i++) {
            int cur = Integer.parseInt(buf[i]);
            arr[i]=cur;
            idxVal[i] = new int[]{i,cur};
            update(i,INF,plusTree);
            update(i,INF,minusTree);
        }
        Arrays.sort(idxVal,Comparator.comparingInt(e->e[1]));
        PriorityQueue<Edge> pq = new PriorityQueue<>(2*n);
        TreeSet<Integer> used = new TreeSet<>();
        for(int i=0;i<n;i++){
            int[] cur = idxVal[i];
            int idx = cur[0]; long val = cur[1];
            Integer left = used.lower(idx), right = used.higher(idx);
            if(left!=null){
                Node node = query(0,0,idx-1,0,N-1,minusTree);
                long weight = node.val+idx*D+val;
                pq.add(new Edge(node.minIdx,idx,weight));
            }
            if(right!=null){
                Node node = query(0,idx+1,n-1,0,N-1,plusTree);
                long weight = node.val-idx*D+val;
                pq.add(new Edge(node.minIdx,idx,weight));
            }
            update(idx,val+idx*D,plusTree);
            update(idx,val-idx*D,minusTree);
            used.add(idx);
        }
        id = new int[n];
        for(int i=0;i<n;i++) id[i]=i;
        long ans = 0;
        while(pq.size()>0){
            Edge e = pq.poll();
            int i = find(e.from), j = find(e.to);
            if(i==j) continue;
            ans += e.weight;
            join(i,j);
        }
        return ans;
    }
    Node query(int k, int qStart, int qEnd, int nStart, int nEnd, Node[] seg){
        if(qEnd<nStart || nEnd<qStart) return maxiNode;
        if(qStart <= nStart && nEnd <= qEnd) return seg[k];
        int mid = (nStart+nEnd)/2;
        Node left = query(2*k+1,qStart,qEnd,nStart,mid,seg);
        Node right = query(2*k+2,qStart,qEnd,mid+1,nEnd,seg);
        if(left.val<right.val) return left;
        else return right;
    }
    void update(int k, long newVal, Node[] seg){
        // here update is to change the exact value of single point
        // instead of in the lazy tag case
        k += N-1;
        seg[k].val = newVal;
        seg[k].minIdx = k-(N-1);
        while(k>0){
            k = (k-1)/2;
            Node left = seg[2*k+1], right = seg[2*k+2], son;
            if(left.val<=right.val) son = left;
            else son = right;
            seg[k].val = son.val; seg[k].minIdx = son.minIdx;
        }
    }
    class Node{
        int minIdx;
        long val;
        public Node(long v, int i){val=v;minIdx=i;}
        public Node(){}
    }
    class Edge implements Comparable<Edge>{
        int from,to;
        long weight;
        public Edge(int f, int t, long w){from=f;to=t;weight=w;}
        public int compareTo(Edge e){
            return Long.compare(weight,e.weight);
        }
    }
    int find(int p){
        while(p!=id[p]){
            id[p] = id[id[p]];
            p = id[p];
        }
        return p;
    }
    void join(int p, int q){
        int i = find(p), j = find(q);
        if(i!=j) id[i]=j;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int d = sc.nextInt();
		Map<Integer,Integer> cityMap = new HashMap<Integer,Integer>();

		for(int i = 0; i < n; i++) {
			cityMap.put(i, sc.nextInt());
		}

		List<Entry<Integer,Integer>> cityList = new ArrayList<Entry<Integer,Integer>>(cityMap.entrySet());

		Collections.sort(cityList, new Comparator<Entry<Integer,Integer>>() {
			public int compare(Entry<Integer,Integer> obj1, Entry<Integer,Integer> obj2) {
					return obj1.getValue().compareTo(obj2.getValue());
			}
		});

		// 確定した一番左のインデックス
		int lIndex = cityList.get(0).getKey();
		// ここより左側に橋を架けるとき基準にするべきインデックス
		int minIndex = cityList.get(0).getKey();
		// ここより右側に橋を架けるとき基準にするべきインデックス
		int maxIndex = cityList.get(0).getKey();
		// 確定した一番右のインデックス
		int uIndex = cityList.get(0).getKey();

		Map<Integer, Integer> keepMinMaxMap = new HashMap<Integer, Integer>();
		int amt = 0;
		for(int i = 1; i < n; i++) {
			Entry<Integer, Integer> cityE = cityList.get(i);
			int index = cityE.getKey();
			int value = cityE.getValue();
			if (index < lIndex) {
				int minIndexValue = cityMap.get(minIndex);
				int far = minIndex - index;
				if(value - minIndexValue > far * d) {
					// 全部minIdexから！
					for(int j = lIndex - 1; j >= index; j--) {
						if(keepMinMaxMap.containsKey(j)) {
							minIndex = keepMinMaxMap.get(j);
							minIndexValue = cityMap.get(minIndex);
						}
						int minFar = minIndex - j;
						amt += minFar * d + cityMap.get(j) + minIndexValue;
					}
				} else {
					// いい感じの位置を探す
					int evenFar = (value - minIndexValue) / d;
					// これから先でkeyから先はvalueがminIndexになる
					int key;
					if( (value - minIndexValue) % d == 0) {
						key = evenFar;
					} else {
						key = evenFar + 1;
					}
					keepMinMaxMap.put(index - key, index);
					int keepIndex = index;
					for(int j = lIndex - 1; j > index; j--) {
						if(keepMinMaxMap.containsKey(j)) {
							minIndex = keepMinMaxMap.get(j);
							minIndexValue = cityMap.get(minIndex);
						}
						int jValue = cityMap.get(j);
						int minFar = minIndex - j;
						int currentFar = j - index;
						int keepVal = 0;
						if(evenFar <= minFar - currentFar) {
							// ここから
							amt += currentFar * d + jValue + value;
							// minとつなぐところを変えたほうがいいか
							int diff = (currentFar * d) - jValue;
							if(diff > 0 && diff > keepVal) {
								keepVal = diff;
								keepIndex = j;
							}
						} else {
							// minから
							amt += minFar * d + jValue + minIndexValue;
						}
					}
					// min～をつなぐためにつなぐところ決め
					amt += (minIndex - keepIndex) * d + cityMap.get(keepIndex) + minIndexValue;
				}
				lIndex = index;
			} else if(uIndex < index) {
				int maxIndexValue = cityMap.get(maxIndex);
				int far = index - maxIndex;
				if(value - maxIndexValue > far * d) {
					// 全部maxIdexから！
					for(int j = uIndex + 1; j <= index; j++) {
						if(keepMinMaxMap.containsKey(j)) {
							maxIndex = keepMinMaxMap.get(j);
							maxIndexValue = cityMap.get(maxIndex);
						}
						int maxFar = j - maxIndex;
						amt += maxFar * d + cityMap.get(j) + maxIndexValue;
					}
				} else {
					// いい感じの位置を探す
					int evenFar = (value - maxIndexValue) / d;
					// これから先でkeyから先はvalueがmaxIndexになる
					int key;
					if( (value - maxIndexValue) % d == 0) {
						key = evenFar;
					} else {
						key = evenFar + 1;
					}
					keepMinMaxMap.put(index + key, index);
					int keepIndex = index;
					for(int j = uIndex + 1; j < index; j++) {
						if(keepMinMaxMap.containsKey(j)) {
							maxIndex = keepMinMaxMap.get(j);
							maxIndexValue = cityMap.get(maxIndex);
						}
						int jValue = cityMap.get(j);
						int maxFar = j - maxIndex;
						int currentFar = index - j;
						int keepVal = 0;
						if(evenFar <= maxFar - currentFar) {
							// ここから
							amt += currentFar * d + jValue + value;
							// maxとつなぐところを変えたほうがいいか
							int diff = (currentFar * d) - jValue;
							if(diff > 0 && diff > keepVal) {
								keepVal = diff;
								keepIndex = j;
							}
						} else {
							// minから
							amt += maxFar * d + jValue + maxIndexValue;
						}
					}
					// max～をつなぐためにつなぐところ決め
					amt += (keepIndex - maxIndex) * d + cityMap.get(keepIndex) + maxIndexValue;
				}
				uIndex = index;
			} else {
				// minとmaxの間はもう決まってる
				continue;
			}

			if(lIndex == 0 && uIndex == n) {
				break;
			}
		}

		System.out.println(amt);

	}
}

