/**
 * Union-Find木
 * @author Yuichiro.Yamashita
 *
 */
class UnionFind {

	private int[] data;

	/**
	 * コンストラクタ
	 * @param size
	 */
	public UnionFind(final int size) {
		data = new int[size];
		clear();
	}

	/**
	 * 全てのデータを初期化
	 */
	public void clear() {
		Arrays.fill(data, -1);
	}

	public int root(final int x) {
		if (data[x] < 0) {
			return x;
		} else {
			return root(data[x]);
		}
	}

	public void union(int x, int y) {
		if ((x = root(x)) != (y = root(y))) {
			if (data[y] < data[x]) {
				final int t = x;
				x = y;
				y = t;
			}
			data[x] += data[y];
			data[y] = x;
		}
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}

	public int size(int x) {
		return -data[root(x)];
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Queue;

public class Main {

	public static void main(String... args) throws IOException {

		// 標準入力を取得
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line = br.readLine();
		int N = Integer.parseInt(line.split(" ")[0]);
		int D = Integer.parseInt(line.split(" ")[1]);

		List<String> strs = Arrays.asList(br.readLine().split(" "));
		List<Integer> aList = new ArrayList<Integer>();
		List<Integer> aListIndexKey = new ArrayList<Integer>();

		for (int i = 0; i < strs.size(); i++) {
			aList.add(Integer.parseInt(strs.get(i)));
			aListIndexKey.add(Integer.parseInt(strs.get(i)));
		}

		// 計算済みコストをキャッシュ
		Map<String, Integer> cacheCosts = new HashMap<String, Integer>();

		// 2次元目には、接続元ノード, 接続先ノード, コストが格納される
		List<Edge>[] edgeList = new List[N];
		for (int i = 0; i < N; i++) {
			edgeList[i] = new ArrayList<Edge>();
		}

		// 全島を走査
		int size = aList.size();
		for (int i = 0; i < size; i++) {

			// 最小コストを初期化
			int minCost = 0;
			int minIndex = 0;

			// 自分の島より左側の島たちのみ処理
			for (int j = 0; j < i; j++) {

				// 最小コストかを判断
				Integer cost = cacheCosts.get(j + ":" + i);
				if (cost == null) {
					cost = Math.abs(i - j) * D + aListIndexKey.get(i) + aListIndexKey.get(j);
					cacheCosts.put(j + ":" + i, cost);
				}

				// 既知最小コスト以下の場合は最小コストに設定
				if (minCost == 0 || minCost > cost) {
					minCost = cost;
					minIndex = j;
				}
			}

			// 橋一覧に追加
			edgeList[i].add(new Edge(i, minIndex, minCost));
			edgeList[minIndex].add(new Edge(minIndex, i, minCost));

			// 自分の島より右側の島たちのみ処理
			for (int j = i + 1; j < size; j++) {

				// 最小コストかを判断
				Integer cost = cacheCosts.get(i + ":" + j);
				if (cost == null) {
					cost = Math.abs(i - j) * D + aListIndexKey.get(i) + aListIndexKey.get(j);
					cacheCosts.put(i + ":" + j, cost);
					cacheCosts.put(j + ":" + i, cost);
				}

				// 既知最小コスト以下の場合は最小コストに設定
				if (minCost == 0 || minCost > cost) {
					minCost = cost;
					minIndex = j;
				}
			}

			// 橋一覧に追加
			edgeList[i].add(new Edge(i, minIndex, minCost));
			edgeList[minIndex].add(new Edge(minIndex, i, minCost));

		}

		int ans = prim(N, edgeList);
		System.out.println(ans); //最小全域木の重み
	}

	//プリム法[最小全域木(Minimum Spannig Tree)]
	static int prim(int n, List<Edge>[] edges) {
		boolean[] done = new boolean[n]; //訪問フラグ

		Queue<Edge> q = new PriorityQueue<Edge>();
		q.add(new Edge(0, 0, 0)); //０から(ダミー)

		int totalCost = 0; //最小全域木の重み
		while (!q.isEmpty()) {
			Edge e = q.poll(); //最小コストの辺を取り出す
			if (done[e.target]) {
				continue;
			}

			done[e.target] = true; //訪問済にする
			totalCost += e.cost;
			q.addAll(edges[e.target]); //隣接しているすべての辺を追加
		}

		return totalCost;
	}
}

//辺情報の構造体
class Edge implements Comparable<Edge> {
	public int source = 0; //接続元ノード
	public int target = 0; //接続先ノード
	public int cost = 0; //重み

	public Edge(int source, int target, int cost) {
		this.source = source;
		this.target = target;
		this.cost = cost;
	}

	@Override
	public int compareTo(Edge o) {
		return this.cost - o.cost;
	}

	@Override
	public String toString() { //デバッグ用
		return "source = " + source + ", target = " + target + ", cost = " + cost;
	}
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni(), D = ni();
		int[] a = na(n);
		Long[] res = dfs(0, n, a, D);
		long ans = 0;
		for(Long e : res){
			ans += cost((int)(e>>>32), (int)(long)e, a, D);
		}
		out.println(ans);
	}

	static Long[] dfs(int l, int r, int[] a, long D)
	{
		if(r-l <= 1)return new Long[0];
		int h = l+r>>1;
		// [l,h), [h,r)

		long min = Long.MAX_VALUE;
		int argr =-1;
		for(int i = h;i < r;i++){
			long oc = a[i] + (i-h)*D;
			if(oc < min){
				min = oc;
				argr = i;
			}
		}

		Long[] es = new Long[r-l+(r-h)*2];
		int p = 0;

		long minl = Long.MAX_VALUE;
		int argl = -1;
		for(int i = l;i < h;i++){
			long v = (h-i)*D + a[i];
			if(v < minl){
				minl = v;
				argl = i;
			}
		}

		for(int i = h;i < r;i++){
			es[p++] = (long)argl<<32|i;
		}
		for(int i = l;i < h;i++){
			es[p++] = (long)i<<32|argr;
		}

		Long[] les = dfs(l, h, a, D);
		Long[] res = dfs(h, r, a, D);

		for(Long e : les)es[p++] = e;
		for(Long e : res)es[p++] = e;

		es = Arrays.copyOf(es, p);
		Arrays.sort(es, new Comparator<Long>() {
			public int compare(Long x, Long y) {
				return Long.compare(cost((int)(x>>>32), (int)(long)x, a, D), 
						cost((int)(y>>>32), (int)(long)y, a, D));
			}
		});

		DJSet ds = new DJSet(r-l);
		Long[] ret = new Long[r-l-1];
		int rp = 0;
		for(Long e : es){
			if(!ds.union((int)(e>>>32)-l, ((int)(long)e)-l)){
				ret[rp++] = e;
			}
		}
		assert rp == ret.length;
		return ret;
	}

	static long cost(int x, int y, int[] a, long D)
	{
		return Math.abs(x-y)*D + a[x]+a[y];
	}

		public static class DJSet {
			public int[] upper;

			public DJSet(int n) {
				upper = new int[n];
				Arrays.fill(upper, -1);
			}

			public int root(int x) {
				return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
			}

			public boolean equiv(int x, int y) {
				return root(x) == root(y);
			}

			public boolean union(int x, int y) {
				x = root(x);
				y = root(y);
				if (x != y) {
					if (upper[y] < upper[x]) {
						int d = x;
						x = y;
						y = d;
					}
					upper[x] += upper[y];
					upper[y] = x;
				}
				return x == y;
			}

			public int count() {
				int ct = 0;
				for (int u : upper)
					if (u < 0)
						ct++;
				return ct;
			}
		}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

