            C[i] = A[i] + D * (N - i - 1);
        }

        var Q = new PriorityQueue<Edge>(-1);

        var ans = 0L;
        var min = long.MaxValue;
        var id = -1;
        for (int i = N - 2; i >= 0; i--)
        {
            if (B[i + 1] < min)
            {
                min = B[i + 1];
                id = i + 1;
            }
            Q.Enqueue(new Edge(i, id, A[i] + A[id] + D * Math.Abs(i - id)));
            Q.Enqueue(new Edge(i, N - 1, A[i] + A[N - 1] + D * Abs(N - 1 - i)));
        }

        min = long.MaxValue;
        id = -1;
        for (int i = 1; i < N; i++)
        {
            if (C[i - 1] < min)
            {
                min = C[i - 1];
                id = i - 1;
            }
            Q.Enqueue(new Edge(i, id, A[i] + A[id] + D * Math.Abs(i - id)));
            Q.Enqueue(new Edge(0, i, A[0] + A[i] + D * Abs(i)));
        }
        var G = new DisjointSet(N);

        while (Q.Any())
        {
            var d = Q.Dequeue();

            if (!G.Same(d.from, d.to))
