    void chmax<T>(ref T a, T b) where T : IComparable<T> { a = a.CompareTo(b) < 0 ? b : a; }
    void chmin<T>(ref T a, T b) where T : IComparable<T> { a = a.CompareTo(b) < 0 ? a : b; }

    void solve()
    {
        int N = cin.nextint;
        var D = cin.nextlong;
        var A = cin.scanlong;
        var B = new long[N];
        var C = new long[N];
        for (int i = 0; i < N; i++)
        {
            B[i] = A[i] + D * i;
            C[i] = A[i] + D * (N - i - 1);
        }

        var Q = new PriorityQueue<Edge>();

        var ans = 0L;
        var min = long.MaxValue;
        var id = -1;
        for (int i = N - 2; i >= 0; i--)
        {
            if (B[i + 1] < min)
            {
                min = B[i + 1];
                id = i + 1;
            }
            Q.Enqueue(new Edge(i, id, -(A[i] + A[id] + D * Math.Abs(i - id))));
        }

        min = long.MaxValue;
        id = -1;
        for (int i = 1; i < N; i++)
        {
            if (C[i - 1] < min)
            {
                min = C[i - 1];
                id = i - 1;
            }
            Q.Enqueue(new Edge(i, id, -(A[i] + A[id] + D * Math.Abs(i - id))));
        }
        var G = new DisjointSet(N);

        while (Q.Any())
        {
            var d = Q.Dequeue();

            if (!G.Same(d.from, d.to))
            {
                G.Unite(d.from, d.to);
                ans += -d.cost;
            }
        }

        WriteLine(ans);
    }
}

