class RMQ
{
    internal int n;
    internal pair[] dat;

    public RMQ(int t)
    {
        n = t;
        dat = new pair[2 * n - 1];
        for (int i = 0; i < 2 * n - 1; i++)
        {
            dat[i] = new pair(long.MaxValue, -1);
        }
    }

    public void update(int k, pair a)
    {
        k += n - 1;
        dat[k] = a;
        while (k > 0)
        {
            k = (k - 1) / 2;
            if (dat[k * 2 + 1].f < dat[k * 2 + 2].f)
            {
                dat[k] = new pair(dat[k * 2 + 1].f, dat[k * 2 + 1].s);
            }
            else
            {
                dat[k] = new pair(dat[k * 2 + 2].f, dat[k * 2 + 2].s);
            }
        }
    }

    public pair query(int a, int b, int k, int l, int r)
    {
        if (r <= a || b <= l) return new pair(long.MaxValue, -1);

        if (a <= l && r <= b) return dat[k];
        else
        {
            var vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            var vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            if (vl.f < vr.f)
            {
                return vl;
            }
            else
            {
                return vr;
            }
        }
    }
}
