        {
            var p = SS.query(0, i, 0, 0, n);
            var P = p.f - D * (N - i - 1) + A[i];
            Q.Enqueue(new Edge(i, p.s, -P));
        }
        var G = new DisjointSet(N);

        while (Q.Any())
        {
            var d = Q.Dequeue();

            if (!G.Same(d.from, d.to))
            {
                G.Unite(d.from, d.to);
                ans += -d.cost;
            }
        }

        WriteLine(ans);
    }

    struct Edge : IComparable<Edge>
    {
        public int from, to, id; public long cost;
        public Edge(int from, int to, long cost)
        {
            this.from = from;
            this.to = to;
            this.cost = cost;
            id = -1;
        }
        public void set_id(int id)
        {
            this.id = id;
        }
        public int CompareTo(Edge e)
        {
            return cost.CompareTo(e.cost);
        }
    }

}


class PriorityQueue<T> where T : IComparable<T>
{
    List<T> heap; int size;
    int cmp = 1;
    int Compare(T x, T y) { return y.CompareTo(x); }
    public PriorityQueue() { heap = new List<T>(); }
    public PriorityQueue(int k) { heap = new List<T>(); cmp = k; }
    public void Enqueue(T x)
    {
        heap.Add(x);
        int i = size++;
        while (i > 0)
        {
            int p = (i - 1) >> 1;
            if (Compare(heap[p], x) * cmp <= 0) break;
            heap[i] = heap[p]; i = p;
        }
        heap[i] = x;
    }
    public T Dequeue()
    {
        T ret = heap[0]; T x = heap[--size];
        int i = 0;
        while ((i << 1) + 1 < size)
        {
            int a = (i << 1) + 1; int b = (i << 1) + 2;
            if (b < size && Compare(heap[b], heap[a]) * cmp < 0) a = b;
            if (Compare(heap[a], x) * cmp >= 0) break;
            heap[i] = heap[a]; i = a;
        }
        heap[i] = x; heap.RemoveAt(size);
        return ret;
    }
    public int Count { get { return size; } }
    public bool Any() { return size > 0; }
    public T Peek() { return heap[0]; }
}


