    PriorityQueue<Edge> Q;
    long[] A;
    long D;

    void dfs(int l, int r)
    {
        if (r <= l) return;
        int mid = (l + r) / 2;
        int idx = -1;
        long min = long.MaxValue;
        for (int i = mid + 1; i <= r; i++)
        {
            var cost = i * D + A[i];
            if (cost < min)
            {
                min = cost;
                idx = i;
            }
        }
        for (int i = l; i <= mid; i++)
        {
            Q.Enqueue(new Edge(i, idx, A[i] + A[idx] + D * Abs(i - idx)));
        }

        idx = -1;
        min = long.MaxValue;
        for (int i = l; i <= mid; i++)
        {
            var cost = -i * D + A[i];
            if (chmin(ref min, cost))
            {
                idx = i;
            }
        }
        for (int i = mid + 1; i <= r; i++)
        {
            //WriteLine(idx);
            Q.Enqueue(new Edge(i, idx, A[i] + A[idx] + D * Abs(i - idx)));
        }

        dfs(l, mid);
        dfs(mid + 1, r);
    }
