	public class SegmentTree<T>
	{
		private readonly int n_;
		private readonly T unit_;
		private readonly T[] tree_;
		private readonly Func<T, T, T> merge_;

		public int Count { get; }
		public T Top => tree_[1];

		public SegmentTree(int count, T unit, Func<T, T, T> merge)
		{
			merge_ = merge;
			unit_ = unit;

			Count = count;
			n_ = 1;
			while (n_ < count) {
				n_ <<= 1;
			}

			tree_ = new T[n_ << 1];
			for (int i = 0; i < tree_.Length; i++) {
				tree_[i] = unit;
			}
		}

		public SegmentTree(T[] src, T max, Func<T, T, T> merge)
			: this(src.Length, max, merge)
		{
			for (int i = 0; i < n_; ++i) {
				tree_[i + n_] = src[i];
			}

			for (int i = n_ - 1; i > 0; --i) {
				tree_[i] = merge_(tree_[i << 1], tree_[(i << 1) + 1]);
			}
		}

		public T this[int index]
		{
			get { return tree_[index + n_]; }
			set { Update(index, value); }
		}

		public void Update(int index, T val)
		{
			if (index >= Count) {
				return;
			}

			index += n_;
			tree_[index] = val;
			index >>= 1;
			while (index != 0) {
				tree_[index] = merge_(tree_[index << 1], tree_[(index << 1) + 1]);
				index >>= 1;
			}
		}

		public T Query(int l, int r)
		{
			if (l > r || r < 0 || l >= Count) {
				return unit_;
			}

			l += n_;
			r += n_;
			T minL = unit_;
			T minR = unit_;
			while (l < r) {
				if ((l & 1) != 0) {
					minL = merge_(minL, tree_[l]);
					++l;
				}
				if ((r & 1) != 0) {
					--r;
					minR = merge_(tree_[r], minR);
				}

				l >>= 1;
				r >>= 1;
			}

			return merge_(minL, minR);
		}
	}

	public class UnionFindTree
	{
		private readonly List<int> sizes_;
		private readonly List<int> parents_;

