class Program
{
    public static bool chmin<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == 1) { num = val; return true; } return false; }
    public static bool chmax<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == -1) { num = val; return true; } return false; }
    public static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        new Program().Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        int num;long d;
        Input.Make(out num, out d);
        var ar = Input.ar;
        var so = Enumerable.Range(0, num).Select(v => new Pair<int, int>(ar[v], v)).OrderBy(v => v).ToArray();
        var edge = new List<Pair<long, int, int>>();
        Func<Pair<long, int>, Pair<long, int>, Pair<long, int>> func =
            (a, b) => a.v1 > b.v1 ? b : a;
        var leftseg = new SegmentTree<Pair<long, int>>(num, new Pair<long, int>(long.MaxValue, -1), func);
        var rightseg = new SegmentTree<Pair<long, int>>(num, new Pair<long, int>(long.MaxValue, -1), func);
        for (var i = 0; i < num; i++)
        {
            leftseg.Update(i, new Pair<long, int>(ar[i] - i * d, i));
            rightseg.Update(i, new Pair<long, int>(ar[i] + i *d, i));
        }
        for (var i = d - 1; i >= 0; i--)
        {
            if (so[i].v2 != 0)
            {
                var min = leftseg.Query(0, so[i].v2);
                edge.Add(new Pair<long, int, int>(min.v1 + so[i].v2 * d + so[i].v1, so[i].v2, min.v2));
                leftseg.Update(so[i].v2, new Pair<long, int>(long.MaxValue, -1));
            }
            if (so[i].v2 != num - 1)
            {
                var min = rightseg.Query(so[i].v2 + 1,num);
                edge.Add(new Pair<long, int, int>(min.v1 - so[i].v2 * d + so[i].v1, so[i].v2, min.v2));
                rightseg.Update(so[i].v2, new Pair<long, int>(long.MaxValue, -1));
            }
        }
        edge.Sort();
        var uf = new UnionFind(num);
        var res = 0L;
        foreach (var e in edge)
            if (!uf.IsSame(e.v2, e.v3))
            {
                res += e.v1;
                uf.Union(e.v2, e.v3);
            }
        WriteLine(res);
    }
}

public class UnionFind
{
    private int[] _parent, _size, _rank;
    public UnionFind(int num)
    {
        IndependenceNum = num;
        _parent = new int[num]; _size = new int[num]; _rank = new int[num];
        for (var i = 0; i < num; i++) { _parent[i] = i; _size[i] = 1; }
    }
    //独立な集合の数
    public int IndependenceNum { get; private set; }
    private int Find(int i)
        => i == _parent[i] ? i : (_parent[i] = Find(_parent[i]));
    public int Parent(int i)
        => Find(i);
    public int Size(int i)
        => _size[Find(i)];
    public bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        IndependenceNum--;
        if (_rank[v1] > _rank[v2])
        {
            _parent[v2] = v1;
            _size[v1] += _size[v2];
        }
        else
        {
            _parent[v1] = v2;
            _size[v2] += _size[v1];
            if (_rank[v1] == _rank[v2])
                _rank[v2]++;
        }
        return true;
    }
    public bool IsSame(int v1, int v2)
        => Find(v1) == Find(v2);
}

public class SegmentTree<T>
{
    protected readonly T[] item;
    protected readonly int num;
    protected readonly Func<T, T, T> func;
    protected readonly Func<T, T, T> updateFunc;
    protected readonly T init;

    protected int Parent(int index)
        => (index - 1) >> 1;
    protected int Left(int index)
        => (index << 1) + 1;
    protected int Right(int index)
        => (index + 1) << 1;
    public T this[int i]
    {
        get { return item[i + num - 1]; }
        set { item[i + num - 1] = value; }
    }

    public SegmentTree(int num, T init, Func<T, T, T> func, Func<T, T, T> updateFunc = null)
    {
        this.func = func;
        this.num = 1;
        this.init = init;
        this.updateFunc = updateFunc ?? ((T val1, T val2) => val2);
        while (this.num <= num)
            this.num *= 2;
        item = new T[2 * this.num - 1];
        for (var i = 0; i < 2 * this.num - 1; i++)
            item[i] = init;
    }
    public void Update(int index, T value)
    {
        index += num - 1;
        item[index] = updateFunc(item[index], value);
        while (index > 0)
        {
            index = Parent(index);
            item[index] = func(item[Left(index)], item[Right(index)]);
        }
    }
    public virtual void Update(int left, int right, T value)
        => Update(left, right, 0, 0, num, value);
    protected virtual void Update(int left, int right, int k, int l, int r, T value)
    {
        if (r <= left || right <= l) return;
        if (left <= l && r <= right) item[k] = updateFunc(item[k], value);
        else
        {
            Update(left, right, Left(k), l, (l + r) >> 1, value);
            Update(left, right, Right(k), (l + r) >> 1, r, value);
        }
    }
    public void All_Update()
    {
        for (int i = num - 2; i >= 0; i--)
            item[i] = func(item[Left(i)], item[Right(i)]);
    }
    public T Query(int index)
    {
        index += num - 1;
        var value = func(init, item[index]);
        while (index > 0)
        {
            index = Parent(index);
            value = func(value, item[index]);
        }
        return value;
    }
    //[left,right)
    public virtual T Query(int left, int right)
        => Query(left, right, 0, 0, num);
    protected virtual T Query(int left, int right, int k, int l, int r)
    {
        if (r <= left || right <= l) return init;
        if (left <= l && r <= right) return item[k];
        else
            return func(Query(left, right, Left(k), l, (l + r) >> 1), Query(left, right, Right(k), (l + r) >> 1, r));
    }
}

