class Program
{
    static void Main()
    {
        //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        new Program().solve();
        Out.Flush();
    }
    readonly Scanner cin = new Scanner();
    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;
    readonly int dom = 998244353;
    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    List<Edge> Q;
    long[] A;
    long D;

    void dfs(int l, int r)
    {
        if (r <= l) return;
        int mid = (l + r) / 2;
        int idx = -1;
        long min = long.MaxValue;
        for (int i = mid + 1; i <= r; i++)
        {
            var cost = i * D + A[i];
            if (cost < min)
            {
                min = cost;
                idx = i;
            }
        }
        for (int i = l; i <= mid; i++)
        {
            Q.Add(new Edge(i, idx, A[i] + A[idx] + D * Abs(i - idx)));
        }

        idx = -1;
        min = long.MaxValue;
        for (int i = l; i <= mid; i++)
        {
            var cost = -i * D + A[i];
            if (chmin(ref min, cost))
            {
                idx = i;
            }
        }
        for (int i = mid + 1; i <= r; i++)
        {
            //WriteLine(idx);
            Q.Add(new Edge(i, idx, A[i] + A[idx] + D * Abs(i - idx)));
        }

        dfs(l, mid);
        dfs(mid + 1, r);
    }
    void solve()
    {
        int N = cin.nextint;
        D = cin.nextlong;
        A = cin.scanlong;
        Q = new List<Edge>();

        dfs(0, N - 1);


        var G = new DisjointSet(N);
        long ans = 0;
        Q.Sort();
        foreach(var d in Q)
        {
            if (!G.Same(d.from, d.to))
            {
                G.Unite(d.from, d.to);
                ans += d.cost;
            }
        }

        WriteLine(ans);
    }

}

