class Program
{
    public static bool chmin<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == 1) { num = val; return true; } return false; }
    public static bool chmax<T>(ref T num, T val) where T : IComparable<T>
    { if (num.CompareTo(val) == -1) { num = val; return true; } return false; }
    public static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        new Program().Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        int num;long d;
        Input.Make(out num, out d);
        var ar = Input.ar;
        var so = Enumerable.Range(0, num).Select(v => new Pair<int, int>(ar[v], v)).ToArray();
        Array.Sort(so);

        Func<int, int[], Pair<long, int>[]> f = (a, b) =>
          {
              var p = Input.create(a, _ => new Pair<long, int>(long.MaxValue, -1));
              var p1 = new Pair<long, int>(long.MaxValue, -1);
              var p2 = new Pair<long, int>(long.MaxValue, -1);

              for(var i=0;i<num;i++)
              {
                  if(p1.v2!=-1&&p1.v2!=b[i])
                  {
                      var dist = p1.v1 + i * d + ar[i];
                      if (p[b[i]].v1 > dist)
                          p[b[i]] = new Pair<long, int>(dist, p1.v2);
                  }else if (p2.v2 != -1 && p2.v2 != b[i])
                  {
                      var dist = p2.v1 + i * d + ar[i];
                      if (p[b[i]].v1 > dist)
                          p[b[i]] = new Pair<long, int>(dist, p2.v2);
                  }
                  var tm = new Pair<long, int>(ar[i] - i * d, b[i]);
                  if (p1.v2 == -1 || p1.v1 > tm.v1)
                  {
                      if (p1.v2 != tm.v2) p2 = p1;
                      p1 = tm;
                  }
                  else if (p2.v2 == -1 || (p1.v2 != b[i] && p2.v1 > tm.v1))
                      p2 = tm;
              }
              p1 = new Pair<long, int>(long.MaxValue, -1);
              p2 = new Pair<long, int>(long.MaxValue, -1);
              for (var i = num-1; i >= 0; i--)
              {
                  if (p1.v2 != -1 && p1.v2 != b[i])
                  {
                      var dist = p1.v1 - i * d + ar[i];
                      if (p[b[i]].v1 > dist)
                          p[b[i]] = new Pair<long, int>(dist, p1.v2);
                  }
                  else if (p2.v2 != -1 && p2.v2 != b[i])
                  {
                      var dist = p2.v1 - i * d + ar[i];
                      if (p[b[i]].v1 > dist)
                          p[b[i]] = new Pair<long, int>(dist, p2.v2);
                  }
                  var tm = new Pair<long, int>(ar[i] + i * d, b[i]);
                  if (p1.v2 == -1 || p1.v1 > tm.v1)
                  {
                      if (p1.v2 != tm.v2) p2 = p1;
                      p1 = tm;
                  }
                  else if (p2.v2 == -1 || (p1.v2 != b[i] && p2.v1 > tm.v1))
                      p2 = tm;
              }
              return p;
          };
        WriteLine(Boruvka(num, f));
    }
    public static long Boruvka(int num, Func<int, int[], Pair<long, int>[]> func)
    {
        var uf = new UnionFind(num);
        var res = 0L;
        var rev = new int[num];
        var parent = new int[num];
        while (true)
        {
            var update = false;
            var c = 0;
            for (var i = 0; i < num; i++)
                if (i == uf.Parent(i))
                {
                    rev[c] = i;
                    parent[i] = c++;
                }
            for (var i = 0; i < num; i++)
                parent[i] = parent[uf.Parent(i)];
            var pair = func(c, parent);
            for (var i = 0; i < c; i++)
                if (pair[i].v2 != -1 && !uf.IsSame(rev[pair[i].v2], rev[i]))
                {
                    uf.Union(rev[pair[i].v2], rev[i]);
                    res += pair[i].v1;
                    update = true;
                }
            if (!update) break;
        }
        return res;
    }
}

public class UnionFind
{
    private int[] _parent, _size, _rank;
    public UnionFind(int num)
    {
        IndependenceNum = num;
        _parent = new int[num]; _size = new int[num]; _rank = new int[num];
        for (var i = 0; i < num; i++) { _parent[i] = i; _size[i] = 1; }
    }
    //独立な集合の数
    public int IndependenceNum { get; private set; }
    private int Find(int i)
        => i == _parent[i] ? i : (_parent[i] = Find(_parent[i]));
    public int Parent(int i)
        => Find(i);
    public int Size(int i)
        => _size[Find(i)];
    public bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        IndependenceNum--;
        if (_rank[v1] > _rank[v2])
        {
            _parent[v2] = v1;
            _size[v1] += _size[v2];
        }
        else
        {
            _parent[v1] = v2;
            _size[v2] += _size[v1];
            if (_rank[v1] == _rank[v2])
                _rank[v2]++;
        }
        return true;
    }
    public bool IsSame(int v1, int v2)
        => Find(v1) == Find(v2);
}

