        return Math.Abs(city1 - city2) * d + city[city1] + city[city2];
    }
    public void Slove()
    {
        string[] inputs = Console.ReadLine().Split();
        int n = int.Parse(inputs[0]);
        long d = int.Parse(inputs[1]);
        int[] city = 
            Console.ReadLine().Split()
            .Select(int.Parse).ToArray();
        //long[][] distance =
