        //        distance[j][i] = distance[i][j];
        //    }
        //}
        bool[] conect = new bool[n];
        conect[0] = true; 
        long cost = 0;
        long[] dp = 
            Enumerable.Range(0, n)
            .Select(x => GetDistance(0, x, city, d)).ToArray();
        foreach(int j in Enumerable.Range(0, n - 1))
        {
            int next = 
                Enumerable.Range(0, n) 
                .Where(x => !conect[x])
                .Aggregate(0, (ret, index) => 
                    dp[index] > dp[ret] ? ret : index);
