			long d = cin.Long();
			long[] a = cin.ArrayLong(n);
			int[] ai = Enumerable.Range(0, n).OrderBy(x => a[x]).ToArray();
			var RSeg = new SegmentTree<Tuple<long, int>>(n, new Tuple<long, int>(long.MaxValue, -1), Merge);
			var LSeg = new SegmentTree<Tuple<long, int>>(n, new Tuple<long, int>(long.MaxValue, -1), Merge);

			var edge = new List<Edge>();
			for (int i = 0; i < n; i++) {
				int pos = ai[i];
				var cost = a[pos];

				var r = RSeg.Query(pos, n).Item2;
				if (r != -1) {
					edge.Add(new Edge(pos, r, cost + a[r] + d * Math.Abs(pos - r)));
				}

				var l = LSeg.Query(0, pos + 1).Item2;
				if (l != -1) {
					edge.Add(new Edge(pos, l, cost + a[l] + d * Math.Abs(pos - l)));
				}

				RSeg.Update(pos, new Tuple<long, int>(cost + d * pos, pos));
				LSeg.Update(pos, new Tuple<long, int>(cost - d * pos, pos));
			}

			var uf = new UnionFindTree(n);
			long ans = 0;
			var edge2 = edge.OrderBy(x => x.Cost).ToArray();
			foreach (var e in edge2) {
				if (uf.IsUnited(e.From, e.To) == false) {
