            var r = S.Run(pos, N - 1).s;
            if(r != -1)
            {
                Q.Add(new Edge(pos, r, cost + B[r] + D * Abs(pos - r)));
            }
            var l = T.Run(0, pos).s;
            if (l != -1)
            {
                Q.Add(new Edge(pos, l, cost + B[l] + D * Abs(pos - l)));
            }
            S.Update(pos, new pair(cost + D * pos, pos));
            T.Update(pos, new pair(cost - D * pos, pos));
        }

        var U = new DisjointSet(N);
        long ans = 0;
        Q.Sort();
        foreach(var d in Q)
        {
            if (!U.Same(d.from, d.to))
            {
                U.Unite(d.from, d.to);
                ans += d.cost;
            }
        }

        WriteLine(ans);
    }
    static pair merge(pair a, pair b)
    {
        return a.f < b.f ? a : b;
    }
}

class SegTree<T>
{
    readonly int n;
    int s, t;
    T[] tr;
    readonly Func<T, T, T> f;
    readonly T exnum;

    /// <summary>
    ///  セグメントツリーの構築1
    /// </summary>
    /// <param name="m">要素数</param>
    /// <param name="f">マージ関数</param>
    /// <param name="ex">単位元</param>
    public SegTree(int m, Func<T, T, T> f, T ex)
    {
        this.f = f; exnum = ex; n = 1;
        while (n < m) n <<= 1;
        tr = new T[(n << 1) - 1];
        for (int i = 0; i < tr.Length; i++) tr[i] = ex;
    }
    /// <summary>
    /// セグメントツリーの構築2
    /// </summary>
    /// <param name="m">要素数</param>
    /// <param name="f">マージ関数</param>
    /// <param name="ex">単位元</param>
    /// <param name="ini">初期値 <typeparamref name="T"/>? </param>
    public SegTree(int m, Func<T, T, T> f, T ex, T ini) : this(m, f, ex)
    {
        for (int i = 0; i < m; ++i) Assign(i, ini);
        All_Update();
    }
    /// <summary>
    /// セグメントツリーの構築3
    /// </summary>
    /// <param name="m">要素数</param>
    /// <param name="f">マージ関数</param>
    /// <param name="ex">単位元</param>
    /// <param name="ini">初期値 IList<typeparamref name="T"/>? </param>
    public SegTree(int m, Func<T, T, T> f, T ex, IList<T> ini) : this(m, f, ex)
    {
        for (int i = 0; i < m; ++i) Assign(i, ini[i]);
        All_Update();
    }
    /// <summary>
    /// 最下層に値の代入
    /// </summary>
    /// <param name="j">代入するインデックス</param>
    /// <param name="x">代入する値</param>
    public void Assign(int j, T x) => tr[j + n - 1] = x;
    /// <summary>
    /// 代入して更新
    /// </summary>
    /// <param name="j">インデックス</param>
    /// <param name="x">値</param>
    public void Update(int j, T x)
    {
        Assign(j, x);
        Update(j);
    }
    public void Update(int j)
    {
        int i = j + n - 1;
        while (i > 0) { i = i - 1 >> 1; tr[i] = f(tr[i << 1 | 1], tr[i + 1 << 1]); }
    }
    public void All_Update() { for (int i = n - 2; i >= 0; i--) tr[i] = f(tr[i << 1 | 1], tr[i + 1 << 1]); }
    public T Look(int j) => tr[j + n - 1];
    public T Peek() => tr[0];

    ///<summary>return node[s, t]</summary>
    public T Run(int s, int t) { t++; this.s = s; this.t = t; return Query(0, 0, n); }
    T Query(int k, int l, int r) => r <= s || t <= l ? exnum : s <= l && r <= t ? tr[k]
                              : f(Query(k << 1 | 1, l, l + r >> 1), Query(k + 1 << 1, l + r >> 1, r));
}

