        A = cin.scanlong;
        Q = new List<Edge>();
        S = new SegTree<pair>(N, merge, new pair(long.MaxValue, -1), Enumerable.Range(0, N).Select(i => new pair(A[i] + i * D, i)).ToArray());
        T = new SegTree<pair>(N, merge, new pair(long.MaxValue, -1), Enumerable.Range(0, N).Select(i => new pair(A[i] - i * D, i)).ToArray());

        dfs(0, N - 1);

        var G = new DisjointSet(N);
        long ans = 0;
        Q.Sort();
        foreach(var d in Q)
        {
            if (!G.Same(d.from, d.to))
            {
                G.Unite(d.from, d.to);
                ans += d.cost;
            }
        }

        WriteLine(ans);
