class Program
{
    static void Main(string[] args)
    {
        Solve();
        //WriteLine(Solve());
    }
    static int[] ar;
    static void Solve()
    {
        var nd = Pair<int,long>.makePair();
        ar = Input.ar;
        var so = Enumerable.Range(0, nd.v1).Select(v => new Pair<int, int>(ar[v], v)).OrderBy(v=>v).ToArray();
        var edge = new List<Pair<long, int, int>>();
        Func<Pair<long, int>, Pair<long, int>, Pair<long, int>> func =
            (a, b) => a.v1 > b.v1 ? b : a;
        var leftseg = new SegmentTree<Pair<long,int>>(nd.v1, new Pair<long, int>(long.MaxValue,-1), func);
        var rightseg = new SegmentTree<Pair<long,int>>(nd.v1, new Pair<long, int>(long.MaxValue,-1), func);
        for(var i = 0; i < nd.v1; i++)
        {
            leftseg.Update(i, new Pair<long, int>(ar[i] - i * nd.v2,i));
            rightseg.Update(i, new Pair<long, int>(ar[i] + i * nd.v2,i));
        }
        for(var i = nd.v1-1; i >= 0; i--)
        {
            if (so[i].v2 != 0)
            {
                var min = leftseg.Query(0, so[i].v2);
                edge.Add(new Pair<long, int, int>(min.v1 + so[i].v2 * nd.v2 + so[i].v1, so[i].v2, min.v2));
                leftseg.Update(so[i].v2, new Pair<long, int>(long.MaxValue,-1));
            }
            if (so[i].v2 != nd.v1 - 1)
            {
                var min = rightseg.Query(so[i].v2 + 1, nd.v1);
                edge.Add(new Pair<long, int, int>(min.v1 - so[i].v2 * nd.v2 + so[i].v1, so[i].v2, min.v2));
                rightseg.Update(so[i].v2, new Pair<long, int>(long.MaxValue, -1));
            }
        }
        edge.Sort();
        var uf = UnionFind<int>.Make(nd.v1);
        var res = 0L;
        foreach (var e in edge)
            if (!uf.IsSame(e.v2, e.v3))
            {
                res += e.v1;
                uf.Union(e.v2, e.v3);
            }
        WriteLine(res);
    }
}

