enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

void main() {
  long N, D;
  scanln(N, D);
  long[] as = readln.split.to!(long[]);

  if (N == 1) {
    0.writeln;
    return;
  }

  auto seg1 = RMQ!long(
    N.iota.map!(i => as[i] - i*D).array
  );
  auto seg2 = RMQ!long(
    N.iota.map!(i => as[i] + i*D).array
  );

  struct Edge {
    size_t i, j;
    long cost;
    int num;
  }
  auto tree = redBlackTree!(
    "a.cost != b.cost ? a.cost < b.cost : a.i != b.i ? a.i < b.i : a.j < b.j",
    true,
    Edge
  )();

  {
    long i = 0;
    long j = seg2.queryIndex(i+1, N);
    tree.insert(Edge(i, j, seg2.get(j) - i*D + as[i], 2));
  }

  long ans = 0;
  bool[] bs = new bool[N];
  bs[0] = true;
  seg1.update(0, long.max);
  seg2.update(0, long.max);

  Edge[][] ess = new Edge[][N];
  while(!tree.empty) {
    Edge e = tree.front;
    tree.removeFront;

    if (bs[e.i] && bs[e.j]) continue;

    assert(bs[e.i] && !bs[e.j]);
    ans += e.cost;
    bs[e.j] = true;
    seg1.update(e.j, long.max);
    seg2.update(e.j, long.max);

    foreach(f; ess[e.j]) {
      if (f.i > 0 && f.num == 1) {
        long v = seg1.query(0, f.i);
        if (v < long.max) {
          long j = seg1.queryIndex(0, f.i);
          Edge g = Edge(f.i, j, v + f.i*D + as[f.i], 1);
          tree.insert(g);
          ess[j] ~= g;
        }
      }
      if (f.i < N-1 && f.num == 2) {
        long v = seg2.query(f.i+1, N);
        if (v < long.max) {
          long j = seg2.queryIndex(f.i+1, N);
          Edge g = Edge(f.i, j, v - f.i*D + as[f.i], 2);
          tree.insert(g);
          ess[j] ~= g;
        }
      }
    }

    if (e.j > 0) {
      long v = seg1.query(0, e.j);
      if (v < long.max) {
        long j = seg1.queryIndex(0, e.j);
        Edge f = Edge(e.j, j, v + e.j*D + as[e.j], 1);
        tree.insert(f);
        ess[j] ~= f;
      }
    }
    if (e.j < N-1) {
      long v = seg2.query(e.j+1, N);
      if (v < long.max) {
        long j = seg2.queryIndex(e.j+1, N);
        Edge f = Edge(e.j, j, v - e.j*D + as[e.j], 2);
        tree.insert(f);
        ess[j] ~= f;
      }
    }
  }

  ans.writeln;
}

// RMQ (Range Minimum Query)
alias RMQ(T) = SegTree!(T, (a, b) => a<b ? a:b, T.max);

// SegTree (Segment Tree)
struct SegTree(T, alias fun, T initValue)
  if (is(typeof(fun(T.init, T.init)) : T)) {

private:
  Node[] _data;
  size_t _size;
  size_t _l, _r;

public:
  // size ... データ数
  // initValue ... 初期値(例えばRMQだとINF)
  this(size_t size) {
    init(size);
  }

  // 配列で指定
  this(T[] ary) {
    init(ary.length);
    update(ary);
  }

  // O(N)
  void init(size_t size){
    _size = 1;
    while(_size < size) {
      _size *= 2;
    }
    _data.length = _size*2-1;
    _data[] = Node(size_t.max, initValue);
    _l = 0;
    _r = size;
  }

  // i番目の要素をxに変更
  // O(logN)
  void update(size_t i, T x) {
    size_t index = i;
    i += _size-1;
    _data[i] = Node(index, x);
    while(i > 0) {
      i = (i-1)/2;
      Node nl = _data[i*2+1];
      Node nr = _data[i*2+2];
      _data[i] = select(nl, nr);
    }
  }

  // 配列で指定
  // O(N)
  void update(T[] ary) {
    foreach(i, e; ary) {
      _data[i+_size-1] = Node(i, e);
    }
    foreach(i; (_size-1).iota.retro) {
      Node nl = _data[i*2+1];
      Node nr = _data[i*2+2];
      _data[i] = select(nl, nr);
    }
  }

  // 区間[a, b)でのクエリ (値の取得)
  // O(logN)
  T query(size_t a, size_t b) {
    return queryRec(a, b, 0, 0, _size).value;
  }

  // 区間[a, b)でのクエリ (indexの取得)
  // O(logN)
  size_t queryIndex(size_t a, size_t b) out(result) {
    // fun == (a, b) => a+b のようなときはindexを聞くとassertion
    assert(result != size_t.max);
  } body {
    return queryRec(a, b, 0, 0, _size).index;
  }

  private Node queryRec(size_t a, size_t b, size_t k, size_t l, size_t r) {
    if (b<=l || r<=a) return Node(size_t.max, initValue);
    if (a<=l && r<=b) return _data[k];
    Node nl = queryRec(a, b, k*2+1, l, (l+r)/2);
    Node nr = queryRec(a, b, k*2+2, (l+r)/2, r);
    return select(nl, nr);
  }

  private Node select(Node nl, Node nr) {
    T v = fun(nl.value, nr.value);
    if (nl.value == v) {
      return nl;
    } else if (nr.value == v) {
      return nr;
    } else {
      return Node(size_t.max, v);
    }
  }

  // O(1)
  T get(size_t i) {
    return _data[_size-1 + i].value;
  }

  // O(N)
  T[] array() {
    return _data[_l+_size-1.._r+_size-1].map!"a.value".array;
  }

private:
  struct Node {
    size_t index;
    T value;
  }
}


