enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

// RMQ (Range Minimum Query)
alias RMQ(T) = SegTree!(T, (a, b) => a<b ? a:b, INF);

// O(N log^2 N) 解法
//   with Borůvka's algorithm (ブルーフカ法)
void main() {
  long N, D;
  scanln(N, D);
  long[] as = readln.split.to!(long[]);

  auto seg1 = RMQ!long(
    N.iota.map!(i => as[i] - i*D).array
  );
  auto seg2 = RMQ!long(
    N.iota.map!(i => as[i] + i*D).array
  );

  auto uf = UnionFind(N);
  long ans = 0;

  bool updated = true;
  long[][] indss = new long[][N];
  while(updated) {
    updated = false;
    foreach(i; 0..N) indss[i].length = 0;
    foreach(i; 0..N) {
      indss[uf.findSet(i)] ~= i;
    }

    foreach(i; 0..N) {
      if (!uf.isRoot(i)) continue;
      foreach(ind; indss[i]) {
        seg1.update(ind, INF);
        seg2.update(ind, INF);
      }
      long minS = -1;
      long minT = -1;
      long minV = INF;
      foreach(ind; indss[i]) {
        long x1 = seg1.query(0, ind);
        if (x1 < INF) {
          long v1 = v1 + ind*D + as[ind];
          if (v1 < minV) {
            minV = v1
            minS = ind;
            minT = seg1.queryIndex(0, ind);
          }
        }
        long x2 = seg2.query(ind+1, N);
        if (x2 < INF) {
          long v2 = v2 - ind*D + as[ind];
          if (v2 < minV) {
            minV = v2;
            minS = ind;
            minT = seg2.queryIndex(ind+1, N);
          }
        }
      }
      if (minS != -1) {
        updated = true;
        if (!uf.same(minS, minT)) {
          ans += minV;
          uf.unite(minS, minT);
        }
      }
      foreach(ind; indss[i]) {
        seg1.update(ind, as[ind] - ind*D);
        seg2.update(ind, as[ind] + ind*D);
      }
    }
  }

  ans.writeln;
}


struct UnionFind {

private:
  Vertex[] _vertices;

public:
  this(size_t size) {
    init(size);
  }

  void init(size_t size) {
    _vertices.length = size;
    foreach(i, ref v; _vertices) {
      v.index = i;
      v.parent = i;
    }
  }

  void unite(size_t x, size_t y) {
    link(findSet(x), findSet(y));
  }

  void link(size_t x, size_t y) {
    if (x==y) return;
    if (_vertices[x].rank > _vertices[y].rank) {
      _vertices[y].parent = x;
    } else {
      _vertices[x].parent = y;
      if (_vertices[x].rank == _vertices[y].rank) {
        _vertices[y].rank++;
      }
    }
  }

  bool same(size_t x, size_t y) {
    return findSet(x) == findSet(y);
  }

  size_t findSet(size_t index) {
    if (_vertices[index].parent == index) {
      return index;
    } else {
      return _vertices[index].parent = findSet(_vertices[index].parent);
    }
  }

  bool isRoot(size_t index) {
    return findSet(index) == index;
  }

private:
  struct Vertex {
    size_t index;
    size_t parent;
    size_t rank = 1;
  }
}

// SegTree (Segment Tree)
struct SegTree(T, alias fun, T initValue)
  if (is(typeof(fun(T.init, T.init)) : T)) {

private:
  Node[] _data;
  size_t _size;
  size_t _l, _r;

public:
  // size ... データ数
  // initValue ... 初期値(例えばRMQだとINF)
  this(size_t size) {
    init(size);
  }

  // 配列で指定
  this(T[] ary) {
    init(ary.length);
    update(ary);
  }

  // O(N)
  void init(size_t size){
    _size = 1;
    while(_size < size) {
      _size *= 2;
    }
    _data.length = _size*2-1;
    _data[] = Node(size_t.max, initValue);
    _l = 0;
    _r = size;
  }

  // i番目の要素をxに変更
  // O(logN)
  void update(size_t i, T x) {
    size_t index = i;
    i += _size-1;
    _data[i] = Node(index, x);
    while(i > 0) {
      i = (i-1)/2;
      Node nl = _data[i*2+1];
      Node nr = _data[i*2+2];
      _data[i] = select(nl, nr);
    }
  }

  // 配列で指定
  // O(N)
  void update(T[] ary) {
    foreach(i, e; ary) {
      _data[i+_size-1] = Node(i, e);
    }
    foreach(i; (_size-1).iota.retro) {
      Node nl = _data[i*2+1];
      Node nr = _data[i*2+2];
      _data[i] = select(nl, nr);
    }
  }

  // 区間[a, b)でのクエリ (値の取得)
  // O(logN)
  T query(size_t a, size_t b) {
    return queryRec(a, b, 0, 0, _size).value;
  }

  // 区間[a, b)でのクエリ (indexの取得)
  // O(logN)
  size_t queryIndex(size_t a, size_t b) out(result) {
    // fun == (a, b) => a+b のようなときはindexを聞くとassertion
    assert(result != size_t.max);
  } body {
    return queryRec(a, b, 0, 0, _size).index;
  }

  private Node queryRec(size_t a, size_t b, size_t k, size_t l, size_t r) {
    if (b<=l || r<=a) return Node(size_t.max, initValue);
    if (a<=l && r<=b) return _data[k];
    Node nl = queryRec(a, b, k*2+1, l, (l+r)/2);
    Node nr = queryRec(a, b, k*2+2, (l+r)/2, r);
    return select(nl, nr);
  }

  private Node select(Node nl, Node nr) {
    T v = fun(nl.value, nr.value);
    if (nl.value == v) {
      return nl;
    } else if (nr.value == v) {
      return nr;
    } else {
      return Node(size_t.max, v);
    }
  }

  // O(1)
  T get(size_t i) {
    return _data[_size-1 + i].value;
  }

  // O(N)
  T[] array() {
    return _data[_l+_size-1.._r+_size-1].map!"a.value".array;
  }

private:
  struct Node {
    size_t index;
    T value;
  }
}


