// O(N\log N)解法
//   ボロノイ + MST
void main() {
  long N, D;
  scanln(N, D);
  long[] as = readln.split.to!(long[]);

  struct Event {
    long i, j;
    long t;
  }
  auto tree = N.iota.map!(
    i => Event(i, i, as[i])
  ).array.redBlackTree!(
    "a.t!=b.t ? a.t<b.t : a.i!=b.i ? a.i<b.i : a.j<b.j",
    true,
    Event
  );

  long[] bs = new long[N];
  bs[] = -1;
  while(!tree.empty) {
    Event e = tree.front;
    tree.removeFront;
    if (bs[e.j] < 0) {
      bs[e.j] = e.i;
      if (e.j>0) {
        tree.insert(
          Event(e.i, e.j-1, e.t+D)
        );
      }
      if (e.j<N-1) {
        tree.insert(
          Event(e.i, e.j+1, e.t+D)
        );
      }
    }
  }
  assert(bs.all!"a>=0");

  auto prim = Prim!long(N);
  foreach(i; 0..N) {
    if (bs[i] != i) {
      prim.addEdge(
        i, bs[i],
        as[i] + as[bs[i]] + D*abs(i - bs[i])
      );
    }
  }
  foreach(i; 1..N) {
    if (bs[i-1] != bs[i]) {
      prim.addEdge(
        bs[i-1], bs[i],
        as[bs[i-1]] + as[bs[i]] + D*abs(bs[i-1] - bs[i])
      );
    }
  }
  prim.solve.writeln;
}

// プリム法
// O(E+VlogV)
// 無向グラフの最小全域木問題
struct Prim(T, T inf = T.max) {

private:
  Vertex[] _vertices;

public:
  this(size_t size) {
    _vertices.length = size;
    foreach(i; 0..size) {
      _vertices[i] = new Vertex(i);
    }
  }

  void addEdge(size_t start, size_t end, T weight) {
    _vertices[start].edges ~= Edge(start, end, weight);
    _vertices[end].edges   ~= Edge(end, start, weight);
  }

  T solve() {
    _vertices.front.cost = 0;
    auto tree = redBlackTree!(
      "a.cost==b.cost ? a.index<b.index : a.cost<b.cost",
      true,
      Vertex
    )(_vertices.front);
    while(!tree.empty) {
      Vertex v = tree.front;
      v.used = true;
      tree.removeFront;
      v.edges.each!((Edge e) {
        if (_vertices[e.end].used) return;
        tree.removeKey(_vertices[e.end]);
        _vertices[e.end].cost = min(_vertices[e.end].cost, e.weight);
        tree.insert(_vertices[e.end]);
      });
    }
    return _vertices.map!"a.cost".sum;
  }

private:
  class Vertex {
    size_t index;
    bool used;
    T cost = inf;
    Edge[] edges;
    this(size_t index) {
      this.index = index;
    }
    override string toString() const {return "";} // for old compilers
  }
  struct Edge {
    size_t start;
    size_t end;
    T weight;
  }
}


