immutable INF = 10L^^18;

int N;
long D;
long[] A;

void main() {
  try {
    for (; ; ) {
      N = readInt();
      D = readLong();
      A = new long[N];
      foreach (u; 0 .. N) {
        A[u] = readLong();
      }

      BinaryHeap!(Array!(Tuple!(long, int, int)), "a > b") q;
      auto dist = new long[N];
      auto ss = new int[N];
      dist[] = INF;
      ss[] = -1;
      foreach (u; 0 .. N) {
        q.insert(tuple!(long, int, int)(A[u], u, u));
      }
      for (; !q.empty; ) {
        const c = q.front[0];
        const u = q.front[1];
        const s = q.front[2];
        q.popFront;
        if (ss[u] == -1) {
          dist[u] = c;
          ss[u] = s;
          foreach (du; [+1, -1]) {
            const v = u + du;
            if (0 <= v && v < N) {
              q.insert(tuple!(long, int, int)(c + D, v, s));
            }
          }
        }
      }
      debug {
        writefln("dist = %s", dist);
        writefln("ss = %s", ss);
      }

      long cost(int u, int v) {
        return abs(u - v) * D + A[u] + A[v];
      }
      long ans;
      foreach (u; 0 .. N) {
        if (u != ss[u]) {
          ans += cost(u, ss[u]);
        }
      }
      foreach (u; 0 .. N - 1) {
        if (ss[u] != ss[u + 1]) {
          ans += cost(ss[u], ss[u + 1]);
        }
      }
      writeln(ans);
    }
  } catch (EOFException e) {
  }
}

