enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

// RMQ (Range Minimum Query)
alias RMQ(T) = SegTree!(T, (a, b) => a<b ? a:b, INF, false);

// O(N log^2 N) 解法
//   with Borůvka's algorithm (ブルーフカ法)
void main() {
  long N, D;
  scanln(N, D);
  long[] as = readln.split.to!(long[]);

  auto seg1 = RMQ!long(
    N.iota.map!(i => as[i] - i*D).array
  );
  auto seg2 = RMQ!long(
    N.iota.map!(i => as[i] + i*D).array
  );

  struct Edge {
    long s, t;
    long cost;
  }

  auto qf = QuickFind(N);
  long ans = 0;
  long cnt = 0;

  while(cnt < N-1) {
    Edge[] es = [];
    foreach(i; 0..N) {
      if (!qf.isRoot(i)) continue;
      size_t[] inds = qf.getSet(i);
      bool one = inds.length * log2(N) < N;
      if (one) {
        foreach(ind; inds) {
          seg1.update(ind, INF);
          seg2.update(ind, INF);
        }
      } else {
        long[] xs1 = seg1.array;
        long[] xs2 = seg2.array;
        foreach(ind; inds) {
          xs1[ind] = xs2[ind] = INF;
        }
        seg1.update(xs1);
        seg2.update(xs2);
      }
      long minS = -1;
      long minT = -1;
      long minV = INF;
      foreach(ind; inds) {
        auto p1 = seg1.queryPair(0, ind);
        if (p1.value < INF) {
          long v1 = p1.value + ind*D + as[ind];
          if (v1 < minV) {
            minV = v1;
            minS = ind;
            minT = p1.index;
          }
        }
        auto p2 = seg2.queryPair(ind+1, N);
        if (p2.value < INF) {
          long v2 = p2.value - ind*D + as[ind];
          if (v2 < minV) {
            minV = v2;
            minS = ind;
            minT = p2.index;
          }
        }
      }
      foreach(ind; inds) {
        seg1.update(ind, as[ind] - ind*D);
        seg2.update(ind, as[ind] + ind*D);
      }
      if (one) {
        foreach(ind; inds) {
          seg1.update(ind, as[ind] - ind*D);
          seg2.update(ind, as[ind] + ind*D);
        }
      } else {
        long[] xs1 = seg1.array;
        long[] xs2 = seg2.array;
        foreach(ind; inds) {
          xs1[ind] = as[ind] - ind*D;
          xs2[ind] = as[ind] + ind*D;
        }
        seg1.update(xs1);
        seg2.update(xs2);
      }
      if (minS != -1) {
        es ~= Edge(minS, minT, minV);
      }
    }

    foreach(e; es) {
      if (!qf.same(e.s, e.t)) {
        qf.unite(e.s, e.t);
        ans += e.cost;
        cnt++;
      }
    }
  }

  assert(cnt == N-1);
  ans.writeln;
}

