enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

// RMQ (Range Minimum Query)
alias RMQ(T) = SegTree!(T, (a, b) => a<b ? a:b, INF, false);

// O(N log^2 N) 解法
//   with Borůvka's algorithm (ブルーフカ法)
void main() {
  long N, D;
  scanln(N, D);
  long[] as = readln.split.to!(long[]);

  auto seg1 = RMQ!long(
    N.iota.map!(i => as[i] - i*D).array
  );
  auto seg2 = RMQ!long(
    N.iota.map!(i => as[i] + i*D).array
  );

  struct Edge {
    long s, t;
    long cost;
  }

  auto uf = UnionFind(N);
  long ans = 0;
  long cnt = 0;

  Edge[] es = [];
  while(cnt < N-1) {
    es.length = 0;
    foreach(i; 0..N) {
      if (!uf.isRoot(i)) continue;
      size_t[] inds = uf.getSet(i);
      foreach(ind; inds) {
        seg1.update(ind, INF);
        seg2.update(ind, INF);
      }
      long minS = -1;
      long minT = -1;
      long minV = INF;
      foreach(ind; inds) {
        auto p1 = seg1.queryPair(0, ind);
        if (p1.value < INF) {
          long v1 = p1.value + ind*D + as[ind];
          if (v1 < minV) {
            minV = v1;
            minS = ind;
            minT = p1.index;
          }
        }
        auto p2 = seg2.queryPair(ind+1, N);
        if (p2.value < INF) {
          long v2 = p2.value - ind*D + as[ind];
          if (v2 < minV) {
            minV = v2;
            minS = ind;
            minT = p2.index;
          }
        }
      }
      foreach(ind; inds) {
        seg1.update(ind, as[ind] - ind*D);
        seg2.update(ind, as[ind] + ind*D);
      }
      if (minS != -1) {
        es ~= Edge(minS, minT, minV);
      }
    }

    foreach(e; es) {
      if (!uf.same(e.s, e.t)) {
        uf.unite(e.s, e.t);
        ans += e.cost;
        cnt++;
      }
    }
  }

  assert(cnt == N-1);
  ans.writeln;
}


struct UnionFind {

private:
  Vertex[] _vertices;
  size_t[][] _indss;

public:
  this(size_t size) {
    init(size);
  }

  void init(size_t size) {
    _vertices.length = size;
    _indss.length = size;
    foreach(i, ref v; _vertices) {
      v.index = i;
      v.parent = i;
      _indss[i] = [i];
    }
  }

  void unite(size_t x, size_t y) {
    link(findSet(x), findSet(y));
  }

  void link(size_t x, size_t y) {
    if (x==y) return;
    if (_vertices[x].rank > _vertices[y].rank) {
      _vertices[y].parent = x;
      _indss[x] ~= _indss[y];
      _indss[y].length = 0;
    } else {
      _vertices[x].parent = y;
      _indss[y] ~= _indss[x];
      _indss[x].length = 0;
      if (_vertices[x].rank == _vertices[y].rank) {
        _vertices[y].rank++;
      }
    }
  }

  bool same(size_t x, size_t y) {
    return findSet(x) == findSet(y);
  }

  size_t findSet(size_t index) {
    if (_vertices[index].parent == index) {
      return index;
    } else {
      return _vertices[index].parent = findSet(_vertices[index].parent);
    }
  }

  bool isRoot(size_t index) {
    return _vertices[index].parent == index;
  }

  size_t[] getSet(size_t index) {
    return _indss[findSet(index)];
  }

private:
  struct Vertex {
    size_t index;
    size_t parent;
    size_t rank = 1;
  }
}


// SegTree (Segment Tree)
//    - with 1-based array
struct SegTree(T, alias fun, T initValue, bool structly = true)
  if (is(typeof(fun(T.init, T.init)) : T)) {

private:
  Node[] _data;
  size_t _size;
  size_t _l, _r;

public:
  // size ... データ数
  // initValue ... 初期値(例えばRMQだとINF)
  this(size_t size) {
    init(size);
  }

  // 配列で指定
  this(T[] ary) {
    init(ary.length);
    update(ary);
  }

  // O(N)
  void init(size_t size){
    _size = 1;
    while(_size < size) {
      _size *= 2;
    }
    _data.length = _size*2;
    _data[] = Node(size_t.max, initValue);
    _l = 0;
    _r = size;
  }

  // i番目の要素をxに変更
  // O(logN)
  void update(size_t i, T x) {
    size_t index = i;
    i += _size-1;
    _data[i] = Node(index, x);
    while(i > 0) {
      i >>= 1;
      Node nl = _data[i*2+0];
      Node nr = _data[i*2+1];
      _data[i] = select(nl, nr);
    }
  }

  // 配列で指定
  // O(N)
  void update(T[] ary) {
    foreach(i, e; ary) {
      _data[i+_size] = Node(i, e);
    }
    foreach(i; (_size-1).iota.retro) {
      Node nl = _data[i*2+0];
      Node nr = _data[i*2+1];
      _data[i] = select(nl, nr);
    }
  }

  // 区間[a, b)でのクエリ (valueの取得)
  // O(logN)
  T query(size_t a, size_t b) {
    Node node = accumulate(a, b);
    // Node node = queryRec(a, b, 0, 0, _size);
    return node.value;
  }

  // 区間[a, b)でのクエリ (indexの取得)
  // O(logN)
  size_t queryIndex(size_t a, size_t b) out(result) {
    // fun == (a, b) => a+b のようなときはindexを聞くとassertion
    if (structly) assert(result != size_t.max);
  } body {
    Node node = accumulate(a, b);
    // Node node = queryRec(a, b, 0, 0, _size);
    return node.index;
  }

  // 区間[a, b)でのクエリ ((index, value)の取得)
  // O(logN)
  Tuple!(size_t, "index", T, "value") queryPair(size_t a, size_t b) out(result) {
    // fun == (a, b) => a+b のようなときはindexを聞くとassertion
    if (structly) assert(result.index != size_t.max);
  } body {
    Node node = accumulate(a, b);
    // Node node = queryRec(a, b, 0, 0, _size);
    return tuple!("index", "value")(node.index, node.value);
  }

  private Node accumulate(size_t l, size_t r) {
    Node accl = Node(size_t.max, initValue);
    Node accr = Node(size_t.max, initValue);
    for (l += _size, r += _size; l < r; l >>= 1, r >>= 1) {
      if (l&1) accl = select(accl, _data[l++]);
      if (r&1) accr = select(accr, _data[r-1]);
    }
    return select(accl, accr);
  }

  // private Node queryRec(size_t a, size_t b, size_t k, size_t l, size_t r) {
  //   if (b<=l || r<=a) return Node(size_t.max, initValue);
  //   if (a<=l && r<=b) return _data[k];
  //   size_t c = (l+r)/2;
  //   Node nl = queryRec(a, b, k*2+0, l, c);
  //   Node nr = queryRec(a, b, k*2+1, c, r);
  //   return select(nl, nr);
  // }

  private Node select(Node nl, Node nr) {
    T v = fun(nl.value, nr.value);
    if (nl.value == v) {
      return nl;
    } else if (nr.value == v) {
      return nr;
    } else {
      return Node(size_t.max, v);
    }
  }

  // O(1)
  T get(size_t i) {
    return _data[_size + i].value;
  }

  // O(N)
  T[] array() {
    return _data[_l+_size.._r+_size].map!"a.value".array;
  }

private:
  struct Node {
    size_t index;
    T value;
  }
}

