    g = defaultdict(dict)
    for a, i in AA:

        l = st_l.query(0, i)
        r = st_r.query(i, N)
        if l[1] != -1:
            j = l[1]
            g[i][j] = D*(abs(i-j))+A[i]+A[j]
            g[j][i] = g[i][j]
        if r[1] != -1:
            j = r[1]
            g[i][j] = D*(abs(i-j))+A[i]+A[j]
            g[j][i] = g[i][j]
        st_r.update(i, (D*i+a,i))
        st_l.update(i, (D*(N-i)+a,i))


    return Prim(g)


