    st_l = SegmentTree(N)
    st_r = SegmentTree(N)
    g = defaultdict(dict)
    for a, i in AA:

        l = st_l.query(0, i)
        r = st_r.query(i, N)
        if l[1] != -1:
            j = l[1]
            g[i][j] = D*(abs(i-j))+A[i]+A[j]
