class SegmentTree:
    def __init__(self, n, func, default):
        self.n = pow(2, (n-1).bit_length())
        self.func = func
        self.default = default

        self.segtree = [default for _ in range(2*self.n-1)]

    def update(self, idx, value):
        idx += (self.n-1)
        self.segtree[idx] = value
        while idx > 0:
            idx = (idx-1) // 2
            self.segtree[idx] = self.func(self.segtree[2*idx+1],
                                          self.segtree[2*idx+2])

    def query(self, a, b, idx, l, r):
        if r <= a or b <= l:
            return self.default

        elif a <= l and r <= b:
            return self.segtree[idx]

        else:
            return self.func(self.query(a,b,2*idx+1,l,(l+r)//2),
                             self.query(a,b,2*idx+2,(l+r)//2,r))

    def between(self, a, b):
        return self.query(a,b,0,0,self.n)


    def reset(self):
        self.segtree = [self.default]*(2*self.n-1)


    def inarray(self, arr):
        for i, ai in enumerate(arr):
            idx = i + (self.n-1)
            self.update(idx, ai)

# クラスカル法
class UnionFind:
    def __init__(self, node:int) -> None:
        self.n = node
        self.par = [i for i in range(self.n)]
        self.rank = [0 for i in range(self.n)]

    def find(self, x:int) -> int:
        if x == self.par[x]:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def unite(self, x:int, y:int) -> bool:
        if self.isSame(x,y):
            #print("x and y has already united")
            return False

        rx = self.find(x)
        ry = self.find(y)

        if self.rank[rx] < self.rank[ry]:
            self.par[rx] = self.par[ry]
        else:
            self.par[ry] = self.par[rx]

            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1

        return True


    def isSame(self, x:int, y:int) -> bool:
        return self.find(x) == self.find(y)


# edgesは(cost, prev_node, nex_node)をE本格納しているリスト
def kruskal(edges: list, node_num: int) -> int:
    edges.sort(key=lambda x:x[0])

    uf = UnionFind(node_num)
    rem = node_num-1
    ans = 0
    for cost, prev, nex in edges:
        if uf.find(prev) != uf.find(nex):           
            uf.unite(prev, nex)
            ans += cost
            rem -= 1

        if rem == 0:
            break

    return ans

# セグメント木の判定関数
def segfunc(a:list, b:list):
    if a[0] > b[0]:
        return b
    else:
        return a


