    let mut done = vec![false; N];
    let mut Q = BinaryHeap::new();
    Q.push((Rev(0), 0));
    while let Some((Rev(w), v)) = Q.pop() {
        if done[v] {
            continue;
        }

        done[v] = true;
        W += w;

        for z in 0..N {
            if done[z] {
                continue;
            }

            let w = (z as i64 - v as i64).abs() * D + A[v] + A[z];
            Q.push((Rev(w), z));
        }
    }

    println!("{}", W)
}

