    let mut sc = Scanner { stdin: s.lock() };
    let n = sc.read();
    let d: i64 = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let left_side = a
        .iter()
        .cloned()
        .enumerate()
        .map(|(i, a)| ((n - i) as i64 * d + a, i))
        .collect::<Vec<_>>();
    let right_side = a
        .iter()
        .cloned()
        .enumerate()
        .map(|(i, a)| (i as i64 * d + a, i))
        .collect::<Vec<_>>();
    let left_table = SparseTable::from(&left_side, (0, 0), cmp::min);
    let right_table = SparseTable::from(&right_side, (0, 0), cmp::min);
    let mut candidates = vec![];
    for i in 0..n {
        if i > 0 {
            let (_, left) = left_table.get(0, i);
            let cost = (i - left) as i64 * d + a[i] + a[left];
            candidates.push((cost, left, i));
        }
        if i < n - 1 {
            let (_, right) = right_table.get(i + 1, n);
            let cost = (right - i) as i64 * d + a[i] + a[right];
            candidates.push((cost, i, right));
        }
    }
    candidates.sort();

    let mut uf = UnionFind::new(n);
    let mut ans = 0;
    for (cost, i, j) in candidates.into_iter() {
        if uf.find(i) != uf.find(j) {
            uf.unite(i, j);
            ans += cost;
        }
    }
    println!("{}", ans);
}

pub struct UnionFind {
    parent: Vec<usize>,
    sizes: Vec<usize>,
    size: usize,
}

impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        UnionFind {
            parent: (0..n).map(|i| i).collect::<Vec<usize>>(),
            sizes: vec![1; n],
            size: n,
        }
    }

    pub fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let px = self.parent[x];
            self.parent[x] = self.find(px);
            self.parent[x]
        }
    }

    pub fn unite(&mut self, x: usize, y: usize) -> bool {
        let parent_x = self.find(x);
        let parent_y = self.find(y);
        if parent_x == parent_y {
            return false;
        }

        let (large, small) = if self.sizes[parent_x] < self.sizes[parent_y] {
            (parent_y, parent_x)
        } else {
            (parent_x, parent_y)
        };

        self.parent[small] = large;
        self.sizes[large] += self.sizes[small];
        self.sizes[small] = 0;
        self.size -= 1;
        return true;
    }
}

pub mod sparse_table {
    use std::cmp;

    pub struct SparseTable<T, F> {
        data: Vec<Vec<T>>,
        op: F,
    }

    impl<T, F> SparseTable<T, F>
    where
        T: Copy,
        F: Fn(T, T) -> T,
    {
        pub fn from(v: &[T], init: T, op: F) -> Self {
            let size = v.len().next_power_of_two();
            let count = size.trailing_zeros() as usize + 1;
            let mut data = vec![vec![init; size]; count];
            for (i, v) in v.iter().cloned().enumerate() {
                data[0][i] = v;
            }
            for c in 1..count {
                for i in 0..size {
                    let next = cmp::min(size - 1, i + (1 << (c - 1)));
                    data[c][i] = op(data[c - 1][i], data[c - 1][next]);
                }
            }

            Self { data: data, op: op }
        }

        /// get the result for [l, r)
        pub fn get(&self, l: usize, r: usize) -> T {
            assert!(l < r);
            let length = r - l;
            if length == 1 {
                return self.data[0][l];
            }
            let block_size = length.next_power_of_two() >> 1;
            let c = block_size.trailing_zeros() as usize;
            let left = self.data[c][l];
            let right = self.data[c][r - block_size];
            (self.op)(left, right)
        }
    }
}
pub struct Scanner<R> {
    stdin: R,
