use std::cmp;

const INF: usize = 1e16 as usize;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n = sc.read();
    let d: usize = sc.read();
    let a: Vec<usize> = sc.vec(n);

    let mut left_seg = SegmentTree::new(n, (INF, 0), |a, b| cmp::min(a, b));
    let mut right_seg = SegmentTree::new(n, (INF, 0), |a, b| cmp::min(a, b));
    for i in 0..n {
        right_seg.update(i, (a[i] + i * d, i));
        left_seg.update(i, (a[i] + (n - i) * d, i));
    }

    let mut edges = vec![];
    for i in 0..n {
        if i > 0 {
            let (_, j) = left_seg.query(0, i);
            let cost = (i - j) * d + a[i] + a[j];
            edges.push((cost, i, j));
        }
        if i < n - 1 {
            let (_, j) = right_seg.query(i + 1, n);
            let cost = (j - i) * d + a[i] + a[j];
            edges.push((cost, i, j));
        }
    }
    edges.sort();

    let mut ans = 0;
    let mut uf = UnionFind::new(n);

    for (cost, i, j) in edges.into_iter() {
        if uf.find(i) == uf.find(j) {
            continue;
        }
        uf.unite(i, j);
        ans += cost;
    }

    assert_eq!(uf.sizes.into_iter().max().unwrap(), n);
    println!("{}", ans);
}

