#[derive(Eq, PartialEq, Ord, PartialOrd)]
struct Edge {
    cost: isize,
    from: usize,
    to: usize,
}

struct Solve {
    n: usize,
    d: isize,
    a: Vec<isize>,
}

impl Solve {
    fn rec(&self, l: usize, r: usize) -> Vec<Edge> {
        if r - l == 1 {
            return vec![];
        }
        let m = (l + r) / 2;
        // [l, m)
        // [m, r)
        let (_, li) = (l..m)
            .map(|i| (self.a[i] - self.d * i as isize, i))
            .min()
            .unwrap();
        let (_, ri) = (m..r)
            .map(|i| (self.a[i] + self.d * i as isize, i))
            .min()
            .unwrap();
        let mut res = self.rec(l, m);
        res.extend(self.rec(m, r));

        for i in l..m {
            let from = i;
            let to = ri;
            let cost = self.a[from] + self.a[to] + self.d * (to as isize - from as isize);
            res.push(Edge {
                cost: cost,
                from: from,
                to: to,
            });
        }
        for j in m..r {
            let from = li;
            let to = j;
            let cost = self.a[from] + self.a[to] + self.d * (to as isize - from as isize);
            res.push(Edge {
                cost: cost,
                from: from,
                to: to,
            });
        }
        res
    }

    fn solve(&self) {
        let mut edges = self.rec(0, self.n);
        edges.sort();
        let mut uf = UnionFind::new(self.n);
        let mut answer = 0;
        for e in edges {
            if uf.unite(e.from, e.to) {
                answer += e.cost;
            }
        }
        println!("{}", answer);
    }
}

fn run() {
    input! {
        n: usize,
        d: isize,
        a: [isize; n],
    }
    Solve { n: n, d: d, a: a }.solve();
}

