const INF: i32 = std::i32::MAX / 2;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };

    let n = sc.read();
    let d: i32 = sc.read();
    let p: Vec<i32> = sc.read_vec(n);
    let mut a = p
        .iter()
        .enumerate()
        .map(|(i, &a)| (a, i))
        .collect::<Vec<_>>();
    a.sort();
    let mut seg_l = SegmentTree::new(n, (INF, 0), |a, b| cmp::min(a, b));
    let mut seg_r = SegmentTree::new(n, (INF, 0), |a, b| cmp::min(a, b));
    let mut edges = vec![];
    for &(a, i) in a.iter() {
        let (left_a, left_i) = seg_l.query(0, i + 1);
        if left_a < INF {
            edges.push((left_i, i));
        }
        let (right_a, right_i) = seg_r.query(i, n);
        if right_a < INF {
            edges.push((i, right_i));
        }
        seg_l.update(i, ((n - i) as i32 * d + a, i));
        seg_r.update(i, (i as i32 * d + a, i));
    }

    let mut edges = edges
        .iter()
        .map(|&(i, j)| {
            assert!(i < j);
            let cost = (j - i) as i32 * d + p[i] + p[j];
            (cost, i, j)
        })
        .collect::<Vec<_>>();
    edges.sort();

    let mut uf = UnionFind::new(n);
    let mut ans = 0;
    for &(cost, i, j) in edges.iter() {
        if uf.find(i) != uf.find(j) {
            uf.unite(i, j);
            ans += cost;
        }
    }
    println!("{}", ans);
}
