/**
 * Union-Find tree.
 * Verified by yukicoder No.94 (http://yukicoder.me/submissions/82111)
 */
struct UnionFind { disj: Vec<usize>,
rank: Vec<usize> }

impl UnionFind {
    fn new(n: usize) -> Self {
        let mut disj = vec![0; n];
        for i in 0 .. n {
            disj[i] = i;
        }
        UnionFind { disj: disj, rank: vec![0; n] }
    }
    fn root(self: &mut Self, x: usize) -> usize {
        if x != self.disj[x] {
            let par = self.disj[x];
            let r = self.root(par);
            self.disj[x] = r;
        }
        return self.disj[x];
    }
    fn unite(self: &mut Self, x: usize, y: usize) {
        let mut xr = self.root(x);
        let mut yr = self.root(y);
        if self.rank[xr] > self.rank[yr] {
            std::mem::swap(&mut xr, &mut yr);
        }
        self.disj[xr] = yr;
        self.rank[yr] = max(self.rank[yr], self.rank[xr] + 1);
    }
    fn is_same_set(self: &mut Self, x: usize, y: usize) -> bool {
        return self.root(x) == self.root(y);
    }
}

const INF: i64 = 1 << 50;

// Reference: https://atcoder.jp/contests/keyence2019/submissions/4005570
// Divide and conquer
fn dc(l: usize, r: usize, a: &[i64], d: i64,
      pool: &mut Vec<(i64, usize, usize)>) {
    let n = a.len();
    if l + 1 >= r { return }
    let mid = (l + r) / 2;
    let mut mil = (INF, n);
    for i in l .. mid {
        mil = min(mil, (a[i] - d * i as i64, i));
    }
    let mut mir = (INF, n);
    for i in mid .. r {
        mir = min(mir, (a[i] + d * i as i64, i));
    }
    for i in l .. mid {
        let idx = mir.1;
        pool.push((a[i] + a[idx] + d * (idx - i) as i64, i, idx));
    }
    for i in mid .. r {
        let idx = mil.1;
        pool.push((a[idx] + a[i] + d * (i - idx) as i64, idx, i));
    }
    dc(l, mid, a, d, pool);
    dc(mid, r, a, d, pool);
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        d: i64,
        a: [i64; n],
    }
    let mut pool = Vec::new();
    dc(0, n, &a, d, &mut pool);
    pool.sort();
    let mut uf = UnionFind::new(n);
    let mut tot = 0;
    for (cost, x, y) in pool {
        if !uf.is_same_set(x, y) {
            uf.unite(x, y);
            tot += cost;
        }
    }
    puts!("{}\n", tot);
}

