fn wei(i: usize, j: usize) -> i64 {
    (i as i64 - j as i64).abs()
}

fn main() {
    let (N, D) = read!(usize, i64);
    let A = read![[i64]];

    let mut L = vec![0; N];
    let mut R = vec![0; N];

    let mut li = 0;
    for i in 1..N {
        let l = wei(i, li) * D + A[li];
        if l < A[i] {
            L[i] = li;
        } else {
            L[i] = i;
            li = i;
        }
    }

    let mut ri = N - 1;
    R[ri] = ri;
    for i in (0..N - 1).rev() {
        let r = wei(i, ri) * D + A[ri];
        if r < A[i] {
            R[i] = ri;
        } else {
            R[i] = i;
            ri = i;
        }
    }

    let mut roots = vec![];
    let mut W = 0_i64;
    for i in 0..N {
        let li = L[i];
        let ri = R[i];
        if li == i && ri == i {
            roots.push(i);
            continue;
        }

        let l = if i == li {
            std::i64::MAX
        } else {
            wei(i, li) * D + A[li]
        };

        let r = if i == ri {
            std::i64::MAX
        } else {
            wei(i, ri) * D + A[ri]
        };

        debug!((i, li, ri, l, r));
        W += min(l, r) + A[i];
    }
    debug!(roots);

    for win in roots.windows(2) {
        let i = win[0];
        let j = win[1];
        let w = wei(i, j) * D + A[i] + A[j];
        W += w;
        debug!((i, j, w));
    }

    println!("{}", W);
}

