            let mut min_1_id = n;
            let mut min_2 = inf;
            let mut min_2_id = n;
            for i in 0..n {
                min_1 += d;
                min_2 += d;
                if closest[i].0 > min_1 && uf.root(i) != uf.root(min_1_id) {
                    closest[i] = (min_1, min_1_id);
                }
                if closest[i].0 > min_2 && uf.root(i) != uf.root(min_2_id) {
                    closest[i] = (min_2, min_2_id);
                }
                if xs[i] < min_1 && uf.root(i) == uf.root(min_1_id) {
                    min_1 = xs[i];
                    min_1_id = i;
                }
                else if xs[i] < min_1 && uf.root(i) != uf.root(min_1_id) {
                    min_2 = min_1;
                    min_2_id = min_1_id;
                    min_1 = xs[i];
                    min_1_id = i;
                }
                else if xs[i] < min_2 && uf.root(i) == uf.root(min_2_id) {
                    min_2 = xs[i];
                    min_2_id = i;
                }
                else if xs[i] < min_2 && uf.root(i) != uf.root(min_1_id) {
                    min_2 = xs[i];
                    min_2_id = i;
                }
            }
        }
        // right
        {
            let mut min_1 = inf;
            let mut min_1_id = n;
            let mut min_2 = inf;
            let mut min_2_id = n;
            for i in (0..n).rev() {
                min_1 += d;
                min_2 += d;
                if closest[i].0 > min_1 && uf.root(i) != uf.root(min_1_id) {
                    closest[i] = (min_1, min_1_id);
                }
                if closest[i].0 > min_2 && uf.root(i) != uf.root(min_2_id) {
                    closest[i] = (min_2, min_2_id);
                }
                if xs[i] < min_1 && uf.root(i) == uf.root(min_1_id) {
                    min_1 = xs[i];
                    min_1_id = i;
                }
                else if xs[i] < min_1 && uf.root(i) != uf.root(min_1_id) {
                    min_2 = min_1;
                    min_2_id = min_1_id;
                    min_1 = xs[i];
                    min_1_id = i;
                }
                else if xs[i] < min_2 && uf.root(i) == uf.root(min_2_id) {
                    min_2 = xs[i];
                    min_2_id = i;
                }
                else if xs[i] < min_2 && uf.root(i) != uf.root(min_1_id) {
                    min_2 = xs[i];
                    min_2_id = i;
                }
            }
        }
        let mut zs = vec![];
        for i in 0..n {
            zs.push((closest[i].0 + xs[i], i));
        }
        zs.sort();
        for &(d, i) in &zs {
            if uf.root(i) != uf.root(closest[i].1) && closest[i].1 != n {
                uf.unite(i, closest[i].1);
                res += d;
            }
        }
        for i in 0..n {
        }
    }
    println!("{}", res);
}

use std::io::BufRead;
