use std::ops::AddAssign;

struct BinaryIndexedTree<T> {
    v: Vec<T>,
}

impl<T: Clone + Copy + From<i64> + AddAssign> BinaryIndexedTree<T> {
    fn new(n: usize) -> BinaryIndexedTree<T> {
        BinaryIndexedTree {
            v: vec![0.into(); n],
        }
    }

    fn update(&mut self, x: usize, delta: T) {
        let mut x = x;
        while x < self.v.len() {
            self.v[x] += delta;
            x += x & (!x + 1);
        }
    }

    fn query(&self, x: usize) -> T {
        let mut x = x;
        let mut sum = 0.into();
        while x > 0 {
            sum += self.v[x];
            x -= x & (!x + 1);
        }
        sum
    }
}

